"""قانون تجارت مصوب ۱۳۱۱: متن کامل ۶۰۰ ماده و متن جاری مواد دارای تعدیل جزای نقدی ۱۴۰۳."""

COMMERCIAL_CODE_1311_ORIGINAL = [(1, 'تاجر کسی است که شغل معمولی خود را معاملات تجارتی قرار بدهد.'),
 (2,
  'معاملات تجارتی از قرار ذیل است: ۱) خرید یا تحصیل هر نوع مال منقوض به قصد فروش یا اجاره اعم از اینکه تصرفاتی در آن '
  'شده یا نشده باشد. ۲) تصدی به حمل و نقل از راه خشکی یا آب یا هوا به هر نحوی که باشد. ۳) هر قسم عملیات دلالی یا '
  'حق\u200cالعمل\u200cکاری (\u200cکمیسیون) و یا عاملی و همچنین تصدی به هر نوع تأسیساتی که برای انجام بعضی امور '
  'ایجادمی\u200cشود از قبیل تسهیل معاملات ملکی یا پیدا کردن خدمه یا تهیه و رسانیدن ملزومات و غیره. ۴) تأسیس و به کار '
  'انداختن هر قسم کارخانه مشروط بر اینکه برای رفع حوائج شخصی نباشد. ۵) تصدی به عملیات حراجی. ۶) تصدی به هر قسم '
  'نمایشگاه\u200cهای عمومی. ۷) هر قسم عملیات صرافی و بانکی. ۸) معاملات برواتی اعم از اینکه بین تاجر یا غیر تاجر '
  'باشد. ۹) عملیات بیمه بحری و غیر بحری ۱۰) کشتی\u200cسازی و خرید و فروش کشتی و کشتیرانی داخلی یا خارجی و معاملات '
  'راجعه به آنها.'),
 (3,
  'معاملات ذیل به اعتبار تاجر بودن متعاملین یا یکی از آنها تجارتی محسوب می\u200cشود: ۱) کلیه معاملات بین تجار و کسبه '
  'و صرافان و بانکها. ۲) کلیه معاملاتی که تاجر یا غیر تاجر برای حوائج تجارتی خود می\u200cنماید. ۳) کلیه معاملاتی که '
  'اجزاء یا خدمه یا شاگرد تاجر برای امور تجارتی ارباب خود می\u200cنماید. ۴) کلیه معاملات شرکتهای تجارتی.'),
 (4, 'معاملات غیر منقول به هیچ وجه تجارتی محسوب نمی\u200cشود.'),
 (5, 'کلیه معاملات تجار تجارتی محسوب است مگر اینکه ثابت شود معامله مربوط به امور تجارتی نیست.'),
 (6,
  'هر تاجری به استثنای کسبه جزء مکلف است دفاتر ذیل یا دفاتر دیگری را که وزارت عدلیه به موجب نظامنامه قائم\u200cمقام '
  'این دفاتر قرارمی\u200cدهد داشته باشد: ۱) دفتر روزنامه. ۲) دفتر کل. ۳) دفتر دارایی. ۴) دفتر کپیه.'),
 (7,
  'دفتر روزنامه دفتری است که تاجر باید همه روزه مطالبات و دیون و داد و ستد تجارتی و معاملات راجع به اوراق تجارتی '
  '(\u200cاز قبیل خرید وفروش و ظهرنویسی) و به طور کلی جمیع واردات و صادرات تجارتی خود را به هر اسم و رسمی که باشد و '
  'وجوهی را که برای مخارج شخصی خودبرداشت می\u200cکند در آن دفتر ثبت نماید.'),
 (8,
  'دفتر کل دفتری است که تاجر باید کلیه معاملات را لااقل هفته یک مرتبه از دفتر روزنامه استخراج و انواع مختلفه آن را '
  'تشخیص و جداکرده هر نوعی را در صفحه مخصوصی در آن دفتر به طور خلاصه ثبت کند.'),
 (9,
  'دفتر دارایی دفتری است که تاجر باید هر سال صورت جامعی از کلیه دارایی منقول و غیر منقول و دیون و مطالبات سال گذشته '
  'خود را به\u200cریز ترتیب داده در آن دفتر ثبت و امضاء نماید و این کار باید تا پانزدهم فروردین سال بعد انجام '
  'پذیرد.'),
 (10,
  'دفتر کپیه دفتری است که تاجر باید کلیه مراسلات و مخابرات و صورت\u200cحسابهای صادره خود را در آن به ترتیب تاریخ ثبت '
  'نماید. تبصره - تاجر باید کلیه مراسلات و مخابرات و صورت\u200cحسابهای وارده را نیز به ترتیب تاریخ ورود مرتب نموده و '
  'در لفاف مخصوصی ضبط کند.'),
 (11,
  'دفاتر مذکور در ماده ۶ به استثناء دفتر کپیه قبل از آنکه در آن چیزی نوشته شده باشد به توسط نماینده اداره ثبت '
  '(\u200cکه مطابق نظامنامه\u200cوزارت عدلیه معین می\u200cشود) امضاء خواهد شد. برای دفتر کپیه امضاء مزبور لازم نیست '
  'ولی باید اوراق آن دارای نمره ترتیبی باشد. در موقع تجدیدسالیانه هر دفتر مقررات این ماده رعایت خواهد شد. حق امضاء '
  'از قرار هر صد صفحه یا کسور آن دو ریال به علاوه مشمول ماده (۱۳۵) قانون ثبت اسناد است.'),
 (12,
  'دفتری که برای امضاء به متصدی امضاء تسلیم می\u200cشود باید دارای نمره ترتیبی و قیطان کشیده باشد و متصدی امضاء مکلف '
  'است\u200cصفحات دفتر را شمرده در صفحه اول و آخر هر دفتر مجموع عدد صفحات آن را با تصریح به اسم و رسم صاحب دفتر '
  'نوشته با قید تاریخ امضاء و دوطرف قیطان را با مهر سربی که وزارت عدلیه برای این مقصود تهیه می\u200cنماید منگنه کند. '
  'لازم است کلیه اعداد حتی تاریخ با تمام حروف نوشته شود.'),
 (13,
  'کلیه معاملات و صادرات و واردات در دفاتر مذکوره فوق باید به ترتیب تاریخ در صفحات مخصوصه نوشته شود - تراشیدن و '
  'حک\u200cکردن و همچنین جای سفید گذاشتن بیش از آنچه که در دفترنویسی معمول است و در حاشیه و یا بین سطور نوشتن ممنوع '
  'است و تاجر باید تمام آن\u200cدفاتر را از ختم هر سالی لااقل تا ده سال نگاهدارد.'),
 (14,
  'دفاتر مذکور در ماده ۶ و سایر دفاتری که تجار برای امور تجارتی خود به کار می\u200cبرند در صورتی که مطابق مقررات این '
  'قانون مرتب شده\u200cباشد بین تجار - در امور تجارتی - سندیت خواهد داشت و غیر این صورت فقط بر علیه صاحب آن معتبر '
  'خواهد بود.'),
 (15,
  'تخلف از ماده ۶ و ماده ۱۱ مستلزم دویست تا ده هزار ریال جزای نقدی است. این مجازات را محکمه حقوق رأساً و بدون '
  'تقاضای\u200cمدعی\u200cالعموم می\u200cتواند حکم بدهد و اجرای آن مانع اجرای مقررات راجع به تاجر ورشکسته که دفتر '
  'مرتب ندارد نخواهد بود.'),
 (16,
  'در نقاطی که وزارت عدلیه مقتضی دانسته و دفتر ثبت تجارتی تأسیس کند کلیه اشخاصی که در آن نقاط به شغل تجارت اشتغال '
  'دارند اعم\u200cاز ایرانی و خارجی به استثنای کسبه جزء باید در مدت مقرر اسم خود را در دفتر ثبت تجارتی به ثبت '
  'برسانند و الا به جزای نقدی از دویست تا دو هزارریال محکوم خواهند شد.'),
 (17,
  'مقررات مربوطه به دفتر ثبت تجارتی را وزارت عدلیه با تصریح به موضوعاتی که باید به ثبت برسد به موجب نظامنامه معین '
  'خواهد کرد.'),
 (18,
  'شش ماه پس از الزامی شدن ثبت تجارتی هر تاجری که مکلف به ثبت است باید در کلیه اسناد و صورت\u200cحسابها و نشریات خطی '
  'یا چاپی\u200cخود در ایران تصریح نماید که در تحت چه نمره به ثبت رسیده و الا علاوه بر مجازات مقرر در فوق به جزای '
  'نقدی از دویست تا دو هزار ریال محکوم\u200cمی\u200cشود.'),
 (19, 'کسبه جزء مذکور در این فصل و فصل اول مطابق مقررات نظامنامه وزارت عدلیه تشخیص می\u200cشوند.'),
 (20,
  'شرکتهای تجارتی بر هفت قسمت است: ۱) شرکت سهامی. ۲) شرکت با مسئولیت محدود. ۳) شرکت تضامنی. ۴) شرکت مختلط غیر سهامی. '
  '۵) شرکت مختلط سهامی. ۶) شرکت نسبی. ۷) شرکت تعاونی تولید و مصرف.'),
 (21,
  'شرکت سهامی شرکتی است که برای امور تجارتی تشکیل و سرمایه آن به سهام تقسیم شده و مسئولیت صاحبان سهام محدود به '
  'سهام\u200cآنها است.'),
 (22, 'در اسم شرکت سهامی نام هیچیک از شرکاء قید نخواهد شد - در اسم شرکت باید کلمه (\u200cسهامی) قید شود.'),
 (23, 'سهام ممکن است با اسم یا بی\u200cاسم باشد.'),
 (24,
  'سهام بی\u200cاسم به صورت سند در وجه حامل مرتب و دارنده آن مالک شناخته می\u200cشود مگر آنکه خلاف آن قانوناً ثابت '
  'گردد - نقل و انتقال\u200cاین نوع سهام به قبض و اقباض به عمل می\u200cآید.'),
 (25,
  'انتقال سهام با اسم باید در دفتر شرکت به ثبت برسد صاحب سهم باید شخصاً یا به توسط وکیل انتقال را در دفتر شرکت تصدیق '
  'و امضانماید.'),
 (26,
  'سهام ممکن است نقدی باشد یا غیر نقدی - سهام غیر نقدی سهامی است که در ازاء آن به جای وجه نقد چیز دیگری از قبیل '
  'کارخانه وامتیازنامه و غیره داده شود.'),
 (27, 'قیمت سهام و همچنین قیمت قطعات سهام (\u200cدر صورت تجزیه) متساوی خواهد بود.'),
 (28,
  'در صورتی که سرمایه شرکتهای سهامی از دویست هزار ریال تجاوز نکند سهام یا قطعات سهام نباید کمتر از پنجاه ریال باشد و '
  'هر گاه\u200cسرمایه زائد بر دویست هزار ریال باشد سهام و قطعات سهام کمتر از یک صد ریال نخواهد بود.'),
 (29,
  'مادام که شرکت سهامی تشکیل نشده سهام یا تصدیق موقتی (\u200cاعم از بااسم یا بی\u200cاسم) نمی\u200cتوان صادر کرد هر '
  'سهم یا تصدیق موقتی که\u200cقبل از تشکیل شرکت به کسی داده شده باشد باطل و صادرکنندگان متضامناً مسئول خساراتی هستند '
  'که به دارندگان این قبیل اوراق وارد شده\u200cاست. تا زمانی که پنجاه درصد قیمت اسمی سهام تأدیه نشده نمی\u200cتوان '
  'سهام بی\u200cاسم یا تصدیق موقتی بی\u200cاسم انتشار داد.'),
 (30,
  'کسانی که تعهد ابتیاع سهام کرده\u200cاند تا موقعی که پنجاه درصد قیمت اسمی سهام خود را نپرداخته\u200cاند مسئول '
  'تأدیه بقیه قیمت آن خواهندبود اگر چه سهام خود را به دیگری منتقل کرده و منتقل\u200cالیه نیز پرداخت بقیه را تعهد '
  'کرده باشد.'),
 (31,
  'بعد از تأدیه پنجاه درصد نیز کسی که تعهد ابتیاع سهمی را کرده\u200cاست از تأدیه بقیه قیمت آن بری نخواهد بود مگر '
  'اینکه اساسنامه شرکت\u200cآن را تجویز کرده باشد که در این صورت منتقل\u200cالیه مسئول تأدیه آن بقیه\u200cاست.'),
 (32,
  'هر کس تعهد ابتیاع سهامی را کرده و در موعد مقرر وجه تعهد شده را نپردازد علاوه بر آن وجه به خسارات تأخیر تأدیه '
  '(\u200cاز قرار صدی\u200cدوازده در سال و به نسبت مدت تأخیر) محکوم خواهد شد.'),
 (33,
  'اساسنامه شرکت می\u200cتواند نسبت به اشخاص مذکور در ماده فوق ترتیب دیگری اتخاذ نموده حتی مقرر دارد که در صورت عدم '
  'تأدیه بقیه\u200cقیمت سهام مقدار تأدیه شده از آن بابت بلاعوض تعلق به شرکت یافته و تعهدکننده نسبت به سهام تعهدی هیچ '
  'حقی نداشته باشد لیکن در این صورت\u200cپرداخت وجه تعهد شده باید لااقل سه مرتبه به وسیله مکتوب با قبض رسید مطالبه و '
  'از تاریخ آخرین مکتوب یک ماه منقضی شده باشد در مورد سهام\u200cبی\u200cاسم به جای مکتوب اعلان در جراید به عمل خواهد '
  'آمد مفاد این ماده باید در موقع تعهد صریحاً در دفتر شرکت قید شده و متعهد ذیل آن را امضاءنماید.'),
 (34,
  'خواه در سهام بااسم و خواه در سهام بی\u200cاسم مادام که قیمت آنها کاملاً تأدیه نشده\u200cاست باید آن مقدار از قیمت '
  'که پرداخته شده صریحاً\u200cروی سهم قید شود به علاوه شرکت مکلف است در هر گونه اسناد و صورت\u200cحسابها و اعلانات و '
  'نشریات و غیره که به طور خطی یا چاپی صادر یامنتشر می\u200cنماید میزان سرمایه خود و آن قسمتی را که تأدیه '
  'شده\u200cاست صریحاً قید کند.'),
 (35,
  'هر شرکت سهامی می\u200cتواند به موجب رأی مجمع عمومی که مطابق ماده (۷۴) این قانون تشکیل شده باشد سهام ممتازه ترتیب '
  'دهد که\u200cنسبت به سایر سهام رجحان و مزایایی داشته باشد ولی ایجاد این نوع سهام مشروط است به اینکه اساسنامه شرکت '
  'چنین اقدامی را تجویز کرده باشد.'),
 (36,
  'شرکت سهامی به موجب شرکتنامه که در دو نسخه نوشته شده باشد تشکیل می\u200cشود یکی از نسختین به طوری که در ماده (۵۰) '
  'مقرراست ضمیمه اظهارنامه مدیر شرکت و دیگری در مرکز اصلی شرکت ضبط خواهد شد.'),
 (37,
  'شرکت باید دارای اساسنامه باشد که نکات ذیل مخصوصاً در آن تصریح بشود: ۱) اسم و مرکز اصلی شرکت. ۲) موضوع شرکت. ۳) '
  'مدت شرکت در صورتی که شرکت برای مدت معینی تشکیل شود. ۴) مقدار سرمایه شرکت و مقدار قیمت سهام. ۵) نوع سهام (\u200cکه '
  'سهام بااسم یا بی\u200cاسم) عده هر نوع از سهام و تعیین اینکه سهام بااسم و بی\u200cاسم به چه شکل ممکن است به هم '
  'تبدیل شود درصورتی که این تبدیل اساساً پذیرفته باشد. ۶) هیأت\u200cهای اداره و تفتیش. ۷) عده سهامی را که مدیران '
  'شرکت باید به صندوق شرکت بسپارند. ۸) مقررات راجع به دعوت مجمع عمومی و حق رأی صاحبان سهام و طریقه شور و اخذ رأی. ۹) '
  'مطالبی که برای قطع آن در مجموع عمومی اکثریت مخصوصی لازم است. ۱۰) طرز ترتیب صورت\u200cحساب سالیانه و رسیدگی به آن '
  'و همچنین اصولی که برای حساب منافع و تقسیم آن باید رعایت شود. ۱۱) طریق تغییر اساسنامه.'),
 (38,
  'تشکیل شرکت\u200cهای سهامی محقق نمی\u200cشود مگر بعد از آنکه تأدیه تمام سرمایه شرکت تعهد شده باشد به علاوه هر گاه '
  'سهام یا قطعات آن\u200cزائد بر پنجاه ریال نباشد تعهدکنندگان باید تمام وجه را تأدیه نمایند و الا باید لااقل ثلث '
  'قیمت سهام را نقداً بپردازند و در هر حال وجهی که پرداخته\u200cمی\u200cشود نباید کمتر از ۵۰ ریال باشد.'),
 (39, 'چیزی که در ازاء سهام غیر نقدی تعهد شده تماماً باید تحویل شود.'),
 (40,
  'مؤسسین باید پس از تنظیم نوشته که حاکی از تعهد پرداخت سرمایه شرکت و تأدیه واقعی ثلث سرمایه نقدی است مجمع '
  'عمومی\u200cشرکت را دعوت نمایند این مجمع اولین مدیرهای شرکت و همچنین مفتش (\u200cکمیسر)\u200cهایی را که به موجب '
  'ماده (۶۲) مقرر است معین می\u200cکند.'),
 (41,
  'هر گاه یکی از تعهدکنندگان سهم غیر نقدی اختیار کند یا مزایای خاصی برای خود مطالبه نماید مجمع عمومی در جلسه اول که '
  'منعقدمی\u200cشود امر به تقویم سهم غیر نقدی نموده یا موجبات مزایای مطالبه شده را تحت نظر می\u200cگیرد تصویب قطعی '
  'تقویم یا موجبات مزایا به عمل نمی\u200cآید وتشکیل شرکت واقع نمی\u200cشود مگر در جلسه دیگر مجمع عمومی که بر حسب '
  'دعوت جدید منعقد خواهد شد و برای اینکه در جلسه دوم تقویم یاموجبات مزایا تصویب شود باید لااقل پنج روز قبل از انعقاد '
  'جلسه راپرتی در این خصوص طبع و بین تمام تعهدکنندگان توزیع شده باشد تصویب امورمذکور باید به اکثریت دو ثلث '
  'تعهدکنندگان حاضر باشد و جلسه مجمع عمومی قانونی نخواهد بود مگر اینکه عدداً نصف کل شرکایی که خرید سهام\u200cنقدی را '
  'تعهد کرده\u200cاند حاضر بوده و نصف کل سرمایه نقدی را دارا باشند کسانی که دارای سهم غیر نقدی هستند یا مزایای خاصی '
  'برای خود مطالبه\u200cکرده\u200cاند در موقعی که سهم غیر نقدی یا مزایای آنها موضوع رأی است حق رأی ندارند آن قسمت از '
  'سرمایه غیر نقدی که موضوع مذاکره و رأی است درجزو سرمایه شرکت محسوب نخواهد شد اگر در جلسه دوم مجمع عمومی نصف '
  'تعهدکنندگان سهام نقدی و نصف سرمایه نقدی حاضر نش ده مجمع به\u200cطور موقت تصمیم خواهد گرفت و مطابق قسمت اخیر ماده '
  '(۴۵) رفتار می\u200cشود. هر گاه سهام غیر نقدی یا موجبات مزایایی که مطالبه شده و تصویب نشود هر یک از تعهدکنندگان '
  'می\u200cتواند از شرکت خارج شود.'),
 (42, 'تصویب مراتب مذکور در ماده فوق مانع نیست از اینکه بعداً نسبت به آنها دعوی تزویر و تقلب اقامه شود.'),
 (43,
  'هر گاه شرکت بین اشخاصی منعقد شود که سرمایه\u200cهای غیر نقدی مشاعاً و منحصراً متعلق به خودشان باشد رعایت ترتیبات '
  'مذکوره درماده (۴۱) راجع به تقویم سهام غیر نقدی لازم نخواهد بود.'),
 (44,
  'اظهارنامه که به موجب ماده (۵۰) به دایره ثبت اسناد باید تسلیم شود مؤسسین شرکت تهیه نموده با اسناد مربوطه به اولین '
  'مجمع\u200cعمومی تقدیم می\u200cنمایند تا مجمع صحت یا سقم آن را معین کند.'),
 (45,
  'مجمع عمومی که در باب صحت اظهارات مؤسسین اظهار رأی و اولین مدیرها و مفتشین را انتخاب می\u200cنماید باید از یک عده '
  'صاحبان\u200cسهام مرکب شود که لااقل نصف سرمایه شرکت را دارا باشند - اگر در مجمع عمومی عده که نصف سرمایه را دارا '
  'باشند حاضر نشدند تصمیمات مجمع\u200cموقتی خواهد بود در این صورت مجمع عمومی جدیدی دعوت می\u200cشود و اگر پس از آنکه '
  'لااقل یک ماه قبل از انعقاد مجمع دو دفعه متوالی به فاصله\u200cهشت روز به وسیله یکی از جراید محلی تصمیمات موقتی '
  'مجمع سابق اعلان و منتشر شد و مجمع جدید آن را تصویب نمود تصمیمات مزبوره قطعی\u200cمی\u200cشود مشروط بر اینکه در '
  'مجمع جدید عده حاضر شوند که لااقل ثلث سرمایه شرکت را دارا باشند. تبصره - جرایدی که اعلانات فوق را باید منتشر '
  'نمایند همه\u200cساله توسط وزارت عدلیه معین و اعلان خواهد شد.'),
 (46,
  'مجمع عمومی فوق اولین مدیرها و مفتشین شرکت را انتخاب می\u200cکند مفتشین برای سال اول و مدیران منتها برای مدت چهار '
  'سال معین\u200cمی\u200cشوند مدیرها را می\u200cتوان پس از انقضاء مدت چهار سال مجدداً انتخاب نمود مگر آنکه اساسنامه '
  'شرکت غیر از این مقرر داشته باشد ولی در صورتی\u200cکه بر حسب مقررات اساسنامه تعیین آنها موکول به تصویب مجمع عمومی '
  'نباشد مدت مدیری آنها بیش از دو سال نخواهد بود.'),
 (47,
  'در صورتی که مدیرها و مفتشینی که از طرف مجمع عمومی انتخاب شده\u200cاند قبول انجام وظیفه نمایند قبولی آنها در '
  'صورت\u200cمجلس قید وشرکت از همان تاریخ تشکیل می\u200cگردد. ۳ - مدیرهای شرکت و وظایف آنها'),
 (48,
  'شرکت سهامی به واسطه یک یا چند نفر نماینده موظف یا غیر موظف که از میان شرکاء به سمت مدیری و برای مدت محدودی '
  'معین\u200cشده و قابل عزل می\u200cباشند اداره خواهد شد.'),
 (49,
  'در صورتی که چند نفر به سمت مدیری معین شده باشند باید یک نفر از میان خود به سمت ریاست انتخاب کنند - رییس مزبور و '
  'هر یک\u200cاز مدیران می\u200cتوانند در صورتی که اساسنامه شرکت اجازه داده باشد با تصویب یکدیگر یک نفر شخص خارج را '
  'به جای خود معین کنند ولی مسئولیت\u200cاعمال شخص خارج به عهده خود آنها خواهد بود.'),
 (50,
  'برای این که تعهد و تأدیه وجه سرمایه از طرف شرکاء ثابت شود باید مدیر شرکت وقوع آن را به موجب نوشته که به دایره ثبت '
  'اسناد مرکزاصلی شرکت می\u200cسپارد و به ثبت می\u200cرسد اعلام نماید و باید اسامی شرکاء را با مقداری از سرمایه که '
  'پرداخته شده با یک نسخه از اساسنامه و یکی ازنسختین شرکتنامه به نوشته مزبور منضم نماید.'),
 (51, 'مسئولیت مدیر شرکت در مقابل شرکاء همان مسئولیتی است که وکیل در مقابل موکل دارد.'),
 (52,
  'مدیرها باید یک عده سهامی را که به موجب اساسنامه مقرر است دارا باشند این سهام برای تضمین خساراتی است که ممکن است '
  'ازاعمال اداری مدیرها مشترکاً یا منفرداً بر شرکت وارد شود- سهام مذکوره با اسم بوده و قابل انتقال نیست و به وسیله '
  'مهری که بر روی آنها زده می\u200cشودغیر قابل انتقال بودن آنها معلوم و در صندوق شرکت ودیعه خواهد ماند.'),
 (53,
  'مدیرهای شرکت نمی\u200cتوانند بدون اجازه مجمع عمومی در معاملاتی که با شرکت یا به حساب شرکت می\u200cشود به طور '
  'مستقیم یاغیر مستقیم سهیم شوند و در صورت اجازه باید صورت مخصوص آن را همه\u200cساله به مجمع عمومی بدهند.'),
 (54, 'مدیران هر شرکت سهامی باید شش ماه به شش ماه خلاصه صورت دارایی و قروض شرکت را مرتب کرده به مفتشین بدهند.'),
 (55,
  'مدیران هر شرکت سهامی باید مطابق ماده (۹) این قانون صورت\u200cحسابی که متضمن دارایی منقول و غیر منقول و همچنین '
  'صورت\u200cمطالبات و قروض شرکت باشد مرتب کنند - این صورت\u200cحساب و همچنین بیلان حساب نفع و ضرر شرکت باید لااقل '
  'چهل روز قبل از انعقاد مجمع\u200cعمومی به مفتشین داده شود که به مجمع مزبور بدهند.'),
 (56,
  'از پانزده روز قبل از انعقاد مجمع عمومی هر صاحب سهم می\u200cتواند در مرکز شرکت به صورت حساب و صورت اسامی صاحبان '
  'سهام\u200cمراجعه کرده و از بیلان که متضمن خلاصه صورت\u200cحساب شرکت است و از راپورت مفتشین سواد بگیرد.'),
 (57,
  'همه\u200cساله لااقل یک بیستم از عایدات خالص شرکت برای تشکیل سرمایه احتیاطی موضوع خواهد شد - همین که سرمایه '
  'احتیاطی به\u200cعشر سرمایه شرکت رسید موضوع کردن این مقدار اختیاری است.'),
 (58,
  'اگر به واسطه ضررهای وارده نصف سرمایه شرکت از میان برود مدیران شرکت مکلفند تمام صاحبان سهام را برای انعقاد مجمع '
  'عمومی\u200cدعوت نمایند تا موضوع انحلال یا ابقاء شرکت مورد شور و رأی شود - تصمیم این مجمع در هر حال منتشر خواهد '
  'شد.'),
 (59,
  'هر گاه مدیران شرکت برخلاف ماده فوق مجمع عمومی را دعوت نکردند و یا مجمعی که دعوت می\u200cشود نتواند مطابق مقررات '
  'قانونی\u200cمنعقد گردد هر ذیحقی می\u200cتواند انحلال شرکت را از محاکم صالحه بخواهد.'),
 (60,
  'هر گاه یک یا چند نفر از ارباب سهامی که مجموع سهام آنها لااقل معادل یک خمس سرمایه شرکت باشد کتباً تقاضای انعقاد '
  'مجمع\u200cعمومی فوق\u200cالعاده نمایند و منظور خود را در آن تقاضانامه تصریح نموده باشند باید مجمع عمومی به طور '
  'فوق\u200cالعاده منعقد شود.'),
 (61,
  'مدیرهای شرکت در مقابل شرکت یا اشخاص ثالث برای تخلف از مقررات این قانون و تقصیراتی که در اعمال اداری شرکت مرتکب '
  'شوندموافق قواعد عمومی مسئول می\u200cباشند مخصوصاً در موقعی که منافع موهومی را تقسیم نمایند یا از تقسیم منافع '
  'موهومی جلوگیری نکنند.'),
 (62,
  'مجمع عمومی سالیانه یک یا چند مفتش (\u200cکمیسر) معین می\u200cکند - مفتشین مزبور که ممکن است از غیر شرکاء نیز '
  'انتخاب شوند مأموریت\u200cخواهند داشت که در موضوع اوضاع عمومی شرکت و همچنین در باب بیلان (\u200cخلاصه جمع و خرج) و '
  'صورت\u200cحسابهایی که مدیرها تقدیم می\u200cکنندراپرتی به مجمع عمومی سال آینده بدهند - تصمیماتی که بدون این راپرت '
  'راجع به تصدیق بیلان و صورت\u200cحسابهای مدیران اخذ می\u200cشود معتبرنخواهد بود - در صورتی که مجمع عمومی مفتشین '
  'مذکور را معین نکرده باشد یا یک یا چند نفر از مفتشینی که معین شده\u200cاند نتوانند راپرت بدهند یا ازدادن راپرت '
  'امتناع نمایند رییس محکمه بدایت مرکز اصلی شرکت به تقاضای هر ذیحقی و پس از احضار مدیران شرکت مفتشین را انتخاب و یا '
  'به جای\u200cآنهایی که نتوانسته\u200cاند یا امتناع کرده\u200cاند مفتشین جدیدی معین می\u200cکند.'),
 (63,
  'در ظرف سه ماه قبل از تاریخی که به موجب اساسنامه شرکت برای انعقاد مجمع عمومی معین است مفتشین می\u200cتوانند به '
  'دفاتر شرکت\u200cمراجعه نموده و از عملیات آن تحقیقاتی بنمایند مفتشین می\u200cتوانند در مواقعی که ضرورت فوری دارد '
  'مجمع عمومی را دعوت نمایند.'),
 (64,
  'حدود مسئولیت مفتشین و اثرات آن همان است که راجع به حدود مسئولیت وکلاء و اثرات آن در مقابل موکلین قانوناً معین '
  'است.'),
 (65, 'مجمع عمومی شرکت باید لااقل سالی یک دفعه در موقعی که به موجب اساسنامه معین است منعقد شود.'),
 (66, 'اساسنامه معین می\u200cکند برای حق ورود در مجمع چند سهم (\u200cبه عنوان وکالت یا مالکیت) باید داشت.'),
 (67, 'عده آرایی که هر یک از شرکاء به نسبت عده سهام خود دارند به موجب اساسنامه معین می\u200cگردد.'),
 (68,
  'در جلسات مجمع عمومی هیچکدام از صاحبان سهام معمولی و صاحبان سهام ممتازه از حیث رأی تفاوتی ندارند مگر اینکه '
  'اساسنامه\u200cشرکت طور دیگر مقرر کرده باشد.'),
 (69,
  'دارندگان سهامی که عده سهام هر یک از آنها برای حضور یا رأی در مجمع عمومی کافی نیست می\u200cتوانند به اندازه که '
  'مجمع عده سهام آنهابرای داشتن حق حضور و رأی کافی باشد با یکدیگر متفق شده یک نفر را از میان خود برای حضور و رأی در '
  'مجمع مذکور معین نمایند.'),
 (70,
  'در مجامع عمومی که برای رسیدگی به سهم\u200cالشرکه و مزایا مطابق ماده (۴۱) و در مجامعی که برای تعیین اولین مدیرها و '
  'مفتشین وتصدیق اظهارات مؤسسین مطابق ماده (۴۵) منعقد می\u200cشود کلیه صاحبان سهام قطع نظر از عده سهامی که دارند '
  'می\u200cتوانند حضور به هم رسانند.'),
 (71,
  'مجمع عمومی شرکت جز در موارد مذکور در مواد (۴۱ و ۴۵ و ۷۴) باید مرکب از یک عده صاحبان سهامی باشد که لااقل ثلث '
  'سرمایه\u200cشرکت را دارا باشند و اگر در دفعه اول این حد نصاب حاصل نشد مجمع عمومی جدیدی مطابق شرایط مقرر در '
  'اساسنامه شرکت تشکیل و تصمیمات\u200cاین مجمع قطعی خواهد بود ولو اینکه حد نصاب فوق حاصل نشود.'),
 (72, 'تصمیمات مجمع عمومی به اکثریت آراء خواهد بود.'),
 (73,
  'در مواردی که مجمع عمومی شرکاء نسبت به حقوق نوع مخصوصی از سهام تصمیمی نماید که تغییری در حقوق آنها بدهد آن '
  'تصمیم\u200cقطعی نخواهد بود مگر بعد از آنکه صاحبان سهام مزبوره در جلسه خاصی آن تصمیم را تصویب نمایند و برای اینکه '
  'آراء جلسه خاص مذکور معتبرباشد باید حاضرین جلسه لااقل صاحب بیش از نصف سرمایه مجموع سهامی باشد که موضوع '
  'مذاکره\u200cاست.'),
 (74,
  'در مجامع عمومی که برای امتداد مدت شرکت یا برای انحلال شرکت قبل از موعد مقرر یا هر نوع تغییر دیگری در اساسنامه '
  'تشکیل\u200cمی\u200cشود باید عده از صاحبان سهام که بیش از سه ربع سرمایه شرکت را دارا باشند حاضر گردند. اگر در مجمع '
  'عمومی عده که سه ربع سرمایه شرکت را دارا باشند حاضر نشدند ممکن است مجمع عمومی جدیدی دعوت کرد مشروط بر اینکه '
  'لااقل\u200cیک ماه قبل از انعقاد مجمع دو دفعه متوالی به فاصله هشت روز به وسیله یکی از جراید محل (\u200cکه سالیانه '
  'از طرف وزارت عدلیه معین می\u200cشود) دستورجلسه قبل و نتیجه آن اعلان گردد. مجمع عمومی جدید وقتی قانونی است که '
  'صاحبان لااقل نصف سرمایه شرکت حاضر باشند اگر این حد نصاب حاصل نشد ممکن است با رعایت\u200cتشریفات فوق مجمع عمومی '
  'دیگری دعوت نمود این مجمع با حضور صاحبان لااقل ثلث سرمایه شرکت حق تصمیم خواهد داشت در هر یک از سه\u200cمجمع فوق '
  'تصمیمات به اکثریت دو ثلث آراء حاضر گرفته می\u200cشود. در این مجامع کلیه صاحبان سهام قطع نظر از عده سهام خود حق '
  'حضور و به نسبت هر یک سهم یک رأی دارند ولو اینکه اساسنامه برخلاف این مقررداشته باشد. هیچ مجمع عمومی تابعیت شرکت را '
  'نمی\u200cتواند تغییر بدهد. بر تعهدات صاحبان سهام با هیچ اکثریتی نمی\u200cتوان افزود.'),
 (75,
  'در مجمع عمومی ورقه حاضر و غائبی خواهد بود حاوی اسم و محل اقامت و عده سهام هر یک از شرکاء ورقه مزبور پس از '
  'تصدیق\u200cهیأت رییسه مجمع در مرکز شرکت حفظ و به هر کسی تقاضا نماید ارائه می\u200cشود.'),
 (76,
  'هر گاه شرکت بخواهد به موجب مقررات اساسنامه سهام بی\u200cاسم خود را به سهام بااسم تبدیل نماید باید اعلانی در این '
  'موضوع منتشرکرده و مهلتی که کمتر از شش ماه نباشد به صاحبان سهام بدهد تا در ظرف مهلت مزبور سهام خود را به سهام جدید '
  'تبدیل نمایند.'),
 (77,
  'اعلان مذکور در فوق باید در مجله رسمی عدلیه و در یکی از جراید کثیرالانتشار مرکز اصلی شرکت دو دفعه و به فاصله ده '
  'روز منتشرشود در صورتی که مرکز اصلی شرکت در خارج از تهران باشد باید در یکی از روزنامه\u200cهای یومیه تهران که '
  'همه\u200cساله از طرف وزارت عدلیه برای انتشاراین قبیل اعلانات معین می\u200cشود نیز منتشر گردد. ابتداء مهلت از '
  'تاریخ اولین انتشار اعلان در مجله رسمی خواهد بود.'),
 (78,
  'هر صاحب سهمی که سهام خود را تا انقضاء مهلت مذکور در ماده (۷۶) به سهام جدید تبدیل نکند دیگر نمی\u200cتواند تقاضای '
  'تبدیل نماید وشرکت حق خواهد داشت سهام جدیدی را که در ازاء سهام تبدیل نشده موجود می\u200cباشد به اشخاص دیگر به طریق '
  'مزایده بفروشد.'),
 (79,
  'قیمت سهامی که به طریق مذکور در فوق فروخته می\u200cشود در مرکز اصلی شرکت یا در بانک ملی ایران ودیعه گذاشته خواهد '
  'شد و هر گاه\u200cدر ظرف ده سال از تاریخ فروش سهام صاحب سهم سهام سابق خود را نداده و وجهی را که به طریق فوق امانت '
  'گذاشته شده\u200cاست مطالبه ننماید نسبت\u200cبه حق او مرور زمان حاصل شده و وجه مزبور در حکم اموال بلاصاحب بوده و '
  'مدیر شرکت مکلف است آن را به مقامات صلاحیتدار تسلیم نماید - هرمدیر شرکت که به این تکلیف عمل نکند به تأدیه سه برابر '
  'وجه مذکور محکوم خواهد شد.'),
 (80,
  'در صورتی که شرکت بخواهد سهام با اسم خود را به سهام بی\u200cاسم تبدیل نماید باید مراتب را به طریقی که فوقاً مقرر '
  'است یک مرتبه\u200cاعلان نماید و اگر در ظرف مهلتی که معین می\u200cشود و نباید کمتر از دو ماه باشد صاحبان سهام سهام '
  'بااسم خود را به سهام بی\u200cاسم تبدیل نکنند سهام\u200cبااسمی که در دست آنها باقی می\u200cماند باطل و سهام جدید '
  'در مرکز اصلی شرکت به اسم آنها ودیعه خواهد بود.'),
 (81,
  'در هر موقع که شرکت بخواهد تصدیق\u200cهای موقتی را که به اشخاص داده تبدیل به سهام کند در مورد تصدیقهای موقتی '
  'بی\u200cاسم مطابق\u200cمقررات مواد (۷۶) و (۷۷) و (۷۸) و (۷۹) و در مورد تصدیق موقتی با اسم مطابق ماده (۸۰) رفتار '
  'خواهد شد. ۷ - بطلان شرکت و یا بطلان اعمال و تصمیمات آن'),
 (82,
  'هر شرکت سهامی که مقررات یکی از مواد ۲۸ - ۲۹ - ۳۶ - ۳۷ - ۳۸ - ۳۹ - ۴۱ - ۴۴ - ۴۵ - ۴۶ - ۴۷ - ۵۰ این قانون را '
  'رعایت\u200cنکرده باشد از درجه اعتبار ساقط و بلااثر خواهد بود لیکن شرکاء نمی\u200cتوانند در مقابل اشخاص خارج به '
  'این بطلان استناد نمایند.'),
 (83,
  'در هر مورد که موافق مقررات ماده قبل محکمه بر بطلان شرکت یا اعمال و تصمیمات آن حکم کند مؤسسینی که مسئول این '
  'بطلان\u200cهستند و همچنین مفتشین و مدیرهایی که در حین حدوث سبب بطلان یا بلافاصله پس از آن سر کار بوده و انجام '
  'وظیفه نکرده\u200cاند متضامناً مسئول\u200cخساراتی خواهند بود که از این بطلان به صاحبان سهام و اشخاص ثالثی متوجه '
  'می\u200cشود همین مسئولیت ممکن است به شرکایی متوجه شود که سهم\u200cغیر نقدی آنها تقویم و تصویب نشده یا مزایایی که '
  'مطالبه کرده\u200cاند به تصدیق نرسیده باشد.'),
 (84,
  'هر گاه قبل از اقامه دعوی برای ابطال شرکت یا برای ابطال عملیات و قراردادهای شرکت موجبات بطلان مرتفع شود دعوای '
  'ابطال درمحکمه پذیرفته نخواهد شد.'),
 (85,
  'اگر از تاریخ رفع موجبات بطلان یک سال منقضی شده و اشخاص خارج از جهت معاملاتی که با ایشان شده\u200cاست به استناد '
  'اموری که\u200cموجب بطلان بوده دعوای خسارت نکرده باشند دیگر دعوی مزبور از آنها پذیرفته نمی\u200cشود.'),
 (86,
  'هر گاه مقرر شده باشد که مجمع عمومی مخصوصی برای رفع موجبات بطلان منعقد شود و دعوت اعضاء نیز برای انعقاد مجمع '
  'موافق\u200cاساسنامه به عمل آمده باشد دعوای بطلان از تاریخ دعوت مجمع در محکمه پذیرفته نخواهد شد مگر اینکه مجمع '
  'مزبور موجبات بطلان را رفع ننماید.'),
 (87,
  'هر گاه از تاریخ حدوث سبب بطلان شرکت ده سال گذشته و اقامه دعوی بطلان و خسارت نشده باشد دیگر دعوی مذکور '
  'پذیرفته\u200cنخواهد شد.'),
 (88,
  'استرداد منافعی که بین شرکاء تقسیم شده ممکن نیست مگر اینکه تقسیم بدون ترتیب صورت دارایی یا مخالف نتیجه حاصل از '
  'صورت\u200cمزبور به عمل آمده باشد در این صورت نیز فقط تا پنج سال اقامه دعوی استرداد می\u200cتوان نمود. مبدأ مرور '
  'زمان روز تقسیم منافع است. مقررات جزایی'),
 (89,
  'هر کس سهام یا قطعات سهام شرکتی را که در مورد آن یکی از مواد ۲۸ - ۲۹ - ۳۶ - ۳۷ - ۳۸ - ۳۹ - ۴۴ و ۵۰ این قانون رعایت '
  'نشده\u200cصادر نماید به پانصد الی ده هزار ریال جزای نقدی علاوه بر خسارات وارده به شرکت یا افراد محکوم خواهد شد. '
  'در مواردی که عمل مشمول ماده ۲۳۸\u200cقانون مجازات عمومی است مرتکب به مجازات مقرر در آن ماده نیز محکوم '
  'می\u200cشود.'),
 (90,
  'حکم فوق درباره اشخاصی نیز مقرر است که برخلاف واقع خود را صاحب سهام یا قطعات سهام قلمداد کرده و در مجمع عمومی '
  'واردشوند یا در دادن رأی شرکت نمایند و یا سهامی را برای اینکه به طور تقلب استعمال شود به دیگری بدهند. در مورد این '
  'ماده علاوه بر جزای نقدی\u200cمتخلف را می\u200cتوان به یک تا شش ماه حبس تأدیبی نیز محکوم نمود.'),
 (91,
  'هر کس سهام یا قطعات سهامی را که در مورد آنها مقررات یکی از مواد ۲۸ - ۲۹ - ۳۸ و ۳۹ رعایت نشده با علم به عدم رعایت '
  'قانون\u200cمعامله کرده یا شرکت در معامله داشته و یا قیمت آنها را اعلان نموده باشد به پانصد الی ده هزار ریال جزای '
  'نقدی محکوم خواهد شد. مقررات این ماده مانع نخواهد بود که اگر عمل مشمول ماده ۲۳۸ قانون مجازات عمومی باشد مرتکب به '
  'مجازات حبس مذکور در آن ماده نیز محکوم\u200cشود.'),
 (92,
  'اشخاص ذیل کلاهبردار محسوب می\u200cشوند: ۱ - هر کس برخلاف حقیقت مدعی وقوع تعهد ابتیاع سهام یا تأدیه قیمت سهام شده '
  'یا وقوع تعهد و یا تأدیه را که واقعیت ندارد اعلام یا جعلیاتی\u200cمنتشر کند که به این وسایل دیگری را وادار به تعهد '
  'خرید سهام یا تأدیه قیمت سهام نماید اعم از اینکه عملیات مذکور مؤثر شده یا نشده باشد. ۲ - هر کس به طور تقلب برای '
  'جلب تعهد یا پرداخت قیمت سهام اسم اشخاصی را برخلاف واقع به عنوانی از عناوین جزء شرکت قلمداد نماید. ۳ - مدیرهایی که '
  'با نبودن صورت دارایی یا به استناد صورت دارایی مزور منافع موهومی را بین صاحبان سهام تقسیم نموده باشند.'),
 (93, 'شرکت سهامی در موارد ذیل منحل می\u200cشود:'),
 (94,
  'شرکت با مسئولیت محدود شرکتی است که بین دو یا چند نفر برای امور تجارتی تشکیل شده و هر یک از شرکاء بدون اینکه '
  'سرمایه به\u200cسهام یا قطعات سهام تقسیم شده باشد - فقط تا میزان سرمایه خود در شرکت مسئول قروض و تعهدات شرکت است.'),
 (95,
  'در اسم شرکت باید عبارت (\u200cبا مسئولیت محدود) قید شود و الا آن شرکت در مقابل اشخاص ثالث شرکت تضامنی محسوب و '
  'تابع\u200cمقررات آن خواهد بود. اسم شرکت نباید متضمن اسم هیچ یک از شرکاء باشد و الا شریکی که اسم او در اسم شرکت '
  'قید شده در مقابل اشخاص ثالث حکم شریک ضامن درشرکت تضامنی را خواهد داشت.'),
 (96,
  'شرکت با مسئولیت محدود وقتی تشکیل می\u200cشود که تمام سرمایه نقدی تأدیه و سهم\u200cالشرکه غیر نقدی نیز تقویم و '
  'تسلیم شده باشد.'),
 (97,
  'در شرکتنامه باید صراحتاً قید شده باشد که سهم\u200cالشرکه\u200cهای غیر نقدی هر کدام به چه میزان تقویم '
  'شده\u200cاست.'),
 (98,
  'شرکاء نسبت به قیمتی که در حین تشکیل شرکت برای سهم\u200cالشرکه\u200cهای غیر نقدی معین شده در مقابل اشخاص ثالث '
  'مسئولیت تضامنی\u200cدارند.'),
 (99, 'مرور زمان دعاوی ناشی از مقررات فوق ده سال از تاریخ تشکیل شرکت است.'),
 (100,
  'هر شرکت با مسئولیت محدود که برخلاف مواد ۹۶ و ۹۷ تشکیل شده باشد باطل و از درجه اعتبار ساقط است لیکن شرکاء در '
  'مقابل\u200cاشخاص ثالث حق استناد به این بطلان ندارند.'),
 (101,
  'اگر حکم بطلان شرکت به استناد ماده قبل صادر شود شرکایی که بطلان مستند به عمل آنها است و هیأت نظار و مدیرهایی که در '
  'حین\u200cحدوث سبب بطلان یا بلافاصله پس از آن سر کار بوده و انجام وظیفه نکرده\u200cاند در مقابل شرکاء دیگر و اشخاص '
  'ثالث نسبت به خسارات ناشیه از این\u200cبطلان متضامناً مسئول خواهند بود. مدت مرور زمان ده سال از تاریخ حدوث موجب '
  'بطلان است.'),
 (102,
  'سهم\u200cالشرکه شرکاء نمی\u200cتواند به شکل اوراق تجارتی قابل انتقال اعم از بااسم یا بی\u200cاسم و غیره درآید. '
  'سهم\u200cالشرکه را نمی\u200cتوان منتقل به\u200cغیر نمود مگر با رضایت عده از شرکاء که لااقل سه ربع سرمایه متعلق به '
  'آنها بوده و اکثریت عددی نیز داشته باشند.'),
 (103, 'انتقال سهم\u200cالشرکه به عمل نخواهد آمد مگر به موجب سند رسمی.'),
 (104,
  'شرکت با مسئولیت محدود به وسیله یک یا چند نفر مدیر موظف یا غیر موظف که از بین شرکاء یا از خارج برای مدت محدود '
  'یانامحدودی معین می\u200cشوند اداره می\u200cگردد.'),
 (105,
  'مدیران شرکت کلیه اختیارات لازمه را برای نمایندگی و اداره شرکت خواهند داشت مگر اینکه در اساسنامه غیر این ترتیب '
  'مقرر شده\u200cباشد هر قرارداد راجع به محدود کردن اختیارات مدیران که در اساسنامه تصریح به آن نشده در مقابل اشخاص '
  'ثالث باطل و کان\u200cلم\u200cیکن است.'),
 (106,
  'تصمیمات راجعه به شرکت باید به اکثریت لااقل نصف سرمایه اتخاذ شود - اگر در دفعه اولی این اکثریت حاصل نشد باید تمام '
  'شرکاءمجدداً دعوت شوند در این صورت تصمیمات به اکثریت عددی شرکاء اتخاذ می\u200cشود اگر چه اکثریت مزبور دارای نصف '
  'سرمایه نباشد. اساسنامه شرکت\u200cمی\u200cتواند ترتیبی برخلاف مراتب فوق مقرر دارد.'),
 (107,
  'هر یک از شرکاء به نسبت سهمی که در شرکت دارد دارای رأی خواهد بود مگر اینکه اساسنامه به ترتیب دیگری مقرر داشته '
  'باشد.'),
 (108,
  'روابط بین شرکاء تابع اساسنامه\u200cاست - اگر در اساسنامه راجع به تقسیم نفع و ضرر مقررات خاصی نباشد تقسیم مزبور به '
  'نسبت سرمایه\u200cشرکاء به عمل خواهد آمد.'),
 (109,
  'هر شرکت با مسئولیت محدود که عده شرکاء آن بیش از دوازده نفر باشد باید دارای هیأت نظار بوده و هیأت مزبور لااقل سالی '
  'یک مرتبه\u200cمجمع عمومی شرکاء را تشکیل دهد. هیأت نظار باید بلافاصله بعد از انتخاب شدن تحقیق کرده و اطمینان حاصل '
  'کند که دستور مواد ۹۶ و ۹۷ رعایت شده\u200cاست. هیأت نظار می\u200cتواند شرکاء را برای انعقاد مجمع عمومی '
  'فوق\u200cالعاده دعوت نماید مقررات مواد ۱۶۵ - ۱۶۷ - ۱۶۸ و ۱۷۰ در مورد شرکتهای با مسئولیت\u200cمحدود نیز رعایت '
  'خواهد شد.'),
 (110, 'شرکاء نمی\u200cتوانند تبعیت شرکت را تغییر دهند مگر به اتفاق آراء.'),
 (111,
  'هر تغییر دیگری راجع به اساسنامه باید به اکثریت عددی شرکاء که لااقل سه ربع سرمایه را نیز دارا باشند به عمل آید مگر '
  'اینکه دراساسنامه اکثریت دیگری مقرر شده باشد.'),
 (112, 'در هیچ مورد اکثریت شرکاء نمی\u200cتواند شریکی را مجبور به ازدیاد سهم\u200cالشرکه خود کند.'),
 (113,
  'مفاد ماده ۷۸ این قانون راجع به تشکیل سرمایه احتیاطی در شرکتهای با مسئولیت محدود نیز لازم\u200cالرعایه\u200cاست.'),
 (114,
  'شرکت با مسئولیت محدود در موارد ذیل منحل می\u200cشود: الف) در مورد فقرات ۱ - ۲ - ۳ ماده ۹۳. ب) در صورت تصمیم عده '
  'از شرکاء که سهم\u200cالشرکه آنها بیش از نصف سرمایه شرکت باشد. ج) در صورتی که به واسطه ضررهای وارده نصف سرمایه '
  'شرکت از بین رفته و یکی از شرکاء تقاضای انحلال کرده و محکمه دلایل او را موجه\u200cدیده و سایر شرکاء حاضر نباشند '
  'سهمی را که در صورت انحلال به او تعلق می\u200cگیرد پرداخته و او را از شرکت خارج کنند. د) در مورد فوت یکی از شرکاء '
  'اگر به موجب اساسنامه پیش\u200cبینی شده باشد.'),
 (115,
  'اشخاص ذیل کلاهبردار محسوب می\u200cشوند: الف) مؤسسین و مدیرانی که برخلاف واقع پرداخت تمام سهم\u200cالشرکه نقدی و '
  'تقویم و تسلیم سهم\u200cالشرکه غیر نقدی را در اوراق و اسنادی که بایدبرای ثبت شرکت بدهند اظهار کرده باشند. ب) کسانی '
  'که به وسیله متقلبانه سهم\u200cالشرکه غیر نقدی را بیش از قیمت واقعی آن تقویم کرده باشند. ج) مدیرانی که با نبودن '
  'صورت دارایی یا با استناد صورت دارایی مزور منافع موهومی را بین شرکاء تقسیم کنند.'),
 (116,
  'شرکت تضامنی شرکتی است که در تحت اسم مخصوصی برای امور تجارتی بین دو یا چند نفر با مسئولیت تضامنی تشکیل '
  'می\u200cشود:اگر دارایی شرکت برای تأدیه تمام قروض کافی نباشد هر یک از شرکاء مسئول پرداخت تمام قروض شرکت است. هر '
  'قراری که بین شرکاء برخلاف این ترتیب داده شده باشد در مقابل اشخاص ثالث کان\u200cلم\u200cیکن خواهد بود.'),
 (117,
  'در اسم شرکت تضامنی باید عبارت (\u200cشرکت تضامنی) و لااقل اسم یک نفر شرکاء ذکر شود. در صورتی که اسم شرکت مشتمل بر '
  'اسامی تمام شرکاء نباشد باید بعد از اسم شریک یا شرکایی که ذکر شده\u200cاست عبارتی از قبیل (\u200cو شرکاء) یا '
  '(\u200cوبرادران) قید شود.'),
 (118,
  'شرکت تضامنی وقتی تشکیل می\u200cشود که تمام سرمایه نقدی تأدیه و سهم\u200cالشرکه غیر نقدی نیز تقویم و تسلیم شده '
  'باشد.'),
 (119,
  'در شرکت تضامنی منافع به نسبت سهم\u200cالشرکه بین شرکاء تقسیم می\u200cشود مگر آنکه شرکتنامه غیر از این ترتیب را '
  'مقرر داشته باشد.'),
 (120, 'در شرکت تضامنی شرکاء باید لااقل یک نفر از میان خود یا از خارج به سمت مدیری معین نمایند.'),
 (121, 'حدود مسئولیت مدیر یا مدیران شرکت تضامنی همان است که در ماده ۵۱ مقرر شده.'),
 (122,
  'در شرکتهای تضامنی اگر سهم\u200cالشرکه یک یا چند نفر غیر نقدی باشد باید سهم\u200cالشرکه مزبور قبلاً به تراضی تمام '
  'شرکاء تقویم شود.'),
 (123, 'در شرکت تضامنی هیچ یک از شرکاء نمی\u200cتواند سهم خود را به دیگری منتقل کند مگر به رضایت تمام شرکاء.'),
 (124,
  'مادام که شرکت تضامنی منحل نشده مطالبه قروض آن باید از خود شرکت به عمل آید و پس از انحلال طلبکاران شرکت '
  'می\u200cتوانند برای\u200cوصول مطالبات خود به هر یک از شرکاء که بخواهند و یا به تمام آنها رجوع کنند و در هر حال '
  'هیچ یک از شرکاء نمی\u200cتواند به استناد اینکه میزان قروض\u200cشرکت از میزان سهم او در شرکت تجاوز می\u200cنماید '
  'از تأدیه قروض شرکت امتناع ورزد فقط در روابط بین شرکاء مسئولیت هر یک از آنها در تأدیه قروض\u200cشرکت به نسبت '
  'سرمایه خواهد بود که در شرکت گذاشته\u200cاست آن هم در صورتی که در شرکتنامه ترتیب دیگری اتخاذ نشده باشد.'),
 (125,
  'هر کس به عنوان شریک ضامن در شرکت تضامنی موجودی داخل شود متضامناً با سایر شرکاء مسئول قروضی هم خواهد بود '
  'که\u200cشرکت قبل از ورود او داشته اعم از اینکه در اسم شرکت تغییری داده شده یا نشده باشد. هر قراری که بین شرکاء '
  'برخلاف این ترتیب داده شده باشد در مقابل اشخاص ثالث کان\u200cلم\u200cیکن خواهد بود.'),
 (126,
  'هر گاه شرکت تضامنی منحل شود مادام که قروض شرکت از دارایی آن تأدیه نشده هیچ یک از طلبکاران شخصی شرکاء حقی در '
  'آن\u200cدارایی نخواهد داشت اگر دارایی شرکت برای پرداخت قروض آن کفایت نکند طلبکاران شرکت حق دارند بقیه طلب خود را '
  'از تمام یا فرد فرد شرکاءضامن مطالبه کنند ولی در این مورد طلبکاران شرکت بر طلبکاران شخصی شرکاء حق تقدم نخواهند '
  'داشت.'),
 (127, 'به ورشکستگی شرکت تضامنی بعد از انحلال نیز می\u200cتوان حکم داد مشروط به اینکه دارایی شرکت تقسیم نشده باشد.'),
 (128,
  'ورشکستگی شرکت ملازمه قانونی با ورشکستگی شرکاء و ورشکستگی بعضی از شرکاء ملازمه قانونی با ورشکستگی شرکت ندارد.'),
 (129,
  'طلبکاران شخصی شرکاء حق ندارند طلب خود را از دارایی شرکت تأمین یا وصول کنند ولی می\u200cتوانند نسبت به سهمیه مدیون '
  'خود ازمنافع شرکت یا سهمی که در صورت انحلال شرکت ممکن است به مدیون مزبور تعلق گیرد هر اقدام قانونی که مقتضی باشد '
  'به عمل آورند. طلبکاران شخصی شرکاء در صورتی که نتوانسته باشند طلب خود را از دارایی شخصی مدیون خود وصول کنند و سهم '
  'مدیون از منافع شرکت کافی\u200cبرای تأدیه طلب آنها نباشد می\u200cتوانند انحلال شرکت را تقاضا نمایند (\u200cاعم از '
  'اینکه شرکت برای مدت محدود یا غیر محدود تشکیل شده باشد) مشروط\u200cبر اینکه لااقل شش ماه قبل قصد خود را به وسیله '
  'اظهارنامه رسمی به اطلاع شرکت رسانیده باشند در این صورت شرکت یا بعضی از شرکاء می\u200cتوانندمادام که حکم نهایی '
  'انحلال صادر نشده با تأدیه طلب دائنین مزبور تا حد دارایی مدیون در شرکت یا با جلب رضایت آنان به طریق دیگر از '
  'انحلال\u200cشرکت جلوگیری کنند.'),
 (130,
  'نه مدیون شرکت می\u200cتواند در مقابل طلبی که ممکن است از یکی از شرکاء داشته باشد استناد به تهاتر کند نه خود شریک '
  'می\u200cتواند درمقابل قرضی که ممکن است طلبکار او به شرکت داشته باشد به تهاتر استناد نماید معذالک کسی که طلبکار '
  'شرکت و مدیون به یکی از شرکاء بوده وپس از انحلال شرکت طلب او لاوصول مانده در مقابل آن شرکت حق استناد به تهاتر '
  'خواهد داشت.'),
 (131,
  'در صورت ورشکستگی یکی از شرکاء و همچنین در صورتی که یکی از طلبکاران شخصی یکی از شرکاء به موجب ماده ۱۲۹ '
  'انحلال\u200cشرکت را تقاضا کرده سایر شرکاء می\u200cتوانند سهمی آن شریک را از دارایی شرکت نقداً تأدیه کرده و او را '
  'از شرکت خارج کنند.'),
 (132,
  'اگر در نتیجه ضررهای وارده سهم\u200cالشرکه کم شود مادام که این کمبود جبران نشده تأدیه هر نوع منفعت به شرکاء ممنوع '
  'است.'),
 (133,
  'جز در مورد فوق هیچ یک از شرکاء را شرکت نمی\u200cتواند به تکمیل سرمایه که به علت ضررهای وارده کم شده\u200cاست ملزم '
  'کرده و یا او رامجبور نماید بیش از آنچه که در شرکتنامه مقرر شده\u200cاست به شرکت سرمایه دهد.'),
 (134,
  'هیچ شریکی نمی\u200cتواند بدون رضایت سایر شرکاء (\u200cبه حساب شخصی خود یا به حساب شخص ثالث) تجارتی از نوع تجارت '
  'شرکت\u200cنموده و یا به عنوان شریک ضامن یا شریک با مسئولیت محدود در شرکت دیگری که نظیر آن تجارت را دارد داخل '
  'شود.'),
 (135,
  'هر شرکت تضامنی می\u200cتواند با تصویب تمام شرکاء به شرکت سهامی مبدل گردد در این صورت رعایت تمام مقررات راجعه به '
  'شرکت\u200cسهامی حتمی است.'),
 (136,
  'شرکت تضامنی در موارد ذیل منحل می\u200cشود: الف) در مورد فقرات ۱ - ۲ - ۳ ماده ۹۳. ب) در صورت تراضی تمام شرکاء: ج) '
  'در صورتی که یکی از شرکاء به دلائلی انحلال شرکت را از محکمه تقاضا نماید و محکمه آن دلائل را موجه دانسته و حکم به '
  'انحلال بدهد. د) در صورت فسخ یکی از شرکاء مطابق ماده ۱۳۷. ه) در صورت ورشکستگی یکی از شرکاء مطابق ماده ۱۳۸. و) در '
  'صورت فوت یا محجوریت یکی از شرکاء مطابق مواد ۱۳۹ و ۱۴۰. تبصره - در مورد بند (ج) هر گاه دلائل انحلال منحصراً مربوط '
  'به شریک یا شرکاء معینی باشد محکمه می\u200cتواند به تقاضای سایر شرکاء به جای\u200cانحلال حکم اخراج آن شریک یا '
  'شرکای معین را بدهد.'),
 (137,
  'فسخ شرکت در صورتی ممکن است که در اساسنامه این حق از شرکاء سلب نشده و ناشی از قصد اضرار نباشد - تقاضای فسخ بایدشش '
  'ماه قبل از فسخ کتباً به شرکاء اعلام شود. اگر موافق اساسنامه باید سال به سال به حساب شرکت رسیدگی شود فسخ در موقع '
  'ختم محاسبه سالیانه به عمل می\u200cآید.'),
 (138,
  'در مورد ورشکستگی یکی از شرکاء انحلال وقتی صورت می\u200cگیرد که مدیر تصفیه کتباً تقاضای انحلال شرکت را نموده و از '
  'تقاضای\u200cمزبور شش ماه گذشته و شرکت مدیر تصفیه را از تقاضای انحلال منصرف نکرده باشد.'),
 (139,
  'در صورت فوت یکی از شرکاء بقاء شرکت موقوف به رضایت سایر شرکاء و قائم\u200cمقام متوفی خواهد بود - اگر سایر شرکاء به '
  'بقاء شرکت\u200cتصمیم نموده باشند قائم\u200cمقام متوفی باید در مدت یک ماه از تاریخ فوت رضایت یا عدم رضایت خود را '
  'راجع به بقاء شرکت کتباً اعلام نماید در صورتی\u200cکه قائم\u200cمقام متوفی رضایت خود را اعلام نمود نسبت به اعمال '
  'شرکت در مدت مزبور از نفع و ضرر شریک خواهد بود ولی در صورت اعلام عدم\u200cرضایت در منافع حاصله در مدت مذکور شریک '
  'بوده و نسبت به ضرر آن مدت سهیم نخواهد بود. سکوت تا انقضای یک ماه در حکم اعلام رضایت است.'),
 (140, 'در مورد محجوریت یکی از شرکاء مطابق مدلول ماده فوق عمل خواهد شد.'),
 (141,
  'شرکت مختلط غیر سهامی شرکتی است که برای امور تجارتی در تحت اسم مخصوصی بین یک یا چند نفر شریک ضامن و یک یا چندنفر '
  'شریک با مسئولیت محدود بدون انتشار سهام تشکیل می\u200cشود. شریک ضامن مسئول کلیه قروضی است که ممکن است علاوه بر '
  'دارایی شرکت پیدا شود - شریک با مسئولیت محدود کسی است که مسئولیت اوفقط تا میزان سرمایه\u200cاست که در شرکت گذارده '
  'و یا بایستی بگذارد. در اسم شرکت باید عبارت (\u200cشرکت مختلط) و لااقل اسم یکی از شرکاء ضامن قید شود.'),
 (142, 'روابط بین شرکاء با رعایت مقررات ذیل تابع شرکتنامه خواهد بود.'),
 (143,
  'هر یک از شرکاء با مسئولیت محدود که اسمش جزء اسم شرکت باشد در مقابل طلبکاران شرکت شریک ضامن محسوب خواهد شد. هر '
  'قراری که برخلاف این ترتیب بین شرکاء داده شده باشد در مقابل اشخاص ثالث بی\u200cاثر است.'),
 (144,
  'اداره شرکت مختلط غیر سهامی به عهده شریک یا شرکای ضامن و حدود اختیارات آنها همان است که در مورد شرکاء شرکت '
  'تضامنی\u200cمقرر است.'),
 (145, 'شریک با مسئولیت محدود نه به عنوان شریک حق اداره کردن شرکت را دارد نه اداره امور شرکت از وظایف او است.'),
 (146,
  'اگر شریک با مسئولیت محدود معامله برای شرکت کند - در مورد تعهدات ناشیه از آن معامله در مقابل طرف معامله حکم '
  'شریک\u200cضامن را خواهد داشت مگر اینکه تصریح کرده باشد معامله را به سمت وکالت از طرف شرکت انجام می\u200cدهد.'),
 (147,
  'هر شریک با مسئولیت محدود حق نظارت در امور شرکت داشته و می\u200cتواند از روی دفاتر اسناد شرکت برای اطلاع شخص خود '
  'راجع\u200cبه وضعیت مالی شرکت صورت خلاصه ترتیب دهد. هر قراردادی که بین شرکاء برخلاف این ترتیب داده شود از درجه '
  'اعتبار ساقط است.'),
 (148,
  'هیچ شریک با مسئولیت محدود نمی\u200cتواند بدون رضایت سایر شرکاء شخص ثالثی را با انتقال تمامی قسمتی از '
  'سهم\u200cالشرکه خود به اوداخل در شرکت کند.'),
 (149,
  'اگر یک یا چند نفر از شرکاء با مسئولیت محدود حق خود را در شرکت بدون اجازه سایرین کلاً یا بعضاً به شخص ثالثی واگذار '
  'نمایندشخص مزبور نه حق دخالت در اداره شرکت و نه حق تفتیش در امور شرکت را خواهد داشت.'),
 (150,
  'در مورد تعهداتی که شرکت مختلط غیر سهامی ممکن است قبل از ثبت شرکت کرده باشد شریک با مسئولیت محدود در '
  'مقابل\u200cاشخاص ثالث در حکم شریک ضامن خواهد بود مگر ثابت نماید که اشخاص مزبور از محدود بودن مسئولیت او اطلاع '
  'داشته\u200cاند.'),
 (151, 'شریک ضامن را وقتی می\u200cتوان شخصاً برای قروض شرکت تعقیب نمود که شرکت منحل شده باشد.'),
 (152,
  'هر گاه شرکت به طریقی غیر از ورشکستگی منحل شود و شریک با مسئولیت محدود هنوز تمام یا قسمتی از سهم\u200cالشرکه خود '
  'رانپرداخته و یا پس از تأدیه مسترد داشته\u200cاست طلبکاران شرکت حق دارند معادله آنچه که از بابت سهم\u200cالشرکه '
  'باقی مانده\u200cاست مستقیماً بر علیه شریک بامسئولیت محدود اقامه دعوی نمایند. اگر شرکت ورشکست شود حق مزبور را مدیر '
  'تصفیه خواهد داشت.'),
 (153,
  'اگر در نتیجه قرارداد با شرکاء ضامن و یا در اثر برداشت قبلی از سرمایه شرکت شریک با مسئولیت محدود از '
  'سهم\u200cالشرکه خود که به\u200cثبت رسیده\u200cاست بکاهد این تقلیل مادام که به ثبت نرسیده و بر طبق مقررات راجعه به '
  'نشر شرکت\u200cها منتشر نشده\u200cاست در مقابل طلبکاران شرکت معتبرنبوده و طلبکاران مزبور می\u200cتوانند برای '
  'تعهداتی که از طرف شرکت قبل از ثبت و انتشار تقلیل سرمایه به عمل آمده\u200cاست تأدیه همان سرمایه اولیه\u200cشریک با '
  'مسئولیت محدود را مطالبه نمایند.'),
 (154,
  'به شریک با مسئولیت محدود فرع نمی\u200cتوان داد مگر در صورتی که موجب کسر سرمایه او در شرکت نشود. اگر در نتیجه '
  'ضررهای وارده سهم\u200cالشرکه شریک با مسئولیت محدود کسر شد مادام که این کمبود جبران نشده تأدیه هر ربح یا منفعتی به '
  'او ممنوع است. هر گاه وجهی برخلاف حکم فوق تأدیه گردید شریک با مسئولیت محدود تا معادل وجه دریافتی مسئول تعهدات شرکت '
  'است مگر در موردی که باحسن نیت و به اعتبار بیلان مرتبی وجهی گرفته باشد.'),
 (155,
  'هر کس به عنوان شریک با مسئولیت محدود در شرکت مختلط غیر سهامی موجودی داخل شود تا معادل سهم\u200cالشرکه خود '
  'مسئول\u200cقروضی خواهد بود که شرکت قبل از ورود او داشته خواه اسم شرکت عوض شده یا نشده باشد. هر شرطی که برخلاف این '
  'ترتیب باشد در مقابل اشخاص ثالث کان\u200cلم\u200cیکن خواهد بود.'),
 (156,
  'اگر شرکت مختلط غیر سهامی ورشکست شود دارایی شرکت بین طلبکاران خود شرکت تقسیم شده و طلبکاران شخصی شرکاء در '
  'آن\u200cحقی ندارند - سهم\u200cالشرکه شرکاء با مسئولیت محدود نیز جزو دارایی شرکت محسوب است.'),
 (157,
  'اگر دارایی شرکت برای تأدیه تمام قروض آن کافی نباشد طلبکاران آن حق دارند بقیه طلب خود را از دارایی شخصی تمام یا هر '
  'یک ازشرکاء ضامن وصول کنند در این صورت بین طلبکاران شرکت و طلبکاران شخصی شرکاء ضامن تفاوتی نخواهد بود.'),
 (158,
  'در صورت ورشکستگی یکی از شرکاء با مسئولیت محدود خود شرکت یا طلبکاران آن با طلبکاران شریک مزبور '
  'متساوی\u200cالحقوق\u200cخواهند بود.'),
 (159, 'مقررات مواد ۱۲۹ و ۱۳۰ در شرکت\u200cهای مختلط غیر سهامی نیز لازم\u200cالرعایه\u200cاست.'),
 (160,
  'اگر شریک ضامن بیش از یک نفر باشد مسئولیت آنها در مقابل طلبکاران و روابط آنها با یکدیگر تابع مقررات راجع به '
  'شرکتهای تضامنی\u200cاست.'),
 (161,
  'مقررات مواد ۱۳۶ - ۱۳۷ - ۱۳۸ - ۱۳۹ و ۱۴۰ در مورد شرکت\u200cهای مختلط غیر سهامی نیز جاری است. مرگ یا محجوریت یا '
  'ورشکستگی شریک یا شرکاء با مسئولیت محدود موجب انحلال شرکت نمی\u200cشود.'),
 (162,
  'شرکت مختلط سهامی شرکتی است که در تحت اسم مخصوصی بین عده شرکاء سهامی و یک یا چند نفر شریک ضامن '
  'تشکیل\u200cمی\u200cشود. شرکاء سهامی کسانی هستند که سرمایه آنها به صورت سهام یا قطعات سهام متساوی\u200cالقیمه در '
  'آمده و مسئولیت آنها تا میزان همان سرمایه\u200cاست که درشرکت دارند. شریک ضامن کسی است که سرمایه او به صورت سهام در '
  'نیامده و مسئول کلیه قروضی است که ممکن است علاوه بر دارایی شرکت پیدا شود درصورت تعدد شریک ضامن مسئولیت آنها در '
  'مقابل طلبکاران و روابط آنها با یکدیگر تابع مقررات شرکت تضامنی خواهد بود.'),
 (163, 'در اسم شرکت باید عبارت (\u200cشرکت مختلط) و لااقل اسم یکی از شرکاء ضامن قید شود.'),
 (164, 'مدیریت شرکت مختلف سهامی مخصوص به شریک یا شرکاء ضامن است.'),
 (165,
  'در هر یک از شرکتهای مختلط سهامی هیأت نظاری لااقل مرکب از سه نفر از شرکاء برقرار می\u200cشود و این هیأت را مجمع '
  'عمومی شرکاءبلافاصله بعد از تشکیل قطعی شرکت و قبل از هر اقدامی در امور شرکت معین می\u200cکند انتخاب هیأت بر حسب '
  'شرایط مقرر در اساسنامه شرکت تجدیدمی\u200cشود در هر صورت اولین هیأت نظار برای یک سال انتخاب خواهد شد.'),
 (166,
  'اولین هیأت نظار باید بعد از انتخاب شدن بلافاصله تحقیق کرده و اطمینان حاصل کند که تمام مقررات مواد ۲۸ - ۲۹ - ۳۸ - '
  '۳۹ - ۴۱\u200cو ۵۰ این قانون رعایت شده\u200cاست.'),
 (167,
  'اعضاء هیأت نظار از جهت اعمال اداری و نتایج حاصله از آن هیچ مسئولیتی ندارند لیکن هر یک از آنها در انجام مأموریت '
  'خود بر طبق\u200cقوانین معموله مملکتی مسئول اعمال و تقصیرات خود می\u200cباشند.'),
 (168,
  'اعضاء هیأت نظار دفاتر و صندوق و کلیه اسناد شرکت را تحت تدقیق در آورده همه\u200cساله راپورتی به مجمع عمومی '
  'می\u200cدهند و هر گاه درتنظیم صورت دارایی بی\u200cترتیبی و خطایی مشاهده نمایند در راپورت مزبور ذکر نموده و اگر '
  'مخالفتی با پیشنهاد مدیر شرکت در تقسیم منافع داشته باشنددلائل خود را بیان می\u200cکنند.'),
 (169,
  'هیأت نظار می\u200cتواند شرکاء را برای انعقاد مجمع عمومی دعوت نماید و با موافقت رأی مجمع مزبور بر طبق فقره (ب) '
  'ماده ۱۸۱ شرکت\u200cرا منحل کند.'),
 (170,
  'تا پانزده روز قبل از انعقاد مجمع عمومی هر صاحب سهمی می\u200cتواند (\u200cخود یا نماینده او) در مرکز اصلی شرکت '
  'حاضر شده از صورت\u200cبیلان و صورت دارایی و راپورت هیأت نظار اطلاع حاضر کند.'),
 (171, 'ورشکستگی هیچ یک از شرکاء ضامن موجب انحلال شرکت نخواهد شد مگر در مورد ماده ۱۳۸.'),
 (172, 'حکم مواد ۱۲۴ و ۱۳۴ در مورد شرکت مختلط سهامی و شرکاء ضامن آن جاری است.'),
 (173,
  'هر گاه شرکت مختلط سهامی ورشکست شود شرکاء سهامی تمام قیمت سهام خود را نپرداخته باشند مدیر تصفیه آنچه را که بر '
  'عهده\u200cآنها باقی است وصول می\u200cکند.'),
 (174,
  'اگر شرکت به طریقی غیر از ورشکستگی منحل شد هر یک از طلبکاران شرکت می\u200cتواند به هر یک از شرکاء سهامی که از بابت '
  'قیمت\u200cسهام خود مدیون شرکت است رجوع کرده در حدود بدهی آن شریک طلب خود را مطالبه نماید مادام که شرکت منحل نشده '
  'طلبکاران برای وصول\u200cطلب خود حق رجوع به هیچ یک از شرکاء سهامی ندارند.'),
 (175,
  'اگر شرکت مختلط ورشکست شد تا قروض شرکت از دارایی آن تأدیه نشده طلبکاران شخصی شرکاء ضامن حقی به دارایی '
  'شرکت\u200cندارند.'),
 (176, 'مفاد مواد ۲۸ - ۲۹ - ۳۸ - ۳۹ - ۴۱ و ۵۰ شامل شرکتهای مختلط سهامی است.'),
 (177,
  'هر شرکت مختلط سهامی که برخلاف مواد ۲۸ - ۲۹ - ۳۹ و ۵۰ تشکیل شود باطل است لیکن شرکاء نمی\u200cتوانند در مقابل '
  'اشخاص\u200cخارج به این بطلان استناد نمایند.'),
 (178, 'هر گاه شرکت بر حسب ماده قبل محکوم به بطلان شود مطابق ماده ۱۰۱ رفتار خواهد شد.'),
 (179, 'مفاد مواد ۸۴ - ۸۵ - ۸۶ - ۸۷ این قانون در شرکتهای مختلط نیز باید رعایت شود.'),
 (180, 'مفاد مواد ۸۹ - ۹۰ - ۹۱ و ۹۲ این قانون در مورد شرکت مختلط نیز لازم\u200cالرعایه\u200cاست.'),
 (181,
  'شرکت مختلط در موارد ذیل منحل می\u200cشود: الف) در مورد فقرات ۱ - ۲ - ۳ ماده ۹۳. ب) بر حسب تصمیم مجمع عمومی در '
  'صورتی که در اساسنامه این حق برای مجمع مذکور تصریح شده باشد. ج) بر حسب تصمیم مجمع عمومی و رضایت شرکاء ضامن.'),
 (182,
  'هر گاه در اساسنامه برای مجمع عمومی حق تصمیم به انحلال معین نشده و بین مجمع عمومی و شرکاء ضامن راجع به انحلال '
  'موافقت\u200cحاصل نشود و محکمه دلائل طرفداران انحلال را موجه بیند حکم به انحلال خواهد داد. همین حکم در موردی نیز '
  'جاری است که یکی از شرکاء ضامن\u200cبه دلائلی انحلال شرکت را از محکمه تقاضا نموده و محکمه آن دلائل را موجه ببیند.'),
 (183,
  'شرکت نسبی شرکتی است که برای امور تجارتی در تحت اسم مخصوصی بین دو یا چند نفر تشکیل و مسئولیت هر یک از شرکاء '
  'به\u200cنسبت سرمایه\u200cای است که در شرکت گذاشته.'),
 (184,
  'در اسم شرکت نسبی عبارت (\u200cشرکت نسبی) و لااقل اسم یک نفر از شرکاء باید ذکر شود - در صورتی که اسم شرکت مشتمل بر '
  'اسامی\u200cتمام شرکاء نباشد بعد از اسم شریک یا شرکایی که ذکر شده عبارتی از قبیل (\u200cو شرکاء) (\u200cو برادران) '
  'ضروری است.'),
 (185, 'دستور ماده ۱۱۸ - ۱۱۹ - ۱۲۰ - ۱۲۱ - ۱۲۲ - ۱۲۳ در مورد شرکت نسبی نیز لازم\u200cالرعایه\u200cاست.'),
 (186,
  'اگر دارایی شرکت نسبی برای تأدیه تمام قروض شرکت کافی نباشد هر یک از شرکاء به نسبت سرمایه که در شرکت داشته مسئول '
  'تأدیه\u200cقروض شرکت است.'),
 (187,
  'مادام که شرکت نسبی منحل نشده مطالبه قروض آن باید از خود شرکت به عمل آید فقط پس از انحلال طلبکاران می\u200cتوانند '
  'با رعایت\u200cماده فوق به فرد فرد شرکاء مراجعه کنند.'),
 (188,
  'هر کس به عنوان شریک ضامن در شرکت نسبی موجودی داخل شود به نسبت سرمایه که در شرکت می\u200cگذارد مسئول قروضی '
  'هم\u200cخواهد بود که شرکت قبل از ورود او داشته اعم از اینکه در اسم شرکت تغییری داده شده یا نشده باشد. قرار شرکاء '
  'برخلاف این ترتیب نسبت به اشخاص ثالث اثر ندارد.'),
 (189,
  'مفاد ماده ۱۲۶ (\u200cجز مسئولیت شرکاء که به نسبت سرمایه آنها است) و مواد ۱۲۷ تا ۱۳۶ در شرکتهای نسبی نیز جاری '
  'است.'),
 (190,
  'شرکت تعاونی تولید شرکتی است که بین عده از ارباب حرف تشکیل می\u200cشود و شرکاء مشاغل خود را برای تولید و فروش '
  'اشیاء یااجناس به کار می\u200cبرند.'),
 (191,
  'اگر در شرکت تولید یک عده از شرکاء در خدمت دائمی شرکت نبوده یا از اهل حرفه که موضوع عملیات شرکت است نباشند لااقل '
  'دوثلث اعضاء اداره\u200cکننده شرکت باید از شرکایی انتخاب شوند که حرفه آنها موضوع عملیات شرکت است.'),
 (192,
  'شرکت تعاونی مصرف شرکتی است که برای مقاصد ذیل تشکیل می\u200cشود: ۱ - فروش اجناس لازمه برای مصارف زندگانی اعم از '
  'اینکه اجناس مزبوره را شرکاء ایجاد کرده یا خریده باشند.'),
 (193,
  'شرکت تعاونی اعم از تولید یا مصرف ممکن است مطابق اصول شرکت سهامی یا بر طبق مقررات مخصوصی که با تراضی شرکاءترتیب '
  'داده شده باشد تشکیل بشود ولی در هر حال مفاد مواد ۳۲ - ۳۳ لازم\u200cالرعایه\u200cاست.'),
 (194,
  'در صورتی که شرکت تعاونی تولید یا مصرف مطابق اصول شرکت سهامی تشکیل شود حداقل سهام یا قطعات سهام ده ریال خواهد بودو '
  'هیچ یک از شرکاء نمی\u200cتوانند در مجمع عمومی بیش از یک رأی داشته باشد.'),
 (195, 'ثبت کلیه شرکتهای مذکور در این قانون الزامی و تابع جمیع مقررات قانون ثبت شرکتها است.'),
 (196, 'اسناد و نوشتجاتی که برای به ثبت رساندن شرکت لازم است در نظامنامه وزارت عدلیه معین می\u200cشود.'),
 (197, 'در ظرف ماه اول تشکیل هر شرکت خلاصه شرکتنامه و منضمات آن طبق نظامنامه وزارت عدلیه اعلان خواهد شد.'),
 (198,
  'اگر به علت عدم رعایت دستور دو ماده فوق بطلان عملیات شرکت اعلام شده هیچ یک از شرکاء نمی\u200cتوانند این بطلان را '
  'در مقابل\u200cاشخاص ثالثی که با آنها معامله کرده\u200cاند عذر قرار دهند.'),
 (199,
  'هر گاه شرکت در چندین حوزه شعبه داشته باشد مقررات مواد ۱۹۵ و ۱۹۷ باید به قسمی که در نظامنامه وزارت عدلیه معین '
  'می\u200cشود درهر حوزه جداگانه انجام گردد.'),
 (200,
  'در هر موقع که تصمیماتی برای تغییر اساسنامه شرکت یا تمدید مدت شرکت زائد بر مدت مقرر یا انحلال شرکت (\u200cحتی در '
  'مواردی که\u200cانحلال به واسطه انقضای مدت شرکت صورت می\u200cگیرد) و تعیین کیفیت تفریغ حساب یا تبدیل شرکاء یا خروج '
  'بعضی از آنها از شرکت یا تغییر اسم\u200cشرکت اتخاذ شود مقررات مواد ۱۹۵ و ۱۹۷ لازم\u200cالرعایه\u200cاست. همین '
  'ترتیب در موقع هر تصمیمی که نسبت به مورد معین در ماده ۷۹ این قانون اتخاذمی\u200cشود رعایت خواهد شد.'),
 (201,
  'در هر گونه اسناد و صورت\u200cحسابها و اعلانات و نشریات و غیره که به طور خطی یا چاپی از طرف شرکت\u200cهای مذکور در '
  'این قانون به\u200cاستثنای شرکتهای تعاونی صادر می\u200cشود سرمایه شرکت صریحاً باید ذکر گردد و اگر تمام سرمایه '
  'پرداخته نشده قسمتی که پرداخته شده نیز باید صریحاً\u200cمعین شود - شرکت متخلف به جزای نقدی از دویست تا سه هزار '
  'ریال محکوم خواهد شد. تبصره - شرکتهای خارجی نیز که به وسیله شعبه یا نماینده در ایران اشتغال به تجارت دارند در مورد '
  'اسناد و صورت\u200cحسابها و اعلانات و نشریات\u200cخود در ایران مشمول مقررات این ماده خواهند بود.'),
 (202,
  'تصفیه امور شرکتها پس از انحلال موافق مواد ذیل خواهد بود مگر در مورد ورشکستگی که تابع مقررات مربوط به ورشکستگی '
  'است.'),
 (203,
  'در شرکت\u200cهای تضامنی و نسبی و مختلط سهامی و غیر سهامی امر تصفیه با مدیر یا مدیران شرکت است مگر آن که شرکاء '
  'ضامن\u200cاشخاص دیگری را از خارج یا از بین خود برای تصفیه معین نمایند.'),
 (204,
  'اگر از طرف یک یا چند شریک ضامن تعیین اشخاص مخصوص برای تصفیه تقاضا شد و سایر شرکاء ضامن آن تقاضا را نپذیرفتندمحکمه '
  'بدایت اشخاصی را برای تصفیه معین خواهد کرد.'),
 (205,
  'در هر مورد که اشخاصی غیر از مدیران شرکت برای تصفیه معین شوند اسامی آنها باید در اداره ثبت اسناد ثبت و اعلان '
  'گردد.'),
 (206,
  'در شرکتهای مختلط (\u200cسهامی و غیر سهامی) شرکاء غیر ضامن حق دارند یک یا چند نفر برای نظارت در امر تصفیه معین '
  'نمایند.'),
 (207,
  'وظیفه متصدیان تصفیه خاتمه دادن به کارهای جاری و اجرای تعهدات و وصول مطالبات و تقسیم دارایی شرکت است به ترتیب '
  'مقرردر مواد ۲۰۸ - ۲۰۹ - ۲۱۰ - ۲۱۱ و ۲۱۲.'),
 (208, 'اگر برای اجرای تعهدات شرکت معاملات جدیدی لازم شود متصدیان تصفیه انجام خواهند داد.'),
 (209, 'متصدیان تصفیه حق دارند شخصاً یا به توسط وکیل از طرف شرکت محاکمه کنند.'),
 (210,
  'متصدی تصفیه وقتی حق اصلاح و تعیین حکم دارد که شرکاء ضامن به او اجازه داده باشند - مواردی که به حکم قانون '
  'حکمیت\u200cاجباری است از این قاعده مستثنی است.'),
 (211,
  'آن قسمت از دارایی شرکت که در مدت تصفیه محل احتیاج نیست به طور موقت بین شرکاء تقسیم می\u200cشود ولی متصدیان تصفیه '
  'بایدمعادل قروضی که هنوز موعد تأدیه آن نرسیده\u200cاست و همچنین معادل مبلغی که در حساب بین شرکاء مورد اختلاف است '
  'موضوع نمایند.'),
 (212,
  'متصدیان تصفیه حساب شرکاء را نسبت به هم و سهم هر یک از شرکاء را از نفع و ضرر معین می\u200cکنند - رفع اختلاف در '
  'تقسیم به\u200cمحکمه بدایت رجوع می\u200cشود.'),
 (213,
  'در شرکتهای سهامی و شرکتهای با مسئولیت محدود و شرکتهای تعاونی امر تصفیه به عهده مدیران شرکت است مگر آنکه اساسنامه '
  'یااکثریت مجمع عمومی شرکت ترتیب دیگری مقرر داشته باشد.'),
 (214,
  'وظیفه و اختیارات متصدیان تصفیه در شرکت سهامی و شرکتهای با مسئولیت محدود و تعاونی به ترتیبی است که در ماده ۲۰۷ '
  'مقررشده با این تفاوت که حق اصلاح و تعیین حکم برای متصدیان تصفیه این شرکتها (\u200cبه استثنای مورد حکمیت اجباری) '
  'فقط وقتی خواهد بود که\u200cاساسنامه یا مجمع عمومی این حق را به آنها داده باشد.'),
 (215,
  'تقسیم دارایی شرکتهای مذکور در ماده فوق بین شرکاء خواه در ضمن مدت تصفیه و خواه پس از ختم آن ممکن نیست مگر آن که '
  'قبلاً\u200cسه مرتبه در مجله رسمی و یکی از جراید اعلان و یک سال از تاریخ انتشار اولین اعلان در مجله گذشته باشد.'),
 (216, 'تخلف از ماده قبل متصدیان تصفیه را مسئول خسارت طلبکارانی قرار خواهد داد که به طلب خود نرسیده\u200cاند.'),
 (217,
  'دفاتر هر شرکتی که منحل شده با نظر مدیر ثبت اسناد در محل معینی از تاریخ ختم تصفیه تا ده سال محفوظ خواهد ماند.'),
 (218,
  'هر شرکتی مجاز است در اساسنامه خود برای تصفیه ترتیب دیگری مقرر دارد ولی در هر حال آن مقررات نباید مخالف مواد ۲۰۷ '
  '-۲۰۸ - ۲۰۹ - ۲۱۰ - ۲۱۵ - ۲۱۶ - ۲۱۷ و قسمت اخیر ماده ۲۱۱ باشد.'),
 (219,
  'مدت مرور زمان در دعاوی اشخاص ثالث بر علیه شرکاء یا وراث آنها راجع به معاملات شرکت (\u200cدر مواردی که قانون شرکاء '
  'یا وراث آنهارا مسئول قرار داده) پنج سال است. مبدأ مرور زمان روزی است که انحلال شرکت یا کناره\u200cگیری شریک یا '
  'اخراج او از شرکت در اداره ثبت به ثبت رسیده و در مجله رسمی اعلان شده باشد. در صورتی که طلب پس از ثبت و اعلان قابل '
  'مطالبه شده باشد مرور زمان از روزی شروع می\u200cشود که طلبکار حق مطالبه پیدا کرده. تبصره - دعوایی که سنخاً تابع '
  'مرور زمان کوتاه\u200cتری بوده یا به موجب این قانون مرور زمان طولانی\u200cتری برای آن معین شده از مقررات این '
  'ماده\u200cمستثنی است.'),
 (220,
  'هر شرکت ایرانی که فعلاً وجود داشته یا در آتیه تشکیل شود و با اشتغال به امور تجارتی خود را به صورت یکی از شرکتهای '
  'مذکور دراین قانون در نیاورده و مطابق مقررات مربوطه به آن شرکت عمل ننماید شرکت تضامنی محسوب شده و احکام راجع به '
  'شرکتهای تضامنی در مورد آن\u200cاجرا می\u200cگردد. هر شرکت تجارتی ایرانی مذکور در این قانون و هر شرکت خارجی که بر '
  'طبق قانون ثبت شرکتها مصوب خرداد ماه ۱۳۱۰ مکلف به ثبت است باید درکلیه اسناد و صورت\u200cحسابها و اعلانات و نشریات '
  'خطی یا چاپی خود در ایران تصریح نماید که در تحت چه نمره در ایران به ثبت رسیده و الا محکوم به\u200cجزای نقدی از '
  'دویست تا دو هزار ریال خواهد شد - این مجازات علاوه بر مجازاتی است که در قانون ثبت شرکتها برای عدم ثبت مقرر شده.'),
 (221,
  'اگر شرکت سهام یا اوراق استقراضی داشته باشد که مطابق اساسنامه شرکت یا تصمیم مجمع عمومی قیمت آنها به طریق قرعه باید '
  'تأدیه\u200cشود و قبل از تأدیه قیمت آن سهام یا اوراق منافعی که به آنها تعلق گرفته پرداخته شده باشد شرکت در موقع '
  'تأدیه اصل قیمت نمی\u200cتواند منافع تأدیه شده\u200cرا استرداد نماید.'),
 (222,
  'هر شرکت تجارتی می\u200cتواند در اساسنامه خود قید کند که سرمایه اولیه خود را به وسیله تأدیه اقساط بعدی از طرف '
  'شرکاء یا قبول\u200cشریک جدید زیاد کرده و یا به واسطه برداشت از سرمایه آن را تقلیل دهد. در اساسنامه حداقلی که تا '
  'آن میزان می\u200cتوان سرمایه اولیه را تقلیل داد صراحتاً معین می\u200cشود. کمتر از عشر سرمایه اولیه شرکت را حداقل '
  'قرار دادن ممنوع است.'),
 (223,
  'برات علاوه بر امضاء یا مهر برات\u200cدهنده باید دارای شرایط ذیل باشد: ۱) قید کلمه (\u200cبرات) در روی ورقه. ۲) '
  'تاریخ تحریر (\u200cروز و ماه و سال). ۳) اسم شخصی که باید برات را تأدیه کند. ۴) تعیین مبلغ برات. ۵) تاریخ تأدیه '
  'وجه برات. ۶) مکان تأدیه وجه برات اعم از اینکه محل اقامت محال\u200cعلیه باشد یا محل دیگر. ۷) اسم شخصی که برات در '
  'وجه یا حواله\u200cکرد او پرداخته می\u200cشود. ۸) تصریح به اینکه نسخه اول یا دوم یا سوم یا چهارم الخ است.'),
 (224, 'برات ممکن است به حواله\u200cکرد شخص دیگر باشد یا به حواله\u200cکرد خود برات\u200cدهنده.'),
 (225,
  'تاریخ تحریر و مبلغ برات با تمام حروف نوشته می\u200cشود. اگر مبلغ بیش از یک دفعه به تمام حروف نوشته شده و بین آنها '
  'اختلاف باشد مبلغ کمتر مناط اعتبار است اگر مبلغ با حروف و رقم هر دو نوشته شده وبین آنها اختلاف باشد مبلغ با حروف '
  'معتبر است.'),
 (226,
  'در صورتی که برات متضمن یکی از شرایط اساسی مقرر در فقرات ۲ - ۳ - ۴ - 5 - 6 - 7 و 8 [m]\u200cماده ۲۲۳ نباشد مشمول '
  'مقررات\u200cراجعه به بروات تجارتی نخواهد بود.'),
 (227, 'برات ممکن است به دستور و حساب شخص دیگری صادر شود.'),
 (228,
  'قبولی برات در خود برات با قید تاریخ نوشته شده امضاء یا مهر می\u200cشود. در صورتی که برات به وعده از رؤیت باشد '
  'تاریخ قبولی با تمام حروف نوشته خواهد شد - اگر قبولی بدون تاریخ نوشته شد تاریخ برات تاریخ رؤیت\u200cحساب '
  'می\u200cشود.'),
 (229,
  'هر عبارتی که محال\u200cعلیه در برات نوشته امضاء یا مهر کند قبولی محسوب است مگر اینکه صریحاً عبارت مشعر بر عدم '
  'قبول باشد. اگر عبارت فقط مشعر بر عدم قبول یک جزء از برات باشد بقیه وجه برات قبول شده محسوب است. در صورتی که '
  'محال\u200cعلیه بدون تحریر هیچ عبارتی برات را امضاء یا مهر نماید برات قبول شده محسوب می\u200cشود.'),
 (230, 'قبول\u200cکننده برات ملزم است وجه آن را سر وعده تأدیه نماید.'),
 (231, 'قبول\u200cکننده حق نکول ندارد.'),
 (232, 'ممکن است قبولی منحصر به یک قسمت از وجه برات باشد در این صورت دارنده برات باید برای بقیه اعتراض نماید.'),
 (233,
  'اگر قبولی مشروط به شرط نوشته شد برات نکول شده محسوب می\u200cشود ولی معهذا قبول\u200cکننده به شرط در حدود شرطی که '
  'نوشته\u200cمسئول پرداخت وجه برات است.'),
 (234, 'در قبولی براتی که وجه آن در خارج از محل اقامت قبول\u200cکننده باید تأدیه شود تصریح به مکان تأدیه ضروری است.'),
 (235, 'برات باید به محض ارائه یا منتهی در ظرف ۲۴ ساعت از تاریخ ارائه قبول یا نکول شود.'),
 (236,
  'نکول برات باید به موجب تصدیقنامه که رسماً تنظیم می\u200cشود محقق گردد - تصدیقنامه مزبور موسم است به اعتراض '
  '(\u200cپروتست)\u200cنکول.'),
 (237,
  'پس از اعتراض نکول ظهرنویسها و برات\u200cدهنده به تقاضای دارنده برات باید ضامنی برای تأدیه وجه آن در سر وعده بدهند '
  'یا وجه برات\u200cرا به انضمام مخارج اعتراضنامه و مخارج برات رجوعی (\u200cاگر باشد) فوراً تأدیه نمایند.'),
 (238,
  'اگر بر علیه کسی که براتی قبول کرده ولی وجه آن را نپرداخته اعتراض عدم تأدیه شود دارنده براتی نیز که همان شخص قبول '
  'کرده ولی\u200cهنوز موعد پرداخت آن نرسیده\u200cاست می\u200cتواند از قبول\u200cکننده تقاضا نماید که برای پرداخت وجه '
  'آن ضامن دهد یا پرداخت آن را به نحو دیگری تضمین\u200cکند.'),
 (239,
  'هر گاه براتی نکول شد و اعتراض به عمل آمد شخص ثالثی می\u200cتواند آن را به برات\u200cدهنده یا یکی از ظهرنویسها '
  'قبول کند - قبولی\u200cشخص ثالث باید در اعتراضنامه قید شده به امضاء او برسد.'),
 (240,
  'بعد از قبولی شخص ثالث نیز تا برات تأدیه نشده کلیه حقوقی که برای دارنده برات از نکول آن در مقابل برات\u200cدهنده و '
  'ظهرنویس\u200cهاحاصل می\u200cشود محفوظ خواهد بود.'),
 (241,
  'برات ممکن است به رویت باشد یا به وعده یک یا چند روز یا یک یا چند ماه از رؤیت برات یا به وعده یک یا چند روز یا یک '
  'یا چند ماه\u200cاز تاریخ برات - ممکن است پرداخت به روز معینی موکول شده باشد.'),
 (242, 'هر گاه برات بی\u200cوعده قبول شد باید فوراً پرداخته شود.'),
 (243,
  'موعد پرداخت براتی که یک یا چند روز یا یک یا چند ماه از رؤیت وعده دارد به وسیله تاریخ قبولی یا تاریخ اعتراضنامه '
  'نکول معین\u200cمی\u200cشود.'),
 (244,
  'اگر موعد پرداخت برات با تعطیل رسمی تصادف کرد باید روز بعد تعطیل تأدیه شود. تبصره - همین قاعده در مورد سایر اوراق '
  'تجارتی نیز رعایت خواهد شد.'),
 (245, 'انتقال برات به وسیله ظهرنویسی به عمل می\u200cآید.'),
 (246,
  'ظهرنویسی باید به امضاء ظهرنویس برسد - ممکن است در ظهرنویسی تاریخ و اسم کسی که برات به او انتقال داده می\u200cشود '
  'قید گردد.'),
 (247,
  'ظهرنویسی حاکی از انتقال برات است مگر اینکه ظهرنویسی وکالت در وصول را قید نموده باشد که در این صورت انتقال برات '
  'واقع\u200cنشده ولی دارنده برات حق وصول و لدی\u200cالاقتضاء حق اعتراض و اقامه دعوی برای وصول خواهد داشت. جز در '
  'مواردی که خلاف این در برات تصریح\u200cشده باشد.'),
 (248, 'هر گاه ظهرنویس در ظهرنویسی تاریخ مقدمی قید کند مزور شناخته می\u200cشود.'),
 (249,
  'برات\u200cدهنده - کسی که برات را قبول کرده و ظهرنویسها در مقابل دارنده برات مسئولیت تضامنی دارند. دارنده برات در '
  'صورت عدم تأدیه و اعتراض می\u200cتواند به هر کدام از آنها که بخواهد منفرداً یا به چند نفر یا به تمام آنها مجتمعاً '
  'رجوع نماید. همین حق را هر یک از ظهرنویسها نسبت به برات\u200cدهنده و ظهرنویسهای ماقبل خود دارد. اقامه دعوی بر علیه '
  'یک یا چند نفر از مسئولین موجب اسقاط حق رجوع به سایر مسئولیت برات نیست - اقامه\u200cکننده دعوی ملزم نیست '
  'ترتیب\u200cظهرنویسی را از حیث تاریخ رعایت کند. ضامنی که ضمانت برات\u200cدهنده یا محال\u200cعلیه یا ظهرنویسی را '
  'کرده فقط با کسی مسئولیت تضامنی دارد که از او ضمانت نموده\u200cاست.'),
 (250,
  'هر یک از مسئولین تأدیه برات می\u200cتواند پرداخت را به تسلیم برات و اعتراضنامه و صورت\u200cحساب متفرعات و مخارج '
  'قانونی که بایدبپردازد موکول کند.'),
 (251,
  'هر گاه چند نفر از مسئولین برات ورشکست شوند دارنده برات می\u200cتواند در هر یک از غرما یا در تمام غرما برای وصول '
  'تمام طلب خود(\u200cوجه برات و متفرعات و مخارج قانونی) داخل شود تا اینکه طلب خود را کاملاً وصول نماید - مدیر تصفیه '
  'هیچ یک از ورشکستگان نمی\u200cتواند برای\u200cوجهی که به صاحب چنین طلب پرداخته می\u200cشود به مدیر تصفیه ورشکسته '
  'دیگر رجوع نماید مگر در صورتی که مجموع وجوهی که از دارایی تمام\u200cورشکستگان به صاحب طلب تخصیص می\u200cیابد بیش '
  'از میزان طلب او باشد در این صورت مازاد باید به ترتیب تاریخ تعهد تا میزان وجهی که هر کدام\u200cپرداخته\u200cاند - '
  'جزء دارایی ورشکستگان محسوب گردد که به سایر ورشکسته\u200cها حق رجوع دارند. تبصره - مفاد این ماده در مورد ورشکستگی '
  'هر چند نفری نیز که برای پرداخت یک دین مسئولیت تضامنی داشته باشند مرعی خواهد بود.'),
 (252, 'پرداخت برات به انواع پولی که در آن معین شده به عمل می\u200cآید.'),
 (253,
  'اگر دارنده برات به برات\u200cدهنده یا کسی که برات را به او منتقل کرده\u200cاست پولی غیر از آن نوع که در برات معین '
  'شده\u200cاست بدهد و آن برات\u200cدر نتیجه نکول یا امتناع از قبول یا عدم تأدیه اعتراض شود دارنده برات '
  'می\u200cتواند از دهنده برات یا انتقال\u200cدهنده نوع پولی را که داده یا نوع پولی که دربرات معین شده مطالبه کند '
  'ولی از سایر مسئولین وجه برات جز نوع پولی که در برات معین شده قابل مطالبه نیست.'),
 (254, 'برات به وعده باید روز آخر وعده پرداخته شود.'),
 (255,
  'روز رؤیت در برواتی که به وعده از رؤیت است و روز صدور برات در برواتی که به وعده از تاریخ صدور است حساب نخواهد شد.'),
 (256, 'شخصی که وجه برات را قبل از موعد تأدیه نموده در مقابل اشخاصی که نسبت به وجه برات حقی دارند مسئول است.'),
 (257,
  'اگر دارنده برات به کسی که قبولی نوشته مهلتی برای پرداخت بدهد به ظهرنویسهای ماقبل خود و برات\u200cدهنده که به مهلت '
  'مزبوررضایت نداده\u200cاند حق رجوع نخواهد داشت.'),
 (258,
  'شخصی که در سر وعده وجه برات را می\u200cپردازد بری\u200cالذمه محسوب می\u200cشود مگر آنکه وجه برات قانوناً در نزد '
  'او توقیف شده باشد.'),
 (259,
  'پرداخت وجه برات ممکن است به موجب نسخه ثانی یا ثالث یا رابع الخ به عمل آید در صورتی که در روی آن نسخه قید شده باشد '
  'که\u200cپس از پرداخت وجه به موجب این نسخه نسخ دیگر از اعتبار ساقط است.'),
 (260,
  'شخصی که وجه برات را بر حسب نسخه بپردازد که در روی آن قبولی نوشته نشده در مقابل شخصی که نسخه قبولی شده را '
  'داردمسئول پرداخت وجه آن است.'),
 (261,
  'در صورت گم شدن براتی که هنوز قبول نشده\u200cاست صاحب آن می\u200cتواند وصول وجه آن را بر حسب نسخه ثانی یا ثالث یا '
  'رابع الخ\u200cتقاضا کند.'),
 (262,
  'اگر نسخه مفقود نسخه باشد که قبولی در روی آن نوشته شده تقاضای پرداخت از روی نسخه\u200cهای دیگر فقط به موجب امر '
  'محکمه پس\u200cاز دادن ضامن به عمل می\u200cآید.'),
 (263,
  'اگر شخصی که برات را گم کرده - اعم از اینکه قبولی نوشته شده یا نشده باشد می\u200cتواند نسخه ثانی یا ثالث یا رابع '
  'الخ را تحصیل نمایدپس از اثبات اینکه برات متعلق به او است می\u200cتواند با دادن ضامن تأدیه وجه آن را به موجب امر '
  'محکمه مطالبه کند.'),
 (264,
  'اگر با وجود تقاضایی که در مورد مواد ۲۶۱ - ۲۶۲ و ۲۶۳ به عمل آمده\u200cاست از تأدیه وجه برات امتناع شود صاحب برات '
  'مفقودمی\u200cتواند تمام حقوق خود را به موجب اعتراضنامه محفوظ بدارد.'),
 (265,
  'اعتراضنامه مذکور در ماده فوق باید در ظرف ۲۴ ساعت از تاریخ وعده برات تنظیم شده و در مواعد و به ترتیبی که در این '
  'قانون برای\u200cابلاغ اعتراضنامه معین شده\u200cاست به برات\u200cدهنده و ظهرنویسها ابلاغ گردد.'),
 (266,
  'صاحب برات مفقود برای تحصیل نسخه ثانی باید به ظهرنویسی که بلافاصله قبل از او بوده\u200cاست رجوع نماید - ظهرنویس '
  'مزبور ملزم\u200cاست به صاحب برات اختیار مراجعه به ظهرنویس ماقبل خود داده و راهنمایی کند و همچنین هر ظهرنویس باید '
  'اختیار رجوع به ظهرنویس ماقبل خودبدهد تا به برات\u200cدهنده برسد - مخارج این اقدامات بر عهده صاحب برات مفقود خواهد '
  'بود. ظهرنویس در صورت امتناع از دادن اختیار مسئول تأدیه وجه برات و خساراتی است که بر صاحب برات مفقود وارد '
  'شده\u200cاست.'),
 (267,
  'در صورتی که ضامن برات مفقود (\u200cرجوع به مواد ۲۶۲ و ۲۶۳) مدتی برای ضمانت خود معین نکرده باشد مدت ضمان سه سال '
  'است وهر گاه در ظرف این سه سال رسماً مطالبه یا اقامه دعوی نشده باشد دیگر از این حیث دعوی بر علیه او در محکمه مسموع '
  'نخواهد بود.'),
 (268,
  'اگر مبلغی از وجه برات پرداخته شود به همان اندازه برات\u200cدهنده و ظهرنویسها بری می\u200cشوند و دارنده برات فقط '
  'نسبت به بقیه می\u200cتوانداعتراض کند.'),
 (269, 'محاکم نمی\u200cتوانند بدون رضایت صاحب برات برای تأدیه وجه برات مهلتی بدهند.'),
 (270,
  'هر شخص ثالثی می\u200cتواند از طرف برات\u200cدهنده یا یکی از ظهرنویسها وجه برات اعتراض شده را کارسازی نماید - '
  'دخالت شخص ثالث وپرداخت وجه باید در اعتراضنامه یا در ذیل آن قید شود.'),
 (271, 'شخص ثالثی که وجه برات را پرداخته دارای تمام حقوق و وظایف دارنده برات است.'),
 (272,
  'اگر وجه برات را شخص ثالث از طرف برات\u200cدهنده پرداخت تمام ظهرنویسها بری\u200cالذمه می\u200cشوند و اگر پرداخت '
  'وجه از طرف یکی ازظهرنویسها به عمل آید ظهرنویسهای بعد از او بری\u200cالذمه\u200cاند.'),
 (273,
  'اگر دو شخص متفقاً هر یک از جانب یکی از مسئولین برات برای پرداخت وجه حاضر شوند پیشنهاد آن کس پذیرفته\u200cاست که '
  'تأدیه وجه\u200cاز طرف او عده زیادتری از مسئولین را بری\u200cالذمه می\u200cکند - اگر خود محال\u200cعلیه پس از '
  'اعتراض برای تأدیه وجه حاضر شود بر هر شخص ثالثی ترجیح\u200cدارد.'),
 (274,
  'نسبت به برواتی که وجه آن باید در ایران به رؤیت یا به وعده از رؤیت تأدیه شود اعم از اینکه برات در ایران صادر شده '
  'باشد یا درخارجه دارنده برات مکلف است پرداخت یا قبولی آن را در ظرف یک سال از تاریخ برات مطالبه نماید و الا حق رجوع '
  'به ظهرنویسها و همچنین به\u200cبرات\u200cدهنده که وجه برات را به محال\u200cعلیه رسانیده\u200cاست نخواهد داشت.'),
 (275,
  'اگر در برات اعم از اینکه در ایران صادر شده باشد یا در خارجه برای تقاضای قبولی مدت بیشتر یا کمتری مقرر شده باشد '
  'دارنده برات\u200cباید در همان مدت قبولی برات را تقاضا نماید و الا حق رجوع به ظهرنویسها و برات\u200cدهنده که وجه '
  'برات را به محال\u200cعلیه رسانیده\u200cاست نخواهد داشت.'),
 (276,
  'اگر ظهرنویسی برای تقاضای قبولی مدتی معین کرده باشد دارنده برات باید در مدت مزبور تقاضای قبولی نماید و الا در '
  'مقابل آن\u200cظهرنویس نمی\u200cتواند از مقررات مربوطه به بروات استفاده کند.'),
 (277,
  'هر گاه دارنده برات به رؤیت یا به وعده که در یکی از شهرهای ایران صادر و باید در ممالک خارجه تأدیه شود در مواعد '
  'مقرر در موادفوق قبولی نوشتن یا پرداخت وجه را مطالبه نکرده باشد مطابق مقررات همان مواد حق او ساقط خواهد شد.'),
 (278, 'مقررات فوق مانع نخواهد بود که بین دارنده برات و برات\u200cدهنده و ظهرنویسها قرارداد دیگری مقرر گردد.'),
 (279, 'دارنده برات باید روز وعده وجه برات را مطالبه کند.'),
 (280,
  'امتناع از تأدیه وجه برات باید در ظرف ده روز از تاریخ وعده به وسیله نوشته که اعتراض عدم تأدیه نامیده می\u200cشود '
  'معلوم گردد.'),
 (281, 'اگر روز دهم تعطیل باشد اعتراض روز بعد آن به عمل خواهد آمد.'),
 (282, 'نه فوت محال\u200cعلیه نه ورشکستگی او نه اعتراض نکولی دارنده برات را از اعتراض عدم تأدیه مستغنی نخواهد کرد.'),
 (283, 'در صورتی که قبول\u200cکننده برات قبل از وعده ورشکست شود حق اعتراض برای دارنده برات باقی است.'),
 (284,
  'دارنده براتی که به علت عدم تأدیه اعتراض شده\u200cاست باید در ظرف ده روز از تاریخ اعتراض عدم تأدیه را به وسیله '
  'اظهارنامه رسمی یامراسله سفارشی دو قبضه به کسی که برات را به او واگذار نموده اطلاع دهد.'),
 (285,
  'هر یک از ظهرنویسها نیز باید در ظرف ده روز از تاریخ دریافت اطلاع\u200cنامه فوق آن را به همان وسیله به ظهرنویس سابق '
  'خود اطلاع دهد.'),
 (286,
  'اگر دارنده براتی که بایستی در ایران تأدیه شود و به علت عدم پرداخت اعتراض شده بخواهد از حقی که ماده ۲۴۹ برای او '
  'مقرر داشته\u200cاستفاده کند باید در ظرف سه ماه از تاریخ اعتراض اقامه دعوی نماید. تبصره - هر گاه محل اقامت '
  'مدعی\u200cعلیه خارج از محلی باشد که وجه برات باید در آنجا پرداخته شود برای هر شش فرسخ یک روز اضافه خواهدشد.'),
 (287,
  'در مورد برواتی که باید در خارجه تأدیه شود اقامه دعوی بر علیه برات\u200cدهنده و یا ظهرنویس\u200cهای مقیم ایران در '
  'ظرف شش ماه از تاریخ\u200cاعتراض باید به عمل آید.'),
 (288,
  'هر یک از ظهرنویسها بخواهد از حقی که در ماده ۲۴۹ به او داده شده استفاده نماید باید در مواعدی که به موجب مواد ۲۸۶ و '
  '۲۸۷ مقرراست اقامه دعوی کند و نسبت به او موعد از فردای ابلاغ احضاریه محکمه محسوب است و اگر وجه برات را بدون اینکه '
  'بر علیه او اقامه دعوی شده\u200cباشد تأدیه نماید از فردای روز تأدیه محسوب خواهد شد.'),
 (289,
  'پس از انقضاء مواعد مقرره در مواد فوق دعوی دارنده برات بر ظهرنویسها و همچنین دعوی هر یک از ظهرنویسها بر ید سابق '
  'خود درمحکمه پذیرفته نخواهد شد.'),
 (290,
  'پس از انقضاء مواعد فوق دعوی دارنده و ظهرنویسهای برات بر علیه برات\u200cدهنده نیز پذیرفته نمی\u200cشود مشروط بر '
  'اینکه برات\u200cدهنده ثابت\u200cنماید در سر وعده وجه برات را به محال\u200cعلیه رسانیده و در این صورت دارنده برات '
  'فقط حق مراجعه به محال\u200cعلیه خواهد داشت.'),
 (291,
  'اگر پس از انقضاء موعدی که برای اعتراض و ابلاغ اعتراضنامه یا برای اقامه دعوی مقرر است برات\u200cدهنده یا هر یک از '
  'ظهرنویسها به\u200cطریق محاسبه یا عنوان دیگر وجهی را که برای تأدیه برات به محال\u200cعلیه رسانیده بود مسترد دارد '
  'دارنده برات برخلاف مقررات دو ماده قبل حق خواهدداشت که بر علیه دریافت\u200cکننده وجه اقامه دعوی نماید.'),
 (292,
  'پس از اقامه دعوی محکمه مکلف است به مجرد تقاضای دارنده براتی که به علت عدم تأدیه اعتراض شده\u200cاست معادل وجه '
  'برات را ازاموال مدعی\u200cعلیه به عنوان تأمین توقیف نماید.'),
 (293,
  'اعتراض در موارد ذیل به عمل می\u200cآید: ۱) در مورد نکول. ۲) در مورد امتناع از قبول یا نکول. ۳) در مورد عدم تأدیه. '
  'اعتراضنامه باید در یک نسخه تنظیم و به موجب امر محکمه بدایت به توسط مأمور اجراء به محل اقامت اشخاص ذیل ابلاغ شود: '
  '۱) محال\u200cعلیه. ۲) اشخاصی که در برات برای تأدیه وجه عندالاقتضاء معین شده\u200cاند. ۳) شخص ثالثی که برات را '
  'قبول کرده\u200cاست. اگر در محلی که اعتراض به عمل می\u200cآید محکمه بدایت نباشد وظایف او با رعایت ترتیب به عهده '
  'امین صلح یا رییس ثبت اسناد یا حاکم محل خواهدبود.'),
 (294,
  'اعتراضنامه باید مراتب ذیل را دارا باشد: ۱) سواد کامل برات با کلیه محتویات آن اعم از قبولی و ظهرنویسی و غیره. ۲) '
  'امر به تأدیه وجه برات. مأمور اجرا باید حضور یا غیاب شخصی که باید وجه برات را بدهد و علل امتناع از تأدیه یا از '
  'قبول و همچنین علل عدم امکان امضاء یا امتناع از امضاءرا در ذیل اعتراضنامه قید و امضاء کند.'),
 (295,
  'هیچ نوشته نمی\u200cتواند از طرف دارنده برات جایگیر اعتراضنامه شود مگر در موارد مندرجه در مواد ۲۶۱ - ۲۶۲ و ۲۶۳ '
  'راجع به مفقودشدن برات.'),
 (296, 'مأمور اجرا باید سواد صحیح اعتراضنامه را به محل اقامت اشخاص مذکور در ماده ۲۹۳ بدهد.'),
 (297,
  'دفتر محکمه یا دفتر مقاماتی که وظیفه محکمه را انجام می\u200cدهند باید مفاد اعتراضنامه را روز به روز به ترتیب تاریخ '
  'و نمره در دفترمخصوصی که صفحات آن به توسط رییس محکمه یا قائم\u200cمقام او نمره و امضاء شده\u200cاست ثبت نمایند - '
  'در صورتی که محل اقامت برات\u200cدهنده یاظهرنویس اولی در روی برات قید شده باشد دفتر محکمه باید آنها را توسط کاغذ '
  'سفارشی از علل امتناع از تأدیه مستحضر سازد.'),
 (298,
  'برات رجوعی براتی است که دارنده برات اصلی پس از اعتراض برای دریافت وجه آن و مخارج صدور اعتراضنامه و تفاوت نرخ '
  'به\u200cعهده برات\u200cدهنده یا یکی از ظهرنویسها صادر می\u200cکند.'),
 (299,
  'اگر برات رجوعی به عهده برات\u200cدهنده اصلی صادر شود تفاوت بین نرخ مکان تأدیه برات اصلی و نرخ مکان صدور آن به '
  'عهده اوخواهد بود و اگر برات رجوعی به عهده یکی از ظهرنویسها صادر شود مشارالیه باید از عهده تفاوت نرخ مکانی که برات '
  'اصلی را در آنجا معامله یاتسلیم کرده\u200cاست و نرخ مکانی که برای رجوعی در آنجا صادر شده\u200cاست برآید.'),
 (300,
  'به برات رجوعی باید صورت\u200cحسابی (\u200cحساب بازگشت) ضمیمه شود - در صورت حساب مزبور مراتب ذیل قید می\u200cگردد: '
  '۱) اسم شخصی که برات رجوعی به عهده او صادر شده\u200cاست. ۲) مبلغ اصلی برات اعتراض شده. ۳) مخارج اعتراضنامه و سایر '
  'مخارج معموله از قبیل حق\u200cالعمل صراف و دلال و وجه تمبر و مخارج پست و غیره. ۴) مبلغ تفاوت نرخهای مذکور در ماده '
  '(۲۹۹).'),
 (301,
  'صورت\u200cحساب مذکور در ماده قبل باید توسط دو نفر تاجر تصدیق شود به علاوه لازم است برات اعتراض شده و سواد مصدقی '
  'ازاعتراضنامه به صورت حساب مزبور ضمیمه گردد.'),
 (302,
  'هر گاه برات رجوعی به عهده یکی از ظهرنویسها صادر شود علاوه بر مراتب مذکور در مواد ۳۰۰ و ۳۰۱ باید تصدیقنامه که '
  'تفاوت بین\u200cنرخ مکان تأدیه برات اصلی و مکان صدور آن را معین نماید ضمیمه شود.'),
 (303,
  'نسبت به یک برات صورت\u200cحساب بازگشت متعدد نمی\u200cتوان ترتیب داد و اگر برات رجوعی به عهده یکی از ظهرنویسها '
  'صادر شده باشدحساب بازگشت متوالیاً به توسط ظهرنویسها پرداخته می\u200cشود تا به برات\u200cدهنده اولی برسد. تحمیلات '
  'براتهای رجوعی را نمی\u200cتوان تماماً بر یک نفر وارد ساخت - هر یک از ظهرنویسها و برات\u200cدهنده اولی فقط '
  'عهده\u200cدار یک خرج است.'),
 (304,
  'خسارت تأخیر تأدیه مبلغ اصلی برات که به واسطه عدم تأدیه اعتراض شده\u200cاست از روز اعتراض و خسارت تأخیر تأدیه '
  'مخارج\u200cاعتراض و مخارج برات رجوعی فقط از روز اقامه دعوی محسوب می\u200cشود.'),
 (305,
  'در مورد برواتی که در خارج ایران صادر شده شرایط اساسی برات تابع قوانین مملکت صدور است. هر قسمت از سایر تعهدات '
  'براتی (\u200cتعهدات ناشی از ظهرنویسی - ضمانت - قبولی و غیره) نیز که در خارجه به وجود آمده تابع قوانین مملکتی است '
  'که\u200cتعهد در آنجا وجود پیدا کرده\u200cاست. معذالک اگر شرایط اساسی برات مطابق قانون ایران موجود و یا تعهدات '
  'براتی موافق قانون ایران صحیح باشد کسانی که در ایران تعهداتی کرده\u200cاند حق\u200cاستناد به این ندارند که شرایط '
  'اساسی برات یا تعهدات براتی مقدم بر تعهد آنها مطابق با قوانین خارجی نیست.'),
 (306,
  'اعتراض و به طور کلی هر اقدامی که برای حفظ حقوق ناشیه از برات و استفاده از آن در خارجه باید به عمل آید تابع قوانین '
  'مملکتی\u200cخواهد بود که آن اقدام باید در آنجا بشود.'),
 (307,
  'فته\u200cطلب سندی است که به موجب آن امضاکننده تعهد می\u200cکند مبلغی در موعد معین یا عندالمطالبه در وجه حامل یا '
  'شخص معین و یا به\u200cحواله\u200cکرد آن شخص کارسازی نماید.'),
 (308,
  'فته\u200cطلب علاوه بر امضاء یا مهر باید دارای تاریخ و متضمن مراتب ذیل باشد: ۱) مبلغی که باید تأدیه شود با تمام '
  'حروف. ۲) گیرنده وجه. ۳) تاریخ پرداخت.'),
 (309,
  'تمام مقررات راجع به بروات تجارتی (\u200cاز مبحث چهارم الی آخر فصل اول این باب) در مورد فته\u200cطلب نیز '
  'لازم\u200cالرعایه\u200cاست.'),
 (310,
  'چک نوشته\u200cای است که به موجب آن صادرکننده وجوهی را که در نزد محال\u200cعلیه دارد کلاً یا بعضاً مسترد یا به '
  'دیگری واگذار می\u200cنماید.'),
 (311, 'در چک باید محل و تاریخ صدور قید شده و به امضای صادرکننده برسد - پرداخت وجه نباید وعده داشته باشد.'),
 (312,
  'چک ممکن است در وجه حامل یا شخص معین یا به حواله\u200cکرد باشد - ممکن است به صرف امضاء در ظهر به دیگری منتقل شود.'),
 (313, 'وجه چک باید به محض ارائه کارسازی شود.'),
 (314,
  'صدور چک ولو اینکه از محلی به محل دیگر باشد ذاتاً عمل تجارتی محسوب نیست لیکن مقررات این قانون از ضمانت صادرکننده '
  'وظهرنویسها و اعتراض و اقامه دعوی ضمان و مفقود شدن راجع به بروات شامل چک نیز خواهد بود.'),
 (315,
  'اگر چک در همان مکانی که صادر شده\u200cاست باید تأدیه گردد دارنده چک باید در ظرف پانزده روز از تاریخ صدور وجه آن '
  'را مطالبه کند واگر از یک نقطه به نقطه دیگر ایران صادر شده باشد باید در ظرف چهل و پنج روز از تاریخ صدور چک مطالبه '
  'شود. اگر دارنده چک در ظرف مواعد مذکوره در این ماده پرداخت وجه آن را مطالبه نکند دیگر دعوی او بر علیه ظهرنویس '
  'مسموع نخواهد بود و اگر وجه\u200cچک به سببی که مربوط به محال\u200cعلیه\u200cاست از بین برود دعوی دارنده چک بر علیه '
  'صادرکننده نیز در محکمه مسموع نیست.'),
 (316, 'کسی که وجه چک را دریافت می\u200cکند باید ظهر آن را امضاء یا مهر نماید اگر چه چک در وجه حامل باشد.'),
 (317,
  'مقررات راجعه به چکهایی که در ایران صادر شده\u200cاست در مورد چکهایی که از خارجه صادر شده و باید در ایران پرداخته '
  'شود نیزرعایت خواهد شد - لیکن مهلتی که در ظرف آن دارنده چک می\u200cتواند وجه چک را مطالبه کند چهار ماه از تاریخ '
  'صدور است.'),
 (318,
  'دعاوی راجعه به برات و فته\u200cطلب و چک که از طرف تجار یا برای امور تجارتی صادر شده پس از انقضای پنج سال از تاریخ '
  'صدوراعتراضنامه و یا آخرین تعقیب قضایی در محاکم مسموع نخواهد بود مگر اینکه در ظرف این مدت رسماً اقرار به دین شده '
  'باشد که در این صورت مبدأمرور زمان از تاریخ اقرار محسوب است. در صورت عدم اعتراض مدت مرور زمان از تاریخ انقضاء مهلت '
  'اعتراض شروع می\u200cشود. تبصره - مفاد این ماده در مورد بروات و چک و فته\u200cطلبهایی که قبل از تاریخ اجرای قانون '
  'تجارت مصوب ۲۵ دلو ۱۳۰۳ و ۱۲ فروردین و ۱۲ خرداد۱۳۰۴ صادر شده\u200cاست قابل اجرا نبوده و این اسناد از حیث مرور زمان '
  'تابع مقررات مربوط به مرور زمان راجع به اموال منقول است.'),
 (319,
  'اگر وجه برات یا فته\u200cطلب یا چک را نتوان به واسطه حصول مرور زمان پنج سال مطالبه کرد دارنده برات یا '
  'فته\u200cطلب یا چک می\u200cتواند تاحصول مرور زمان اموال منقوله وجه آن را از کسی که به ضرر او استفاده بلاجهت '
  'کرده\u200cاست مطالبه نماید. تبصره - حکم فوق در موردی نیز جاری است که برات یا فته\u200cطلب یا چک یکی از شرایط '
  'اساسی مقرر در این قانون را فاقد باشد.'),
 (320,
  'دارنده هر سند در وجه حامل مالک و برای مطالبه وجه آن محق محسوب می\u200cشود مگر در صورت ثبوت خلاف. معذلک اگر '
  'مقامات\u200cصلاحیتدار قضایی یا پلیس تأدیه وجه آن سند را منع کند تأدیه وجه به حامل مدیون را نسبت به شخص ثالثی که '
  'ممکن است سند متعلق به او باشدبری نخواهد کرد.'),
 (321, 'جز در موردی که حکم بطلان سند صادر شده مدیون سند در وجه حامل مکلف به تأدیه نیست مگر در مقابل اخذ سند.'),
 (322,
  'در صورت گم شدن سند در وجه حامل که دارای ورقه\u200cهای کوپن یا دارای ضمیمه برای تجدید اوراق کوپن باشد و همچنین در '
  'صورت\u200cگم شدن سند در وجه حامل که خود سند به دارنده آن حق می\u200cدهد ربح یا منفعتی را مرتباً دریافت کند برای '
  'اصدار حکم بطلان مطابق ذیل عمل خواهدشد.'),
 (323,
  'مدعی باید در محکمه محل اقامت مدیون معلوم نماید سند در تصرف او بوده و فعلاً گم شده\u200cاست. اگر مدعی فقط اوراق '
  'کوپن یا ضمیمه مربوط به سند خود را گم کرده باشد ابراز خود سند کافی است.'),
 (324,
  'اگر محکمه ادعای مدعی را بنا بر اوضاع و احوال قابل اعتماد دانست باید به وسیله اعلان در جراید به دارنده مجهول سند '
  'اخطار کند -\u200cهر گاه از تاریخ انتشار اولین اعلان تا سه سال سند را ابراز ننمود حکم بطلان آن صادر خواهد شد - '
  'محکمه می\u200cتواند لدی\u200cالاقتضاء مدتی بیش از سه\u200cسال تعیین کند.'),
 (325,
  'به تقاضای مدعی محکمه می\u200cتواند به مدیون قدغن کند که وجه سند را به کسی نپردازد مگر پس از گرفتن ضامن یا تأمینی '
  'که محکمه\u200cتصویب نماید.'),
 (326,
  'در مورد گم شدن اوراق کوپن نسبت به کوپنهایی که در ضمن جریان دعوی لازم\u200cالتأدیه می\u200cشود به ترتیب مقرر در '
  'مواد ۳۳۲ و ۳۳۳ عمل\u200cخواهد شد.'),
 (327,
  'اخطار مذکور در ماده ۳۲۴ باید سه دفعه در مجله رسمی منتشر شود محکمه می\u200cتواند به علاوه اعلان در جراید دیگر را '
  'نیز مقرر دارد.'),
 (328,
  'اگر پس از اعلان فوق سند مفقود ابراز شود محکمه به مدعی مهلت متناسبی داده و اخطار خواهد کرد که هر گاه تا انقضای '
  'مهلت دعوی\u200cخود را تعقیب و دلائل خود را اظهار نکند محکوم شده و سند به ابرازکننده آن مسترد خواهد گردید.'),
 (329, 'اگر در ظرف مدتی که مطابق ماده ۳۲۴ مقرر و اعلان شده سند ابراز نگردد محکمه حکم بطلان آن را صادر خواهد نمود.'),
 (330, 'ابطال سند فوراً به وسیله درج در مجله رسمی و هر وسیله دیگری که محکمه مقتضی بداند به اطلاع عموم خواهد رسید.'),
 (331,
  'پس از صدور حکم ابطال مدعی حق دارد تقاضا کند به خرج او سند جدید یا لدی\u200cالاقتضاء اوراق کوپن تازه به او بدهند. '
  'اگر سند حال\u200cشده باشد مدعی حق تقاضای تأدیه خواهد داشت.'),
 (332,
  'هر گاه سند گم شده از اسناد مذکور در ماده (۳۲۲) نباشد به ترتیب ذیل رفتار خواهد شد: محکمه در صورتی که ادعای مدعی '
  'سبق تصرف و گم کردن سند را قابل اعتماد دید حکم می\u200cدهد مدیون وجه سند را فوراً در صورتی که حال باشد وپس از '
  'انقضاء اجل - در صورت مؤجل بودن - به صندوق عدلیه بسپارد.'),
 (333,
  'اگر قبل از انقضای مدت مرور زمانی که وجه سند مفقود پس از آن مدت قابل مطالبه نیست سند ابراز شده مطابق ماده ۳۲۸ '
  'رفتار و الاوجهی که در صندوق عدلیه امانت گذاشته شده به مدعی داده می\u200cشود.'),
 (334, 'مقررات این باب شامل اسکناس نیست.'),
 (335,
  'دلال کسی است که در مقابل اجرت واسطه انجام معاملاتی شده یا برای کسی که می\u200cخواهد معاملاتی نماید طرف معامله '
  'پیدا می\u200cکند. اصولاً قرارداد دلالی تابع مقررات راجع به وکالت است.'),
 (336, 'دلال می\u200cتواند در رشته\u200cهای مختلف دلالی نموده و شخصاً نیز تجارت کند.'),
 (337,
  'دلال باید در نهایت صحت و از روی صداقت طرفین معامله را از جزئیات راجعه به معامله مطلع سازد ولو اینکه دلالی را فقط '
  'برای یکی\u200cاز طرفین بکند - دلال در مقابل هر یک از طرفین مسئول تقلب و تقصیرات خود می\u200cباشد.'),
 (338,
  'دلال نمی\u200cتواند عوض یکی از طرفین معامله قبض وجه یا تأدیه دین نماید و یا آنکه تعهدات آنها را به موقع اجرا '
  'گذارد مگر اینکه\u200cاجازه\u200cنامه مخصوصی داشته باشد.'),
 (339,
  'دلال مسئول تمام اشیاء و اسنادی است که در ضمن معاملات به او داده شده مگر اینکه ثابت نماید که ضایع یا تلف شدن اشیاء '
  'یا اسنادمزبوره مربوط به شخص او نبوده\u200cاست.'),
 (340,
  'در موردی که فروش از روی نمونه باشد دلال باید نمونه مال\u200cالتجاره را تا موقع ختم معامله نگاه بدارد مگر اینکه '
  'طرفین معامله او را ازاین قید معاف دارند.'),
 (341,
  'دلال می\u200cتواند در زمان واحد برای چند آمر در یک رشته یا رشته\u200cهای مختلف دلالی کند ولی در این صورت باید '
  'آمرین را از این ترتیب وامور دیگری که ممکن است موجب تغییر رأی آنها شود مطلع نماید.'),
 (342,
  'هر گاه معامله به توسط دلال واقع و نوشتجات و اسنادی راجع به آن معامله بین طرفین به توسط او رد و بدل شود در صورتی '
  'که امضاهاراجع به اشخاصی باشد که به توسط او معامله را کرده\u200cاند دلال ضامن صحت و اعتبار امضاهای نوشتجات و اسناد '
  'مزبور است.'),
 (343,
  'دلال ضامن اعتبار اشخاصی که برای آنها دلالی می\u200cکند و ضامن اجرای معاملاتی که به توسط او می\u200cشود نیست.'),
 (344,
  'دلال در خصوص ارزش یا جنس مال\u200cالتجاره که مورد معامله بوده مسئول نیست مگر اینکه ثابت شود تقصیر از جانب او '
  'بوده.'),
 (345, 'هر گاه طرفین معامله یا یکی از آنها به اعتبار تعهد شخص دلال معامله نمود دلال ضامن معامله\u200cاست.'),
 (346,
  'در صورتی که دلال در نفس معامله منتفع یا سهیم باشد باید به طرفی که این نکته را نمی\u200cداند اطلاع دهد و الا مسئول '
  'خسارات وارده\u200cبوده و به علاوه به پانصد تا سه هزار ریال جزای نقدی محکوم خواهد شد.'),
 (347, 'در صورتی که دلال در معامله سهیم باشد با آمر خود متضامناً مسئول اجرای تعهد خواهد بود.'),
 (348, 'دلال نمی\u200cتواند حق دلالی را مطالبه کند مگر در صورتی که معامله به راهنمایی یا وساطت او تمام شده باشد.'),
 (349,
  'اگر دلال برخلاف وظیفه خود نسبت به کسی که به او مأموریت داده به نفع طرف دیگر معامله اقدام نماید و یا برخلاف عرف '
  'تجارتی\u200cمحل از طرف مزبور وجهی دریافت و یا وعده وجهی را قبول کند مستحق اجرت و مخارجی که کرده نخواهد بود به '
  'علاوه محکوم به مجازات مقرربرای خیانت در امانت خواهد شد.'),
 (350, 'هر گاه معامله مشروط به شرط تعلیقی باشد دلال پس از حصول شرط مستحق اجرت خواهد بود.'),
 (351,
  'اگر شرط شده باشد مخارجی که دلال می\u200cکند به او داده شود دلال مستحق اخذ مخارج خواهد بود ولو آنکه معامله سر '
  'نگیرد. همین\u200cترتیب در موردی نیز جاری است که عرف تجارتی محل به پرداخت مخارجی که دلال کرده حکم کند.'),
 (352,
  'در صورتی که معامله به رضایت طرفین یا به واسطه یکی از خیارات قانونی فسخ بشود حق مطالبه دلالی از دلال سلب '
  'نمی\u200cشودمشروط بر اینکه فسخ معامله مستند به دلال نباشد.'),
 (353, 'دلالی معاملات ممنوعه اجرت ندارد.'),
 (354,
  'حق\u200cالزحمه دلال به عهده طرفی است که او را مأمور انجام معامله نموده مگر اینکه قرارداد خصوصی غیر این ترتیب را '
  'مقرر بدارد.'),
 (355,
  'حق\u200cالزحمه دلال به واسطه قرارداد مخصوصی باید معین شده باشد و الا محکمه با رجوع به اهل خبره و رعایت مقتضیات '
  'زمانی ومکانی و نوع معامله حق\u200cالزحمه را معین خواهد کرد.'),
 (356,
  'هر دلال باید دفتری داشته و کلیه معاملاتی را که به دلالی او انجام گرفته به ترتیب ذیل در آن ثبت نماید: ۱) اسم '
  'متعاملین. ۲) مالی که موضوع معامله\u200cاست. ۳) نوع معامله. ۴) شرایط معامله با تشخیص به اینکه تسلیم موضوع معامله '
  'فوری است یا به وعده\u200cاست. ۵) عوض مالی که باید پرداخته شود و تشخیص اینکه فوری است یا به وعده\u200cاست وجه نقد '
  'است یا مال\u200cالتجاره یا برات در صورتی که برات باشدبه رؤیت است یا به وعده. ۶) امضاء طرفین معامله مطابق مقررات '
  'نظامنامه وزارت عدلیه. دفتر دلالی تابع کلیه مقررات راجع به دفاتر تجارتی است.'),
 (357,
  'حق\u200cالعمل\u200cکار کسی است که به اسم خود ولی به حساب دیگری (\u200cآمر) معاملاتی کرده و در مقابل '
  'حق\u200cالعملی دریافت می\u200cدارد.'),
 (358,
  'جز در مواردی که به موجب مواد ذیل استثناء شده مقررات راجعه به وکالت در حق\u200cالعمل\u200cکاری نیز رعایت خواهد '
  'شد.'),
 (359,
  'حق\u200cالعمل\u200cکار باید آمر را از جریان اقدامات خود مستحضر داشته و مخصوصاً در صورت انجام مأموریت این نکته را '
  'به فوریت به اواطلاع دهد.'),
 (360,
  'حق\u200cالعمل\u200cکار مکلف به بیمه کردن اموالی که موضوع معامله\u200cاست نیست مگر اینکه آمر دستور داده باشد.'),
 (361,
  'اگر مال\u200cالتجاره که برای فروش نزد حق\u200cالعمل\u200cکار ارسال شده دارای عیوب ظاهری باشد '
  'حق\u200cالعمل\u200cکار باید برای محفوظ داشتن حق رجوع\u200cبر علیه متصدی حمل و نقل و تعیین میزان خسارات بحری '
  '(\u200cآواری) به وسایل مقتضیه و محافظت مال\u200cالتجاره اقدامات لازمه به عمل آورده و آمر را ازاقدامات خود مستحضر '
  'کند و الا مسئول خسارات ناشیه از این غفلت خواهد بود.'),
 (362,
  'اگر بیم فساد سریع مال\u200cالتجاره رود که نزد حق\u200cالعمل\u200cکار برای فروش ارسال شده حق\u200cالعمل\u200cکار '
  'می\u200cتواند و حتی در صورتی که منافع آمرایجاب کند مکلف است مال\u200cالتجاره را با اطلاع مدعی\u200cالعمومی محلی '
  'که مال\u200cالتجاره در آنجا است یا نماینده او به فروش برساند.'),
 (363,
  'اگر حق\u200cالعمل\u200cکار مال\u200cالتجاره را به کمتر از حداقل قیمتی که آمر معین کرده به فروش رساند مسئول تفاوت '
  'خواهد بود مگر اینکه ثابت\u200cنماید از ضرر بیشتری احتراز کرده و تحصیل اجازه آمر در موقع مقدور نبوده\u200cاست.'),
 (364,
  'اگر حق\u200cالعمل\u200cکار تقصیر کرده باشد باید از عهده کلیه خساراتی نیز که از عدم رعایت دستور آمر ناشی شده '
  'برآید.'),
 (365,
  'اگر حق\u200cالعمل\u200cکار مال\u200cالتجاره را به کمتر از قیمتی که آمر معین کرده بخرد و یا به بیشتر از قیمتی که '
  'آمر تعیین نموده به فروش رساند حق\u200cاستفاده از تفاوت نداشته و باید آن را در حساب آمر محسوب دارد.'),
 (366,
  'اگر حق\u200cالعمل\u200cکار بدون رضایت آمر مالی را به نسیه بفروشد یا پیش قسطی دهد ضررهای ناشیه از آن متوجه خود او '
  'خواهد بود معذالک\u200cاگر فروش به نسیه داخل در عرف تجارتی محل باشد حق\u200cالعمل\u200cکار مأذون به آن محسوب '
  'می\u200cشود مگر در صورت دستور مخالف آمر.'),
 (367,
  'حق\u200cالعمل\u200cکار در مقابل آمر مسئول پرداخت وجوه و یا انجام سایر تعهدات طرف معامله نیست مگر اینکه مجاز در '
  'معامله به اعتبار نبوده\u200cو یا شخصاً ضمانت طرف معامله را کرده و یا عرف تجارتی بلد او را مسئول قرار دهد.'),
 (368,
  'مخارجی که حق\u200cالعمل\u200cکار کرده و برای انجام معامله و نفع آمر لازم بوده و همچنین هر مساعده که به نفع آمر '
  'داده باشد باید اصلاً ومنفعتاً به حق\u200cالعمل\u200cکار مسترد شود. حق\u200cالعمل\u200cکار می\u200cتواند مخارج '
  'انبارداری و حمل و نقل را نیز به حساب آمر گذارد.'),
 (369,
  'وقتی حق\u200cالعمل\u200cکار مستحق حق\u200cالعمل می\u200cشود که معامله اجرا شده و یا عدم اجرای آن مستند به فعل آمر '
  'باشد. نسبت به اموری که در نتیجه علل دیگری انجام\u200cپذیر نشده حق\u200cالعمل\u200cکار برای اقدامات خود فقط مستحق '
  'اجرتی خواهد بود که عرف و عادت محل معین\u200cمی\u200cنماید.'),
 (370,
  'اگر حق\u200cالعمل\u200cکار نادرستی کرده و مخصوصاً در موردی که به حساب آمر قیمتی علاوه بر قیمت خرید و یا کمتر از '
  'قیمت فروش محسوب\u200cدارد مستحق حق\u200cالعمل نخواهد بود - به علاوه در دو صورت اخیر آمر می\u200cتواند '
  'حق\u200cالعمل\u200cکار را خریدار یا فروشنده محسوب کند. تبصره - دستور فوق مانع از اجرای مجازاتی که برای خیانت در '
  'امانت مقرر است نیست.'),
 (371,
  'حق\u200cالعمل\u200cکار در مقابل آمر برای وصول مطالبات خود از او نسبت به اموالی که موضوع معامله بوده و یا نسبت به '
  'قیمتی که اخذ کرده -\u200cحق حبس خواهد داشت.'),
 (372,
  'اگر فروش مال ممکن نشده و یا آمر از اجازه فروش رجوع کرده و مال\u200cالتجاره را بیش از حد متعارف نزد '
  'حق\u200cالعمل\u200cکار بگذاردحق\u200cالعمل\u200cکار می\u200cتواند آن را با نظارت مدعی\u200cالعموم بدایت محل یا '
  'نماینده او به طریق مزایده به فروش برساند. اگر آمر در محل نبوده و در آنجا نماینده نیز نداشته باشد فروش بدون حضور '
  'او یا نماینده او به عمل خواهد آمد ولی در هر حال قبلاً باید به او اخطاریه رسمی ارسال گردد مگر اینکه اموال از جمله '
  'اموال سریع\u200cالفساد باشد.'),
 (373,
  'اگر حق\u200cالعمل\u200cکار مأمور به خرید یا فروش مال\u200cالتجاره یا اسناد تجارتی و یا سایر اوراق بهاداری باشد که '
  'مظنه بورسی یا بازاری داردمی\u200cتواند چیزی را که مأمور به خرید آن بوده خود شخصاً به عنوان فروشنده تسلیم بکند و '
  'یا چیزی را که مأمور به فروش آن بوده شخصاً به عنوان\u200cخریدار نگاه دارد مگر اینکه آمر دستور مخالفی داده باشد.'),
 (374,
  'در مورد ماده فوق حق\u200cالعمل\u200cکار باید قیمت را بر طبق مظنه بورسی یا نرخ بازار در روزی که وکالت خود را انجام '
  'می\u200cدهد منظور دارد وحق خواهد داشت که هم حق\u200cالعمل و هم مخارج عادیه حق\u200cالعمل\u200cکار را برداشت کند.'),
 (375,
  'در هر موردی که حق\u200cالعمل\u200cکار شخصاً می\u200cتواند خریدار یا فروشنده واقع شود اگر معامله را به آمر بدون '
  'تعیین طرف معامله اطلاع دهدخود طرف معامله محسوب خواهد شد.'),
 (376,
  'اگر آمر از امر خود رجوع کرده و حق\u200cالعمل\u200cکار قبل از ارسال خبر انجام معامله از این رجوع مستحضر گردد دیگر '
  'نمی\u200cتواند شخصاً\u200cخریدار یا فروشنده واقع شود.'),
 (377, 'متصدی حمل و نقل کسی است که در مقابل اجرت حمل اشیاء را به عهده می\u200cگیرد.'),
 (378, 'قرارداد حمل و نقل تابع مقررات وکالت خواهد بود مگر در مواردی که ذیلاً استثناء شده باشد.'),
 (379,
  'ارسال\u200cکننده باید نکات ذیل را به اطلاع متصدی حمل و نقل برساند: آدرس صحیح مرسل\u200cالیه - محل تسلیم مال - عده '
  'عدل یا بسته وطرز عدل\u200cبندی - وزن و محتوی عدل\u200cها - مدتی که مال باید در آن مدت تسلیم شود - راهی که حمل '
  'باید از آن راه به عمل آید - قیمت اشیایی که\u200cگرانبها است. خسارات ناشیه از عدم تعیین نکات فوق و یا از تعیین '
  'آنها به غلط متوجه ارسال\u200cکننده خواهد بود.'),
 (380,
  'ارسال\u200cکننده باید مواظبت نماید که مال\u200cالتجاره به طرز مناسبی عدل\u200cبندی شود - خسارات بحری (آواری) ناشی '
  'از عیوب عدل\u200cبندی به\u200cعهده ارسال\u200cکننده\u200cاست.'),
 (381,
  'اگر عدل\u200cبندی عیب ظاهر داشته و متصدی حمل و نقل مال را بدون قید عدم مسئولیت قبول کرده باشد مسئول آواری خواهد '
  'بود.'),
 (382,
  'ارسال\u200cکننده می\u200cتواند مادام که مال\u200cالتجاره در ید متصدی حمل و نقل است آن را با پرداخت مخارجی که '
  'متصدی حمل و نقل کرده وخسارات او پس بگیرد.'),
 (383,
  'در موارد ذیل ارسال\u200cکننده نمی\u200cتواند از حق استرداد مذکور در ماده ۳۸۲ استفاده کند: ۱ - در صورتی که بارنامه '
  'توسط ارسال\u200cکننده تهیه و به وسیله متصدی حمل و نقل به مرسل\u200cالیه تسلیم شده باشد. ۳ - در صورتی که متصدی حمل '
  'و نقل به مرسل\u200cالیه اعلام کرده باشد که مال\u200cالتجاره به مقصد رسیده و باید آن را تحویل گیرد. ۴ - در صورتی '
  'که پس از وصول مال\u200cالتجاره به مقصد مرسل\u200cالیه تسلیم آن را تقاضا کرده باشد. در این موارد متصدی حمل و نقل '
  'باید مطابق دستور مرسل\u200cالیه عمل کند معذالک اگر متصدی حمل و نقل رسیدی به ارسال\u200cکننده داده مادام '
  'که\u200cمال\u200cالتجاره به مقصد نرسیده مکلف به رعایت دستور مرسل\u200cالیه نخواهد بود مگر اینکه رسید به '
  'مرسل\u200cالیه تسلیم شده باشد.'),
 (384,
  'اگر مرسل\u200cالیه مال\u200cالتجاره را قبول نکند و یا مخارج و سایر مطالبات متصدی حمل و نقل بابت مال\u200cالتجاره '
  'تأدیه نشود و یا به مرسل\u200cالیه\u200cدسترسی نباشد متصدی حمل و نقل باید مراتب را به اطلاع ارسال\u200cکننده '
  'رسانیده و مال\u200cالتجاره را موقتاً نزد خود به طور امانت نگاهداشته یا نزد ثالثی\u200cامانت گذارد و در هر دو صورت '
  'مخارج و هر نقص و عین به عهده ارسال\u200cکننده خواهد بود. اگر ارسال\u200cکننده و یا مرسل\u200cالیه در مدت مناسبی '
  'تکلیف مال\u200cالتجاره را معین نکند متصدی حمل و نقل می\u200cتواند مطابق ماده ۳۶۲ آن را به فروش برساند.'),
 (385,
  'اگر مال\u200cالتجاره در معرض تضییع سریع باشد و یا قیمتی که می\u200cتوان برای آن فرض کرد با مخارجی که برای آن شده '
  'تکافو ننماید متصدی\u200cحمل و نقل باید فوراً مراتب را به اطلاع مدعی\u200cالعموم بدایت محل یا نماینده او رسانیده و '
  'با نظارت او مال را به فروش رساند. حتی\u200cالمقدور ارسال\u200cکننده و مرسل\u200cالیه را باید از اینکه '
  'مال\u200cالتجاره به فروش خواهد رسید مسبوق نمود.'),
 (386,
  'اگر مال\u200cالتجاره تلف یا گم شود متصدی حمل و نقل مسئول قیمت آن خواهد بود مگر اینکه ثابت نماید تلف یا گم شدن '
  'مربوط به جنس\u200cخود مال\u200cالتجاره یا مستند به تقصیر ارسال\u200cکننده و یا مرسل\u200cالیه و یا ناشی از '
  'تعلیماتی بوده که یکی از آنها داده\u200cاند و یا مربوط به حوادثی بوده که هیچ\u200cمتصدی مواظبی نیز نمی\u200cتوانست '
  'از آن جلوگیری نماید قرارداد طرفین می\u200cتواند برای میزان خسارت مبلغی کمتر یا زیادتر از قیمت کامل '
  'مال\u200cالتجاره معین\u200cنماید.'),
 (387,
  'در مورد خسارات ناشیه از تأخیر تسلیم یا نقص یا خسارات بحری (\u200cآواری) مال\u200cالتجاره نیز متصدی حمل و نقل در '
  'حدود ماده فوق\u200cمسئول خواهد بود. خسارات مزبور نمی\u200cتواند از خساراتی که ممکن بود در صورت تلف شدن تمام '
  'مال\u200cالتجاره حکم به آن شود تجاوز نماید مگر اینکه قرارداد طرفین\u200cخلاف این ترتیب را مقرر داشته باشد.'),
 (388,
  'متصدی حمل و نقل مسئول حوادث و تقصیراتی است که در مدت حمل و نقل واقع شده اعم از اینکه خود مباشرت به حمل و '
  'نقل\u200cکرده و یا حمل و نقل\u200cکننده دیگری را مأمور کرده باشد - بدیهی است که در صورت اخیر حق رجوع او به متصدی '
  'حمل و نقلی که از جانب او مأمورشده محفوظ است.'),
 (389, 'متصدی حمل و نقل باید به محض وصول مال\u200cالتجاره مرسل\u200cالیه را مستحضر نماید.'),
 (390,
  'اگر مرسل\u200cالیه میزان مخارج و سایر وجوهی را که متصدی حمل و نقل بابت مال\u200cالتجاره مطالبه می\u200cنماید قبول '
  'نکند حق تقاضای تسلیم\u200cمال\u200cالتجاره را نخواهد داشت مگر اینکه مبلغ متنازع\u200cفیه را تا ختم اختلاف در '
  'صندوق عدلیه امانت گذارد.'),
 (391,
  'اگر مال\u200cالتجاره بدون هیچ قیدی قبول و کرایه آن تأدیه شود دیگر بر علیه متصدی حمل و نقل دعوی پذیرفته نخواهد شد '
  'مگر در موردتدلیس یا تقصیر عمده به علاوه متصدی حمل و نقل مسئول آواری غیر ظاهر نیز خواهد بود در صورتی که '
  'مرسل\u200cالیه آن آواری را در مدتی که مطابق\u200cاوضاع و احوال رسیدگی به مال\u200cالتجاره ممکن بود به عمل آید و '
  'یا بایستی به عمل آمده باشد مشاهده کرده و فوراً پس از مشاهده به متصدی حمل و نقل\u200cاطلاع دهد در هر حال این اطلاع '
  'باید منتها تا هشت روز بعد از تحویل گرفتن مال\u200cالتجاره داده شود.'),
 (392,
  'در هر موردی که بین متصدی حمل و نقل و مرسل\u200cالیه اختلاف باشد محکمه صلاحیتدار محل می\u200cتواند به تقاضای یکی '
  'از طرفین امر دهدمال\u200cالتجاره نزد ثالثی امانت گذارده شده و یا لدی\u200cالاقتضاء فروخته شود در صورت اخیر فروش '
  'باید پس از تنظیم صورت\u200cمجلسی حاکی از آنکه\u200cمال\u200cالتجاره در چه حال بوده به عمل آید. به وسیله پرداخت '
  'تمام مخارج و وجوهی که بابت مال\u200cالتجاره ادعا می\u200cشود و یا سپردن آن به صندوق عدلیه از فروش '
  'مال\u200cالتجاره می\u200cتوان جلوگیری کرد.'),
 (393,
  'نسبت به دعوی خسارت بر علیه متصدی حمل و نقل مدت مرور زمان یک سال است - مبدأ این مدت در صورت تلف یا گم '
  'شدن\u200cمال\u200cالتجاره و یا تأخیر در تسلیم روزی است که تسلیم بایستی در آن روز به عمل آمده باشد و در صورت '
  'خسارات بحری (\u200cآواری) روزی که مال به\u200cمرسل\u200cالیه تسلیم شده.'),
 (394, 'حمل و نقل به وسیله پست تابع مقررات این باب نیست.'),
 (395,
  'قائم\u200cمقام تجارتی کسی است که رییس تجارتخانه او را برای انجام کلیه امور مربوطه به تجارتخانه یا یکی از شعب آن '
  'نایب خود قرار داده\u200cو امضای او برای تجارتخانه الزام\u200cآور است. سمت مزبور ممکن است کتباً داده شود یا '
  'عملاً.'),
 (396, 'تحدید اختیارات قائم\u200cمقام تجارتی در مقابل اشخاصی که از آن اطلاع نداشته\u200cاند معتبر نیست.'),
 (397,
  'قائم\u200cمقام تجارتی ممکن است به چند نفر مجتمعاً داده شود با قید اینکه تا تمام امضاء نکنند تجارتخانه ملزم نخواهد '
  'شد ولی در مقابل\u200cاشخاص ثالثی که از این قید اطلاع نداشته\u200cاند فقط در صورتی می\u200cتوان از آن استفاده کرد '
  'که این قید مطابق مقررات وزارت عدلیه به ثبت رسیده و اعلان\u200cشده باشد.'),
 (398,
  'قائم\u200cمقام تجارتی بدون اذن رییس تجارتخانه نمی\u200cتواند کسی را در کلیه کارهای تجارتخانه نایب خود قرار دهد.'),
 (399,
  'عزل قائم\u200cمقام تجارتی که وکالت او به ثبت رسیده و اعلان شده باید مطابق مقررات وزارت عدلیه به ثبت رسیده و اعلان '
  'شود و الا درمقابل ثالثی که از عزل مطلع نبوده وکالت باقی محسوب می\u200cشود.'),
 (400,
  'با فوت یا حجر رییس تجارتخانه قائم\u200cمقام تجارتی منعزل نیست با انحلال شرکت قائم\u200cمقام تجارتی منعزل است.'),
 (401,
  'وکالت سایر کسانی که در قسمتی از امور تجارتخانه یا شعبه تجارتخانه سمت نمایندگی دارند تابع مقررات عمومی راجع به '
  'وکالت\u200cاست.'),
 (402,
  'ضامن وقتی حق دارد از مضمون\u200cله تقاضا نماید که بدواً به مدیون اصلی رجوع کرده و در صورت عدم وصول طلب به او رجوع '
  'نماید که\u200cبین طرفین (\u200cخواه ضمن قرارداد مخصوص خواه در خود ضمانت\u200cنامه) این ترتیب مقرر شده باشد.'),
 (403,
  'در کلیه مواردی که به موجب قوانین یا موافق قراردادهای خصوصی ضمانت تضامنی باشد طلبکار می\u200cتواند به ضامن و مدیون '
  'اصلی\u200cمجتمعاً رجوع کرده یا پس از رجوع به یکی از آنها و عدم وصول طلب خود برای تمام یا بقیه طلب به دیگری رجوع '
  'نماید'),
 (404, 'حکم فوق در موردی نیز جاری است که چند نفر به موجب قرارداد یا قانون متضامناً مسئول انجام تعهدی باشند.'),
 (405,
  'قبل از رسیدن اجل دین اصلی ضامن ملزم به تأدیه نیست ولو اینکه به واسطه ورشکستگی یا فوت مدیون اصلی دین مؤجل او '
  'حال\u200cشده باشد.'),
 (406, 'ضمان حال از قاعده فوق مستثنی است.'),
 (407, 'اگر حق مطالبه دین اصلی مشروط به اخطار قبلی است این اخطار نسبت به ضامن نیز باید به عمل آید.'),
 (408, 'همین که دین اصلی به نحوی از انحاء ساقط شده ضامن نیز بری می\u200cشود.'),
 (409,
  'همین که دین حال شد ضامن می\u200cتواند مضمون\u200cله را به دریافت طلب یا انصراف از ضمان ملزم کند ولو ضمان مؤجل '
  'باشد.'),
 (410,
  'استنکاف مضمون\u200cله از دریافت طلب یا امتناع از تسلیم وثیقه - اگر دین با وثیقه بوده - ضامن را فوراً و به خودی '
  'خود بری خواهدساخت.'),
 (411,
  'پس از آنکه ضامن دین اصلی را پرداخت مضمون\u200cله باید تمام اسناد و مدارکی را که برای رجوع ضامن به مضمون\u200cعنه '
  'لازم و مفید است\u200cبه او داده و اگر دین اصلی با وثیقه باشد آن را به ضامن تسلیم نماید - اگر دین اصلی وثیقه غیر '
  'منقول داشته مضمون\u200cعنه مکلف به انجام تشریفاتی است\u200cکه برای انتقال وثیقه به ضامن لازم است.'),
 (412,
  'ورشکستگی تاجر یا شرکت تجارتی در نتیجه توقف از تأدیه وجوهی که بر عهده او است حاصل می\u200cشود. حکم ورشکستگی تاجری '
  'را که حین\u200cالفوت در حال توقیف بوده تا یک سال بعد از مرگ او نیز می\u200cتوان صادر نمود.'),
 (413,
  'تاجر باید در ظرف سه روز از تاریخ وقفه که در تأدیه قروض یا سایر تعهدات نقدی او حاصل شده\u200cاست توقف خود را به '
  'دفتر محکمه\u200cبدایت محل اقامت خود اظهار نموده صورت\u200cحساب دارایی و کلیه دفاتر تجارتی خود را به دفتر محکمه '
  'مزبوره تسلیم نماید.'),
 (414,
  'صورتحساب مذکور در ماده فوق باید مورخ بوده و به امضاء تاجر رسیده و متضمن مراتب ذیل باشد: ۱) تعداد و تقویم کلیه '
  'اموال منقول و غیر منقول تاجر متوقف به طور مشروح. ۲) صورت کلیه قروض و مطالبات. ۳) صورت نفع و ضرر و صورت مخارج '
  'شخصی. در صورت توقف شرکتهای تضامنی - مختلط یا نسبی اسامی و محل اقامت کلیه شرکاء ضامن نیز باید ضمیمه شود.'),
 (415,
  'ورشکستگی تاجر به حکم محکمه بدایت در موارد ذیل اعلام می\u200cشود: الف) بر حسب اظهار خود تاجر. ب) به موجب تقاضای یک '
  'یا چند نفر از طلبکارها. ج) بر حسب تقاضای مدعی\u200cالعموم بدایت.'),
 (416, 'محکمه باید در حکم خود تاریخ توقف تاجر را معین نماید و اگر در حکم معین نشد تاریخ حکم تاریخ توقف محسوب است.'),
 (417, 'حکم ورشکستگی به طور موقت اجرا می\u200cشود.'),
 (418,
  'تاجر ورشکسته از تاریخ صدور حکم از مداخله در تمام اموال خود حتی آنچه که ممکن است در مدت ورشکستگی عاید او گرددممنوع '
  'است. در کلیه اختیارات و حقوق مالی ورشکسته که استفاده از آن مؤثر در تأدیه دیون او باشد مدیر تصفیه قائم\u200cمقام '
  'قانونی ورشکسته بوده و حق\u200cدارد به جای او از اختیارات و حقوق مزبوره استفاده کند.'),
 (419,
  'از تاریخ حکم ورشکستگی هر کس نسبت به تاجر ورشکسته دعوایی از منقول یا غیر منقول داشته باشد باید بر مدیر تصفیه اقامه '
  'یا به\u200cطرفیت او تعقیب کند - کلیه اقدامات اجرایی نیز مشمول همین دستور خواهد بود.'),
 (420, 'محکمه هر وقت صلاح بداند می\u200cتواند ورود تاجر ورشکسته را به عنوان شخص ثالث در دعوی مطروحه اجازه دهد.'),
 (421, 'همین که حکم ورشکستگی صادر شد قروض مؤجل با رعایت تخفیفات مقتضیه نسبت به مدت به قروض حال مبدل می\u200cشود.'),
 (422,
  'هر گاه تاجر ورشکسته فته\u200cطلبی داده یا براتی صادر کرده که قبول نشده یا براتی را قبولی نوشته سایر اشخاصی که '
  'مسئول تأدیه وجه\u200cفته\u200cطلب یا برات می\u200cباشند باید با رعایت تخفیفات مقتضیه نسبت به مدت وجه آن را نقداً '
  'بپردازند یا تأدیه آن را در سر وعده تأمین نمایند.'),
 (423,
  'هر گاه تاجر بعد از توقف معاملات ذیل را بنماید باطل و بلااثر خواهد بود: ۱) هر صلح محاباتی یا هبه و به طور کلی هر '
  'نقل و انتقال بلاعوض اعم از اینکه راجع به منقول یا غیر منقول باشد. ۲) تأدیه هر قرض اعم از حال یا مؤجل به هر وسیله '
  'که به عمل آمده باشد. ۳) هر معامله که مالی از اموال منقول یا غیر منقول تاجر را مقید نماید و به ضرر طلبکاران تمام '
  'شود.'),
 (424,
  'هر گاه در نتیجه اقامه دعوی از طرف مدیر تصفیه یا طلبکاری بر اشخاصی که با تاجر طرف معامله بوده یا بر قائم\u200cمقام '
  'قانونی آنها ثابت\u200cشود تاجر متوقف قبل از تاریخ توقف خود برای فرار از ادای دین یا برای اضرار به طلبکارها معامله '
  'نموده که متضمن ضرری بیش از ربع قیمت\u200cحین\u200cالمعامله بوده\u200cاست آن معامله قابل فسخ است مگر اینکه طرف '
  'معامله قبل از صدور حکم فسخ تفاوت قیمت را بپردازد دعوی فسخ در ظرف دوسال از تاریخ وقوع معامله در محکمه پذیرفته '
  'می\u200cشود.'),
 (425,
  'هر گاه محکمه به موجب ماده قبل حکم فسخ معامله را صادر نماید محکوم\u200cعلیه باید پس از قطعی شدن حکم مالی را که '
  'موضوع معامله\u200cبوده\u200cاست عیناً به مدیر تصفیه تسلیم و قیمت حین\u200cالمعامله آن را قبل از آنکه دارایی تاجر '
  'به غرما تقسیم شود دریافت دارد و اگر عین مال مزبور درتصرف او نباشد تفاوت قیمت را خواهد داد.'),
 (426,
  'اگر در محکمه ثابت شود که معامله به طور صوری یا مسبوق به تبانی بوده\u200cاست آن معامله خود به خود باطل - عین و '
  'منافع مالی که\u200cموضوع معامله بوده مسترد و طرف معامله اگر طلبکار شود جزو غرما حصه خواهد بود.'),
 (427, 'در حکمی که به موجب آن ورشکستگی تاجر اعلان می\u200cشود محکمه یک نفر را به سمت عضو ناظر معین خواهد کرد.'),
 (428, 'عضو ناظر مکلف است به نظارت در اداره امور راجعه به ورشکستگی و سرعت جریان آن است.'),
 (429, 'تمام منازعات ناشیه از ورشکستگی را که حل آن از صلاحیت محکمه\u200cاست عضو ناظر به محکمه راپرت خواهد داد.'),
 (430, 'شکایت از تصمیمات عضو ناظر فقط در مواردی ممکن است که این قانون معین نموده.'),
 (431, 'مرجع شکایت محکمه\u200cاست که عضو ناظر را معین کرده.'),
 (432, 'محکمه همیشه می\u200cتواند عضو ناظر با تبدیل و دیگری را به جای او بگمارد.'),
 (433, 'محکمه در حکم ورشکستگی امر به مهر و موم را نیز می\u200cدهد.'),
 (434,
  'مهر و موم باید فوراً توسط عضو ناظر به عمل آید مگر در صورتی که به عقیده عضو مزبور برداشتن صورت دارایی تاجر در یک '
  'روزممکن باشد در این صورت باید فوراً شروع به برداشتن صورت شود.'),
 (435, 'اگر تاجر ورشکسته به مفاد ماده ۴۱۳ - ۴۱۴ عمل نکرده باشد محکمه در حکم ورشکستگی قرار توقیف تاجر را خواهد داد.'),
 (436,
  'قرار توقیف ورشکسته در مواقعی نیز داده خواهد شد که معلوم گردد به واسطه اقدامات خود از اداره و تسویه شدن عمل '
  'ورشکستگی\u200cمی\u200cخواهد جلوگیری کند.'),
 (437,
  'در صورتی که تاجر مقروض فرار کرده یا تمام یا قسمتی از دارایی خود را مخفی نموده باشد امین صلح می\u200cتواند بر حسب '
  'تقاضای یک\u200cیا چند نفر از طلبکاران فوراً اقدام به مهر و موم نماید و باید بلافاصله این اقدام خود را به '
  'مدعی\u200cالعموم اطلاع دهد.'),
 (438,
  'انبارها و حجره\u200cها و صندوق و اسناد و دفاتر و نوشتجات و اسباب و اثاثیه تجارتخانه و منزل تاجر باید مهر موم '
  'شود.'),
 (439,
  'در صورت ورشکستگی شرکتهای تضامنی - مختلط یا نسبی اموال شخصی شرکاء ضامن مهر و موم نخواهد شد مگر اینکه '
  'حکم\u200cورشکستگی آنها نیز در ضمن حکم ورشکستگی شرکت یا به موجب حکم جداگانه صادر شده باشد. تبصره - در مورد این '
  'ماده و ماده فوق مستثنیات دین از مهر و موم معاف است.'),
 (440,
  'محکمه در ضمن حکم ورشکستگی یا منتهی در ظرف پنج روز پس از صدور حکم یک نفر را به سمت مدیریت تصفیه معین می\u200cکند.'),
 (441,
  'اقدامات مدیر تصفیه برای تهیه صورت طلبکاران و اخطار به آنها و مدتی که در آن مدت طلبکاران باید خود را معرفی نمایند '
  'و به طورکلی وظایف مدیر تصفیه علاوه بر آن قسمتی که به موجب این قانون معین شده بر طبق نظامنامه که از طرف وزارت '
  'عدلیه تنظیم می\u200cشود معین خواهدشد.'),
 (442, 'میزان حق\u200cالزحمه مدیر تصفیه را محکمه در حدود مقررات وزارت عدلیه معین خواهد کرد.'),
 (443, 'اگر مهر و موم قبل از تعیین مدیر تصفیه به عمل نیامده باشد مدیر مزبور تقاضای انجام آن را خواهد نمود.'),
 (444,
  'عضو ناظر به تقاضای مدیر تصفیه به او اجازه می\u200cدهد که اشیاء ذیل را از مهر و موم مستثنی کرده و اگر مهر و موم '
  'شده\u200cاست از توقیف\u200cخارج نماید: ۳ - اشیایی که برای به کار انداختن سرمایه تاجر ورشکسته و استفاده از آن لازم '
  'است در صورتی که توقیف آنها موجب خسارت ارباب طلب باشد. اشیاء مذکور در فقره ثانیه و ثالثه باید فوراً تقویم و صورت '
  'آن برداشته شود.'),
 (445,
  'فروش اشیایی که ممکن است قریباً ضایع شده یا کسر قیمت حاصل کند و اشیایی که نگاه داشتن آنها مفید نیست و همچنین به '
  'کارانداختن سرمایه تاجر ورشکسته با اجازه عضو ناظر به توسط مدیر تصفیه به عمل می\u200cآید.'),
 (446,
  'دفتردار محکمه دفاتر تاجر ورشکسته را به اتفاق عضو ناظر یا امین صلحی که آنها را مهر و موم نموده\u200cاست از توقیف '
  'خارج کرده پس ازآن که ذیل دفاتر را بست آنها را به مدیر تصفیه تسلیم می\u200cنماید. دفتردار باید در صورت\u200cمجلس '
  'کیفیت دفاتر را به طور خلاصه قید کند - اوراق تجارتی هم که وعده آنها نزدیک است یا باید قبولی آنها نوشته شود و '
  'یانسبت به آنها باید اقدامات تأمینیه به عمل آید از توقیف خارج شده در صورت\u200cمجلس ذکر و به مدیر تصفیه تحویل '
  'می\u200cشود تا وجه آن را وصول نماید وفهرستی که از مدیر تصفیه گرفته می\u200cشود به عضو ناظر تسلیم می\u200cگردد - '
  'سایر مطالبات را مدیر تصفیه در مقابل قبضی که می\u200cدهد وصول می\u200cنمایدمراسلاتی که به اسم تاجر ورشکسته '
  'می\u200cرسد به مدیر تصفیه تسلیم و به توسط او باز می\u200cشود و اگر خود ورشکسته حاضر باشد در باز کردن '
  'مراسلات\u200cمی\u200cتواند شرکت کند.'),
 (447,
  'تاجر ورشکسته در صورتی که وسیله دیگری برای اعاشه نداشته باشد می\u200cتواند نفقه خود و خانواده\u200cاش را از دارایی '
  'خود درخواست کند- در این صورت عضو ناظر نفقه و مقدار آن را با تصویب محکمه معین می\u200cنماید.'),
 (448,
  'مدیر تصفیه تاجر ورشکسته را برای بستن دفاتر احضار می\u200cنماید برای حضور او منتها چهل و هشت ساعت مهلت داده '
  'می\u200cشود درصورتی که تاجر حاضر نشد با حضور عضو ناظر اقدام به عمل خواهد آمد - تاجر ورشکسته می\u200cتواند در موقع '
  'کلیه عملیات تأمینیه حاضر باشد.'),
 (449,
  'در صورتی که تاجر ورشکسته صورت دارایی خود را تسلیم ننموده باشد مدیر تصفیه آن را فوراً به وسیله دفاتر و اسناد '
  'مشارالیه و سایراطلاعاتی که تحصیل می\u200cنماید تنظیم می\u200cکند.'),
 (450,
  'عضو ناظر مجاز است که راجع به تنظیم صورت دارایی و نسبت به اوضاع و احوال ورشکستگی از تاجر ورشکسته و شاگردها '
  'ومستخدمین او و همچنین از اشخاص دیگر توضیحات بخواهد و باید از تحقیقات مذکوره صورت\u200cمجلس ترتیب دهد.'),
 (451,
  'مدیر تصفیه پس از تقاضای رفع توقیف شروع به تنظیم صورت دارایی نموده و تاجر ورشکسته را هم در این موقع احضار '
  'می\u200cکند ولی\u200cعدم حضور او مانع از عمل نیست.'),
 (452,
  'مدیر تصفیه به تدریجی که رفع توقیف می\u200cشود صورت دارایی را در دو نسخه تهیه می\u200cنماید. یکی از نسختین به دفتر '
  'محکمه تسلیم\u200cشده و دیگری در نزد او می\u200cماند.'),
 (453,
  'مدیر تصفیه می\u200cتواند برای تهیه صورت دارایی و تقویم اموال از اشخاصی که لازم بداند استمداد کند صورت اشیایی که '
  'موافق ماده ۴۴۴\u200cدر تحت توقیف نیامده ولی قبلاً تقویم شده\u200cاست ضمیمه صورت دارایی خواهد شد.'),
 (454,
  'مدیر تصفیه باید در ظرف پانزده روز از تاریخ مأموریت خود صورت خلاصه از وضعیت ورشکستگی و همچنین از علل و اوضاعی '
  'که\u200cموجب آن شده و نوع ورشکستگی که ظاهراً به نظر می\u200cآید ترتیب داده به عضو ناظر بدهد. عضو ناظر صورت مزبور '
  'را فوراً به مدعی\u200cالعمومی ابتدایی\u200cمحل تسلیم می\u200cنماید.'),
 (455,
  'صاحب\u200cمنصبان پارکه می\u200cتوانند فقط به عنوان نظارت به منزل تاجر ورشکسته رفته و در حین برداشتن صورت دارایی '
  'حضور به هم\u200cرسانند. مأمورین پارکه در هر موقع حق دارند به دفاتر و اسناد و نوشتجات مربوطه به ورشکستگی مراجعه '
  'کنند. این مراجعه نباید باعث تعطیل جریان امر باشد.'),
 (456,
  'پس از تهیه شدن صورت دارایی تمام مال\u200cالتجاره و وجه نقد و اسناد طلب و دفاتر و نوشتجات و اثاثیه (\u200cبه غیر '
  'از مستثنیات دین) واشیاء تاجر ورشکسته به مدیر تصفیه تسلیم می\u200cشود.'),
 (457,
  'مدیر تصفیه با نظارت عضو ناظر به وصول مطالبات مداومت می\u200cنماید و همچنین می\u200cتواند با اجازه '
  'مدعی\u200cالعموم و نظارت عضو ناظر به\u200cفروش اثاث\u200cالبیت و مال\u200cالتجاره تاجر مباشرت نماید لیکن قبلاً '
  'باید اظهارات تاجر ورشکسته را استماع یا لااقل مشارالیه را برای دادن توضیحات احضارکند - ترتیب فروش به موجب نظامنامه '
  'وزارت عدلیه معین خواهد شد.'),
 (458,
  'نسبت به تمام دعاوی که هیأت طلبکارها در آن ذینفع می\u200cباشند مدیر تصفیه با اجازه عضو ناظر می\u200cتواند دعوی را '
  'به صلح خاتمه دهداگر چه دعاوی مزبوره راجع به اموال غیر منقول باشد و در این مورد تاجر ورشکسته باید احضار شده باشد.'),
 (459,
  'اگر موضوع صلح قابل تقویم نبوده یا بیش از پنج هزار ریال باشد صلح لازم\u200cالاجرا نخواهد بود مگر اینکه محکمه آن '
  'صلح را تصدیق\u200cنماید در موقع تصدیق صلحنامه تاجر ورشکسته احضار می\u200cشود و در هر صورت مشارالیه حق دارد که به '
  'صلح اعتراض کند - اعتراض ورشکسته درصورتی که صلح راجع به اموال غیر منقول باشد برای جلوگیری از صلح کافی خواهد بود تا '
  'محکمه تکلیف صلح را معین نماید.'),
 (460,
  'وجوهی که به توسط مدیر تصفیه دریافت می\u200cشود باید فوراً به صندوق عدلیه محل تسلیم گردد. صندوق مزبور حساب مخصوصی '
  'برای\u200cعمل ورشکسته اعم از عایدات و مخارج باز می\u200cکند وجوه مزبور از صندوق مسترد نمی\u200cگردد مگر به حواله '
  'عضو ناظر و تصدیق مدیر تصفیه.'),
 (461,
  'مدیر تصفیه مکلف است از روز شروع به مأموریت اقدامات تأمینیه برای حفظ حقوق تاجر ورشکسته نسبت به مدیونین او به '
  'عمل\u200cآورد.'),
 (462,
  'پس از صدور حکم ورشکستگی طلبکارها مکلفند - در مدتی که به موجب اخطار مدیر تصفیه در حدود نظامنامه وزارت عدلیه '
  'معین\u200cشده - اسناد طلب خود یا سواد مصدق آن را به انضمام فهرستی که کلیه مطالبات آنها را معین می\u200cنماید به '
  'دفتردار محکمه تسلیم کرده قبض دریافت\u200cدارند.'),
 (463,
  'تشخیص مطالبات طلبکارها در ظرف سه روز از تاریخ انقضای مهلت مذکور در ماده قبل شروع شده و بدون وقفه در محل و روز '
  'وساعتی که از طرف عضو ناظر معین می\u200cگردد - به ترتیبی که در نظامنامه معین خواهد شد - تعقیب می\u200cشود.'),
 (464,
  'هر طلبکاری که طلب او تشخیص یا جزء صورت\u200cحساب دارایی منظور شده می\u200cتواند در حین تشخیص مطالبات سایر '
  'طلبکارها حضوربه هم رسانیده و نسبت به طلبهایی که سابقاً تشخیص شده یا فعلاً در تحت رسیدگی است اعتراض نماید - همین '
  'حق را خود تاجر ورشکسته هم\u200cخواهد داشت.'),
 (465,
  'محل اقامت طلبکارها و وکلای آنها در صورت\u200cمجلس تشخیص مطالبات معین و به علاوه توصیف مختصری از سند داده '
  'می\u200cشود وتعیین قلم\u200cخوردگی یا تراشیدگی یا الحاقات بین\u200cالسطور نیز باید در صورت\u200cمجلس قید و این '
  'نکته مسلم شود که طلب مسلم یا متنازع\u200cفیه\u200cاست.'),
 (466,
  'عضو ناظر می\u200cتواند به نظر خود امر به ابراز دفاتر طلبکارها دهد یا از محکمه محل تقاضا نماید صورتی از دفاتر '
  'طلبکارها استخراج کرده\u200cو نزد او بفرستد.'),
 (467,
  'اگر طلب مسلم و قبول شد مدیر تصفیه در روی سند عبارت ذیل را نوشته امضاء نموده و عضو ناظر نیز آن را تصدیق '
  'می\u200cکند: «جزو قروض........ مبلغ....... قبول شد به تاریخ.........» هر طلبکار باید در ظرف مدت و به ترتیبی که به '
  'موجب نظامنامه وزارت عدلیه معین می\u200cشود التزام بدهد طلبی را که اظهار کرده طلب حقیقی و بدون\u200cقصد استفاده '
  'نامشروع است.'),
 (468,
  'اگر طلب متنازع\u200cفیه واقع شده عضو ناظر می\u200cتواند حل قضیه را به محکمه رجوع و محکمه باید فوراً از روی راپرت '
  'عضو ناظر رسیدگی\u200cنماید محکمه می\u200cتواند امر دهد که با حضور عضو ناظر تحقیق در امر به عمل آید و اشخاصی را که '
  'می\u200cتوانند راجع به این طلب اطلاعاتی دهند عضوناظر احضار یا از آنها کسب اطلاع کند.'),
 (469,
  'در موقعی که اختلاف راجع به تشخیص طلبی به محکمه رجوع شده و قضیه طوری باشد که محکمه نتواند در ظرف پانزده روز '
  'حکم\u200cصادر کند باید بر حسب اوضاع امر دهد که انعقاد مجلس هیأت طلبکارها برای ترتیب قرارداد ارفاقی به تأخیر افتد '
  'و یا اینکه منتظر نتیجه رسیدگی نشده\u200cو مجلس مزبور منعقد شود.'),
 (470,
  'محکمه می\u200cتواند در صورت تصمیم به انعقاد مجلس قرار دهد که صاحب طلب متنازع\u200cفیه معادل مبلغی که محکمه در '
  'قرار مزبور معین\u200cمی\u200cکند موقتاً طلبکار شناخته شده در مذاکرات هیأت طلبکارها برای مبلغ مذکور شرکت نماید.'),
 (471,
  'در صورتی که طلبی مورد تعقیب جزایی واقع شده باشد محکمه می\u200cتواند قرار تأخیر مجلس را بدهد ولی اگر تصمیم به عدم '
  'تأخیرمجلس نمود نمی\u200cتواند صاحب آن طلب را موقتاً جزو طلبکاران قبول نماید و مادام که محاکم صالحه حکم خود را '
  'نداده\u200cاند طلبکار مزبور نمی\u200cتواند به\u200cهیچ وجه در عملیات راجعه به ورشکستگی شرکت کند.'),
 (472,
  'پس از انقضای مهلت\u200cهای معین در مواد ۴۶۲ و ۴۶۷ به ترتیب قرارداد ارفاقی و به سایر عملیات راجعه به ورشکستگی '
  'مداومت\u200cمی\u200cشود.'),
 (473,
  'طلبکارهایی که در مواعد معینه حاضر نشده و مطابق ماده ۴۶۲ عمل نکردند نسبت به عملیات و تشخیصات و تصمیماتی که راجع '
  'به\u200cتقسیم وجوه قبل از آمدن آنها به عمل آمده حق هیچ گونه اعتراضی ندارند ولی در تقسیماتی که ممکن است به عمل آید '
  'جزء غرما حساب می\u200cشوندبدون اینکه حق داشته باشند حصه را که در تقسیمات سابق به آنها تعلق می\u200cگرفت از اموالی '
  'که هنوز تقسیم نشده مطالبه نمایند.'),
 (474,
  'اگر اشخاصی نسبت به اموال متصرفی تاجر ورشکسته دعوی خیاراتی دارند و صرفنظر از آن نمی\u200cکنند باید آن را در حین '
  'تصفیه عمل\u200cورشکستگی ثابت نموده و به موقع اجرا گذارند.'),
 (475,
  'حکم فوق درباره دعوی خیاراتی نیز مجری خواهد بود که تاجر ورشکسته نسبت به اموال متصرفی خود یا دیگران دارد مشروط '
  'براینکه بر ضرر طلبکارها نباشد.'),
 (476,
  'عضو ناظر در ظرف هشت روز از تاریخ موعدی که به موجب نظامنامه مذکور در ماده ۴۶۷ معین شده به توسط دفتردار محکمه '
  'کلیه\u200cطلبکارهایی را که طلب آنها تشخیص و تصدیق یا موقتاً قبول شده\u200cاست برای مشاوره در انعقاد قرارداد '
  'ارفاقی دعوت می\u200cنماید - موضوع دعوت مجمع\u200cعمومی طلبکارها در رقعه\u200cهای دعوت و اعلانات مندرجه در جراید '
  'باید تصریح شود.'),
 (477,
  'مجمع عمومی مزبور در محل و روز و ساعتی که از طرف عضو ناظر معین شده\u200cاست در تحت ریاست مشارالیه منعقد '
  'می\u200cشود -\u200cطلبکارهایی که طلب آنها تشخیص و تصدیق شده\u200cاست و همچنین طلبکارهایی که طلب آنها موقتاً قبول '
  'گردیده یا وکیل ثابت\u200cالوکاله آنها حاضرمی\u200cشوند تاجر ورشکسته نیز به این مجمع احضار می\u200cشود مشارالیه '
  'باید شخصاً حاضر گردد و فقط وقتی می\u200cتواند اعزام وکیل نماید که عذر موجه داشته\u200cو صحت آن به تصدیق عضو ناظر '
  'رسیده باشد.'),
 (478,
  'مدیر تصفیه به مجمع طلبکارها راپورتی از وضعیت ورشکستگی و اقداماتی که به عمل آمده و عملیاتی که با استحضار تاجر '
  'ورشکسته\u200cشده\u200cاست می\u200cدهد راپورت مزبور به امضاء مدیر تصفیه رسیده به عضو ناظر تقدیم می\u200cشود و عضو '
  'ناظر باید از کلیه مذاکرات و تصمیمات مجمع\u200cطلبکارها صورت مجلسی ترتیب دهد. فقره اول - در ترتیب قرارداد ارفاقی'),
 (479,
  'قرارداد ارفاقی تاجر ورشکسته و طلبکارهای او منعقد نمی\u200cشود مگر پس از اجرای مراسمی که در فوق مقرر '
  'شده\u200cاست.'),
 (480,
  'قرارداد ارفاقی فقط وقتی منعقد می\u200cشود که لااقل نصف به علاوه یک نفر از طلبکارها با داشتن لااقل سه ربع از کلیه '
  'مطالباتی که مطابق\u200cمبحث پنجم از فصل ششم تشخیص و تصدیق شده یا موقتاً قبول گشته\u200cاست در آن قرارداد شرکت '
  'نموده باشند و الا بلااثر خواهد بود.'),
 (481,
  'هر گاه در مجلس قرارداد ارفاقی اکثریت طلبکارها عدداً حاضر شوند ولی از حیث مبلغ دارای سه ربع از مطالبات نباشند یا '
  'آنکه دارای\u200cسه ربع از مطالبات باشند ولی اکثریت عددی را حائز نباشند نتیجه حاصله از آن مجلس معلق و قرار انعقاد '
  'مجلس ثانی برای یک هفته بعد داده می\u200cشود.'),
 (482,
  'طلبکارهایی که در مجلس اول خود یا وکیل ثابت\u200cالوکاله آنها حاضر بوده و صورت\u200cمجلس را امضاء نموده\u200cاند '
  'مجبور نیستند در مجلس\u200cثانی حاضر شوند مگر آنکه بخواهند در تصمیم خود تغییری دهند ولی اگر حاضر نشدند تصمیمات '
  'سابق آنها به اعتبار خود باقی است - اگر در جلسه\u200cثانی اکثریت عددی و مبلغی مطابق ماده ۴۸۰ تکمیل شود قرارداد '
  'ارفاقی قطعی خواهد بود.'),
 (483,
  'اگر تاجر به عنوان ورشکسته به تقلب محکم شده باشد قرارداد ارفاقی منعقد نمی\u200cشود - در موقعی که تاجر به عنوان '
  'ورشکسته به تقلب\u200cتعقیب می\u200cشود لازم است طلبکارها دعوت شوند و معلوم کنند که آیا با احتمال حصول برائت تاجر '
  'و انعقاد قرارداد ارفاقی تصمیم خود را در امرمشارالیه به زمان حصول نتیجه رسیدگی به تقلب موکول خواهند کرد یا تصمیم '
  'فوری خواهند گرفت اگر بخواهند تصمیم را موکول به زمان بعد نمایندباید طلبکارهای حاضر از حیث عده و از حیث مبلغ اکثریت '
  'معین در ماده ۴۸۰ را حائز باشند چنانچه در انقضای مدت و حصول نتیجه رسیدگی به\u200cتقلب بنای انعقاد قرارداد ارفاقی '
  'شود قواعدی که به موجب مواد قبل مقرر است در این موقع نیز باید معمول گردد.'),
 (484,
  'اگر تاجر به عنوان ورشکستگی به تقصیر محکوم شود انعقاد قرارداد ارفاقی ممکن است لیکن در صورتی که تعقیب تاجر شروع '
  'شده\u200cباشد طلبکارها می\u200cتوانند تا حصول نتیجه تعقیب و با رعایت مقررات ماده قبل تصمیم در قرارداد را تأخیر '
  'بیندازند.'),
 (485,
  'کلیه طلبکارها که حق شرکت در انعقاد قرارداد ارفاقی داشته\u200cاند می\u200cتوانند راجع به قرارداد اعتراض کنند - '
  'اعتراض باید موجه بوده و درظرف یک هفته از تاریخ قرارداد به مدیر تصفیه و خود تاجر ورشکسته ابلاغ شود و الا از درجه '
  'اعتبار ساقط خواهد بود. مدیر تصفیه و تاجر ورشکسته به اولین جلسه محکمه که به عمل ورشکستگی رسیدگی می\u200cکنند احضار '
  'می\u200cشوند.'),
 (486,
  'قرارداد ارفاقی باید به تصدیق محکمه برسد و هر یک از طرفین قرارداد می\u200cتوانند تصدیق آن را از محکمه تقاضا نماید. '
  'محکمه نمی\u200cتواند قبل از انقضای مدت یک هفته مذکور در ماده قبل تصمیمی راجع به تصدیق اتخاذ نماید - هر گاه در ظرف '
  'این مدت از طرف\u200cطلبکارهایی که حق اعتراض دارند اعتراضاتی به عمل آمده باشد محکمه باید در موضوع اعتراضات و تصدیق '
  'قرارداد ارفاقی حکم واحد صادر کند -\u200cاگر اعتراضات تصدیق شود قرارداد نسبت به تمام اشخاص ذینفع بلااثر '
  'می\u200cشود.'),
 (487,
  'قبل از آن که محکمه در باب تصدیق قرارداد رأی دهد عضو ناظر باید راپورتی که متضمن کیفیت ورشکستگی و امکان قبول '
  'قراردادباشد به محکمه تقدیم نماید.'),
 (488,
  'در صورت عدم رعایت قواعد مقرره محکمه از تصدیق قرارداد ارفاقی امتناع خواهد نمود. فقره دوم - در اثرات قرارداد '
  'ارفاقی'),
 (489,
  'همین که قرارداد ارفاقی تصدیق شد نسبت به طلبکارهایی که در اکثریت بوده\u200cاند یا در ظرف ده روز از تاریخ تصدیق آن '
  'را امضاء نموده\u200cاندقطعی خواهد بود ولی طلبکارهایی که جزو اکثریت نبوده و قرارداد را هم امضاء نکرده\u200cاند '
  'می\u200cتوانند سهم خود را موافق آنچه از دارایی تاجر به طلبکارهامی\u200cرسد دریافت نمایند لیکن حق ندارند در آتیه '
  'از دارایی تاجر ورشکسته بقیه طلب خود را مطالبه کنند مگر پس از تأدیه تمام طلب کسانی که در قراردادارفاقی شرکت داشته '
  'یا آن را در ظرف ده روز مزبور امضاء نموده\u200cاند.'),
 (490,
  'پس از تصدیق شدن قرارداد ارفاقی دعوی بطلان نسبت به آن قبول نمی\u200cشود مگر اینکه پس از تصدیق مکشوف شود که در '
  'میزان دارایی\u200cیا مقدار قروض حیله به کار رفته و قدر حقیقی قلمداد نشده\u200cاست.'),
 (491,
  'همین که حکم محکمه راجع به تصدیق قرارداد قطعی شد مدیر تصفیه صورت\u200cحساب کاملی با حضور عضو ناظر به تاجر '
  'ورشکسته\u200cمی\u200cدهد که در صورت عدم اختلاف بسته می\u200cشود - مدیر تصفیه کلیه دفاتر و اسناد و نوشتجات و '
  'همچنین دارایی ورشکسته را به استثنای آنچه که بایدبه طلبکارانی که قرارداد ارفاقی را امضاء نکرده\u200cاند داده شود '
  'به مشارالیه رد کرده رسید می\u200cگیرد و پس از آنکه قرار تأدیه سهم طلبکاران مذکور را دادمأموریت مدیر تصفیه ختم '
  'می\u200cشود - از تمام این مراتب عضو ناظر صورت\u200cمجلسی تهیه می\u200cنماید و مأموریتش خاتمه می\u200cیابد - در '
  'صورت تولیداختلاف محکمه رسیدگی کرده حکم مقتضی خواهد داد. فقره سوم - در ابطال یا فسخ قرارداد ارفاقی'),
 (492, 'در مورد ذیل قرارداد ارفاقی باطل است:'),
 (493,
  'اگر محکمه حکم بطلان قرارداد ارفاقی را بدهد ضمانت ضامن یا ضامنها (\u200cدر صورتی که باشد) به خودی خود ملغی '
  'می\u200cشود.'),
 (494,
  'اگر تاجر ورشکسته شرایط قرارداد ارفاقی را اجرا نکرد ممکن است برای فسخ قرارداد مزبور بر علیه او اقامه دعوی نمود.'),
 (495,
  'در صورتی که اجرای تمام یا قسمتی از قرارداد را یک یا چند نفر ضمانت کرده باشند طلبکارها می\u200cتوانند اجرای تمام '
  'یا قسمتی از قراردادرا که ضامن دارد از او بخواهند و در مورد اخیر آن قسمت از قرارداد که ضامن نداشته فسخ '
  'می\u200cشود. در صورت تعدد ضامن مسئولیت آنها تضامنی است.'),
 (496,
  'اگر تاجر ورشکسته پس از تصدیق قرارداد به عنوان ورشکستگی به تقلب تعقیب شده در تحت توقیف یا حبس در آید محکمه '
  'می\u200cتواندهر قسم وسایل تأمینیه را که مقتضی بداند اتخاذ کند ولی به محض صدور قرار منع تعقیب یا حکم تبرئه وسائل '
  'مزبوره مرتفع می\u200cشود.'),
 (497,
  'پس از صدور حکم ورشکستگی به تقلب یا حکم ابطال یا فسخ قرارداد ارفاقی محکمه یک عضو ناظر و یک مدیر تصفیه معین '
  'می\u200cکند.'),
 (498,
  'مدیر تصفیه می\u200cتواند دارایی تاجر را توقیف و مهر و موم نماید مدیر تصفیه فوراً از روی صورت دارایی سابق اقدام به '
  'رسیدگی اسناد ونوشتجات نموده و اگر لازم باشد متممی برای صورت دارایی ترتیب می\u200cدهد مدیر تصفیه باید فوراً به '
  'وسیله اعلان در روزنامه طلبکارهای جدید را اگرباشند دعوت نماید که در ظرف یک ماه اسناد مطالبات خود را برای رسیدگی '
  'ابراز کنند - در اعلان مزبور مفاد قرار محکمه که به موجب آن مدیر تصفیه\u200cمعین شده\u200cاست باید درج شود.'),
 (499,
  'بدون فوت وقت به اسنادی که مطابق ماده قبل ابراز شده رسیدگی می\u200cشود - نسبت به مطالباتی که سابقاً تشخیص یا تصدیق '
  'شده است\u200cرسیدگی جدید به عمل نمی\u200cآید - مطالباتی که تمام یا قسمتی از آنها بعد از تصدیق پرداخته '
  'شده\u200cاست موضوع می\u200cشود.'),
 (500,
  'معاملاتی که تاجر ورشکسته پس از صدور حکم راجع به تصدیق قرارداد ارفاقی تا صدور حکم بطلان یا فسخ قرارداد مزبور نموده '
  'باطل\u200cنمی\u200cشود مگر در صورتی که معلوم شود به قصد اضرار بوده و به ضرر طلبکاران هم باشد.'),
 (501,
  'در صورت فسخ یا ابطال قرارداد ارفاقی دارایی تاجر بین طلبکاران ارفاقی و اشخاصی که بعد از قرارداد ارفاقی طلبکار '
  'شده\u200cاند به غرماتقسیم می\u200cشود.'),
 (502,
  'اگر طلبکاران ارفاقی بعد از توقف تاجر تا زمان فسخ یا ابطال چیزی گرفته\u200cاند مأخوذی آنها از وجهی که به ترتیب '
  'غرما به آنها می\u200cرسدکسر خواهد شد.'),
 (503,
  'هر گاه تاجری ورشکست و امرش منتهی به قرارداد ارفاقی گردید و ثانیاً بدون اینکه قرارداد مزبور ابطال یا فسخ شود '
  'ورشکست شدمقررات دو ماده قبل در ورشکستگی ثانوی لازم\u200cالاجرا است.'),
 (504, 'اگر قرارداد ارفاقی منعقد نشد مدیر تصفیه فوراً به عملیات تصفیه و تفریغ عمل ورشکستگی شروع خواهد کرد.'),
 (505,
  'در صورتی که اکثریت مذکور در ماده (۴۸۰) موافقت نماید محکمه مبلغی را برای اعاشه ورشکسته در حدود مقررات ماده ۴۴۷ '
  'معین\u200cخواهد کرد.'),
 (506,
  'اگر شرکت تضامنی - مختلط یا نسبی ورشکست شود طلبکارها می\u200cتوانند قرارداد ارفاقی را با شرکت یا منحصراً با یک یا '
  'چند نفر ازشرکاء ضامن منعقد نمایند. در صورت ثانی دارایی شرکت تابع مقررات این مبحث و به غرما تقسیم می\u200cشود ولی '
  'دارایی شخصی شرکایی که با آنهاقرارداد ارفاقی منعقد شده\u200cاست به غرما تقسیم نخواهد شد - شریک یا شرکاء ضامن که با '
  'آنها قرارداد خصوصی منعقد شده نمی\u200cتوانند تعهد حصه\u200cنمایند مگر از اموال شخصی خودشان - شریکی که با او '
  'قرارداد مخصوص منعقد شده از مسئولیت ضمانتی مبری است.'),
 (507,
  'اگر طلبکارها بخواهند تجارت تاجر ورشکسته را ادامه دهند می\u200cتوانند برای این امر وکیل یا عامل مخصوصی انتخاب '
  'نموده یا به خودمدیر تصفیه این مأموریت را بدهند.'),
 (508,
  'در ضمن تصمیمی که وکالت مذکور در ماده فوق را مقرر می\u200cدارد باید مدت و حدود وکالت و همچنین میزان وجهی که وکیل '
  'می\u200cتواندبرای مخارج لازمه پیش خود نگاهدارد معین گردد - تصمیم مذکور اتخاذ نمی\u200cشود مگر با حضور عضو ناظر و '
  'با اکثریت سه ربع از طلبکارها عدداً ومبلغاً - خود تاجر ورشکسته و همچنین طلبکارهای مخالف (\u200cبا رعایت ماده ۴۷۳) '
  'می\u200cتوانند نسبت به این تصمیم در محکمه اعتراض نمایند - این\u200cاعتراض اجرای تصمیم را به تأخیر '
  'نمی\u200cاندازد.'),
 (509,
  'اگر از معاملات وکیل یا عاملی که تجارت ورشکسته را ادامه می\u200cدهد تعهداتی حاصل شود که بیش از حد دارایی تاجر '
  'ورشکسته است\u200cفقط طلبکارهایی که آن اجازه را داده\u200cاند شخصاً علاوه بر حصه که در دارایی مزبور دارند به نسبت '
  'طلبشان در حدود اختیاراتی که داده\u200cاند مسئول\u200cتعهدات مذکوره می\u200cباشند.'),
 (510,
  'در صورتی که عمل تاجر ورشکسته منجر به تفریغ حساب شود مدیر تصفیه مکلف است تمام اموال منقول و غیر منقول تاجرورشکسته '
  'را به فروش رسانیده مطالبات و دیون و حقوق او را صلح و مصالحه و وصول و تفریغ کند تمام این مراتب در تحت نظر عضو ناظر '
  'و باحضور تاجر ورشکسته به عمل می\u200cآید. اگر تاجر ورشکسته از حضور استنکاف نمود استحضار مدعی\u200cالعموم کافی است '
  '- فروش اموال مطابق نظامنامه\u200cوزارت عدلیه به عمل خواهد آمد.'),
 (511,
  'همین که تفریغ عمل تاجر به اتمام رسید عضو ناظر طلبکارها و تاجر ورشکسته را دعوت می\u200cنماید. در این جلسه مدیر '
  'تصفیه حساب\u200cخود را خواهد داد.'),
 (512,
  'هر گاه اموالی در اجاره تاجر ورشکسته باشد مدیر تصفیه در فسخ یا ابقاء اجاره به نحوی که موافق منافع طلبکارها باشد '
  'اتخاذ تصمیم\u200cمی\u200cکند - اگر تصمیم بر فسخ اجاره شده صاحبان اموال مستأجره از بابت مال\u200cالاجاره که تا آن '
  'تاریخ مستحق شده\u200cاند جزو غرما منظور می\u200cشوند اگرتصمیم بر ابقاء اجاره بوده و تأمیناتی هم سابقاً به موجب '
  'اجاره\u200cنامه به موجر داده شده باشد آن تأمینات ابقاء خواهد شد و الا تأمیناتی که پس ازورشکستگی داده می\u200cشود '
  'باید کافی باشد - در صورتی که با تصمیم مدیر تصفیه بر فسخ اجاره موجر راضی به فسخ نشود حق مطالبه تأمین را نخواهد '
  'داشت.'),
 (513,
  'مدیر تصفیه می\u200cتواند با اجازه عضو ناظر اجاره را برای بقیه مدت به دیگری تفویض نماید (\u200cمشروط بر اینکه به '
  'موجب قرارداد کتبی\u200cطرفین این حق منع نشده باشد) و در صورت تفویض به غیر باید وثیقه کافی که تأمین پرداخت '
  'مال\u200cالاجاره را بنماید به مالک اموال مستأجره داده و کلیه\u200cشرایط و مقررات اجاره\u200cنامه را به موقع خود '
  'اجرا کند.'),
 (514, 'طلبکارهایی که رهینه در دست دارند فقط در صورت غرما برای یادداشت قید می\u200cشوند.'),
 (515,
  'مدیر تصفیه می\u200cتواند در هر موقع با اجازه عضو ناظر طلب طلبکارها را داده و شیء مرهون را از رهن خارج و جزو '
  'دارایی تاجرورشکسته منظور دارد.'),
 (516,
  'اگر وثیقه فک نشود مدیر تصفیه باید با نظارت مدعی\u200cالعموم آن را به فروش برساند و مرتهن نیز در آن موقع باید دعوت '
  'شود. اگر قیمت\u200cفروش وثیقه پس از وضع مخارج بیش از طلب طلبکار باشد مازاد به مدیر تصفیه تسلیم می\u200cشود و اگر '
  'قیمت فروش کمتر شد مرتهن برای بقیه طلب\u200cخود در جزو طلبکارهای عادی در غرما منظور خواهد شد.'),
 (517,
  'مدیر تصفیه صورت طلبکارهایی را که ادعای وثیقه می\u200cنمایند به عضو ناظر تقدیم می\u200cکند. عضو مزبور در صورت لزوم '
  'اجازه می\u200cدهدطلب آنها از اولین وجوهی که تهیه می\u200cشود پرداخته گردد در صورتی که نسبت به حق وثیقه طلبکارها '
  'اعتراض داشته باشند به محکمه رجوع می\u200cشود.'),
 (518,
  'اگر تقسیم وجوهی که از فروش اموال غیر منقول حاصل شده قبل از تقسیم دارایی منقول یا در همان حین به عمل آمده '
  'باشدطلبکارهایی که نسبت به اموال غیر منقول حقوقی دارند و حاصل فروش اموال مزبور کفایت طلب آنها را ننموده\u200cاست '
  'نسبت به بقیه طلب خود جزوغرما معمولی منظور و از وجوهی که برای غرما مزبور مقرر است حصه می\u200cبرند مشروط بر اینکه '
  'طلب آنها به طوری که قبلاً مذکور شده\u200cاست تصدیق\u200cشده باشد.'),
 (519,
  'اگر قبل از تقسیم وجوهی که از فروش اموال غیر منقول حاصل شده وجهی از بابت دارایی منقول تقسیم شود طلبکارهایی که نسبت '
  'به\u200cاموال غیر منقول حقوقی دارند و طلب آنها تصدیق و اعتراف شده\u200cاست به میزان کلیه طلب خود جزو سایر غرما '
  'وارد و از وجوه مزبوره حصه می\u200cبرندولی عندالاقتضاء مبلغ دریافتی در موقع تقسیم حاصل اموال غیر منقول از طلب آنها '
  'موضوع می\u200cشود.'),
 (520,
  'در مورد طلبکارهایی که نسبت به اموال غیر منقول حقوقی دارند ولی به واسطه مقدم بودن سایر طلبکارها نمی\u200cتوانند در '
  'حین تقسیم\u200cقیمت اموال غیر منقول طلب خود را تماماً وصول کنند ترتیب ذیل مرعی خواهد بود: اگر طلبکارهای مزبور قبل '
  'از تقسیم حاصل اموال غیر منقول از بابت طلب خود وجهی دریافت داشته باشند این مبلغ از حصه که از بابت اموال غیرمنقول '
  'به آنها تعلق می\u200cگیرد موضوع و به حصه که باید بین طلبکارهای معمولی تقسیم شود اضافه می\u200cگردد و بقیه '
  'طلبکارهایی که در اموال غیر منقول\u200cذیحق بوده\u200cاند برای بقیه طلب خود نسبت آن بقیه جزو غرما محسوب شده حصه '
  'می\u200cبرند.'),
 (521,
  'اگر به واسطه مقدم بودن طلبکارهای دیگر بعضی از طلبکارهایی که نسبت به اموال غیر منقول حقی دارند وجهی دریافت نکنند '
  'طلب\u200cآنها جزو غرما محسوب و بدین سمت هر معامله که از بابت قرارداد ارفاقی و غیره با غرما می\u200cشود با آنها '
  'نیز به عمل خواهد آمد.'),
 (522,
  'پس از وضع مخارج اداره امور و ورشکستگی و اعانه که ممکن است به تاجر ورشکسته داده شده باشد و وجوهی که باید به '
  'صاحبان\u200cمطالبات ممتازه تأدیه گردد مجموع دارایی منقول بین طلبکارها به نسبت طلب آنها که قبلاً تشخیص و تصدیق '
  'شده\u200cاست خواهد شد.'),
 (523,
  'مدیر تصفیه برای اجرای مقصود مذکور در ماده فوق ماهی یک مرتبه صورت\u200cحساب عمل ورشکستگی را با تعیین وجوه موجوده '
  'به\u200cعضو ناظر می\u200cدهد. عضو مذکور در صورت لزوم امر به تقسیم وجوه مزبور بین طلبکارها داده مبلغ آن را معین و '
  'مواظبت می\u200cنماید که به تمام طلبکارهااطلاع داده شود.'),
 (524,
  'در موقع تقسیم وجه بین طلبکارها حصه طلبکارهای مقیم ممالک خارجه به نسبت طلب آنها که در صورت دارایی و قروض '
  'منظورشده\u200cاست موضوع می\u200cگردد. چنانچه مطالبات مزبور صحیحاً در صورت دارایی و قروض منظور نشده باشد عضو ناظر '
  'می\u200cتواند حصه موضوعی را زیادکند. برای مطالباتی که هنوز در باب آنها تصمیم قطعی اتخاذ نشده\u200cاست باید مبلغی '
  'موضوع کرد.'),
 (525,
  'وجوهی که برای طلبکارهای مقیم خارجه موضوع شده\u200cاست تا مدتی که قانون برای آنها معین کرده به طور امانت به صندوق '
  'عدلیه\u200cسپرده خواهد شد - اگر طلبکارهای مذکور مطابق این قانون مطالبات خود را به تصدیق نرسانند مبلغ مزبور بین '
  'طلبکارهایی که طلب آنها به تصدیق\u200cرسیده تقسیم می\u200cگردد. وجوهی که برای مطالبات تصدیق\u200cنشده موضوع گردیده '
  'در صورت عدم تصدیق آن مطالبات بین طلبکارهایی که طلب آنها تصدیق شده تقسیم می\u200cشود.'),
 (526,
  'هیچ طلبی را مدیر تصفیه نمی\u200cپردازد مگر آنکه مدارک و اسناد آن را قبلاً ملاحظه کرده باشد مدیر تصفیه مبلغی را که '
  'پرداخته در روی\u200cسند قید می\u200cکند عضو ناظر در صورت عدم امکان ابراز سند می\u200cتواند اجازه دهد که به موجب '
  'صورت\u200cمجلسی که طلب در آن تصدیق شده وجهی\u200cپرداخته شود در هر حال باید طلبکارها رسید وجه را در ذیل صورت '
  'تقسیم ذکر کنند.'),
 (527,
  'ممکن است هیأت طلبکارها با استحضار تاجر ورشکسته از محکمه تحصیل اجازه نمایند که تمام یا قسمتی از حقوق و مطالبات '
  'تاجرورشکسته را که هنوز وصول نشده به طوری که صرفه و صلاح تاجر ورشکسته هم منظور شود خودشان قبول و مورد معامله قرار '
  'دهند در این صورت\u200cمدیر تصفیه اقدامات مقتضیه را به عمل خواهد آورد - در این خصوص هر طلبکاری می\u200cتواند به '
  'عضو ناظر مراجعه کرده تقاضا نماید که طلبکارهای\u200cدیگر را عودت نماید تا تصمیم خود را اتخاذ بنمایند.'),
 (528,
  'اگر قبل از ورشکستگی تاجر کسی اوراق تجارتی به او داده باشد که وجه آن را وصول و به حساب صاحب سند نگاهدارد و یا '
  'به\u200cمصرف معینی برساند و وجه اوراق مزبور وصول یا تأدیه نگشته و اسناد عیناً در حین ورشکستگی در نزد تاجر ورشکسته '
  'موجود باشد صاحبان آن\u200cمی\u200cتوانند عین اسناد را استرداد کنند.'),
 (529,
  'مال\u200cالتجاره\u200cهایی که در نزد تاجر ورشکسته امانت بوده یا به مشارالیه داده شده\u200cاست که به حساب صاحب '
  'مال\u200cالتجاره به فروش برساندمادام که عین آنها کلاً یا جزئاً نزد تاجر ورشکسته موجود یا نزد شخص دیگری از طرف '
  'تاجر مزبور به امانت یا برای فروش گذارده شده و موجود باشدقابل استرداد است.'),
 (530,
  'مال\u200cالتجاره\u200cهایی که تاجر ورشکسته به حساب دیگری خریداری کرده و عین آن موجود است اگر قیمت آن پرداخته نشده '
  'باشد از طرف\u200cفروشنده و الا از طرف کسی که به حساب او آن مال خریداری شده قابل استرداد است.'),
 (531,
  'هر گاه تمام یا قسمتی از مال\u200cالتجاره که برای فروش به تاجر ورشکسته داده شده بود معامله شده و به هیچ نحوی بین '
  'خریدار و تاجرورشکسته احتساب نشده باشد از طرف صاحب مال قابل استرداد است اعم از اینکه نزد تاجر ورشکسته یا خریدار '
  'باشد و به طور کلی عین هر مال\u200cمتعلق به دیگری که در نزد تاجر ورشکسته موجود باشد قابل استرداد است.'),
 (532,
  'اگر مال\u200cالتجاره که برای تاجر ورشکسته حمل شده قبل از وصول از روی صورت\u200cحساب یا بارنامه که دارای امضاء '
  'ارسال\u200cکننده\u200cاست به\u200cفروش رسیده و فروش صوری نباشد دعوی استرداد پذیرفته نمی\u200cشود و الا موافق ماده '
  '۵۲۹ قابل استرداد است و استردادکننده باید وجوهی را که به\u200cطور علی\u200cالحساب گرفته یا مساعدتاً از بابت کرایه '
  'حمل و حق کمیسیون و بیمه و غیره تأدیه شده یا از این بابت\u200cها باید تأدیه بشود به طلبکارها بپردازند.'),
 (533,
  'هر گاه کسی مال\u200cالتجاره به تاجر ورشکسته فروخته ولیکن هنوز آن جنس نه به خود تاجر ورشکسته تسلیم شده و نه به کس '
  'دیگر که به\u200cحساب او بیاورد آن کس می\u200cتواند به اندازه که وجه آن را نگرفته از تسلیم مال\u200cالتجاره امتناع '
  'کند.'),
 (534,
  'در مورد دو ماده قبل مدیر تصفیه می\u200cتواند با اجازه عضو ناظر تسلیم مال\u200cالتجاره را تقاضا نماید ولی باید '
  'قیمتی را که بین فروشنده و تاجرورشکسته مقرر شده\u200cاست بپردازد.'),
 (535,
  'مدیر تصفیه می\u200cتواند با تصویب عضو ناظر تقاضای استرداد را قبول نماید و در صورت اختلاف محکمه پس از استماع عقیده '
  'عضو ناظرحکم مقتضی را می\u200cدهد.'),
 (536,
  'حکم اعلان ورشکستگی و همچنین حکمی که به موجب آن تاریخ توقف تاجر در زمانی قبل از اعلان ورشکستگی تشخیص شود '
  'قابل\u200cاعتراض است.'),
 (537,
  'اعتراض باید از طرف تاجر ورشکسته در ظرف ده روز و از طرف اشخاص ذینفع که در ایران مقیمند در ظرف یک ماه و از طرف '
  'آنهایی\u200cکه در خارجه اقامت دارند در ظرف دو ماه به عمل آید ابتدای مدتهای مزبور از تاریخی است که احکام مذکوره '
  'اعلان می\u200cشود.'),
 (538,
  'پس از انقضای مهلتی که برای تشخیص و تصدیق مطالبات طلبکارها معین شده\u200cاست دیگر هیچ تقاضایی از طرف طلبکارها راجع '
  'به\u200cتعیین تاریخ توقف به غیر آن تاریخی که به موجب حکم ورشکستگی یا حکم دیگری که در این باب صادر شده قبول نخواهد '
  'شد - همین که مهلتهای\u200cمزبور منقضی شد تاریخ توقف نسبت به طلبکارها قطعی و غیر قابل تغییر خواهد بود.'),
 (539,
  'مهلت استیناف از حکم ورشکستگی ده روز از تاریخ ابلاغ است - به این مدت برای کسانی که محل اقامت آنها از مقر محکمه بیش '
  'ازشش فرسخ فاصله دارد از قرار هر شش فرسخ یک روز اضافه می\u200cشود.'),
 (540,
  'قرارهای ذیل قابل اعتراض و استیناف و تمیز نیست: ۱) قرارهای راجعه به تعیین یا تغییر عضو ناظر یا مدیر تصفیه. ۲) '
  'قرارهای راجعه به تقاضای اعانه به جهت تاجر ورشکسته یا خانواده او. ۳) قرارهای فروش اسباب یا مال\u200cالتجاره که '
  'متعلق به ورشکسته\u200cاست. ۴) قرارهایی که قرارداد ارفاقی را موقتاً موقوف یا قبول موقتی مطالبات متنازع\u200cفیه را '
  'مقرر می\u200cدارد. ۵) قرارهای صادره در خصوص شکایت از اوامری که عضو ناظر در حدود صلاحیت خود صادر کرده\u200cاست.'),
 (541,
  'تاجر در موارد ذیل ورشکسته به تقصیر اعلان می\u200cشود: ۱) در صورتی که محقق شود مخارج شخصی یا مخارج خانه مشارالیه '
  'در ایام عادی بالنسبه به عایدی او فوق\u200cالعاده بوده\u200cاست. ۲) در صورتی که محقق شود که تاجر نسبت به سرمایه '
  'خود مبالغ عمده صرف معاملاتی کرده که در عرف تجارت موهوم یا نفع آن منوط به اتفاق\u200cمحض است. ۳) اگر به قصد تأخیر '
  'انداختن ورشکستگی خود خریدی بالاتر یا فروشی نازلتر از مظنه روز کرده باشد یا اگر به همان قصد وسایلی که دور از '
  'صرفه\u200cاست به کار برده تا تحصیل وجهی نماید اعم از اینکه از راه استقراض یا صدور برات یا به طریق دیگر باشد. ۴) '
  'اگر یکی از طلبکارها را پس از تاریخ توقف بر سایرین ترجیح داده و طلب او را پرداخته باشد.'),
 (542,
  'در موارد ذیل هر تاجر ورشکسته ممکن است ورشکسته به تقصیر اعلان شود: ۱) اگر به حساب دیگری و بدون آنکه در مقابل عوضی '
  'دریافت نماید تعهداتی کرده باشد که نظر به وضعیت مالی او در حین انجام آنها آن تعهدات\u200cفوق\u200cالعاده باشد. ۲) '
  'اگر عملیات تجارتی او متوقف شده و مطابق ماده ۴۱۳ این قانون رفتار نکرده باشد. ۳) اگر از تاریخ اجرای قانون تجارت '
  'مصوب ۲۵ دلو ۱۳۰۳ و ۱۲ فروردین و ۱۲ خرداد ۱۳۰۴ دفتر نداشته یا دفاتر او ناقص یا بی\u200cترتیب بوده یا درصورت دارایی '
  'وضعیت حقوقی خود را اعم از قروض و مطالبات به طور صحیح معین نکرده باشد (\u200cمشروط بر اینکه در این موارد مرتکب '
  'تقلبی نشده\u200cباشد).'),
 (543, 'ورشکستگی به تقصیر جنحه محسوب و مجازات آن از ۶ ماه تا سه سال حبس تأدیبی است.'),
 (544,
  'رسیدگی به جرم فوق بر حسب تقاضای مدیر تصفیه یا هر یک از طلبکارها یا تعقیب مدعی\u200cالعموم در محکمه جنحه به عمل '
  'می\u200cآید.'),
 (545,
  'در صورتی که تعقیب تاجر ورشکسته به تقصیر از طرف مدعی\u200cالعموم به عمل آمده باشد مخارج آن را به هیچ وجه '
  'نمی\u200cتوان به هیأت\u200cطلبکارها تحمیل نمود - در صورت انعقاد قرارداد ارفاقی مأمورین اجرا نمی\u200cتوانند اقدام '
  'به وصول این مخارج کنند مگر پس از انقضای مدتهای معینه درقرارداد.'),
 (546,
  'مخارج تعقیبی که از طرف مدیر تصفیه به نام طلبکارها می\u200cشود در صورت برائت تاجر به عهده هیأت طلبکارها و در صورتی '
  'که محکوم\u200cشد به عهده دولت است لیکن دولت حق دارد مطابق ماده قبل به تاجر ورشکسته مراجعه نماید.'),
 (547,
  'مدیر تصفیه نمی\u200cتواند تاجر ورشکسته را به عنوان ورشکستگی به تقصیر تعقیب کند یا از طرف هیأت طلبکارها مدعی خصوصی '
  'واقع\u200cشود مگر پس از تصویب اکثریت طلبکارهای حاضر.'),
 (548,
  'مخارج تعقیبی که از طرف یکی از طلبکارها به عمل می\u200cآید در صورت محکومیت تاجر ورشکسته به عهده دولت و در صورت '
  'برائت\u200cذمه به عهده تعقیب\u200cکننده\u200cاست.'),
 (549,
  'هر تاجر ورشکسته که دفاتر خود را مفقود نموده یا قسمتی از دارایی خود را مخفی کرده و یا به طریق مواضعه و معاملات '
  'صوری ازمیان برده و همچنین هر تاجر ورشکسته که خود را به وسیله اسناد و یا به وسیله صورت دارایی و قروض به طور تقلب '
  'به میزانی که در حقیقت مدیون\u200cنمی\u200cباشد مدیون قلمداد نموده\u200cاست ورشکسته به تقلب اعلام و مطابق قانون '
  'جزا مجازات می\u200cشود.'),
 (550, 'راجع به تقاضای تعقیب و مخارج آن در موارد ماده قبل مفاد مواد ۵۴۵ تا ۵۴۸ لازم\u200cالرعایه\u200cاست.'),
 (551,
  'در مورد ورشکستگی اشخاص ذیل مجرم محسوب و مطابق قانون جزا به مجازات ورشکسته به تقلب محکوم خواهند شد: ۱) اشخاصی که '
  'عالماً به نفع تاجر ورشکسته تمام یا قسمتی از دارایی منقول یا غیر منقول او را از میان ببرند یا پیش خود نگاهدارند یا '
  'مخفی\u200cنمایند. ۲) اشخاصی که به قصد تقلب به اسم خود یا به اسم دیگری طلب غیر مواقعی را قلمداد کرده و مطابق ماده '
  '۴۶۷ التزام داده باشند.'),
 (552,
  'اشخاصی که به اسم دیگری یا به اسم موهومی تجارت نموده و اعمال مندرجه در ماده ۵۴۹ را مرتکب شده\u200cاند به مجازاتی '
  'که برای\u200cورشکسته به تقلب مقرر است محکوم می\u200cباشند.'),
 (553,
  'اگر اقوام شخص ورشکسته بدون شرکت مشارالیه اموال او را از میان ببرند یا مخفی نمایند یا پیش خود نگاهدارند به مجازاتی '
  'که برای\u200cسرقت معین است محکوم خواهند شد.'),
 (554,
  'در موارد معینه در مواد قبل محکمه که رسیدگی می\u200cکند باید در خصوص مسائل ذیل ولو اینکه متهم تبرئه شده باشد - حکم '
  'بدهد: ۱) راجع به رد کلیه اموال و حقوقی که موضوع جرم بوده\u200cاست به هیأت طلبکارها - این حکم را محکمه در صورتی که '
  'مدعی خصوصی هم نباشدباید صادر کند. ۲) راجع به ضرر و خساراتی که ادعا شده\u200cاست.'),
 (555,
  'اگر مدیر تصفیه در حین تصدی به امور تاجر ورشکسته وجهی را حیف و میل کرده باشد به مجازات خیانت در امانت محکوم '
  'خواهدشد.'),
 (556,
  'هر گاه مدیر تصفیه اعم از اینکه طلبکار باشد یا نباشد در مذاکرات راجعه به ورشکستگی با شخص ورشکسته یا با دیگری تبانی '
  'نماید یاقرارداد خصوصی منعقد کند که آن تبانی یا قرارداد به نفع مرتکب و به ضرر طلبکارها یا بعضی از آنها باشد در '
  'محکمه جنحه به حبس تأدیبی از شش ماه\u200cتا دو سال محکوم می\u200cشود.'),
 (557,
  'کلیه قراردادهایی که پس از تاریخ توقف تاجر منعقد شده باشد نسبت به هر کس حتی خود تاجر ورشکسته محکوم به بطلان است '
  '-\u200cطرف قرارداد مجبور است که وجوه یا اموالی را که به موجب قرارداد باطل شده دریافت کرده\u200cاست به اشخاص ذیحق '
  'مسترد دارد.'),
 (558, 'هر حکم محکومیتی که به موجب این فصل یا به موجب فصل سابق صادر بشود باید به خرج محکوم\u200cعلیه اعلان گردد.'),
 (559,
  'در تمام مواردی که کسی به واسطه ورشکستگی به تقصیر یا به تقلب تعقیب و محکوم می\u200cشود رسیدگی به کلیه دعاوی حقوقی '
  'به غیراز آنچه در ماده ۵۵۴ مذکور است از صلاحیت محکمه جزا خارج خواهد بود.'),
 (560,
  'مدیر تصفیه مکلف است در صورت تقاضای مدعی\u200cالعموم بدایت کلیه اسناد و نوشتجات و اوراق و اطلاعات لازمه را به او '
  'بدهد.'),
 (561,
  'هر تاجر ورشکسته که کلیه دیون خود را با متفرعات و مخارجی که به آن تعلق گرفته\u200cاست کاملاً بپردازد حقاً اعاده '
  'اعتبار می\u200cنماید.'),
 (562,
  'طلبکارها نمی\u200cتوانند از جهت تأخیری که در اداء طلب آنها شده\u200cاست برای بیش از پنجاه سال مطالبه متفرعات و '
  'خسارت نمایند و در هرحال متفرعاتی که مطالبه می\u200cشود در سال نباید بیش از صدی هفت طلب باشد.'),
 (563,
  'برای آنکه شریک ضامن یک شریک ورشکسته که حکم ورشکستگی او نیز صادر شده بتواند حق اعاده اعتبار حاصل کند باید '
  'ثابت\u200cنماید که به ترتیب فوق تمام دیون شرکت را پرداخته\u200cاست ولو اینکه نسبت به شخص او قرارداد ارفاقی مخصوصی '
  'وجود داشته باشد.'),
 (564,
  'در صورتی که یک یا چند نفر از طلبکارها مفقودالاثر یا غائب بوده یا اینکه از دریافت وجه امتناع نمایند تاجر ورشکسته '
  'باید وجوهی راکه به آنها مدیون است با اطلاع مدعی\u200cالعموم در صندوق عدلیه بسپارد و همین که تاجر معلوم کرد این '
  'وجوه را سپرده\u200cاست بری\u200cالذمه محسوب است.'),
 (565,
  'تجار ورشکسته در دو مورد ذیل پس از اثبات صحت عمل در مدت پنج سال از تاریخ اعلان ورشکستگی می\u200cتوانند اعتبار خود '
  'را اعاده\u200cنمایند: ۱) تاجر ورشکسته که تحصیل قرارداد ارفاقی نموده و تمام وجوهی را که به موجب قرارداد به عهده '
  'گرفته\u200cاست پرداخته باشد. این ترتیب در موردشریک شرکت ورشکسته که شخصاً تحصیل قرارداد ارفاقی جداگانه '
  'نموده\u200cاست نیز رعایت می\u200cشود. ۲) تاجر ورشکسته که کلیه طلبکاران ذمه او را بری کرده یا به اعاده اعتبار او '
  'رضایت داده\u200cاند.'),
 (566,
  'عرضحال اعاده اعتبار باید به انضمام اسناد مثبته آن به مدعی\u200cالعموم حوزه ابتدایی داده شود که اعلان ورشکستگی در '
  'آن حوزه واقع\u200cشده\u200cاست.'),
 (567,
  'سواد این عرضحال در مدت یک ماه در اتاق جلسه محکمه ابتدایی و همچنین در اداره مدعی\u200cالعموم بدایت الصاق و اعلان '
  'می\u200cشود به\u200cعلاوه دفتردار محکمه باید مفاد عرضحال مزبور را به کلیه طلبکارهایی که مطالبات آنها در حین تصفیه '
  'عمل تاجر ورشکسته یا بعد از آن تصدیق شده وهنوز طلب خود را بر طبق مواد ۵۶۱ و ۵۶۲ کاملاً دریافت نکرده\u200cاند به '
  'وسیله مکتوب سفارشی اعلام دارد.'),
 (568,
  'هر طلبکاری که مطابق مقررات مواد ۵۶۱ و ۵۶۲ طلب خود را کاملاً دریافت نکرده می\u200cتواند در مدت یک ماه از تاریخ '
  'اعلام مذکور درماده قبل به عرضحال اعاده اعتبار اعتراض کند.'),
 (569,
  'اعتراض به وسیله اظهارنامه که به ضمیمه اسناد مثبته به دفتر محکمه بدایت داده می\u200cشود به عمل می\u200cآید - '
  'طلبکار معترض می\u200cتواند به\u200cموجب عرضحال در حین رسیدگی به دعوی اعتبار به طور شخص ثالث ورود کند.'),
 (570,
  'پس از انقضای موعد نتیجه تحقیقاتی که به توسط مدعی\u200cالعموم به عمل آمده\u200cاست به انضمام عرایض اعتراض به رییس '
  'محکمه داده\u200cمی\u200cشود رییس مزبور در صورت لزوم مدعی و معترضین را به جلسه خصوصی محکمه احضار می\u200cکند.'),
 (571,
  'در مورد ماده ۵۶۱ محکمه فقط صحت مدارک را سنجیده در صورت موافقت آنها با قانون حکم اعاده اعتبار می\u200cدهد و در '
  'مورد ماده۵۶۵ محکمه اوضاع و احوال را سنجیده به طوری که مقتضی عدل و انصاف بداند حکم می\u200cدهد و در هر دو صورت حکم '
  'باید در جلسه علنی صادرگردد.'),
 (572,
  'مدعی اعاده اعتبار و همچنین مدعی عمومی و طلبکارهای معترض می\u200cتوانند در ظرف ده روز از تاریخ اعلام حکم به وسیله '
  'مکتوب\u200cسفارشی از حکمی که در خصوص اعاده اعتبار صادر شده استیناف بخواهند - محکمه استیناف پس از رسیدگی بر حسب '
  'مقررات ماده ۵۷۱ حکم\u200cصادر می\u200cکند.'),
 (573, 'اگر عرضحال اعاده اعتبار رد بشود تجدید ممکن نیست مگر پس از انقضای شش ماه.'),
 (574,
  'اگر عرضحال قبول شود حکمی که صادر می\u200cگردد در دفتر مخصوصی که در محکمه بدایت محل اقامت تاجر برای این کار مقرر '
  'است\u200cثبت خواهد شد. اگر محل اقامت تاجر در حوزه محکمه که حکم می\u200cدهد نباشد در ستون ملاحظات دفتر ثبت اسامی '
  'ورشکستگان که در دائره ثبت اسناد محل موجوداست مقابل اسم تاجر ورشکسته با مرکب قرمز به حکم مزبور اشاره می\u200cشود.'),
 (575,
  'ورشکستگان به تقبل و همچنین اشخاصی که برای سرقت یا کلاهبرداری یا خیانت در امانت محکوم شده\u200cاند مادامی که از '
  'جنبه جزایی\u200cاعاده حیثیت نکرده\u200cاند نمی\u200cتوانند از جنبه تجارتی اعاده اعتبار کنند.'),
 (576, 'ثبت اسم تجارتی اختیاری است مگر در مواردی که وزارت عدلی ثبت آن را الزامی کند.'),
 (577,
  'صاحب تجارتخانه که شریک در تجارتخانه ندارد نمی\u200cتواند اسمی برای تجارتخانه خود انتخاب کند که موهم وجود شریک '
  'باشد.'),
 (578,
  'اسم تجارتی ثبت شده را هیچ شخص دیگری در همان محل نمی\u200cتواند اسم تجارتی خود قرار دهد ولو اینکه اسم تجارتی ثبت '
  'شده بااسم خانوادگی او یکی باشد.'),
 (579, 'اسم تجارتی قابل انتقال است.'),
 (580, 'مدت اعتبار ثبت اسم تجارتی پنج سال است.'),
 (581,
  'در مواردی که ثبت اسم تجارتی الزامی شده در موعد مقرر ثبت به عمل نیاید اداره ثبت اقدام به ثبت کرده و سه برابر '
  'حق\u200cالثبت مأخوذخواهد داشت.'),
 (582,
  'وزارت عدلیه به موجب نظامنامه ترتیب ثبت اسم تجارتی و اعلان آن و اصول محاکمات در دعاوی مربوطه به اسم تجارتی را '
  'معین\u200cخواهد کرد.'),
 (583, 'کلیه شرکتهای تجارتی مذکور در این قانون شخصیت حقوقی دارند.'),
 (584,
  'تشکیلات و مؤسساتی که برای مقاصد غیر تجارتی تأسیس شده یا بشوند از تاریخ ثبت در دفتر ثبت مخصوصی که وزارت عدلیه '
  'معین\u200cخواهد کرد شخصیت حقوقی پیدا می\u200cکنند.'),
 (585,
  'شرایط ثبت مؤسسات و تشکیلات مذکور در ماده فوق به موجب نظامنامه وزارت عدلیه معین خواهد شد. حق\u200cالثبت مؤسسات و '
  'تشکیلات مطابق نظامنامه از پنج ریال طلا تا پنج پهلوی و به علاوه مشمول ماده ۱۳۵ قانون ثبت اسناد و املاک است.'),
 (586, 'مؤسسات و تشکیلاتی را که مقاصد آنها مخالف با انتظامات عمومی یا نامشروع است نمی\u200cتوان ثبت کرد.'),
 (587, 'مؤسسات و تشکیلات دولتی و بلدی به محض ایجاد و بدون احتیاج به ثبت دارای شخصیت حقوقی می\u200cشوند.'),
 (588,
  'شخص حقوقی می\u200cتواند دارای کلیه حقوق و تکالیفی شود که قانون برای افراد قائل است مگر حقوق و وظائفی که بالطبیعه '
  'فقط انسان\u200cممکن است دارای آن باشد مانند حقوق و وظایف ابوت - نبوت و امثال ذالک.'),
 (589, 'تصمیمات شخص حقوقی به وسیله مقاماتی که به موجب قانون یا اساسنامه صلاحیت اتخاذ تصمیم دارند گرفته می\u200cشود.'),
 (590, 'اقامتگاه شخص حقوقی محلی است که اداره شخص حقوقی در آنجا است.'),
 (591, 'اشخاص حقوقی تابعیت مملکتی را دارند که اقامتگاه آنها در آن مملکت است.'),
 (592,
  'در مورد معاملاتی که سابقاً تجار یا شرکتها و مؤسسات تجارتی به اعتبار بیش از یک امضاء کرده\u200cاند خواه بعضی از '
  'امضاکنندگان به\u200cعنوان ضامن امضاء کرده باشند خواه به عنوان دیگر طلبکار می\u200cتواند به امضاکنندگان مجتمعاً یا '
  'منفرداً رجوع نماید.'),
 (593,
  'در مورد ماده فوق مطالبه از هر یک از اشخاصی که طلبکار حق رجوع به آنها دارد قاطع مرور زمان نسبت به دیگران نیز هست.'),
 (594,
  'به استثنای شرکتهای سهامی و شرکتهای مختلط سهامی به کلیه شرکتهای ایرانی موجود که به امور تجارتی اشتغال دارند تا اول '
  'تیر ماه۱۳۱۱ مهلت داده می\u200cشود که خود را با مقررات یکی از شرکتهای مذکور در این قانون وفق داده و تقاضای ثبت '
  'نمایند و الا نسبت به شرکت متخلف\u200cمطابق ماده دوم قانون ثبت شرکتها مصوب خرداد ماه ۱۳۱۰ رفتار خواهد شد.'),
 (595,
  'هر گاه مدت مذکور در ماده فوق برای تهیه مقدمات ثبت کافی نباشد ممکن است تا شش ماه دیگر از طرف محکمه صلاحیتدار '
  'مهلت\u200cاضافی داده شود مشروط بر اینکه در موقع تقاضای تمدید نصف حق\u200cالثبت شرکت پرداخته شود.'),
 (596,
  'تاریخ اجرای ماده ۱۵ این قانون در آن قسمتی که مربوط به جزای نقدی است و تاریخ اجرای ماده ۲۰۱ و تبصره آن و قسمت اخیر '
  'ماده۲۲۰ اول فروردین ۱۳۱۲ خواهد بود.'),
 (597,
  'شرکت\u200cهای مختلط سهامی موجود مکلف هستند که در ظرف ۶ ماه از تاریخ اجرای این قانون هیأت نظاری مطابق مقررات این '
  'قانون\u200cتشکیل دهند و الا هر صاحب سهمی حق دارد انحلال شرکت را تقاضا کند.'),
 (598,
  'طلبکاران تاجر متوقفی که قبل از تاریخ اجرای این قانون طلب خود را مطالبه کرده\u200cاند مشمول مقررات ماده ۴۷۳ نبوده '
  'و از حقی که به\u200cموجب قانون سابق برای آنها مقرر بوده استفاده خواهند کرد.'),
 (599,
  'نسبت به طلبکارانی که در امور ورشکستگی\u200cهای سابق قبل از تاریخ اجرای این قانون طلب خود را مطالبه نکرده\u200cاند '
  'مدیر تصفیه هرورشکسته اعلانی منتشر کرده و یک ماه به آنها مهلت خواهد داد که مطابق ماده ۴۶۲ این قانون رفتار کنند و '
  'الا مشمول مقررات ماده ۴۷۳ خواهند شد.'),
 (600,
  'قوانین ذیل: قانون تجارت مصوب ۲۵ دلو ۱۳۰۳ و دوازدهم فروردین و دوازدهم خرداد ۱۳۰۴ - قانون اصلاح ماده ۲۰۶ قانون '
  'تجارت راجع به اعتراض عدم تأدیه\u200cمصوب ۲ تیر ماه ۱۳۰۷ - قانون اجازه عدم رعایت ماده ۲۷۰ و قسمتی از ماده ۴۴ قانون '
  'تجارت نسبت به تشکیلات و اساسنامه شرکت سهامی بانک\u200cملی و شرکت سهامی بانک پهلوی مصوب ۳۰ تیر ماه ۱۳۰۷ از تاریخ '
  'اول خرداد ماه ۱۳۱۱ نسخ و این قانون از تاریخ مزبور به موقع اجرا گذاشته\u200cمی\u200cشود.')]

COMMERCIAL_CODE_1311_CURRENT = [(1, 'تاجر کسی است که شغل معمولی خود را معاملات تجارتی قرار بدهد.'),
 (2,
  'معاملات تجارتی از قرار ذیل است: ۱) خرید یا تحصیل هر نوع مال منقوض به قصد فروش یا اجاره اعم از اینکه تصرفاتی در آن '
  'شده یا نشده باشد. ۲) تصدی به حمل و نقل از راه خشکی یا آب یا هوا به هر نحوی که باشد. ۳) هر قسم عملیات دلالی یا '
  'حق\u200cالعمل\u200cکاری (\u200cکمیسیون) و یا عاملی و همچنین تصدی به هر نوع تأسیساتی که برای انجام بعضی امور '
  'ایجادمی\u200cشود از قبیل تسهیل معاملات ملکی یا پیدا کردن خدمه یا تهیه و رسانیدن ملزومات و غیره. ۴) تأسیس و به کار '
  'انداختن هر قسم کارخانه مشروط بر اینکه برای رفع حوائج شخصی نباشد. ۵) تصدی به عملیات حراجی. ۶) تصدی به هر قسم '
  'نمایشگاه\u200cهای عمومی. ۷) هر قسم عملیات صرافی و بانکی. ۸) معاملات برواتی اعم از اینکه بین تاجر یا غیر تاجر '
  'باشد. ۹) عملیات بیمه بحری و غیر بحری ۱۰) کشتی\u200cسازی و خرید و فروش کشتی و کشتیرانی داخلی یا خارجی و معاملات '
  'راجعه به آنها.'),
 (3,
  'معاملات ذیل به اعتبار تاجر بودن متعاملین یا یکی از آنها تجارتی محسوب می\u200cشود: ۱) کلیه معاملات بین تجار و کسبه '
  'و صرافان و بانکها. ۲) کلیه معاملاتی که تاجر یا غیر تاجر برای حوائج تجارتی خود می\u200cنماید. ۳) کلیه معاملاتی که '
  'اجزاء یا خدمه یا شاگرد تاجر برای امور تجارتی ارباب خود می\u200cنماید. ۴) کلیه معاملات شرکتهای تجارتی.'),
 (4, 'معاملات غیر منقول به هیچ وجه تجارتی محسوب نمی\u200cشود.'),
 (5, 'کلیه معاملات تجار تجارتی محسوب است مگر اینکه ثابت شود معامله مربوط به امور تجارتی نیست.'),
 (6,
  'هر تاجری به استثنای کسبه جزء مکلف است دفاتر ذیل یا دفاتر دیگری را که وزارت عدلیه به موجب نظامنامه قائم\u200cمقام '
  'این دفاتر قرارمی\u200cدهد داشته باشد: ۱) دفتر روزنامه. ۲) دفتر کل. ۳) دفتر دارایی. ۴) دفتر کپیه.'),
 (7,
  'دفتر روزنامه دفتری است که تاجر باید همه روزه مطالبات و دیون و داد و ستد تجارتی و معاملات راجع به اوراق تجارتی '
  '(\u200cاز قبیل خرید وفروش و ظهرنویسی) و به طور کلی جمیع واردات و صادرات تجارتی خود را به هر اسم و رسمی که باشد و '
  'وجوهی را که برای مخارج شخصی خودبرداشت می\u200cکند در آن دفتر ثبت نماید.'),
 (8,
  'دفتر کل دفتری است که تاجر باید کلیه معاملات را لااقل هفته یک مرتبه از دفتر روزنامه استخراج و انواع مختلفه آن را '
  'تشخیص و جداکرده هر نوعی را در صفحه مخصوصی در آن دفتر به طور خلاصه ثبت کند.'),
 (9,
  'دفتر دارایی دفتری است که تاجر باید هر سال صورت جامعی از کلیه دارایی منقول و غیر منقول و دیون و مطالبات سال گذشته '
  'خود را به\u200cریز ترتیب داده در آن دفتر ثبت و امضاء نماید و این کار باید تا پانزدهم فروردین سال بعد انجام '
  'پذیرد.'),
 (10,
  'دفتر کپیه دفتری است که تاجر باید کلیه مراسلات و مخابرات و صورت\u200cحسابهای صادره خود را در آن به ترتیب تاریخ ثبت '
  'نماید. تبصره - تاجر باید کلیه مراسلات و مخابرات و صورت\u200cحسابهای وارده را نیز به ترتیب تاریخ ورود مرتب نموده و '
  'در لفاف مخصوصی ضبط کند.'),
 (11,
  'دفاتر مذکور در ماده ۶ به استثناء دفتر کپیه قبل از آنکه در آن چیزی نوشته شده باشد به توسط نماینده اداره ثبت '
  '(\u200cکه مطابق نظامنامه\u200cوزارت عدلیه معین می\u200cشود) امضاء خواهد شد. برای دفتر کپیه امضاء مزبور لازم نیست '
  'ولی باید اوراق آن دارای نمره ترتیبی باشد. در موقع تجدیدسالیانه هر دفتر مقررات این ماده رعایت خواهد شد. حق امضاء '
  'از قرار هر صد صفحه یا کسور آن دو ریال به علاوه مشمول ماده (۱۳۵) قانون ثبت اسناد است.'),
 (12,
  'دفتری که برای امضاء به متصدی امضاء تسلیم می\u200cشود باید دارای نمره ترتیبی و قیطان کشیده باشد و متصدی امضاء مکلف '
  'است\u200cصفحات دفتر را شمرده در صفحه اول و آخر هر دفتر مجموع عدد صفحات آن را با تصریح به اسم و رسم صاحب دفتر '
  'نوشته با قید تاریخ امضاء و دوطرف قیطان را با مهر سربی که وزارت عدلیه برای این مقصود تهیه می\u200cنماید منگنه کند. '
  'لازم است کلیه اعداد حتی تاریخ با تمام حروف نوشته شود.'),
 (13,
  'کلیه معاملات و صادرات و واردات در دفاتر مذکوره فوق باید به ترتیب تاریخ در صفحات مخصوصه نوشته شود - تراشیدن و '
  'حک\u200cکردن و همچنین جای سفید گذاشتن بیش از آنچه که در دفترنویسی معمول است و در حاشیه و یا بین سطور نوشتن ممنوع '
  'است و تاجر باید تمام آن\u200cدفاتر را از ختم هر سالی لااقل تا ده سال نگاهدارد.'),
 (14,
  'دفاتر مذکور در ماده ۶ و سایر دفاتری که تجار برای امور تجارتی خود به کار می\u200cبرند در صورتی که مطابق مقررات این '
  'قانون مرتب شده\u200cباشد بین تجار - در امور تجارتی - سندیت خواهد داشت و غیر این صورت فقط بر علیه صاحب آن معتبر '
  'خواهد بود.'),
 (15,
  'تخلف از ماده ۶ و ماده ۱۱ مستلزم 33/000/000 تا 200/000/000 ریال جزای نقدی است. این مجازات را محکمه حقوق رأساً و '
  'بدون تقاضای\u200cمدعی\u200cالعموم می\u200cتواند حکم بدهد و اجرای آن مانع اجرای مقررات راجع به تاجر ورشکسته که '
  'دفتر مرتب ندارد نخواهد بود.'),
 (16,
  'در نقاطی که وزارت عدلیه مقتضی دانسته و دفتر ثبت تجارتی تأسیس کند کلیه اشخاصی که در آن نقاط به شغل تجارت اشتغال '
  'دارند اعم\u200cاز ایرانی و خارجی به استثنای کسبه جزء باید در مدت مقرر اسم خود را در دفتر ثبت تجارتی به ثبت '
  'برسانند و الا به جزای نقدی از 33/000/000 تا 200/000/000 ریال محکوم خواهند شد.'),
 (17,
  'مقررات مربوطه به دفتر ثبت تجارتی را وزارت عدلیه با تصریح به موضوعاتی که باید به ثبت برسد به موجب نظامنامه معین '
  'خواهد کرد.'),
 (18,
  'شش ماه پس از الزامی شدن ثبت تجارتی هر تاجری که مکلف به ثبت است باید در کلیه اسناد و صورت\u200cحسابها و نشریات خطی '
  'یا چاپی\u200cخود در ایران تصریح نماید که در تحت چه نمره به ثبت رسیده و الا علاوه بر مجازات مقرر در فوق به جزای '
  'نقدی از 33/000/000 تا 200/000/000 ریال محکوم\u200cمی\u200cشود.'),
 (19, 'کسبه جزء مذکور در این فصل و فصل اول مطابق مقررات نظامنامه وزارت عدلیه تشخیص می\u200cشوند.'),
 (20,
  'شرکتهای تجارتی بر هفت قسمت است: ۱) شرکت سهامی. ۲) شرکت با مسئولیت محدود. ۳) شرکت تضامنی. ۴) شرکت مختلط غیر سهامی. '
  '۵) شرکت مختلط سهامی. ۶) شرکت نسبی. ۷) شرکت تعاونی تولید و مصرف.'),
 (21,
  'شرکت سهامی شرکتی است که برای امور تجارتی تشکیل و سرمایه آن به سهام تقسیم شده و مسئولیت صاحبان سهام محدود به '
  'سهام\u200cآنها است.'),
 (22, 'در اسم شرکت سهامی نام هیچیک از شرکاء قید نخواهد شد - در اسم شرکت باید کلمه (\u200cسهامی) قید شود.'),
 (23, 'سهام ممکن است با اسم یا بی\u200cاسم باشد.'),
 (24,
  'سهام بی\u200cاسم به صورت سند در وجه حامل مرتب و دارنده آن مالک شناخته می\u200cشود مگر آنکه خلاف آن قانوناً ثابت '
  'گردد - نقل و انتقال\u200cاین نوع سهام به قبض و اقباض به عمل می\u200cآید.'),
 (25,
  'انتقال سهام با اسم باید در دفتر شرکت به ثبت برسد صاحب سهم باید شخصاً یا به توسط وکیل انتقال را در دفتر شرکت تصدیق '
  'و امضانماید.'),
 (26,
  'سهام ممکن است نقدی باشد یا غیر نقدی - سهام غیر نقدی سهامی است که در ازاء آن به جای وجه نقد چیز دیگری از قبیل '
  'کارخانه وامتیازنامه و غیره داده شود.'),
 (27, 'قیمت سهام و همچنین قیمت قطعات سهام (\u200cدر صورت تجزیه) متساوی خواهد بود.'),
 (28,
  'در صورتی که سرمایه شرکتهای سهامی از دویست هزار ریال تجاوز نکند سهام یا قطعات سهام نباید کمتر از پنجاه ریال باشد و '
  'هر گاه\u200cسرمایه زائد بر دویست هزار ریال باشد سهام و قطعات سهام کمتر از یک صد ریال نخواهد بود.'),
 (29,
  'مادام که شرکت سهامی تشکیل نشده سهام یا تصدیق موقتی (\u200cاعم از بااسم یا بی\u200cاسم) نمی\u200cتوان صادر کرد هر '
  'سهم یا تصدیق موقتی که\u200cقبل از تشکیل شرکت به کسی داده شده باشد باطل و صادرکنندگان متضامناً مسئول خساراتی هستند '
  'که به دارندگان این قبیل اوراق وارد شده\u200cاست. تا زمانی که پنجاه درصد قیمت اسمی سهام تأدیه نشده نمی\u200cتوان '
  'سهام بی\u200cاسم یا تصدیق موقتی بی\u200cاسم انتشار داد.'),
 (30,
  'کسانی که تعهد ابتیاع سهام کرده\u200cاند تا موقعی که پنجاه درصد قیمت اسمی سهام خود را نپرداخته\u200cاند مسئول '
  'تأدیه بقیه قیمت آن خواهندبود اگر چه سهام خود را به دیگری منتقل کرده و منتقل\u200cالیه نیز پرداخت بقیه را تعهد '
  'کرده باشد.'),
 (31,
  'بعد از تأدیه پنجاه درصد نیز کسی که تعهد ابتیاع سهمی را کرده\u200cاست از تأدیه بقیه قیمت آن بری نخواهد بود مگر '
  'اینکه اساسنامه شرکت\u200cآن را تجویز کرده باشد که در این صورت منتقل\u200cالیه مسئول تأدیه آن بقیه\u200cاست.'),
 (32,
  'هر کس تعهد ابتیاع سهامی را کرده و در موعد مقرر وجه تعهد شده را نپردازد علاوه بر آن وجه به خسارات تأخیر تأدیه '
  '(\u200cاز قرار صدی\u200cدوازده در سال و به نسبت مدت تأخیر) محکوم خواهد شد.'),
 (33,
  'اساسنامه شرکت می\u200cتواند نسبت به اشخاص مذکور در ماده فوق ترتیب دیگری اتخاذ نموده حتی مقرر دارد که در صورت عدم '
  'تأدیه بقیه\u200cقیمت سهام مقدار تأدیه شده از آن بابت بلاعوض تعلق به شرکت یافته و تعهدکننده نسبت به سهام تعهدی هیچ '
  'حقی نداشته باشد لیکن در این صورت\u200cپرداخت وجه تعهد شده باید لااقل سه مرتبه به وسیله مکتوب با قبض رسید مطالبه و '
  'از تاریخ آخرین مکتوب یک ماه منقضی شده باشد در مورد سهام\u200cبی\u200cاسم به جای مکتوب اعلان در جراید به عمل خواهد '
  'آمد مفاد این ماده باید در موقع تعهد صریحاً در دفتر شرکت قید شده و متعهد ذیل آن را امضاءنماید.'),
 (34,
  'خواه در سهام بااسم و خواه در سهام بی\u200cاسم مادام که قیمت آنها کاملاً تأدیه نشده\u200cاست باید آن مقدار از قیمت '
  'که پرداخته شده صریحاً\u200cروی سهم قید شود به علاوه شرکت مکلف است در هر گونه اسناد و صورت\u200cحسابها و اعلانات و '
  'نشریات و غیره که به طور خطی یا چاپی صادر یامنتشر می\u200cنماید میزان سرمایه خود و آن قسمتی را که تأدیه '
  'شده\u200cاست صریحاً قید کند.'),
 (35,
  'هر شرکت سهامی می\u200cتواند به موجب رأی مجمع عمومی که مطابق ماده (۷۴) این قانون تشکیل شده باشد سهام ممتازه ترتیب '
  'دهد که\u200cنسبت به سایر سهام رجحان و مزایایی داشته باشد ولی ایجاد این نوع سهام مشروط است به اینکه اساسنامه شرکت '
  'چنین اقدامی را تجویز کرده باشد.'),
 (36,
  'شرکت سهامی به موجب شرکتنامه که در دو نسخه نوشته شده باشد تشکیل می\u200cشود یکی از نسختین به طوری که در ماده (۵۰) '
  'مقرراست ضمیمه اظهارنامه مدیر شرکت و دیگری در مرکز اصلی شرکت ضبط خواهد شد.'),
 (37,
  'شرکت باید دارای اساسنامه باشد که نکات ذیل مخصوصاً در آن تصریح بشود: ۱) اسم و مرکز اصلی شرکت. ۲) موضوع شرکت. ۳) '
  'مدت شرکت در صورتی که شرکت برای مدت معینی تشکیل شود. ۴) مقدار سرمایه شرکت و مقدار قیمت سهام. ۵) نوع سهام (\u200cکه '
  'سهام بااسم یا بی\u200cاسم) عده هر نوع از سهام و تعیین اینکه سهام بااسم و بی\u200cاسم به چه شکل ممکن است به هم '
  'تبدیل شود درصورتی که این تبدیل اساساً پذیرفته باشد. ۶) هیأت\u200cهای اداره و تفتیش. ۷) عده سهامی را که مدیران '
  'شرکت باید به صندوق شرکت بسپارند. ۸) مقررات راجع به دعوت مجمع عمومی و حق رأی صاحبان سهام و طریقه شور و اخذ رأی. ۹) '
  'مطالبی که برای قطع آن در مجموع عمومی اکثریت مخصوصی لازم است. ۱۰) طرز ترتیب صورت\u200cحساب سالیانه و رسیدگی به آن '
  'و همچنین اصولی که برای حساب منافع و تقسیم آن باید رعایت شود. ۱۱) طریق تغییر اساسنامه.'),
 (38,
  'تشکیل شرکت\u200cهای سهامی محقق نمی\u200cشود مگر بعد از آنکه تأدیه تمام سرمایه شرکت تعهد شده باشد به علاوه هر گاه '
  'سهام یا قطعات آن\u200cزائد بر پنجاه ریال نباشد تعهدکنندگان باید تمام وجه را تأدیه نمایند و الا باید لااقل ثلث '
  'قیمت سهام را نقداً بپردازند و در هر حال وجهی که پرداخته\u200cمی\u200cشود نباید کمتر از ۵۰ ریال باشد.'),
 (39, 'چیزی که در ازاء سهام غیر نقدی تعهد شده تماماً باید تحویل شود.'),
 (40,
  'مؤسسین باید پس از تنظیم نوشته که حاکی از تعهد پرداخت سرمایه شرکت و تأدیه واقعی ثلث سرمایه نقدی است مجمع '
  'عمومی\u200cشرکت را دعوت نمایند این مجمع اولین مدیرهای شرکت و همچنین مفتش (\u200cکمیسر)\u200cهایی را که به موجب '
  'ماده (۶۲) مقرر است معین می\u200cکند.'),
 (41,
  'هر گاه یکی از تعهدکنندگان سهم غیر نقدی اختیار کند یا مزایای خاصی برای خود مطالبه نماید مجمع عمومی در جلسه اول که '
  'منعقدمی\u200cشود امر به تقویم سهم غیر نقدی نموده یا موجبات مزایای مطالبه شده را تحت نظر می\u200cگیرد تصویب قطعی '
  'تقویم یا موجبات مزایا به عمل نمی\u200cآید وتشکیل شرکت واقع نمی\u200cشود مگر در جلسه دیگر مجمع عمومی که بر حسب '
  'دعوت جدید منعقد خواهد شد و برای اینکه در جلسه دوم تقویم یاموجبات مزایا تصویب شود باید لااقل پنج روز قبل از انعقاد '
  'جلسه راپرتی در این خصوص طبع و بین تمام تعهدکنندگان توزیع شده باشد تصویب امورمذکور باید به اکثریت دو ثلث '
  'تعهدکنندگان حاضر باشد و جلسه مجمع عمومی قانونی نخواهد بود مگر اینکه عدداً نصف کل شرکایی که خرید سهام\u200cنقدی را '
  'تعهد کرده\u200cاند حاضر بوده و نصف کل سرمایه نقدی را دارا باشند کسانی که دارای سهم غیر نقدی هستند یا مزایای خاصی '
  'برای خود مطالبه\u200cکرده\u200cاند در موقعی که سهم غیر نقدی یا مزایای آنها موضوع رأی است حق رأی ندارند آن قسمت از '
  'سرمایه غیر نقدی که موضوع مذاکره و رأی است درجزو سرمایه شرکت محسوب نخواهد شد اگر در جلسه دوم مجمع عمومی نصف '
  'تعهدکنندگان سهام نقدی و نصف سرمایه نقدی حاضر نش ده مجمع به\u200cطور موقت تصمیم خواهد گرفت و مطابق قسمت اخیر ماده '
  '(۴۵) رفتار می\u200cشود. هر گاه سهام غیر نقدی یا موجبات مزایایی که مطالبه شده و تصویب نشود هر یک از تعهدکنندگان '
  'می\u200cتواند از شرکت خارج شود.'),
 (42, 'تصویب مراتب مذکور در ماده فوق مانع نیست از اینکه بعداً نسبت به آنها دعوی تزویر و تقلب اقامه شود.'),
 (43,
  'هر گاه شرکت بین اشخاصی منعقد شود که سرمایه\u200cهای غیر نقدی مشاعاً و منحصراً متعلق به خودشان باشد رعایت ترتیبات '
  'مذکوره درماده (۴۱) راجع به تقویم سهام غیر نقدی لازم نخواهد بود.'),
 (44,
  'اظهارنامه که به موجب ماده (۵۰) به دایره ثبت اسناد باید تسلیم شود مؤسسین شرکت تهیه نموده با اسناد مربوطه به اولین '
  'مجمع\u200cعمومی تقدیم می\u200cنمایند تا مجمع صحت یا سقم آن را معین کند.'),
 (45,
  'مجمع عمومی که در باب صحت اظهارات مؤسسین اظهار رأی و اولین مدیرها و مفتشین را انتخاب می\u200cنماید باید از یک عده '
  'صاحبان\u200cسهام مرکب شود که لااقل نصف سرمایه شرکت را دارا باشند - اگر در مجمع عمومی عده که نصف سرمایه را دارا '
  'باشند حاضر نشدند تصمیمات مجمع\u200cموقتی خواهد بود در این صورت مجمع عمومی جدیدی دعوت می\u200cشود و اگر پس از آنکه '
  'لااقل یک ماه قبل از انعقاد مجمع دو دفعه متوالی به فاصله\u200cهشت روز به وسیله یکی از جراید محلی تصمیمات موقتی '
  'مجمع سابق اعلان و منتشر شد و مجمع جدید آن را تصویب نمود تصمیمات مزبوره قطعی\u200cمی\u200cشود مشروط بر اینکه در '
  'مجمع جدید عده حاضر شوند که لااقل ثلث سرمایه شرکت را دارا باشند. تبصره - جرایدی که اعلانات فوق را باید منتشر '
  'نمایند همه\u200cساله توسط وزارت عدلیه معین و اعلان خواهد شد.'),
 (46,
  'مجمع عمومی فوق اولین مدیرها و مفتشین شرکت را انتخاب می\u200cکند مفتشین برای سال اول و مدیران منتها برای مدت چهار '
  'سال معین\u200cمی\u200cشوند مدیرها را می\u200cتوان پس از انقضاء مدت چهار سال مجدداً انتخاب نمود مگر آنکه اساسنامه '
  'شرکت غیر از این مقرر داشته باشد ولی در صورتی\u200cکه بر حسب مقررات اساسنامه تعیین آنها موکول به تصویب مجمع عمومی '
  'نباشد مدت مدیری آنها بیش از دو سال نخواهد بود.'),
 (47,
  'در صورتی که مدیرها و مفتشینی که از طرف مجمع عمومی انتخاب شده\u200cاند قبول انجام وظیفه نمایند قبولی آنها در '
  'صورت\u200cمجلس قید وشرکت از همان تاریخ تشکیل می\u200cگردد. ۳ - مدیرهای شرکت و وظایف آنها'),
 (48,
  'شرکت سهامی به واسطه یک یا چند نفر نماینده موظف یا غیر موظف که از میان شرکاء به سمت مدیری و برای مدت محدودی '
  'معین\u200cشده و قابل عزل می\u200cباشند اداره خواهد شد.'),
 (49,
  'در صورتی که چند نفر به سمت مدیری معین شده باشند باید یک نفر از میان خود به سمت ریاست انتخاب کنند - رییس مزبور و '
  'هر یک\u200cاز مدیران می\u200cتوانند در صورتی که اساسنامه شرکت اجازه داده باشد با تصویب یکدیگر یک نفر شخص خارج را '
  'به جای خود معین کنند ولی مسئولیت\u200cاعمال شخص خارج به عهده خود آنها خواهد بود.'),
 (50,
  'برای این که تعهد و تأدیه وجه سرمایه از طرف شرکاء ثابت شود باید مدیر شرکت وقوع آن را به موجب نوشته که به دایره ثبت '
  'اسناد مرکزاصلی شرکت می\u200cسپارد و به ثبت می\u200cرسد اعلام نماید و باید اسامی شرکاء را با مقداری از سرمایه که '
  'پرداخته شده با یک نسخه از اساسنامه و یکی ازنسختین شرکتنامه به نوشته مزبور منضم نماید.'),
 (51, 'مسئولیت مدیر شرکت در مقابل شرکاء همان مسئولیتی است که وکیل در مقابل موکل دارد.'),
 (52,
  'مدیرها باید یک عده سهامی را که به موجب اساسنامه مقرر است دارا باشند این سهام برای تضمین خساراتی است که ممکن است '
  'ازاعمال اداری مدیرها مشترکاً یا منفرداً بر شرکت وارد شود- سهام مذکوره با اسم بوده و قابل انتقال نیست و به وسیله '
  'مهری که بر روی آنها زده می\u200cشودغیر قابل انتقال بودن آنها معلوم و در صندوق شرکت ودیعه خواهد ماند.'),
 (53,
  'مدیرهای شرکت نمی\u200cتوانند بدون اجازه مجمع عمومی در معاملاتی که با شرکت یا به حساب شرکت می\u200cشود به طور '
  'مستقیم یاغیر مستقیم سهیم شوند و در صورت اجازه باید صورت مخصوص آن را همه\u200cساله به مجمع عمومی بدهند.'),
 (54, 'مدیران هر شرکت سهامی باید شش ماه به شش ماه خلاصه صورت دارایی و قروض شرکت را مرتب کرده به مفتشین بدهند.'),
 (55,
  'مدیران هر شرکت سهامی باید مطابق ماده (۹) این قانون صورت\u200cحسابی که متضمن دارایی منقول و غیر منقول و همچنین '
  'صورت\u200cمطالبات و قروض شرکت باشد مرتب کنند - این صورت\u200cحساب و همچنین بیلان حساب نفع و ضرر شرکت باید لااقل '
  'چهل روز قبل از انعقاد مجمع\u200cعمومی به مفتشین داده شود که به مجمع مزبور بدهند.'),
 (56,
  'از پانزده روز قبل از انعقاد مجمع عمومی هر صاحب سهم می\u200cتواند در مرکز شرکت به صورت حساب و صورت اسامی صاحبان '
  'سهام\u200cمراجعه کرده و از بیلان که متضمن خلاصه صورت\u200cحساب شرکت است و از راپورت مفتشین سواد بگیرد.'),
 (57,
  'همه\u200cساله لااقل یک بیستم از عایدات خالص شرکت برای تشکیل سرمایه احتیاطی موضوع خواهد شد - همین که سرمایه '
  'احتیاطی به\u200cعشر سرمایه شرکت رسید موضوع کردن این مقدار اختیاری است.'),
 (58,
  'اگر به واسطه ضررهای وارده نصف سرمایه شرکت از میان برود مدیران شرکت مکلفند تمام صاحبان سهام را برای انعقاد مجمع '
  'عمومی\u200cدعوت نمایند تا موضوع انحلال یا ابقاء شرکت مورد شور و رأی شود - تصمیم این مجمع در هر حال منتشر خواهد '
  'شد.'),
 (59,
  'هر گاه مدیران شرکت برخلاف ماده فوق مجمع عمومی را دعوت نکردند و یا مجمعی که دعوت می\u200cشود نتواند مطابق مقررات '
  'قانونی\u200cمنعقد گردد هر ذیحقی می\u200cتواند انحلال شرکت را از محاکم صالحه بخواهد.'),
 (60,
  'هر گاه یک یا چند نفر از ارباب سهامی که مجموع سهام آنها لااقل معادل یک خمس سرمایه شرکت باشد کتباً تقاضای انعقاد '
  'مجمع\u200cعمومی فوق\u200cالعاده نمایند و منظور خود را در آن تقاضانامه تصریح نموده باشند باید مجمع عمومی به طور '
  'فوق\u200cالعاده منعقد شود.'),
 (61,
  'مدیرهای شرکت در مقابل شرکت یا اشخاص ثالث برای تخلف از مقررات این قانون و تقصیراتی که در اعمال اداری شرکت مرتکب '
  'شوندموافق قواعد عمومی مسئول می\u200cباشند مخصوصاً در موقعی که منافع موهومی را تقسیم نمایند یا از تقسیم منافع '
  'موهومی جلوگیری نکنند.'),
 (62,
  'مجمع عمومی سالیانه یک یا چند مفتش (\u200cکمیسر) معین می\u200cکند - مفتشین مزبور که ممکن است از غیر شرکاء نیز '
  'انتخاب شوند مأموریت\u200cخواهند داشت که در موضوع اوضاع عمومی شرکت و همچنین در باب بیلان (\u200cخلاصه جمع و خرج) و '
  'صورت\u200cحسابهایی که مدیرها تقدیم می\u200cکنندراپرتی به مجمع عمومی سال آینده بدهند - تصمیماتی که بدون این راپرت '
  'راجع به تصدیق بیلان و صورت\u200cحسابهای مدیران اخذ می\u200cشود معتبرنخواهد بود - در صورتی که مجمع عمومی مفتشین '
  'مذکور را معین نکرده باشد یا یک یا چند نفر از مفتشینی که معین شده\u200cاند نتوانند راپرت بدهند یا ازدادن راپرت '
  'امتناع نمایند رییس محکمه بدایت مرکز اصلی شرکت به تقاضای هر ذیحقی و پس از احضار مدیران شرکت مفتشین را انتخاب و یا '
  'به جای\u200cآنهایی که نتوانسته\u200cاند یا امتناع کرده\u200cاند مفتشین جدیدی معین می\u200cکند.'),
 (63,
  'در ظرف سه ماه قبل از تاریخی که به موجب اساسنامه شرکت برای انعقاد مجمع عمومی معین است مفتشین می\u200cتوانند به '
  'دفاتر شرکت\u200cمراجعه نموده و از عملیات آن تحقیقاتی بنمایند مفتشین می\u200cتوانند در مواقعی که ضرورت فوری دارد '
  'مجمع عمومی را دعوت نمایند.'),
 (64,
  'حدود مسئولیت مفتشین و اثرات آن همان است که راجع به حدود مسئولیت وکلاء و اثرات آن در مقابل موکلین قانوناً معین '
  'است.'),
 (65, 'مجمع عمومی شرکت باید لااقل سالی یک دفعه در موقعی که به موجب اساسنامه معین است منعقد شود.'),
 (66, 'اساسنامه معین می\u200cکند برای حق ورود در مجمع چند سهم (\u200cبه عنوان وکالت یا مالکیت) باید داشت.'),
 (67, 'عده آرایی که هر یک از شرکاء به نسبت عده سهام خود دارند به موجب اساسنامه معین می\u200cگردد.'),
 (68,
  'در جلسات مجمع عمومی هیچکدام از صاحبان سهام معمولی و صاحبان سهام ممتازه از حیث رأی تفاوتی ندارند مگر اینکه '
  'اساسنامه\u200cشرکت طور دیگر مقرر کرده باشد.'),
 (69,
  'دارندگان سهامی که عده سهام هر یک از آنها برای حضور یا رأی در مجمع عمومی کافی نیست می\u200cتوانند به اندازه که '
  'مجمع عده سهام آنهابرای داشتن حق حضور و رأی کافی باشد با یکدیگر متفق شده یک نفر را از میان خود برای حضور و رأی در '
  'مجمع مذکور معین نمایند.'),
 (70,
  'در مجامع عمومی که برای رسیدگی به سهم\u200cالشرکه و مزایا مطابق ماده (۴۱) و در مجامعی که برای تعیین اولین مدیرها و '
  'مفتشین وتصدیق اظهارات مؤسسین مطابق ماده (۴۵) منعقد می\u200cشود کلیه صاحبان سهام قطع نظر از عده سهامی که دارند '
  'می\u200cتوانند حضور به هم رسانند.'),
 (71,
  'مجمع عمومی شرکت جز در موارد مذکور در مواد (۴۱ و ۴۵ و ۷۴) باید مرکب از یک عده صاحبان سهامی باشد که لااقل ثلث '
  'سرمایه\u200cشرکت را دارا باشند و اگر در دفعه اول این حد نصاب حاصل نشد مجمع عمومی جدیدی مطابق شرایط مقرر در '
  'اساسنامه شرکت تشکیل و تصمیمات\u200cاین مجمع قطعی خواهد بود ولو اینکه حد نصاب فوق حاصل نشود.'),
 (72, 'تصمیمات مجمع عمومی به اکثریت آراء خواهد بود.'),
 (73,
  'در مواردی که مجمع عمومی شرکاء نسبت به حقوق نوع مخصوصی از سهام تصمیمی نماید که تغییری در حقوق آنها بدهد آن '
  'تصمیم\u200cقطعی نخواهد بود مگر بعد از آنکه صاحبان سهام مزبوره در جلسه خاصی آن تصمیم را تصویب نمایند و برای اینکه '
  'آراء جلسه خاص مذکور معتبرباشد باید حاضرین جلسه لااقل صاحب بیش از نصف سرمایه مجموع سهامی باشد که موضوع '
  'مذاکره\u200cاست.'),
 (74,
  'در مجامع عمومی که برای امتداد مدت شرکت یا برای انحلال شرکت قبل از موعد مقرر یا هر نوع تغییر دیگری در اساسنامه '
  'تشکیل\u200cمی\u200cشود باید عده از صاحبان سهام که بیش از سه ربع سرمایه شرکت را دارا باشند حاضر گردند. اگر در مجمع '
  'عمومی عده که سه ربع سرمایه شرکت را دارا باشند حاضر نشدند ممکن است مجمع عمومی جدیدی دعوت کرد مشروط بر اینکه '
  'لااقل\u200cیک ماه قبل از انعقاد مجمع دو دفعه متوالی به فاصله هشت روز به وسیله یکی از جراید محل (\u200cکه سالیانه '
  'از طرف وزارت عدلیه معین می\u200cشود) دستورجلسه قبل و نتیجه آن اعلان گردد. مجمع عمومی جدید وقتی قانونی است که '
  'صاحبان لااقل نصف سرمایه شرکت حاضر باشند اگر این حد نصاب حاصل نشد ممکن است با رعایت\u200cتشریفات فوق مجمع عمومی '
  'دیگری دعوت نمود این مجمع با حضور صاحبان لااقل ثلث سرمایه شرکت حق تصمیم خواهد داشت در هر یک از سه\u200cمجمع فوق '
  'تصمیمات به اکثریت دو ثلث آراء حاضر گرفته می\u200cشود. در این مجامع کلیه صاحبان سهام قطع نظر از عده سهام خود حق '
  'حضور و به نسبت هر یک سهم یک رأی دارند ولو اینکه اساسنامه برخلاف این مقررداشته باشد. هیچ مجمع عمومی تابعیت شرکت را '
  'نمی\u200cتواند تغییر بدهد. بر تعهدات صاحبان سهام با هیچ اکثریتی نمی\u200cتوان افزود.'),
 (75,
  'در مجمع عمومی ورقه حاضر و غائبی خواهد بود حاوی اسم و محل اقامت و عده سهام هر یک از شرکاء ورقه مزبور پس از '
  'تصدیق\u200cهیأت رییسه مجمع در مرکز شرکت حفظ و به هر کسی تقاضا نماید ارائه می\u200cشود.'),
 (76,
  'هر گاه شرکت بخواهد به موجب مقررات اساسنامه سهام بی\u200cاسم خود را به سهام بااسم تبدیل نماید باید اعلانی در این '
  'موضوع منتشرکرده و مهلتی که کمتر از شش ماه نباشد به صاحبان سهام بدهد تا در ظرف مهلت مزبور سهام خود را به سهام جدید '
  'تبدیل نمایند.'),
 (77,
  'اعلان مذکور در فوق باید در مجله رسمی عدلیه و در یکی از جراید کثیرالانتشار مرکز اصلی شرکت دو دفعه و به فاصله ده '
  'روز منتشرشود در صورتی که مرکز اصلی شرکت در خارج از تهران باشد باید در یکی از روزنامه\u200cهای یومیه تهران که '
  'همه\u200cساله از طرف وزارت عدلیه برای انتشاراین قبیل اعلانات معین می\u200cشود نیز منتشر گردد. ابتداء مهلت از '
  'تاریخ اولین انتشار اعلان در مجله رسمی خواهد بود.'),
 (78,
  'هر صاحب سهمی که سهام خود را تا انقضاء مهلت مذکور در ماده (۷۶) به سهام جدید تبدیل نکند دیگر نمی\u200cتواند تقاضای '
  'تبدیل نماید وشرکت حق خواهد داشت سهام جدیدی را که در ازاء سهام تبدیل نشده موجود می\u200cباشد به اشخاص دیگر به طریق '
  'مزایده بفروشد.'),
 (79,
  'قیمت سهامی که به طریق مذکور در فوق فروخته می\u200cشود در مرکز اصلی شرکت یا در بانک ملی ایران ودیعه گذاشته خواهد '
  'شد و هر گاه\u200cدر ظرف ده سال از تاریخ فروش سهام صاحب سهم سهام سابق خود را نداده و وجهی را که به طریق فوق امانت '
  'گذاشته شده\u200cاست مطالبه ننماید نسبت\u200cبه حق او مرور زمان حاصل شده و وجه مزبور در حکم اموال بلاصاحب بوده و '
  'مدیر شرکت مکلف است آن را به مقامات صلاحیتدار تسلیم نماید - هرمدیر شرکت که به این تکلیف عمل نکند به تأدیه سه برابر '
  'وجه مذکور محکوم خواهد شد.'),
 (80,
  'در صورتی که شرکت بخواهد سهام با اسم خود را به سهام بی\u200cاسم تبدیل نماید باید مراتب را به طریقی که فوقاً مقرر '
  'است یک مرتبه\u200cاعلان نماید و اگر در ظرف مهلتی که معین می\u200cشود و نباید کمتر از دو ماه باشد صاحبان سهام سهام '
  'بااسم خود را به سهام بی\u200cاسم تبدیل نکنند سهام\u200cبااسمی که در دست آنها باقی می\u200cماند باطل و سهام جدید '
  'در مرکز اصلی شرکت به اسم آنها ودیعه خواهد بود.'),
 (81,
  'در هر موقع که شرکت بخواهد تصدیق\u200cهای موقتی را که به اشخاص داده تبدیل به سهام کند در مورد تصدیقهای موقتی '
  'بی\u200cاسم مطابق\u200cمقررات مواد (۷۶) و (۷۷) و (۷۸) و (۷۹) و در مورد تصدیق موقتی با اسم مطابق ماده (۸۰) رفتار '
  'خواهد شد. ۷ - بطلان شرکت و یا بطلان اعمال و تصمیمات آن'),
 (82,
  'هر شرکت سهامی که مقررات یکی از مواد ۲۸ - ۲۹ - ۳۶ - ۳۷ - ۳۸ - ۳۹ - ۴۱ - ۴۴ - ۴۵ - ۴۶ - ۴۷ - ۵۰ این قانون را '
  'رعایت\u200cنکرده باشد از درجه اعتبار ساقط و بلااثر خواهد بود لیکن شرکاء نمی\u200cتوانند در مقابل اشخاص خارج به '
  'این بطلان استناد نمایند.'),
 (83,
  'در هر مورد که موافق مقررات ماده قبل محکمه بر بطلان شرکت یا اعمال و تصمیمات آن حکم کند مؤسسینی که مسئول این '
  'بطلان\u200cهستند و همچنین مفتشین و مدیرهایی که در حین حدوث سبب بطلان یا بلافاصله پس از آن سر کار بوده و انجام '
  'وظیفه نکرده\u200cاند متضامناً مسئول\u200cخساراتی خواهند بود که از این بطلان به صاحبان سهام و اشخاص ثالثی متوجه '
  'می\u200cشود همین مسئولیت ممکن است به شرکایی متوجه شود که سهم\u200cغیر نقدی آنها تقویم و تصویب نشده یا مزایایی که '
  'مطالبه کرده\u200cاند به تصدیق نرسیده باشد.'),
 (84,
  'هر گاه قبل از اقامه دعوی برای ابطال شرکت یا برای ابطال عملیات و قراردادهای شرکت موجبات بطلان مرتفع شود دعوای '
  'ابطال درمحکمه پذیرفته نخواهد شد.'),
 (85,
  'اگر از تاریخ رفع موجبات بطلان یک سال منقضی شده و اشخاص خارج از جهت معاملاتی که با ایشان شده\u200cاست به استناد '
  'اموری که\u200cموجب بطلان بوده دعوای خسارت نکرده باشند دیگر دعوی مزبور از آنها پذیرفته نمی\u200cشود.'),
 (86,
  'هر گاه مقرر شده باشد که مجمع عمومی مخصوصی برای رفع موجبات بطلان منعقد شود و دعوت اعضاء نیز برای انعقاد مجمع '
  'موافق\u200cاساسنامه به عمل آمده باشد دعوای بطلان از تاریخ دعوت مجمع در محکمه پذیرفته نخواهد شد مگر اینکه مجمع '
  'مزبور موجبات بطلان را رفع ننماید.'),
 (87,
  'هر گاه از تاریخ حدوث سبب بطلان شرکت ده سال گذشته و اقامه دعوی بطلان و خسارت نشده باشد دیگر دعوی مذکور '
  'پذیرفته\u200cنخواهد شد.'),
 (88,
  'استرداد منافعی که بین شرکاء تقسیم شده ممکن نیست مگر اینکه تقسیم بدون ترتیب صورت دارایی یا مخالف نتیجه حاصل از '
  'صورت\u200cمزبور به عمل آمده باشد در این صورت نیز فقط تا پنج سال اقامه دعوی استرداد می\u200cتوان نمود. مبدأ مرور '
  'زمان روز تقسیم منافع است. مقررات جزایی'),
 (89,
  'هر کس سهام یا قطعات سهام شرکتی را که در مورد آن یکی از مواد ۲۸ - ۲۹ - ۳۶ - ۳۷ - ۳۸ - ۳۹ - ۴۴ و ۵۰ این قانون رعایت '
  'نشده\u200cصادر نماید به پانصد الی ده هزار ریال جزای نقدی علاوه بر خسارات وارده به شرکت یا افراد محکوم خواهد شد. '
  'در مواردی که عمل مشمول ماده ۲۳۸\u200cقانون مجازات عمومی است مرتکب به مجازات مقرر در آن ماده نیز محکوم '
  'می\u200cشود.'),
 (90,
  'حکم فوق درباره اشخاصی نیز مقرر است که برخلاف واقع خود را صاحب سهام یا قطعات سهام قلمداد کرده و در مجمع عمومی '
  'واردشوند یا در دادن رأی شرکت نمایند و یا سهامی را برای اینکه به طور تقلب استعمال شود به دیگری بدهند. در مورد این '
  'ماده علاوه بر جزای نقدی\u200cمتخلف را می\u200cتوان به یک تا شش ماه حبس تأدیبی نیز محکوم نمود.'),
 (91,
  'هر کس سهام یا قطعات سهامی را که در مورد آنها مقررات یکی از مواد ۲۸ - ۲۹ - ۳۸ و ۳۹ رعایت نشده با علم به عدم رعایت '
  'قانون\u200cمعامله کرده یا شرکت در معامله داشته و یا قیمت آنها را اعلان نموده باشد به پانصد الی ده هزار ریال جزای '
  'نقدی محکوم خواهد شد. مقررات این ماده مانع نخواهد بود که اگر عمل مشمول ماده ۲۳۸ قانون مجازات عمومی باشد مرتکب به '
  'مجازات حبس مذکور در آن ماده نیز محکوم\u200cشود.'),
 (92,
  'اشخاص ذیل کلاهبردار محسوب می\u200cشوند: ۱ - هر کس برخلاف حقیقت مدعی وقوع تعهد ابتیاع سهام یا تأدیه قیمت سهام شده '
  'یا وقوع تعهد و یا تأدیه را که واقعیت ندارد اعلام یا جعلیاتی\u200cمنتشر کند که به این وسایل دیگری را وادار به تعهد '
  'خرید سهام یا تأدیه قیمت سهام نماید اعم از اینکه عملیات مذکور مؤثر شده یا نشده باشد. ۲ - هر کس به طور تقلب برای '
  'جلب تعهد یا پرداخت قیمت سهام اسم اشخاصی را برخلاف واقع به عنوانی از عناوین جزء شرکت قلمداد نماید. ۳ - مدیرهایی که '
  'با نبودن صورت دارایی یا به استناد صورت دارایی مزور منافع موهومی را بین صاحبان سهام تقسیم نموده باشند.'),
 (93, 'شرکت سهامی در موارد ذیل منحل می\u200cشود:'),
 (94,
  'شرکت با مسئولیت محدود شرکتی است که بین دو یا چند نفر برای امور تجارتی تشکیل شده و هر یک از شرکاء بدون اینکه '
  'سرمایه به\u200cسهام یا قطعات سهام تقسیم شده باشد - فقط تا میزان سرمایه خود در شرکت مسئول قروض و تعهدات شرکت است.'),
 (95,
  'در اسم شرکت باید عبارت (\u200cبا مسئولیت محدود) قید شود و الا آن شرکت در مقابل اشخاص ثالث شرکت تضامنی محسوب و '
  'تابع\u200cمقررات آن خواهد بود. اسم شرکت نباید متضمن اسم هیچ یک از شرکاء باشد و الا شریکی که اسم او در اسم شرکت '
  'قید شده در مقابل اشخاص ثالث حکم شریک ضامن درشرکت تضامنی را خواهد داشت.'),
 (96,
  'شرکت با مسئولیت محدود وقتی تشکیل می\u200cشود که تمام سرمایه نقدی تأدیه و سهم\u200cالشرکه غیر نقدی نیز تقویم و '
  'تسلیم شده باشد.'),
 (97,
  'در شرکتنامه باید صراحتاً قید شده باشد که سهم\u200cالشرکه\u200cهای غیر نقدی هر کدام به چه میزان تقویم '
  'شده\u200cاست.'),
 (98,
  'شرکاء نسبت به قیمتی که در حین تشکیل شرکت برای سهم\u200cالشرکه\u200cهای غیر نقدی معین شده در مقابل اشخاص ثالث '
  'مسئولیت تضامنی\u200cدارند.'),
 (99, 'مرور زمان دعاوی ناشی از مقررات فوق ده سال از تاریخ تشکیل شرکت است.'),
 (100,
  'هر شرکت با مسئولیت محدود که برخلاف مواد ۹۶ و ۹۷ تشکیل شده باشد باطل و از درجه اعتبار ساقط است لیکن شرکاء در '
  'مقابل\u200cاشخاص ثالث حق استناد به این بطلان ندارند.'),
 (101,
  'اگر حکم بطلان شرکت به استناد ماده قبل صادر شود شرکایی که بطلان مستند به عمل آنها است و هیأت نظار و مدیرهایی که در '
  'حین\u200cحدوث سبب بطلان یا بلافاصله پس از آن سر کار بوده و انجام وظیفه نکرده\u200cاند در مقابل شرکاء دیگر و اشخاص '
  'ثالث نسبت به خسارات ناشیه از این\u200cبطلان متضامناً مسئول خواهند بود. مدت مرور زمان ده سال از تاریخ حدوث موجب '
  'بطلان است.'),
 (102,
  'سهم\u200cالشرکه شرکاء نمی\u200cتواند به شکل اوراق تجارتی قابل انتقال اعم از بااسم یا بی\u200cاسم و غیره درآید. '
  'سهم\u200cالشرکه را نمی\u200cتوان منتقل به\u200cغیر نمود مگر با رضایت عده از شرکاء که لااقل سه ربع سرمایه متعلق به '
  'آنها بوده و اکثریت عددی نیز داشته باشند.'),
 (103, 'انتقال سهم\u200cالشرکه به عمل نخواهد آمد مگر به موجب سند رسمی.'),
 (104,
  'شرکت با مسئولیت محدود به وسیله یک یا چند نفر مدیر موظف یا غیر موظف که از بین شرکاء یا از خارج برای مدت محدود '
  'یانامحدودی معین می\u200cشوند اداره می\u200cگردد.'),
 (105,
  'مدیران شرکت کلیه اختیارات لازمه را برای نمایندگی و اداره شرکت خواهند داشت مگر اینکه در اساسنامه غیر این ترتیب '
  'مقرر شده\u200cباشد هر قرارداد راجع به محدود کردن اختیارات مدیران که در اساسنامه تصریح به آن نشده در مقابل اشخاص '
  'ثالث باطل و کان\u200cلم\u200cیکن است.'),
 (106,
  'تصمیمات راجعه به شرکت باید به اکثریت لااقل نصف سرمایه اتخاذ شود - اگر در دفعه اولی این اکثریت حاصل نشد باید تمام '
  'شرکاءمجدداً دعوت شوند در این صورت تصمیمات به اکثریت عددی شرکاء اتخاذ می\u200cشود اگر چه اکثریت مزبور دارای نصف '
  'سرمایه نباشد. اساسنامه شرکت\u200cمی\u200cتواند ترتیبی برخلاف مراتب فوق مقرر دارد.'),
 (107,
  'هر یک از شرکاء به نسبت سهمی که در شرکت دارد دارای رأی خواهد بود مگر اینکه اساسنامه به ترتیب دیگری مقرر داشته '
  'باشد.'),
 (108,
  'روابط بین شرکاء تابع اساسنامه\u200cاست - اگر در اساسنامه راجع به تقسیم نفع و ضرر مقررات خاصی نباشد تقسیم مزبور به '
  'نسبت سرمایه\u200cشرکاء به عمل خواهد آمد.'),
 (109,
  'هر شرکت با مسئولیت محدود که عده شرکاء آن بیش از دوازده نفر باشد باید دارای هیأت نظار بوده و هیأت مزبور لااقل سالی '
  'یک مرتبه\u200cمجمع عمومی شرکاء را تشکیل دهد. هیأت نظار باید بلافاصله بعد از انتخاب شدن تحقیق کرده و اطمینان حاصل '
  'کند که دستور مواد ۹۶ و ۹۷ رعایت شده\u200cاست. هیأت نظار می\u200cتواند شرکاء را برای انعقاد مجمع عمومی '
  'فوق\u200cالعاده دعوت نماید مقررات مواد ۱۶۵ - ۱۶۷ - ۱۶۸ و ۱۷۰ در مورد شرکتهای با مسئولیت\u200cمحدود نیز رعایت '
  'خواهد شد.'),
 (110, 'شرکاء نمی\u200cتوانند تبعیت شرکت را تغییر دهند مگر به اتفاق آراء.'),
 (111,
  'هر تغییر دیگری راجع به اساسنامه باید به اکثریت عددی شرکاء که لااقل سه ربع سرمایه را نیز دارا باشند به عمل آید مگر '
  'اینکه دراساسنامه اکثریت دیگری مقرر شده باشد.'),
 (112, 'در هیچ مورد اکثریت شرکاء نمی\u200cتواند شریکی را مجبور به ازدیاد سهم\u200cالشرکه خود کند.'),
 (113,
  'مفاد ماده ۷۸ این قانون راجع به تشکیل سرمایه احتیاطی در شرکتهای با مسئولیت محدود نیز لازم\u200cالرعایه\u200cاست.'),
 (114,
  'شرکت با مسئولیت محدود در موارد ذیل منحل می\u200cشود: الف) در مورد فقرات ۱ - ۲ - ۳ ماده ۹۳. ب) در صورت تصمیم عده '
  'از شرکاء که سهم\u200cالشرکه آنها بیش از نصف سرمایه شرکت باشد. ج) در صورتی که به واسطه ضررهای وارده نصف سرمایه '
  'شرکت از بین رفته و یکی از شرکاء تقاضای انحلال کرده و محکمه دلایل او را موجه\u200cدیده و سایر شرکاء حاضر نباشند '
  'سهمی را که در صورت انحلال به او تعلق می\u200cگیرد پرداخته و او را از شرکت خارج کنند. د) در مورد فوت یکی از شرکاء '
  'اگر به موجب اساسنامه پیش\u200cبینی شده باشد.'),
 (115,
  'اشخاص ذیل کلاهبردار محسوب می\u200cشوند: الف) مؤسسین و مدیرانی که برخلاف واقع پرداخت تمام سهم\u200cالشرکه نقدی و '
  'تقویم و تسلیم سهم\u200cالشرکه غیر نقدی را در اوراق و اسنادی که بایدبرای ثبت شرکت بدهند اظهار کرده باشند. ب) کسانی '
  'که به وسیله متقلبانه سهم\u200cالشرکه غیر نقدی را بیش از قیمت واقعی آن تقویم کرده باشند. ج) مدیرانی که با نبودن '
  'صورت دارایی یا با استناد صورت دارایی مزور منافع موهومی را بین شرکاء تقسیم کنند.'),
 (116,
  'شرکت تضامنی شرکتی است که در تحت اسم مخصوصی برای امور تجارتی بین دو یا چند نفر با مسئولیت تضامنی تشکیل '
  'می\u200cشود:اگر دارایی شرکت برای تأدیه تمام قروض کافی نباشد هر یک از شرکاء مسئول پرداخت تمام قروض شرکت است. هر '
  'قراری که بین شرکاء برخلاف این ترتیب داده شده باشد در مقابل اشخاص ثالث کان\u200cلم\u200cیکن خواهد بود.'),
 (117,
  'در اسم شرکت تضامنی باید عبارت (\u200cشرکت تضامنی) و لااقل اسم یک نفر شرکاء ذکر شود. در صورتی که اسم شرکت مشتمل بر '
  'اسامی تمام شرکاء نباشد باید بعد از اسم شریک یا شرکایی که ذکر شده\u200cاست عبارتی از قبیل (\u200cو شرکاء) یا '
  '(\u200cوبرادران) قید شود.'),
 (118,
  'شرکت تضامنی وقتی تشکیل می\u200cشود که تمام سرمایه نقدی تأدیه و سهم\u200cالشرکه غیر نقدی نیز تقویم و تسلیم شده '
  'باشد.'),
 (119,
  'در شرکت تضامنی منافع به نسبت سهم\u200cالشرکه بین شرکاء تقسیم می\u200cشود مگر آنکه شرکتنامه غیر از این ترتیب را '
  'مقرر داشته باشد.'),
 (120, 'در شرکت تضامنی شرکاء باید لااقل یک نفر از میان خود یا از خارج به سمت مدیری معین نمایند.'),
 (121, 'حدود مسئولیت مدیر یا مدیران شرکت تضامنی همان است که در ماده ۵۱ مقرر شده.'),
 (122,
  'در شرکتهای تضامنی اگر سهم\u200cالشرکه یک یا چند نفر غیر نقدی باشد باید سهم\u200cالشرکه مزبور قبلاً به تراضی تمام '
  'شرکاء تقویم شود.'),
 (123, 'در شرکت تضامنی هیچ یک از شرکاء نمی\u200cتواند سهم خود را به دیگری منتقل کند مگر به رضایت تمام شرکاء.'),
 (124,
  'مادام که شرکت تضامنی منحل نشده مطالبه قروض آن باید از خود شرکت به عمل آید و پس از انحلال طلبکاران شرکت '
  'می\u200cتوانند برای\u200cوصول مطالبات خود به هر یک از شرکاء که بخواهند و یا به تمام آنها رجوع کنند و در هر حال '
  'هیچ یک از شرکاء نمی\u200cتواند به استناد اینکه میزان قروض\u200cشرکت از میزان سهم او در شرکت تجاوز می\u200cنماید '
  'از تأدیه قروض شرکت امتناع ورزد فقط در روابط بین شرکاء مسئولیت هر یک از آنها در تأدیه قروض\u200cشرکت به نسبت '
  'سرمایه خواهد بود که در شرکت گذاشته\u200cاست آن هم در صورتی که در شرکتنامه ترتیب دیگری اتخاذ نشده باشد.'),
 (125,
  'هر کس به عنوان شریک ضامن در شرکت تضامنی موجودی داخل شود متضامناً با سایر شرکاء مسئول قروضی هم خواهد بود '
  'که\u200cشرکت قبل از ورود او داشته اعم از اینکه در اسم شرکت تغییری داده شده یا نشده باشد. هر قراری که بین شرکاء '
  'برخلاف این ترتیب داده شده باشد در مقابل اشخاص ثالث کان\u200cلم\u200cیکن خواهد بود.'),
 (126,
  'هر گاه شرکت تضامنی منحل شود مادام که قروض شرکت از دارایی آن تأدیه نشده هیچ یک از طلبکاران شخصی شرکاء حقی در '
  'آن\u200cدارایی نخواهد داشت اگر دارایی شرکت برای پرداخت قروض آن کفایت نکند طلبکاران شرکت حق دارند بقیه طلب خود را '
  'از تمام یا فرد فرد شرکاءضامن مطالبه کنند ولی در این مورد طلبکاران شرکت بر طلبکاران شخصی شرکاء حق تقدم نخواهند '
  'داشت.'),
 (127, 'به ورشکستگی شرکت تضامنی بعد از انحلال نیز می\u200cتوان حکم داد مشروط به اینکه دارایی شرکت تقسیم نشده باشد.'),
 (128,
  'ورشکستگی شرکت ملازمه قانونی با ورشکستگی شرکاء و ورشکستگی بعضی از شرکاء ملازمه قانونی با ورشکستگی شرکت ندارد.'),
 (129,
  'طلبکاران شخصی شرکاء حق ندارند طلب خود را از دارایی شرکت تأمین یا وصول کنند ولی می\u200cتوانند نسبت به سهمیه مدیون '
  'خود ازمنافع شرکت یا سهمی که در صورت انحلال شرکت ممکن است به مدیون مزبور تعلق گیرد هر اقدام قانونی که مقتضی باشد '
  'به عمل آورند. طلبکاران شخصی شرکاء در صورتی که نتوانسته باشند طلب خود را از دارایی شخصی مدیون خود وصول کنند و سهم '
  'مدیون از منافع شرکت کافی\u200cبرای تأدیه طلب آنها نباشد می\u200cتوانند انحلال شرکت را تقاضا نمایند (\u200cاعم از '
  'اینکه شرکت برای مدت محدود یا غیر محدود تشکیل شده باشد) مشروط\u200cبر اینکه لااقل شش ماه قبل قصد خود را به وسیله '
  'اظهارنامه رسمی به اطلاع شرکت رسانیده باشند در این صورت شرکت یا بعضی از شرکاء می\u200cتوانندمادام که حکم نهایی '
  'انحلال صادر نشده با تأدیه طلب دائنین مزبور تا حد دارایی مدیون در شرکت یا با جلب رضایت آنان به طریق دیگر از '
  'انحلال\u200cشرکت جلوگیری کنند.'),
 (130,
  'نه مدیون شرکت می\u200cتواند در مقابل طلبی که ممکن است از یکی از شرکاء داشته باشد استناد به تهاتر کند نه خود شریک '
  'می\u200cتواند درمقابل قرضی که ممکن است طلبکار او به شرکت داشته باشد به تهاتر استناد نماید معذالک کسی که طلبکار '
  'شرکت و مدیون به یکی از شرکاء بوده وپس از انحلال شرکت طلب او لاوصول مانده در مقابل آن شرکت حق استناد به تهاتر '
  'خواهد داشت.'),
 (131,
  'در صورت ورشکستگی یکی از شرکاء و همچنین در صورتی که یکی از طلبکاران شخصی یکی از شرکاء به موجب ماده ۱۲۹ '
  'انحلال\u200cشرکت را تقاضا کرده سایر شرکاء می\u200cتوانند سهمی آن شریک را از دارایی شرکت نقداً تأدیه کرده و او را '
  'از شرکت خارج کنند.'),
 (132,
  'اگر در نتیجه ضررهای وارده سهم\u200cالشرکه کم شود مادام که این کمبود جبران نشده تأدیه هر نوع منفعت به شرکاء ممنوع '
  'است.'),
 (133,
  'جز در مورد فوق هیچ یک از شرکاء را شرکت نمی\u200cتواند به تکمیل سرمایه که به علت ضررهای وارده کم شده\u200cاست ملزم '
  'کرده و یا او رامجبور نماید بیش از آنچه که در شرکتنامه مقرر شده\u200cاست به شرکت سرمایه دهد.'),
 (134,
  'هیچ شریکی نمی\u200cتواند بدون رضایت سایر شرکاء (\u200cبه حساب شخصی خود یا به حساب شخص ثالث) تجارتی از نوع تجارت '
  'شرکت\u200cنموده و یا به عنوان شریک ضامن یا شریک با مسئولیت محدود در شرکت دیگری که نظیر آن تجارت را دارد داخل '
  'شود.'),
 (135,
  'هر شرکت تضامنی می\u200cتواند با تصویب تمام شرکاء به شرکت سهامی مبدل گردد در این صورت رعایت تمام مقررات راجعه به '
  'شرکت\u200cسهامی حتمی است.'),
 (136,
  'شرکت تضامنی در موارد ذیل منحل می\u200cشود: الف) در مورد فقرات ۱ - ۲ - ۳ ماده ۹۳. ب) در صورت تراضی تمام شرکاء: ج) '
  'در صورتی که یکی از شرکاء به دلائلی انحلال شرکت را از محکمه تقاضا نماید و محکمه آن دلائل را موجه دانسته و حکم به '
  'انحلال بدهد. د) در صورت فسخ یکی از شرکاء مطابق ماده ۱۳۷. ه) در صورت ورشکستگی یکی از شرکاء مطابق ماده ۱۳۸. و) در '
  'صورت فوت یا محجوریت یکی از شرکاء مطابق مواد ۱۳۹ و ۱۴۰. تبصره - در مورد بند (ج) هر گاه دلائل انحلال منحصراً مربوط '
  'به شریک یا شرکاء معینی باشد محکمه می\u200cتواند به تقاضای سایر شرکاء به جای\u200cانحلال حکم اخراج آن شریک یا '
  'شرکای معین را بدهد.'),
 (137,
  'فسخ شرکت در صورتی ممکن است که در اساسنامه این حق از شرکاء سلب نشده و ناشی از قصد اضرار نباشد - تقاضای فسخ بایدشش '
  'ماه قبل از فسخ کتباً به شرکاء اعلام شود. اگر موافق اساسنامه باید سال به سال به حساب شرکت رسیدگی شود فسخ در موقع '
  'ختم محاسبه سالیانه به عمل می\u200cآید.'),
 (138,
  'در مورد ورشکستگی یکی از شرکاء انحلال وقتی صورت می\u200cگیرد که مدیر تصفیه کتباً تقاضای انحلال شرکت را نموده و از '
  'تقاضای\u200cمزبور شش ماه گذشته و شرکت مدیر تصفیه را از تقاضای انحلال منصرف نکرده باشد.'),
 (139,
  'در صورت فوت یکی از شرکاء بقاء شرکت موقوف به رضایت سایر شرکاء و قائم\u200cمقام متوفی خواهد بود - اگر سایر شرکاء به '
  'بقاء شرکت\u200cتصمیم نموده باشند قائم\u200cمقام متوفی باید در مدت یک ماه از تاریخ فوت رضایت یا عدم رضایت خود را '
  'راجع به بقاء شرکت کتباً اعلام نماید در صورتی\u200cکه قائم\u200cمقام متوفی رضایت خود را اعلام نمود نسبت به اعمال '
  'شرکت در مدت مزبور از نفع و ضرر شریک خواهد بود ولی در صورت اعلام عدم\u200cرضایت در منافع حاصله در مدت مذکور شریک '
  'بوده و نسبت به ضرر آن مدت سهیم نخواهد بود. سکوت تا انقضای یک ماه در حکم اعلام رضایت است.'),
 (140, 'در مورد محجوریت یکی از شرکاء مطابق مدلول ماده فوق عمل خواهد شد.'),
 (141,
  'شرکت مختلط غیر سهامی شرکتی است که برای امور تجارتی در تحت اسم مخصوصی بین یک یا چند نفر شریک ضامن و یک یا چندنفر '
  'شریک با مسئولیت محدود بدون انتشار سهام تشکیل می\u200cشود. شریک ضامن مسئول کلیه قروضی است که ممکن است علاوه بر '
  'دارایی شرکت پیدا شود - شریک با مسئولیت محدود کسی است که مسئولیت اوفقط تا میزان سرمایه\u200cاست که در شرکت گذارده '
  'و یا بایستی بگذارد. در اسم شرکت باید عبارت (\u200cشرکت مختلط) و لااقل اسم یکی از شرکاء ضامن قید شود.'),
 (142, 'روابط بین شرکاء با رعایت مقررات ذیل تابع شرکتنامه خواهد بود.'),
 (143,
  'هر یک از شرکاء با مسئولیت محدود که اسمش جزء اسم شرکت باشد در مقابل طلبکاران شرکت شریک ضامن محسوب خواهد شد. هر '
  'قراری که برخلاف این ترتیب بین شرکاء داده شده باشد در مقابل اشخاص ثالث بی\u200cاثر است.'),
 (144,
  'اداره شرکت مختلط غیر سهامی به عهده شریک یا شرکای ضامن و حدود اختیارات آنها همان است که در مورد شرکاء شرکت '
  'تضامنی\u200cمقرر است.'),
 (145, 'شریک با مسئولیت محدود نه به عنوان شریک حق اداره کردن شرکت را دارد نه اداره امور شرکت از وظایف او است.'),
 (146,
  'اگر شریک با مسئولیت محدود معامله برای شرکت کند - در مورد تعهدات ناشیه از آن معامله در مقابل طرف معامله حکم '
  'شریک\u200cضامن را خواهد داشت مگر اینکه تصریح کرده باشد معامله را به سمت وکالت از طرف شرکت انجام می\u200cدهد.'),
 (147,
  'هر شریک با مسئولیت محدود حق نظارت در امور شرکت داشته و می\u200cتواند از روی دفاتر اسناد شرکت برای اطلاع شخص خود '
  'راجع\u200cبه وضعیت مالی شرکت صورت خلاصه ترتیب دهد. هر قراردادی که بین شرکاء برخلاف این ترتیب داده شود از درجه '
  'اعتبار ساقط است.'),
 (148,
  'هیچ شریک با مسئولیت محدود نمی\u200cتواند بدون رضایت سایر شرکاء شخص ثالثی را با انتقال تمامی قسمتی از '
  'سهم\u200cالشرکه خود به اوداخل در شرکت کند.'),
 (149,
  'اگر یک یا چند نفر از شرکاء با مسئولیت محدود حق خود را در شرکت بدون اجازه سایرین کلاً یا بعضاً به شخص ثالثی واگذار '
  'نمایندشخص مزبور نه حق دخالت در اداره شرکت و نه حق تفتیش در امور شرکت را خواهد داشت.'),
 (150,
  'در مورد تعهداتی که شرکت مختلط غیر سهامی ممکن است قبل از ثبت شرکت کرده باشد شریک با مسئولیت محدود در '
  'مقابل\u200cاشخاص ثالث در حکم شریک ضامن خواهد بود مگر ثابت نماید که اشخاص مزبور از محدود بودن مسئولیت او اطلاع '
  'داشته\u200cاند.'),
 (151, 'شریک ضامن را وقتی می\u200cتوان شخصاً برای قروض شرکت تعقیب نمود که شرکت منحل شده باشد.'),
 (152,
  'هر گاه شرکت به طریقی غیر از ورشکستگی منحل شود و شریک با مسئولیت محدود هنوز تمام یا قسمتی از سهم\u200cالشرکه خود '
  'رانپرداخته و یا پس از تأدیه مسترد داشته\u200cاست طلبکاران شرکت حق دارند معادله آنچه که از بابت سهم\u200cالشرکه '
  'باقی مانده\u200cاست مستقیماً بر علیه شریک بامسئولیت محدود اقامه دعوی نمایند. اگر شرکت ورشکست شود حق مزبور را مدیر '
  'تصفیه خواهد داشت.'),
 (153,
  'اگر در نتیجه قرارداد با شرکاء ضامن و یا در اثر برداشت قبلی از سرمایه شرکت شریک با مسئولیت محدود از '
  'سهم\u200cالشرکه خود که به\u200cثبت رسیده\u200cاست بکاهد این تقلیل مادام که به ثبت نرسیده و بر طبق مقررات راجعه به '
  'نشر شرکت\u200cها منتشر نشده\u200cاست در مقابل طلبکاران شرکت معتبرنبوده و طلبکاران مزبور می\u200cتوانند برای '
  'تعهداتی که از طرف شرکت قبل از ثبت و انتشار تقلیل سرمایه به عمل آمده\u200cاست تأدیه همان سرمایه اولیه\u200cشریک با '
  'مسئولیت محدود را مطالبه نمایند.'),
 (154,
  'به شریک با مسئولیت محدود فرع نمی\u200cتوان داد مگر در صورتی که موجب کسر سرمایه او در شرکت نشود. اگر در نتیجه '
  'ضررهای وارده سهم\u200cالشرکه شریک با مسئولیت محدود کسر شد مادام که این کمبود جبران نشده تأدیه هر ربح یا منفعتی به '
  'او ممنوع است. هر گاه وجهی برخلاف حکم فوق تأدیه گردید شریک با مسئولیت محدود تا معادل وجه دریافتی مسئول تعهدات شرکت '
  'است مگر در موردی که باحسن نیت و به اعتبار بیلان مرتبی وجهی گرفته باشد.'),
 (155,
  'هر کس به عنوان شریک با مسئولیت محدود در شرکت مختلط غیر سهامی موجودی داخل شود تا معادل سهم\u200cالشرکه خود '
  'مسئول\u200cقروضی خواهد بود که شرکت قبل از ورود او داشته خواه اسم شرکت عوض شده یا نشده باشد. هر شرطی که برخلاف این '
  'ترتیب باشد در مقابل اشخاص ثالث کان\u200cلم\u200cیکن خواهد بود.'),
 (156,
  'اگر شرکت مختلط غیر سهامی ورشکست شود دارایی شرکت بین طلبکاران خود شرکت تقسیم شده و طلبکاران شخصی شرکاء در '
  'آن\u200cحقی ندارند - سهم\u200cالشرکه شرکاء با مسئولیت محدود نیز جزو دارایی شرکت محسوب است.'),
 (157,
  'اگر دارایی شرکت برای تأدیه تمام قروض آن کافی نباشد طلبکاران آن حق دارند بقیه طلب خود را از دارایی شخصی تمام یا هر '
  'یک ازشرکاء ضامن وصول کنند در این صورت بین طلبکاران شرکت و طلبکاران شخصی شرکاء ضامن تفاوتی نخواهد بود.'),
 (158,
  'در صورت ورشکستگی یکی از شرکاء با مسئولیت محدود خود شرکت یا طلبکاران آن با طلبکاران شریک مزبور '
  'متساوی\u200cالحقوق\u200cخواهند بود.'),
 (159, 'مقررات مواد ۱۲۹ و ۱۳۰ در شرکت\u200cهای مختلط غیر سهامی نیز لازم\u200cالرعایه\u200cاست.'),
 (160,
  'اگر شریک ضامن بیش از یک نفر باشد مسئولیت آنها در مقابل طلبکاران و روابط آنها با یکدیگر تابع مقررات راجع به '
  'شرکتهای تضامنی\u200cاست.'),
 (161,
  'مقررات مواد ۱۳۶ - ۱۳۷ - ۱۳۸ - ۱۳۹ و ۱۴۰ در مورد شرکت\u200cهای مختلط غیر سهامی نیز جاری است. مرگ یا محجوریت یا '
  'ورشکستگی شریک یا شرکاء با مسئولیت محدود موجب انحلال شرکت نمی\u200cشود.'),
 (162,
  'شرکت مختلط سهامی شرکتی است که در تحت اسم مخصوصی بین عده شرکاء سهامی و یک یا چند نفر شریک ضامن '
  'تشکیل\u200cمی\u200cشود. شرکاء سهامی کسانی هستند که سرمایه آنها به صورت سهام یا قطعات سهام متساوی\u200cالقیمه در '
  'آمده و مسئولیت آنها تا میزان همان سرمایه\u200cاست که درشرکت دارند. شریک ضامن کسی است که سرمایه او به صورت سهام در '
  'نیامده و مسئول کلیه قروضی است که ممکن است علاوه بر دارایی شرکت پیدا شود درصورت تعدد شریک ضامن مسئولیت آنها در '
  'مقابل طلبکاران و روابط آنها با یکدیگر تابع مقررات شرکت تضامنی خواهد بود.'),
 (163, 'در اسم شرکت باید عبارت (\u200cشرکت مختلط) و لااقل اسم یکی از شرکاء ضامن قید شود.'),
 (164, 'مدیریت شرکت مختلف سهامی مخصوص به شریک یا شرکاء ضامن است.'),
 (165,
  'در هر یک از شرکتهای مختلط سهامی هیأت نظاری لااقل مرکب از سه نفر از شرکاء برقرار می\u200cشود و این هیأت را مجمع '
  'عمومی شرکاءبلافاصله بعد از تشکیل قطعی شرکت و قبل از هر اقدامی در امور شرکت معین می\u200cکند انتخاب هیأت بر حسب '
  'شرایط مقرر در اساسنامه شرکت تجدیدمی\u200cشود در هر صورت اولین هیأت نظار برای یک سال انتخاب خواهد شد.'),
 (166,
  'اولین هیأت نظار باید بعد از انتخاب شدن بلافاصله تحقیق کرده و اطمینان حاصل کند که تمام مقررات مواد ۲۸ - ۲۹ - ۳۸ - '
  '۳۹ - ۴۱\u200cو ۵۰ این قانون رعایت شده\u200cاست.'),
 (167,
  'اعضاء هیأت نظار از جهت اعمال اداری و نتایج حاصله از آن هیچ مسئولیتی ندارند لیکن هر یک از آنها در انجام مأموریت '
  'خود بر طبق\u200cقوانین معموله مملکتی مسئول اعمال و تقصیرات خود می\u200cباشند.'),
 (168,
  'اعضاء هیأت نظار دفاتر و صندوق و کلیه اسناد شرکت را تحت تدقیق در آورده همه\u200cساله راپورتی به مجمع عمومی '
  'می\u200cدهند و هر گاه درتنظیم صورت دارایی بی\u200cترتیبی و خطایی مشاهده نمایند در راپورت مزبور ذکر نموده و اگر '
  'مخالفتی با پیشنهاد مدیر شرکت در تقسیم منافع داشته باشنددلائل خود را بیان می\u200cکنند.'),
 (169,
  'هیأت نظار می\u200cتواند شرکاء را برای انعقاد مجمع عمومی دعوت نماید و با موافقت رأی مجمع مزبور بر طبق فقره (ب) '
  'ماده ۱۸۱ شرکت\u200cرا منحل کند.'),
 (170,
  'تا پانزده روز قبل از انعقاد مجمع عمومی هر صاحب سهمی می\u200cتواند (\u200cخود یا نماینده او) در مرکز اصلی شرکت '
  'حاضر شده از صورت\u200cبیلان و صورت دارایی و راپورت هیأت نظار اطلاع حاضر کند.'),
 (171, 'ورشکستگی هیچ یک از شرکاء ضامن موجب انحلال شرکت نخواهد شد مگر در مورد ماده ۱۳۸.'),
 (172, 'حکم مواد ۱۲۴ و ۱۳۴ در مورد شرکت مختلط سهامی و شرکاء ضامن آن جاری است.'),
 (173,
  'هر گاه شرکت مختلط سهامی ورشکست شود شرکاء سهامی تمام قیمت سهام خود را نپرداخته باشند مدیر تصفیه آنچه را که بر '
  'عهده\u200cآنها باقی است وصول می\u200cکند.'),
 (174,
  'اگر شرکت به طریقی غیر از ورشکستگی منحل شد هر یک از طلبکاران شرکت می\u200cتواند به هر یک از شرکاء سهامی که از بابت '
  'قیمت\u200cسهام خود مدیون شرکت است رجوع کرده در حدود بدهی آن شریک طلب خود را مطالبه نماید مادام که شرکت منحل نشده '
  'طلبکاران برای وصول\u200cطلب خود حق رجوع به هیچ یک از شرکاء سهامی ندارند.'),
 (175,
  'اگر شرکت مختلط ورشکست شد تا قروض شرکت از دارایی آن تأدیه نشده طلبکاران شخصی شرکاء ضامن حقی به دارایی '
  'شرکت\u200cندارند.'),
 (176, 'مفاد مواد ۲۸ - ۲۹ - ۳۸ - ۳۹ - ۴۱ و ۵۰ شامل شرکتهای مختلط سهامی است.'),
 (177,
  'هر شرکت مختلط سهامی که برخلاف مواد ۲۸ - ۲۹ - ۳۹ و ۵۰ تشکیل شود باطل است لیکن شرکاء نمی\u200cتوانند در مقابل '
  'اشخاص\u200cخارج به این بطلان استناد نمایند.'),
 (178, 'هر گاه شرکت بر حسب ماده قبل محکوم به بطلان شود مطابق ماده ۱۰۱ رفتار خواهد شد.'),
 (179, 'مفاد مواد ۸۴ - ۸۵ - ۸۶ - ۸۷ این قانون در شرکتهای مختلط نیز باید رعایت شود.'),
 (180, 'مفاد مواد ۸۹ - ۹۰ - ۹۱ و ۹۲ این قانون در مورد شرکت مختلط نیز لازم\u200cالرعایه\u200cاست.'),
 (181,
  'شرکت مختلط در موارد ذیل منحل می\u200cشود: الف) در مورد فقرات ۱ - ۲ - ۳ ماده ۹۳. ب) بر حسب تصمیم مجمع عمومی در '
  'صورتی که در اساسنامه این حق برای مجمع مذکور تصریح شده باشد. ج) بر حسب تصمیم مجمع عمومی و رضایت شرکاء ضامن.'),
 (182,
  'هر گاه در اساسنامه برای مجمع عمومی حق تصمیم به انحلال معین نشده و بین مجمع عمومی و شرکاء ضامن راجع به انحلال '
  'موافقت\u200cحاصل نشود و محکمه دلائل طرفداران انحلال را موجه بیند حکم به انحلال خواهد داد. همین حکم در موردی نیز '
  'جاری است که یکی از شرکاء ضامن\u200cبه دلائلی انحلال شرکت را از محکمه تقاضا نموده و محکمه آن دلائل را موجه ببیند.'),
 (183,
  'شرکت نسبی شرکتی است که برای امور تجارتی در تحت اسم مخصوصی بین دو یا چند نفر تشکیل و مسئولیت هر یک از شرکاء '
  'به\u200cنسبت سرمایه\u200cای است که در شرکت گذاشته.'),
 (184,
  'در اسم شرکت نسبی عبارت (\u200cشرکت نسبی) و لااقل اسم یک نفر از شرکاء باید ذکر شود - در صورتی که اسم شرکت مشتمل بر '
  'اسامی\u200cتمام شرکاء نباشد بعد از اسم شریک یا شرکایی که ذکر شده عبارتی از قبیل (\u200cو شرکاء) (\u200cو برادران) '
  'ضروری است.'),
 (185, 'دستور ماده ۱۱۸ - ۱۱۹ - ۱۲۰ - ۱۲۱ - ۱۲۲ - ۱۲۳ در مورد شرکت نسبی نیز لازم\u200cالرعایه\u200cاست.'),
 (186,
  'اگر دارایی شرکت نسبی برای تأدیه تمام قروض شرکت کافی نباشد هر یک از شرکاء به نسبت سرمایه که در شرکت داشته مسئول '
  'تأدیه\u200cقروض شرکت است.'),
 (187,
  'مادام که شرکت نسبی منحل نشده مطالبه قروض آن باید از خود شرکت به عمل آید فقط پس از انحلال طلبکاران می\u200cتوانند '
  'با رعایت\u200cماده فوق به فرد فرد شرکاء مراجعه کنند.'),
 (188,
  'هر کس به عنوان شریک ضامن در شرکت نسبی موجودی داخل شود به نسبت سرمایه که در شرکت می\u200cگذارد مسئول قروضی '
  'هم\u200cخواهد بود که شرکت قبل از ورود او داشته اعم از اینکه در اسم شرکت تغییری داده شده یا نشده باشد. قرار شرکاء '
  'برخلاف این ترتیب نسبت به اشخاص ثالث اثر ندارد.'),
 (189,
  'مفاد ماده ۱۲۶ (\u200cجز مسئولیت شرکاء که به نسبت سرمایه آنها است) و مواد ۱۲۷ تا ۱۳۶ در شرکتهای نسبی نیز جاری '
  'است.'),
 (190,
  'شرکت تعاونی تولید شرکتی است که بین عده از ارباب حرف تشکیل می\u200cشود و شرکاء مشاغل خود را برای تولید و فروش '
  'اشیاء یااجناس به کار می\u200cبرند.'),
 (191,
  'اگر در شرکت تولید یک عده از شرکاء در خدمت دائمی شرکت نبوده یا از اهل حرفه که موضوع عملیات شرکت است نباشند لااقل '
  'دوثلث اعضاء اداره\u200cکننده شرکت باید از شرکایی انتخاب شوند که حرفه آنها موضوع عملیات شرکت است.'),
 (192,
  'شرکت تعاونی مصرف شرکتی است که برای مقاصد ذیل تشکیل می\u200cشود: ۱ - فروش اجناس لازمه برای مصارف زندگانی اعم از '
  'اینکه اجناس مزبوره را شرکاء ایجاد کرده یا خریده باشند.'),
 (193,
  'شرکت تعاونی اعم از تولید یا مصرف ممکن است مطابق اصول شرکت سهامی یا بر طبق مقررات مخصوصی که با تراضی شرکاءترتیب '
  'داده شده باشد تشکیل بشود ولی در هر حال مفاد مواد ۳۲ - ۳۳ لازم\u200cالرعایه\u200cاست.'),
 (194,
  'در صورتی که شرکت تعاونی تولید یا مصرف مطابق اصول شرکت سهامی تشکیل شود حداقل سهام یا قطعات سهام ده ریال خواهد بودو '
  'هیچ یک از شرکاء نمی\u200cتوانند در مجمع عمومی بیش از یک رأی داشته باشد.'),
 (195, 'ثبت کلیه شرکتهای مذکور در این قانون الزامی و تابع جمیع مقررات قانون ثبت شرکتها است.'),
 (196, 'اسناد و نوشتجاتی که برای به ثبت رساندن شرکت لازم است در نظامنامه وزارت عدلیه معین می\u200cشود.'),
 (197, 'در ظرف ماه اول تشکیل هر شرکت خلاصه شرکتنامه و منضمات آن طبق نظامنامه وزارت عدلیه اعلان خواهد شد.'),
 (198,
  'اگر به علت عدم رعایت دستور دو ماده فوق بطلان عملیات شرکت اعلام شده هیچ یک از شرکاء نمی\u200cتوانند این بطلان را '
  'در مقابل\u200cاشخاص ثالثی که با آنها معامله کرده\u200cاند عذر قرار دهند.'),
 (199,
  'هر گاه شرکت در چندین حوزه شعبه داشته باشد مقررات مواد ۱۹۵ و ۱۹۷ باید به قسمی که در نظامنامه وزارت عدلیه معین '
  'می\u200cشود درهر حوزه جداگانه انجام گردد.'),
 (200,
  'در هر موقع که تصمیماتی برای تغییر اساسنامه شرکت یا تمدید مدت شرکت زائد بر مدت مقرر یا انحلال شرکت (\u200cحتی در '
  'مواردی که\u200cانحلال به واسطه انقضای مدت شرکت صورت می\u200cگیرد) و تعیین کیفیت تفریغ حساب یا تبدیل شرکاء یا خروج '
  'بعضی از آنها از شرکت یا تغییر اسم\u200cشرکت اتخاذ شود مقررات مواد ۱۹۵ و ۱۹۷ لازم\u200cالرعایه\u200cاست. همین '
  'ترتیب در موقع هر تصمیمی که نسبت به مورد معین در ماده ۷۹ این قانون اتخاذمی\u200cشود رعایت خواهد شد.'),
 (201,
  'در هر گونه اسناد و صورت\u200cحسابها و اعلانات و نشریات و غیره که به طور خطی یا چاپی از طرف شرکت\u200cهای مذکور در '
  'این قانون به\u200cاستثنای شرکتهای تعاونی صادر می\u200cشود سرمایه شرکت صریحاً باید ذکر گردد و اگر تمام سرمایه '
  'پرداخته نشده قسمتی که پرداخته شده نیز باید صریحاً\u200cمعین شود - شرکت متخلف به جزای نقدی از 33/000/000 تا '
  '200/000/000 ریال محکوم خواهد شد. تبصره - شرکتهای خارجی نیز که به وسیله شعبه یا نماینده در ایران اشتغال به تجارت '
  'دارند در مورد اسناد و صورت\u200cحسابها و اعلانات و نشریات\u200cخود در ایران مشمول مقررات این ماده خواهند بود.'),
 (202,
  'تصفیه امور شرکتها پس از انحلال موافق مواد ذیل خواهد بود مگر در مورد ورشکستگی که تابع مقررات مربوط به ورشکستگی '
  'است.'),
 (203,
  'در شرکت\u200cهای تضامنی و نسبی و مختلط سهامی و غیر سهامی امر تصفیه با مدیر یا مدیران شرکت است مگر آن که شرکاء '
  'ضامن\u200cاشخاص دیگری را از خارج یا از بین خود برای تصفیه معین نمایند.'),
 (204,
  'اگر از طرف یک یا چند شریک ضامن تعیین اشخاص مخصوص برای تصفیه تقاضا شد و سایر شرکاء ضامن آن تقاضا را نپذیرفتندمحکمه '
  'بدایت اشخاصی را برای تصفیه معین خواهد کرد.'),
 (205,
  'در هر مورد که اشخاصی غیر از مدیران شرکت برای تصفیه معین شوند اسامی آنها باید در اداره ثبت اسناد ثبت و اعلان '
  'گردد.'),
 (206,
  'در شرکتهای مختلط (\u200cسهامی و غیر سهامی) شرکاء غیر ضامن حق دارند یک یا چند نفر برای نظارت در امر تصفیه معین '
  'نمایند.'),
 (207,
  'وظیفه متصدیان تصفیه خاتمه دادن به کارهای جاری و اجرای تعهدات و وصول مطالبات و تقسیم دارایی شرکت است به ترتیب '
  'مقرردر مواد ۲۰۸ - ۲۰۹ - ۲۱۰ - ۲۱۱ و ۲۱۲.'),
 (208, 'اگر برای اجرای تعهدات شرکت معاملات جدیدی لازم شود متصدیان تصفیه انجام خواهند داد.'),
 (209, 'متصدیان تصفیه حق دارند شخصاً یا به توسط وکیل از طرف شرکت محاکمه کنند.'),
 (210,
  'متصدی تصفیه وقتی حق اصلاح و تعیین حکم دارد که شرکاء ضامن به او اجازه داده باشند - مواردی که به حکم قانون '
  'حکمیت\u200cاجباری است از این قاعده مستثنی است.'),
 (211,
  'آن قسمت از دارایی شرکت که در مدت تصفیه محل احتیاج نیست به طور موقت بین شرکاء تقسیم می\u200cشود ولی متصدیان تصفیه '
  'بایدمعادل قروضی که هنوز موعد تأدیه آن نرسیده\u200cاست و همچنین معادل مبلغی که در حساب بین شرکاء مورد اختلاف است '
  'موضوع نمایند.'),
 (212,
  'متصدیان تصفیه حساب شرکاء را نسبت به هم و سهم هر یک از شرکاء را از نفع و ضرر معین می\u200cکنند - رفع اختلاف در '
  'تقسیم به\u200cمحکمه بدایت رجوع می\u200cشود.'),
 (213,
  'در شرکتهای سهامی و شرکتهای با مسئولیت محدود و شرکتهای تعاونی امر تصفیه به عهده مدیران شرکت است مگر آنکه اساسنامه '
  'یااکثریت مجمع عمومی شرکت ترتیب دیگری مقرر داشته باشد.'),
 (214,
  'وظیفه و اختیارات متصدیان تصفیه در شرکت سهامی و شرکتهای با مسئولیت محدود و تعاونی به ترتیبی است که در ماده ۲۰۷ '
  'مقررشده با این تفاوت که حق اصلاح و تعیین حکم برای متصدیان تصفیه این شرکتها (\u200cبه استثنای مورد حکمیت اجباری) '
  'فقط وقتی خواهد بود که\u200cاساسنامه یا مجمع عمومی این حق را به آنها داده باشد.'),
 (215,
  'تقسیم دارایی شرکتهای مذکور در ماده فوق بین شرکاء خواه در ضمن مدت تصفیه و خواه پس از ختم آن ممکن نیست مگر آن که '
  'قبلاً\u200cسه مرتبه در مجله رسمی و یکی از جراید اعلان و یک سال از تاریخ انتشار اولین اعلان در مجله گذشته باشد.'),
 (216, 'تخلف از ماده قبل متصدیان تصفیه را مسئول خسارت طلبکارانی قرار خواهد داد که به طلب خود نرسیده\u200cاند.'),
 (217,
  'دفاتر هر شرکتی که منحل شده با نظر مدیر ثبت اسناد در محل معینی از تاریخ ختم تصفیه تا ده سال محفوظ خواهد ماند.'),
 (218,
  'هر شرکتی مجاز است در اساسنامه خود برای تصفیه ترتیب دیگری مقرر دارد ولی در هر حال آن مقررات نباید مخالف مواد ۲۰۷ '
  '-۲۰۸ - ۲۰۹ - ۲۱۰ - ۲۱۵ - ۲۱۶ - ۲۱۷ و قسمت اخیر ماده ۲۱۱ باشد.'),
 (219,
  'مدت مرور زمان در دعاوی اشخاص ثالث بر علیه شرکاء یا وراث آنها راجع به معاملات شرکت (\u200cدر مواردی که قانون شرکاء '
  'یا وراث آنهارا مسئول قرار داده) پنج سال است. مبدأ مرور زمان روزی است که انحلال شرکت یا کناره\u200cگیری شریک یا '
  'اخراج او از شرکت در اداره ثبت به ثبت رسیده و در مجله رسمی اعلان شده باشد. در صورتی که طلب پس از ثبت و اعلان قابل '
  'مطالبه شده باشد مرور زمان از روزی شروع می\u200cشود که طلبکار حق مطالبه پیدا کرده. تبصره - دعوایی که سنخاً تابع '
  'مرور زمان کوتاه\u200cتری بوده یا به موجب این قانون مرور زمان طولانی\u200cتری برای آن معین شده از مقررات این '
  'ماده\u200cمستثنی است.'),
 (220,
  'هر شرکت ایرانی که فعلاً وجود داشته یا در آتیه تشکیل شود و با اشتغال به امور تجارتی خود را به صورت یکی از شرکتهای '
  'مذکور دراین قانون در نیاورده و مطابق مقررات مربوطه به آن شرکت عمل ننماید شرکت تضامنی محسوب شده و احکام راجع به '
  'شرکتهای تضامنی در مورد آن\u200cاجرا می\u200cگردد. هر شرکت تجارتی ایرانی مذکور در این قانون و هر شرکت خارجی که بر '
  'طبق قانون ثبت شرکتها مصوب خرداد ماه ۱۳۱۰ مکلف به ثبت است باید درکلیه اسناد و صورت\u200cحسابها و اعلانات و نشریات '
  'خطی یا چاپی خود در ایران تصریح نماید که در تحت چه نمره در ایران به ثبت رسیده و الا محکوم به\u200cجزای نقدی از '
  '33/000/000 تا 200/000/000 ریال خواهد شد - این مجازات علاوه بر مجازاتی است که در قانون ثبت شرکتها برای عدم ثبت '
  'مقرر شده.'),
 (221,
  'اگر شرکت سهام یا اوراق استقراضی داشته باشد که مطابق اساسنامه شرکت یا تصمیم مجمع عمومی قیمت آنها به طریق قرعه باید '
  'تأدیه\u200cشود و قبل از تأدیه قیمت آن سهام یا اوراق منافعی که به آنها تعلق گرفته پرداخته شده باشد شرکت در موقع '
  'تأدیه اصل قیمت نمی\u200cتواند منافع تأدیه شده\u200cرا استرداد نماید.'),
 (222,
  'هر شرکت تجارتی می\u200cتواند در اساسنامه خود قید کند که سرمایه اولیه خود را به وسیله تأدیه اقساط بعدی از طرف '
  'شرکاء یا قبول\u200cشریک جدید زیاد کرده و یا به واسطه برداشت از سرمایه آن را تقلیل دهد. در اساسنامه حداقلی که تا '
  'آن میزان می\u200cتوان سرمایه اولیه را تقلیل داد صراحتاً معین می\u200cشود. کمتر از عشر سرمایه اولیه شرکت را حداقل '
  'قرار دادن ممنوع است.'),
 (223,
  'برات علاوه بر امضاء یا مهر برات\u200cدهنده باید دارای شرایط ذیل باشد: ۱) قید کلمه (\u200cبرات) در روی ورقه. ۲) '
  'تاریخ تحریر (\u200cروز و ماه و سال). ۳) اسم شخصی که باید برات را تأدیه کند. ۴) تعیین مبلغ برات. ۵) تاریخ تأدیه '
  'وجه برات. ۶) مکان تأدیه وجه برات اعم از اینکه محل اقامت محال\u200cعلیه باشد یا محل دیگر. ۷) اسم شخصی که برات در '
  'وجه یا حواله\u200cکرد او پرداخته می\u200cشود. ۸) تصریح به اینکه نسخه اول یا دوم یا سوم یا چهارم الخ است.'),
 (224, 'برات ممکن است به حواله\u200cکرد شخص دیگر باشد یا به حواله\u200cکرد خود برات\u200cدهنده.'),
 (225,
  'تاریخ تحریر و مبلغ برات با تمام حروف نوشته می\u200cشود. اگر مبلغ بیش از یک دفعه به تمام حروف نوشته شده و بین آنها '
  'اختلاف باشد مبلغ کمتر مناط اعتبار است اگر مبلغ با حروف و رقم هر دو نوشته شده وبین آنها اختلاف باشد مبلغ با حروف '
  'معتبر است.'),
 (226,
  'در صورتی که برات متضمن یکی از شرایط اساسی مقرر در فقرات ۲ - ۳ - ۴ - 5 - 6 - 7 و 8 [m]\u200cماده ۲۲۳ نباشد مشمول '
  'مقررات\u200cراجعه به بروات تجارتی نخواهد بود.'),
 (227, 'برات ممکن است به دستور و حساب شخص دیگری صادر شود.'),
 (228,
  'قبولی برات در خود برات با قید تاریخ نوشته شده امضاء یا مهر می\u200cشود. در صورتی که برات به وعده از رؤیت باشد '
  'تاریخ قبولی با تمام حروف نوشته خواهد شد - اگر قبولی بدون تاریخ نوشته شد تاریخ برات تاریخ رؤیت\u200cحساب '
  'می\u200cشود.'),
 (229,
  'هر عبارتی که محال\u200cعلیه در برات نوشته امضاء یا مهر کند قبولی محسوب است مگر اینکه صریحاً عبارت مشعر بر عدم '
  'قبول باشد. اگر عبارت فقط مشعر بر عدم قبول یک جزء از برات باشد بقیه وجه برات قبول شده محسوب است. در صورتی که '
  'محال\u200cعلیه بدون تحریر هیچ عبارتی برات را امضاء یا مهر نماید برات قبول شده محسوب می\u200cشود.'),
 (230, 'قبول\u200cکننده برات ملزم است وجه آن را سر وعده تأدیه نماید.'),
 (231, 'قبول\u200cکننده حق نکول ندارد.'),
 (232, 'ممکن است قبولی منحصر به یک قسمت از وجه برات باشد در این صورت دارنده برات باید برای بقیه اعتراض نماید.'),
 (233,
  'اگر قبولی مشروط به شرط نوشته شد برات نکول شده محسوب می\u200cشود ولی معهذا قبول\u200cکننده به شرط در حدود شرطی که '
  'نوشته\u200cمسئول پرداخت وجه برات است.'),
 (234, 'در قبولی براتی که وجه آن در خارج از محل اقامت قبول\u200cکننده باید تأدیه شود تصریح به مکان تأدیه ضروری است.'),
 (235, 'برات باید به محض ارائه یا منتهی در ظرف ۲۴ ساعت از تاریخ ارائه قبول یا نکول شود.'),
 (236,
  'نکول برات باید به موجب تصدیقنامه که رسماً تنظیم می\u200cشود محقق گردد - تصدیقنامه مزبور موسم است به اعتراض '
  '(\u200cپروتست)\u200cنکول.'),
 (237,
  'پس از اعتراض نکول ظهرنویسها و برات\u200cدهنده به تقاضای دارنده برات باید ضامنی برای تأدیه وجه آن در سر وعده بدهند '
  'یا وجه برات\u200cرا به انضمام مخارج اعتراضنامه و مخارج برات رجوعی (\u200cاگر باشد) فوراً تأدیه نمایند.'),
 (238,
  'اگر بر علیه کسی که براتی قبول کرده ولی وجه آن را نپرداخته اعتراض عدم تأدیه شود دارنده براتی نیز که همان شخص قبول '
  'کرده ولی\u200cهنوز موعد پرداخت آن نرسیده\u200cاست می\u200cتواند از قبول\u200cکننده تقاضا نماید که برای پرداخت وجه '
  'آن ضامن دهد یا پرداخت آن را به نحو دیگری تضمین\u200cکند.'),
 (239,
  'هر گاه براتی نکول شد و اعتراض به عمل آمد شخص ثالثی می\u200cتواند آن را به برات\u200cدهنده یا یکی از ظهرنویسها '
  'قبول کند - قبولی\u200cشخص ثالث باید در اعتراضنامه قید شده به امضاء او برسد.'),
 (240,
  'بعد از قبولی شخص ثالث نیز تا برات تأدیه نشده کلیه حقوقی که برای دارنده برات از نکول آن در مقابل برات\u200cدهنده و '
  'ظهرنویس\u200cهاحاصل می\u200cشود محفوظ خواهد بود.'),
 (241,
  'برات ممکن است به رویت باشد یا به وعده یک یا چند روز یا یک یا چند ماه از رؤیت برات یا به وعده یک یا چند روز یا یک '
  'یا چند ماه\u200cاز تاریخ برات - ممکن است پرداخت به روز معینی موکول شده باشد.'),
 (242, 'هر گاه برات بی\u200cوعده قبول شد باید فوراً پرداخته شود.'),
 (243,
  'موعد پرداخت براتی که یک یا چند روز یا یک یا چند ماه از رؤیت وعده دارد به وسیله تاریخ قبولی یا تاریخ اعتراضنامه '
  'نکول معین\u200cمی\u200cشود.'),
 (244,
  'اگر موعد پرداخت برات با تعطیل رسمی تصادف کرد باید روز بعد تعطیل تأدیه شود. تبصره - همین قاعده در مورد سایر اوراق '
  'تجارتی نیز رعایت خواهد شد.'),
 (245, 'انتقال برات به وسیله ظهرنویسی به عمل می\u200cآید.'),
 (246,
  'ظهرنویسی باید به امضاء ظهرنویس برسد - ممکن است در ظهرنویسی تاریخ و اسم کسی که برات به او انتقال داده می\u200cشود '
  'قید گردد.'),
 (247,
  'ظهرنویسی حاکی از انتقال برات است مگر اینکه ظهرنویسی وکالت در وصول را قید نموده باشد که در این صورت انتقال برات '
  'واقع\u200cنشده ولی دارنده برات حق وصول و لدی\u200cالاقتضاء حق اعتراض و اقامه دعوی برای وصول خواهد داشت. جز در '
  'مواردی که خلاف این در برات تصریح\u200cشده باشد.'),
 (248, 'هر گاه ظهرنویس در ظهرنویسی تاریخ مقدمی قید کند مزور شناخته می\u200cشود.'),
 (249,
  'برات\u200cدهنده - کسی که برات را قبول کرده و ظهرنویسها در مقابل دارنده برات مسئولیت تضامنی دارند. دارنده برات در '
  'صورت عدم تأدیه و اعتراض می\u200cتواند به هر کدام از آنها که بخواهد منفرداً یا به چند نفر یا به تمام آنها مجتمعاً '
  'رجوع نماید. همین حق را هر یک از ظهرنویسها نسبت به برات\u200cدهنده و ظهرنویسهای ماقبل خود دارد. اقامه دعوی بر علیه '
  'یک یا چند نفر از مسئولین موجب اسقاط حق رجوع به سایر مسئولیت برات نیست - اقامه\u200cکننده دعوی ملزم نیست '
  'ترتیب\u200cظهرنویسی را از حیث تاریخ رعایت کند. ضامنی که ضمانت برات\u200cدهنده یا محال\u200cعلیه یا ظهرنویسی را '
  'کرده فقط با کسی مسئولیت تضامنی دارد که از او ضمانت نموده\u200cاست.'),
 (250,
  'هر یک از مسئولین تأدیه برات می\u200cتواند پرداخت را به تسلیم برات و اعتراضنامه و صورت\u200cحساب متفرعات و مخارج '
  'قانونی که بایدبپردازد موکول کند.'),
 (251,
  'هر گاه چند نفر از مسئولین برات ورشکست شوند دارنده برات می\u200cتواند در هر یک از غرما یا در تمام غرما برای وصول '
  'تمام طلب خود(\u200cوجه برات و متفرعات و مخارج قانونی) داخل شود تا اینکه طلب خود را کاملاً وصول نماید - مدیر تصفیه '
  'هیچ یک از ورشکستگان نمی\u200cتواند برای\u200cوجهی که به صاحب چنین طلب پرداخته می\u200cشود به مدیر تصفیه ورشکسته '
  'دیگر رجوع نماید مگر در صورتی که مجموع وجوهی که از دارایی تمام\u200cورشکستگان به صاحب طلب تخصیص می\u200cیابد بیش '
  'از میزان طلب او باشد در این صورت مازاد باید به ترتیب تاریخ تعهد تا میزان وجهی که هر کدام\u200cپرداخته\u200cاند - '
  'جزء دارایی ورشکستگان محسوب گردد که به سایر ورشکسته\u200cها حق رجوع دارند. تبصره - مفاد این ماده در مورد ورشکستگی '
  'هر چند نفری نیز که برای پرداخت یک دین مسئولیت تضامنی داشته باشند مرعی خواهد بود.'),
 (252, 'پرداخت برات به انواع پولی که در آن معین شده به عمل می\u200cآید.'),
 (253,
  'اگر دارنده برات به برات\u200cدهنده یا کسی که برات را به او منتقل کرده\u200cاست پولی غیر از آن نوع که در برات معین '
  'شده\u200cاست بدهد و آن برات\u200cدر نتیجه نکول یا امتناع از قبول یا عدم تأدیه اعتراض شود دارنده برات '
  'می\u200cتواند از دهنده برات یا انتقال\u200cدهنده نوع پولی را که داده یا نوع پولی که دربرات معین شده مطالبه کند '
  'ولی از سایر مسئولین وجه برات جز نوع پولی که در برات معین شده قابل مطالبه نیست.'),
 (254, 'برات به وعده باید روز آخر وعده پرداخته شود.'),
 (255,
  'روز رؤیت در برواتی که به وعده از رؤیت است و روز صدور برات در برواتی که به وعده از تاریخ صدور است حساب نخواهد شد.'),
 (256, 'شخصی که وجه برات را قبل از موعد تأدیه نموده در مقابل اشخاصی که نسبت به وجه برات حقی دارند مسئول است.'),
 (257,
  'اگر دارنده برات به کسی که قبولی نوشته مهلتی برای پرداخت بدهد به ظهرنویسهای ماقبل خود و برات\u200cدهنده که به مهلت '
  'مزبوررضایت نداده\u200cاند حق رجوع نخواهد داشت.'),
 (258,
  'شخصی که در سر وعده وجه برات را می\u200cپردازد بری\u200cالذمه محسوب می\u200cشود مگر آنکه وجه برات قانوناً در نزد '
  'او توقیف شده باشد.'),
 (259,
  'پرداخت وجه برات ممکن است به موجب نسخه ثانی یا ثالث یا رابع الخ به عمل آید در صورتی که در روی آن نسخه قید شده باشد '
  'که\u200cپس از پرداخت وجه به موجب این نسخه نسخ دیگر از اعتبار ساقط است.'),
 (260,
  'شخصی که وجه برات را بر حسب نسخه بپردازد که در روی آن قبولی نوشته نشده در مقابل شخصی که نسخه قبولی شده را '
  'داردمسئول پرداخت وجه آن است.'),
 (261,
  'در صورت گم شدن براتی که هنوز قبول نشده\u200cاست صاحب آن می\u200cتواند وصول وجه آن را بر حسب نسخه ثانی یا ثالث یا '
  'رابع الخ\u200cتقاضا کند.'),
 (262,
  'اگر نسخه مفقود نسخه باشد که قبولی در روی آن نوشته شده تقاضای پرداخت از روی نسخه\u200cهای دیگر فقط به موجب امر '
  'محکمه پس\u200cاز دادن ضامن به عمل می\u200cآید.'),
 (263,
  'اگر شخصی که برات را گم کرده - اعم از اینکه قبولی نوشته شده یا نشده باشد می\u200cتواند نسخه ثانی یا ثالث یا رابع '
  'الخ را تحصیل نمایدپس از اثبات اینکه برات متعلق به او است می\u200cتواند با دادن ضامن تأدیه وجه آن را به موجب امر '
  'محکمه مطالبه کند.'),
 (264,
  'اگر با وجود تقاضایی که در مورد مواد ۲۶۱ - ۲۶۲ و ۲۶۳ به عمل آمده\u200cاست از تأدیه وجه برات امتناع شود صاحب برات '
  'مفقودمی\u200cتواند تمام حقوق خود را به موجب اعتراضنامه محفوظ بدارد.'),
 (265,
  'اعتراضنامه مذکور در ماده فوق باید در ظرف ۲۴ ساعت از تاریخ وعده برات تنظیم شده و در مواعد و به ترتیبی که در این '
  'قانون برای\u200cابلاغ اعتراضنامه معین شده\u200cاست به برات\u200cدهنده و ظهرنویسها ابلاغ گردد.'),
 (266,
  'صاحب برات مفقود برای تحصیل نسخه ثانی باید به ظهرنویسی که بلافاصله قبل از او بوده\u200cاست رجوع نماید - ظهرنویس '
  'مزبور ملزم\u200cاست به صاحب برات اختیار مراجعه به ظهرنویس ماقبل خود داده و راهنمایی کند و همچنین هر ظهرنویس باید '
  'اختیار رجوع به ظهرنویس ماقبل خودبدهد تا به برات\u200cدهنده برسد - مخارج این اقدامات بر عهده صاحب برات مفقود خواهد '
  'بود. ظهرنویس در صورت امتناع از دادن اختیار مسئول تأدیه وجه برات و خساراتی است که بر صاحب برات مفقود وارد '
  'شده\u200cاست.'),
 (267,
  'در صورتی که ضامن برات مفقود (\u200cرجوع به مواد ۲۶۲ و ۲۶۳) مدتی برای ضمانت خود معین نکرده باشد مدت ضمان سه سال '
  'است وهر گاه در ظرف این سه سال رسماً مطالبه یا اقامه دعوی نشده باشد دیگر از این حیث دعوی بر علیه او در محکمه مسموع '
  'نخواهد بود.'),
 (268,
  'اگر مبلغی از وجه برات پرداخته شود به همان اندازه برات\u200cدهنده و ظهرنویسها بری می\u200cشوند و دارنده برات فقط '
  'نسبت به بقیه می\u200cتوانداعتراض کند.'),
 (269, 'محاکم نمی\u200cتوانند بدون رضایت صاحب برات برای تأدیه وجه برات مهلتی بدهند.'),
 (270,
  'هر شخص ثالثی می\u200cتواند از طرف برات\u200cدهنده یا یکی از ظهرنویسها وجه برات اعتراض شده را کارسازی نماید - '
  'دخالت شخص ثالث وپرداخت وجه باید در اعتراضنامه یا در ذیل آن قید شود.'),
 (271, 'شخص ثالثی که وجه برات را پرداخته دارای تمام حقوق و وظایف دارنده برات است.'),
 (272,
  'اگر وجه برات را شخص ثالث از طرف برات\u200cدهنده پرداخت تمام ظهرنویسها بری\u200cالذمه می\u200cشوند و اگر پرداخت '
  'وجه از طرف یکی ازظهرنویسها به عمل آید ظهرنویسهای بعد از او بری\u200cالذمه\u200cاند.'),
 (273,
  'اگر دو شخص متفقاً هر یک از جانب یکی از مسئولین برات برای پرداخت وجه حاضر شوند پیشنهاد آن کس پذیرفته\u200cاست که '
  'تأدیه وجه\u200cاز طرف او عده زیادتری از مسئولین را بری\u200cالذمه می\u200cکند - اگر خود محال\u200cعلیه پس از '
  'اعتراض برای تأدیه وجه حاضر شود بر هر شخص ثالثی ترجیح\u200cدارد.'),
 (274,
  'نسبت به برواتی که وجه آن باید در ایران به رؤیت یا به وعده از رؤیت تأدیه شود اعم از اینکه برات در ایران صادر شده '
  'باشد یا درخارجه دارنده برات مکلف است پرداخت یا قبولی آن را در ظرف یک سال از تاریخ برات مطالبه نماید و الا حق رجوع '
  'به ظهرنویسها و همچنین به\u200cبرات\u200cدهنده که وجه برات را به محال\u200cعلیه رسانیده\u200cاست نخواهد داشت.'),
 (275,
  'اگر در برات اعم از اینکه در ایران صادر شده باشد یا در خارجه برای تقاضای قبولی مدت بیشتر یا کمتری مقرر شده باشد '
  'دارنده برات\u200cباید در همان مدت قبولی برات را تقاضا نماید و الا حق رجوع به ظهرنویسها و برات\u200cدهنده که وجه '
  'برات را به محال\u200cعلیه رسانیده\u200cاست نخواهد داشت.'),
 (276,
  'اگر ظهرنویسی برای تقاضای قبولی مدتی معین کرده باشد دارنده برات باید در مدت مزبور تقاضای قبولی نماید و الا در '
  'مقابل آن\u200cظهرنویس نمی\u200cتواند از مقررات مربوطه به بروات استفاده کند.'),
 (277,
  'هر گاه دارنده برات به رؤیت یا به وعده که در یکی از شهرهای ایران صادر و باید در ممالک خارجه تأدیه شود در مواعد '
  'مقرر در موادفوق قبولی نوشتن یا پرداخت وجه را مطالبه نکرده باشد مطابق مقررات همان مواد حق او ساقط خواهد شد.'),
 (278, 'مقررات فوق مانع نخواهد بود که بین دارنده برات و برات\u200cدهنده و ظهرنویسها قرارداد دیگری مقرر گردد.'),
 (279, 'دارنده برات باید روز وعده وجه برات را مطالبه کند.'),
 (280,
  'امتناع از تأدیه وجه برات باید در ظرف ده روز از تاریخ وعده به وسیله نوشته که اعتراض عدم تأدیه نامیده می\u200cشود '
  'معلوم گردد.'),
 (281, 'اگر روز دهم تعطیل باشد اعتراض روز بعد آن به عمل خواهد آمد.'),
 (282, 'نه فوت محال\u200cعلیه نه ورشکستگی او نه اعتراض نکولی دارنده برات را از اعتراض عدم تأدیه مستغنی نخواهد کرد.'),
 (283, 'در صورتی که قبول\u200cکننده برات قبل از وعده ورشکست شود حق اعتراض برای دارنده برات باقی است.'),
 (284,
  'دارنده براتی که به علت عدم تأدیه اعتراض شده\u200cاست باید در ظرف ده روز از تاریخ اعتراض عدم تأدیه را به وسیله '
  'اظهارنامه رسمی یامراسله سفارشی دو قبضه به کسی که برات را به او واگذار نموده اطلاع دهد.'),
 (285,
  'هر یک از ظهرنویسها نیز باید در ظرف ده روز از تاریخ دریافت اطلاع\u200cنامه فوق آن را به همان وسیله به ظهرنویس سابق '
  'خود اطلاع دهد.'),
 (286,
  'اگر دارنده براتی که بایستی در ایران تأدیه شود و به علت عدم پرداخت اعتراض شده بخواهد از حقی که ماده ۲۴۹ برای او '
  'مقرر داشته\u200cاستفاده کند باید در ظرف سه ماه از تاریخ اعتراض اقامه دعوی نماید. تبصره - هر گاه محل اقامت '
  'مدعی\u200cعلیه خارج از محلی باشد که وجه برات باید در آنجا پرداخته شود برای هر شش فرسخ یک روز اضافه خواهدشد.'),
 (287,
  'در مورد برواتی که باید در خارجه تأدیه شود اقامه دعوی بر علیه برات\u200cدهنده و یا ظهرنویس\u200cهای مقیم ایران در '
  'ظرف شش ماه از تاریخ\u200cاعتراض باید به عمل آید.'),
 (288,
  'هر یک از ظهرنویسها بخواهد از حقی که در ماده ۲۴۹ به او داده شده استفاده نماید باید در مواعدی که به موجب مواد ۲۸۶ و '
  '۲۸۷ مقرراست اقامه دعوی کند و نسبت به او موعد از فردای ابلاغ احضاریه محکمه محسوب است و اگر وجه برات را بدون اینکه '
  'بر علیه او اقامه دعوی شده\u200cباشد تأدیه نماید از فردای روز تأدیه محسوب خواهد شد.'),
 (289,
  'پس از انقضاء مواعد مقرره در مواد فوق دعوی دارنده برات بر ظهرنویسها و همچنین دعوی هر یک از ظهرنویسها بر ید سابق '
  'خود درمحکمه پذیرفته نخواهد شد.'),
 (290,
  'پس از انقضاء مواعد فوق دعوی دارنده و ظهرنویسهای برات بر علیه برات\u200cدهنده نیز پذیرفته نمی\u200cشود مشروط بر '
  'اینکه برات\u200cدهنده ثابت\u200cنماید در سر وعده وجه برات را به محال\u200cعلیه رسانیده و در این صورت دارنده برات '
  'فقط حق مراجعه به محال\u200cعلیه خواهد داشت.'),
 (291,
  'اگر پس از انقضاء موعدی که برای اعتراض و ابلاغ اعتراضنامه یا برای اقامه دعوی مقرر است برات\u200cدهنده یا هر یک از '
  'ظهرنویسها به\u200cطریق محاسبه یا عنوان دیگر وجهی را که برای تأدیه برات به محال\u200cعلیه رسانیده بود مسترد دارد '
  'دارنده برات برخلاف مقررات دو ماده قبل حق خواهدداشت که بر علیه دریافت\u200cکننده وجه اقامه دعوی نماید.'),
 (292,
  'پس از اقامه دعوی محکمه مکلف است به مجرد تقاضای دارنده براتی که به علت عدم تأدیه اعتراض شده\u200cاست معادل وجه '
  'برات را ازاموال مدعی\u200cعلیه به عنوان تأمین توقیف نماید.'),
 (293,
  'اعتراض در موارد ذیل به عمل می\u200cآید: ۱) در مورد نکول. ۲) در مورد امتناع از قبول یا نکول. ۳) در مورد عدم تأدیه. '
  'اعتراضنامه باید در یک نسخه تنظیم و به موجب امر محکمه بدایت به توسط مأمور اجراء به محل اقامت اشخاص ذیل ابلاغ شود: '
  '۱) محال\u200cعلیه. ۲) اشخاصی که در برات برای تأدیه وجه عندالاقتضاء معین شده\u200cاند. ۳) شخص ثالثی که برات را '
  'قبول کرده\u200cاست. اگر در محلی که اعتراض به عمل می\u200cآید محکمه بدایت نباشد وظایف او با رعایت ترتیب به عهده '
  'امین صلح یا رییس ثبت اسناد یا حاکم محل خواهدبود.'),
 (294,
  'اعتراضنامه باید مراتب ذیل را دارا باشد: ۱) سواد کامل برات با کلیه محتویات آن اعم از قبولی و ظهرنویسی و غیره. ۲) '
  'امر به تأدیه وجه برات. مأمور اجرا باید حضور یا غیاب شخصی که باید وجه برات را بدهد و علل امتناع از تأدیه یا از '
  'قبول و همچنین علل عدم امکان امضاء یا امتناع از امضاءرا در ذیل اعتراضنامه قید و امضاء کند.'),
 (295,
  'هیچ نوشته نمی\u200cتواند از طرف دارنده برات جایگیر اعتراضنامه شود مگر در موارد مندرجه در مواد ۲۶۱ - ۲۶۲ و ۲۶۳ '
  'راجع به مفقودشدن برات.'),
 (296, 'مأمور اجرا باید سواد صحیح اعتراضنامه را به محل اقامت اشخاص مذکور در ماده ۲۹۳ بدهد.'),
 (297,
  'دفتر محکمه یا دفتر مقاماتی که وظیفه محکمه را انجام می\u200cدهند باید مفاد اعتراضنامه را روز به روز به ترتیب تاریخ '
  'و نمره در دفترمخصوصی که صفحات آن به توسط رییس محکمه یا قائم\u200cمقام او نمره و امضاء شده\u200cاست ثبت نمایند - '
  'در صورتی که محل اقامت برات\u200cدهنده یاظهرنویس اولی در روی برات قید شده باشد دفتر محکمه باید آنها را توسط کاغذ '
  'سفارشی از علل امتناع از تأدیه مستحضر سازد.'),
 (298,
  'برات رجوعی براتی است که دارنده برات اصلی پس از اعتراض برای دریافت وجه آن و مخارج صدور اعتراضنامه و تفاوت نرخ '
  'به\u200cعهده برات\u200cدهنده یا یکی از ظهرنویسها صادر می\u200cکند.'),
 (299,
  'اگر برات رجوعی به عهده برات\u200cدهنده اصلی صادر شود تفاوت بین نرخ مکان تأدیه برات اصلی و نرخ مکان صدور آن به '
  'عهده اوخواهد بود و اگر برات رجوعی به عهده یکی از ظهرنویسها صادر شود مشارالیه باید از عهده تفاوت نرخ مکانی که برات '
  'اصلی را در آنجا معامله یاتسلیم کرده\u200cاست و نرخ مکانی که برای رجوعی در آنجا صادر شده\u200cاست برآید.'),
 (300,
  'به برات رجوعی باید صورت\u200cحسابی (\u200cحساب بازگشت) ضمیمه شود - در صورت حساب مزبور مراتب ذیل قید می\u200cگردد: '
  '۱) اسم شخصی که برات رجوعی به عهده او صادر شده\u200cاست. ۲) مبلغ اصلی برات اعتراض شده. ۳) مخارج اعتراضنامه و سایر '
  'مخارج معموله از قبیل حق\u200cالعمل صراف و دلال و وجه تمبر و مخارج پست و غیره. ۴) مبلغ تفاوت نرخهای مذکور در ماده '
  '(۲۹۹).'),
 (301,
  'صورت\u200cحساب مذکور در ماده قبل باید توسط دو نفر تاجر تصدیق شود به علاوه لازم است برات اعتراض شده و سواد مصدقی '
  'ازاعتراضنامه به صورت حساب مزبور ضمیمه گردد.'),
 (302,
  'هر گاه برات رجوعی به عهده یکی از ظهرنویسها صادر شود علاوه بر مراتب مذکور در مواد ۳۰۰ و ۳۰۱ باید تصدیقنامه که '
  'تفاوت بین\u200cنرخ مکان تأدیه برات اصلی و مکان صدور آن را معین نماید ضمیمه شود.'),
 (303,
  'نسبت به یک برات صورت\u200cحساب بازگشت متعدد نمی\u200cتوان ترتیب داد و اگر برات رجوعی به عهده یکی از ظهرنویسها '
  'صادر شده باشدحساب بازگشت متوالیاً به توسط ظهرنویسها پرداخته می\u200cشود تا به برات\u200cدهنده اولی برسد. تحمیلات '
  'براتهای رجوعی را نمی\u200cتوان تماماً بر یک نفر وارد ساخت - هر یک از ظهرنویسها و برات\u200cدهنده اولی فقط '
  'عهده\u200cدار یک خرج است.'),
 (304,
  'خسارت تأخیر تأدیه مبلغ اصلی برات که به واسطه عدم تأدیه اعتراض شده\u200cاست از روز اعتراض و خسارت تأخیر تأدیه '
  'مخارج\u200cاعتراض و مخارج برات رجوعی فقط از روز اقامه دعوی محسوب می\u200cشود.'),
 (305,
  'در مورد برواتی که در خارج ایران صادر شده شرایط اساسی برات تابع قوانین مملکت صدور است. هر قسمت از سایر تعهدات '
  'براتی (\u200cتعهدات ناشی از ظهرنویسی - ضمانت - قبولی و غیره) نیز که در خارجه به وجود آمده تابع قوانین مملکتی است '
  'که\u200cتعهد در آنجا وجود پیدا کرده\u200cاست. معذالک اگر شرایط اساسی برات مطابق قانون ایران موجود و یا تعهدات '
  'براتی موافق قانون ایران صحیح باشد کسانی که در ایران تعهداتی کرده\u200cاند حق\u200cاستناد به این ندارند که شرایط '
  'اساسی برات یا تعهدات براتی مقدم بر تعهد آنها مطابق با قوانین خارجی نیست.'),
 (306,
  'اعتراض و به طور کلی هر اقدامی که برای حفظ حقوق ناشیه از برات و استفاده از آن در خارجه باید به عمل آید تابع قوانین '
  'مملکتی\u200cخواهد بود که آن اقدام باید در آنجا بشود.'),
 (307,
  'فته\u200cطلب سندی است که به موجب آن امضاکننده تعهد می\u200cکند مبلغی در موعد معین یا عندالمطالبه در وجه حامل یا '
  'شخص معین و یا به\u200cحواله\u200cکرد آن شخص کارسازی نماید.'),
 (308,
  'فته\u200cطلب علاوه بر امضاء یا مهر باید دارای تاریخ و متضمن مراتب ذیل باشد: ۱) مبلغی که باید تأدیه شود با تمام '
  'حروف. ۲) گیرنده وجه. ۳) تاریخ پرداخت.'),
 (309,
  'تمام مقررات راجع به بروات تجارتی (\u200cاز مبحث چهارم الی آخر فصل اول این باب) در مورد فته\u200cطلب نیز '
  'لازم\u200cالرعایه\u200cاست.'),
 (310,
  'چک نوشته\u200cای است که به موجب آن صادرکننده وجوهی را که در نزد محال\u200cعلیه دارد کلاً یا بعضاً مسترد یا به '
  'دیگری واگذار می\u200cنماید.'),
 (311, 'در چک باید محل و تاریخ صدور قید شده و به امضای صادرکننده برسد - پرداخت وجه نباید وعده داشته باشد.'),
 (312,
  'چک ممکن است در وجه حامل یا شخص معین یا به حواله\u200cکرد باشد - ممکن است به صرف امضاء در ظهر به دیگری منتقل شود.'),
 (313, 'وجه چک باید به محض ارائه کارسازی شود.'),
 (314,
  'صدور چک ولو اینکه از محلی به محل دیگر باشد ذاتاً عمل تجارتی محسوب نیست لیکن مقررات این قانون از ضمانت صادرکننده '
  'وظهرنویسها و اعتراض و اقامه دعوی ضمان و مفقود شدن راجع به بروات شامل چک نیز خواهد بود.'),
 (315,
  'اگر چک در همان مکانی که صادر شده\u200cاست باید تأدیه گردد دارنده چک باید در ظرف پانزده روز از تاریخ صدور وجه آن '
  'را مطالبه کند واگر از یک نقطه به نقطه دیگر ایران صادر شده باشد باید در ظرف چهل و پنج روز از تاریخ صدور چک مطالبه '
  'شود. اگر دارنده چک در ظرف مواعد مذکوره در این ماده پرداخت وجه آن را مطالبه نکند دیگر دعوی او بر علیه ظهرنویس '
  'مسموع نخواهد بود و اگر وجه\u200cچک به سببی که مربوط به محال\u200cعلیه\u200cاست از بین برود دعوی دارنده چک بر علیه '
  'صادرکننده نیز در محکمه مسموع نیست.'),
 (316, 'کسی که وجه چک را دریافت می\u200cکند باید ظهر آن را امضاء یا مهر نماید اگر چه چک در وجه حامل باشد.'),
 (317,
  'مقررات راجعه به چکهایی که در ایران صادر شده\u200cاست در مورد چکهایی که از خارجه صادر شده و باید در ایران پرداخته '
  'شود نیزرعایت خواهد شد - لیکن مهلتی که در ظرف آن دارنده چک می\u200cتواند وجه چک را مطالبه کند چهار ماه از تاریخ '
  'صدور است.'),
 (318,
  'دعاوی راجعه به برات و فته\u200cطلب و چک که از طرف تجار یا برای امور تجارتی صادر شده پس از انقضای پنج سال از تاریخ '
  'صدوراعتراضنامه و یا آخرین تعقیب قضایی در محاکم مسموع نخواهد بود مگر اینکه در ظرف این مدت رسماً اقرار به دین شده '
  'باشد که در این صورت مبدأمرور زمان از تاریخ اقرار محسوب است. در صورت عدم اعتراض مدت مرور زمان از تاریخ انقضاء مهلت '
  'اعتراض شروع می\u200cشود. تبصره - مفاد این ماده در مورد بروات و چک و فته\u200cطلبهایی که قبل از تاریخ اجرای قانون '
  'تجارت مصوب ۲۵ دلو ۱۳۰۳ و ۱۲ فروردین و ۱۲ خرداد۱۳۰۴ صادر شده\u200cاست قابل اجرا نبوده و این اسناد از حیث مرور زمان '
  'تابع مقررات مربوط به مرور زمان راجع به اموال منقول است.'),
 (319,
  'اگر وجه برات یا فته\u200cطلب یا چک را نتوان به واسطه حصول مرور زمان پنج سال مطالبه کرد دارنده برات یا '
  'فته\u200cطلب یا چک می\u200cتواند تاحصول مرور زمان اموال منقوله وجه آن را از کسی که به ضرر او استفاده بلاجهت '
  'کرده\u200cاست مطالبه نماید. تبصره - حکم فوق در موردی نیز جاری است که برات یا فته\u200cطلب یا چک یکی از شرایط '
  'اساسی مقرر در این قانون را فاقد باشد.'),
 (320,
  'دارنده هر سند در وجه حامل مالک و برای مطالبه وجه آن محق محسوب می\u200cشود مگر در صورت ثبوت خلاف. معذلک اگر '
  'مقامات\u200cصلاحیتدار قضایی یا پلیس تأدیه وجه آن سند را منع کند تأدیه وجه به حامل مدیون را نسبت به شخص ثالثی که '
  'ممکن است سند متعلق به او باشدبری نخواهد کرد.'),
 (321, 'جز در موردی که حکم بطلان سند صادر شده مدیون سند در وجه حامل مکلف به تأدیه نیست مگر در مقابل اخذ سند.'),
 (322,
  'در صورت گم شدن سند در وجه حامل که دارای ورقه\u200cهای کوپن یا دارای ضمیمه برای تجدید اوراق کوپن باشد و همچنین در '
  'صورت\u200cگم شدن سند در وجه حامل که خود سند به دارنده آن حق می\u200cدهد ربح یا منفعتی را مرتباً دریافت کند برای '
  'اصدار حکم بطلان مطابق ذیل عمل خواهدشد.'),
 (323,
  'مدعی باید در محکمه محل اقامت مدیون معلوم نماید سند در تصرف او بوده و فعلاً گم شده\u200cاست. اگر مدعی فقط اوراق '
  'کوپن یا ضمیمه مربوط به سند خود را گم کرده باشد ابراز خود سند کافی است.'),
 (324,
  'اگر محکمه ادعای مدعی را بنا بر اوضاع و احوال قابل اعتماد دانست باید به وسیله اعلان در جراید به دارنده مجهول سند '
  'اخطار کند -\u200cهر گاه از تاریخ انتشار اولین اعلان تا سه سال سند را ابراز ننمود حکم بطلان آن صادر خواهد شد - '
  'محکمه می\u200cتواند لدی\u200cالاقتضاء مدتی بیش از سه\u200cسال تعیین کند.'),
 (325,
  'به تقاضای مدعی محکمه می\u200cتواند به مدیون قدغن کند که وجه سند را به کسی نپردازد مگر پس از گرفتن ضامن یا تأمینی '
  'که محکمه\u200cتصویب نماید.'),
 (326,
  'در مورد گم شدن اوراق کوپن نسبت به کوپنهایی که در ضمن جریان دعوی لازم\u200cالتأدیه می\u200cشود به ترتیب مقرر در '
  'مواد ۳۳۲ و ۳۳۳ عمل\u200cخواهد شد.'),
 (327,
  'اخطار مذکور در ماده ۳۲۴ باید سه دفعه در مجله رسمی منتشر شود محکمه می\u200cتواند به علاوه اعلان در جراید دیگر را '
  'نیز مقرر دارد.'),
 (328,
  'اگر پس از اعلان فوق سند مفقود ابراز شود محکمه به مدعی مهلت متناسبی داده و اخطار خواهد کرد که هر گاه تا انقضای '
  'مهلت دعوی\u200cخود را تعقیب و دلائل خود را اظهار نکند محکوم شده و سند به ابرازکننده آن مسترد خواهد گردید.'),
 (329, 'اگر در ظرف مدتی که مطابق ماده ۳۲۴ مقرر و اعلان شده سند ابراز نگردد محکمه حکم بطلان آن را صادر خواهد نمود.'),
 (330, 'ابطال سند فوراً به وسیله درج در مجله رسمی و هر وسیله دیگری که محکمه مقتضی بداند به اطلاع عموم خواهد رسید.'),
 (331,
  'پس از صدور حکم ابطال مدعی حق دارد تقاضا کند به خرج او سند جدید یا لدی\u200cالاقتضاء اوراق کوپن تازه به او بدهند. '
  'اگر سند حال\u200cشده باشد مدعی حق تقاضای تأدیه خواهد داشت.'),
 (332,
  'هر گاه سند گم شده از اسناد مذکور در ماده (۳۲۲) نباشد به ترتیب ذیل رفتار خواهد شد: محکمه در صورتی که ادعای مدعی '
  'سبق تصرف و گم کردن سند را قابل اعتماد دید حکم می\u200cدهد مدیون وجه سند را فوراً در صورتی که حال باشد وپس از '
  'انقضاء اجل - در صورت مؤجل بودن - به صندوق عدلیه بسپارد.'),
 (333,
  'اگر قبل از انقضای مدت مرور زمانی که وجه سند مفقود پس از آن مدت قابل مطالبه نیست سند ابراز شده مطابق ماده ۳۲۸ '
  'رفتار و الاوجهی که در صندوق عدلیه امانت گذاشته شده به مدعی داده می\u200cشود.'),
 (334, 'مقررات این باب شامل اسکناس نیست.'),
 (335,
  'دلال کسی است که در مقابل اجرت واسطه انجام معاملاتی شده یا برای کسی که می\u200cخواهد معاملاتی نماید طرف معامله '
  'پیدا می\u200cکند. اصولاً قرارداد دلالی تابع مقررات راجع به وکالت است.'),
 (336, 'دلال می\u200cتواند در رشته\u200cهای مختلف دلالی نموده و شخصاً نیز تجارت کند.'),
 (337,
  'دلال باید در نهایت صحت و از روی صداقت طرفین معامله را از جزئیات راجعه به معامله مطلع سازد ولو اینکه دلالی را فقط '
  'برای یکی\u200cاز طرفین بکند - دلال در مقابل هر یک از طرفین مسئول تقلب و تقصیرات خود می\u200cباشد.'),
 (338,
  'دلال نمی\u200cتواند عوض یکی از طرفین معامله قبض وجه یا تأدیه دین نماید و یا آنکه تعهدات آنها را به موقع اجرا '
  'گذارد مگر اینکه\u200cاجازه\u200cنامه مخصوصی داشته باشد.'),
 (339,
  'دلال مسئول تمام اشیاء و اسنادی است که در ضمن معاملات به او داده شده مگر اینکه ثابت نماید که ضایع یا تلف شدن اشیاء '
  'یا اسنادمزبوره مربوط به شخص او نبوده\u200cاست.'),
 (340,
  'در موردی که فروش از روی نمونه باشد دلال باید نمونه مال\u200cالتجاره را تا موقع ختم معامله نگاه بدارد مگر اینکه '
  'طرفین معامله او را ازاین قید معاف دارند.'),
 (341,
  'دلال می\u200cتواند در زمان واحد برای چند آمر در یک رشته یا رشته\u200cهای مختلف دلالی کند ولی در این صورت باید '
  'آمرین را از این ترتیب وامور دیگری که ممکن است موجب تغییر رأی آنها شود مطلع نماید.'),
 (342,
  'هر گاه معامله به توسط دلال واقع و نوشتجات و اسنادی راجع به آن معامله بین طرفین به توسط او رد و بدل شود در صورتی '
  'که امضاهاراجع به اشخاصی باشد که به توسط او معامله را کرده\u200cاند دلال ضامن صحت و اعتبار امضاهای نوشتجات و اسناد '
  'مزبور است.'),
 (343,
  'دلال ضامن اعتبار اشخاصی که برای آنها دلالی می\u200cکند و ضامن اجرای معاملاتی که به توسط او می\u200cشود نیست.'),
 (344,
  'دلال در خصوص ارزش یا جنس مال\u200cالتجاره که مورد معامله بوده مسئول نیست مگر اینکه ثابت شود تقصیر از جانب او '
  'بوده.'),
 (345, 'هر گاه طرفین معامله یا یکی از آنها به اعتبار تعهد شخص دلال معامله نمود دلال ضامن معامله\u200cاست.'),
 (346,
  'در صورتی که دلال در نفس معامله منتفع یا سهیم باشد باید به طرفی که این نکته را نمی\u200cداند اطلاع دهد و الا مسئول '
  'خسارات وارده\u200cبوده و به علاوه به 82/500/000 تا 200/000/000 ریال جزای نقدی محکوم خواهد شد.'),
 (347, 'در صورتی که دلال در معامله سهیم باشد با آمر خود متضامناً مسئول اجرای تعهد خواهد بود.'),
 (348, 'دلال نمی\u200cتواند حق دلالی را مطالبه کند مگر در صورتی که معامله به راهنمایی یا وساطت او تمام شده باشد.'),
 (349,
  'اگر دلال برخلاف وظیفه خود نسبت به کسی که به او مأموریت داده به نفع طرف دیگر معامله اقدام نماید و یا برخلاف عرف '
  'تجارتی\u200cمحل از طرف مزبور وجهی دریافت و یا وعده وجهی را قبول کند مستحق اجرت و مخارجی که کرده نخواهد بود به '
  'علاوه محکوم به مجازات مقرربرای خیانت در امانت خواهد شد.'),
 (350, 'هر گاه معامله مشروط به شرط تعلیقی باشد دلال پس از حصول شرط مستحق اجرت خواهد بود.'),
 (351,
  'اگر شرط شده باشد مخارجی که دلال می\u200cکند به او داده شود دلال مستحق اخذ مخارج خواهد بود ولو آنکه معامله سر '
  'نگیرد. همین\u200cترتیب در موردی نیز جاری است که عرف تجارتی محل به پرداخت مخارجی که دلال کرده حکم کند.'),
 (352,
  'در صورتی که معامله به رضایت طرفین یا به واسطه یکی از خیارات قانونی فسخ بشود حق مطالبه دلالی از دلال سلب '
  'نمی\u200cشودمشروط بر اینکه فسخ معامله مستند به دلال نباشد.'),
 (353, 'دلالی معاملات ممنوعه اجرت ندارد.'),
 (354,
  'حق\u200cالزحمه دلال به عهده طرفی است که او را مأمور انجام معامله نموده مگر اینکه قرارداد خصوصی غیر این ترتیب را '
  'مقرر بدارد.'),
 (355,
  'حق\u200cالزحمه دلال به واسطه قرارداد مخصوصی باید معین شده باشد و الا محکمه با رجوع به اهل خبره و رعایت مقتضیات '
  'زمانی ومکانی و نوع معامله حق\u200cالزحمه را معین خواهد کرد.'),
 (356,
  'هر دلال باید دفتری داشته و کلیه معاملاتی را که به دلالی او انجام گرفته به ترتیب ذیل در آن ثبت نماید: ۱) اسم '
  'متعاملین. ۲) مالی که موضوع معامله\u200cاست. ۳) نوع معامله. ۴) شرایط معامله با تشخیص به اینکه تسلیم موضوع معامله '
  'فوری است یا به وعده\u200cاست. ۵) عوض مالی که باید پرداخته شود و تشخیص اینکه فوری است یا به وعده\u200cاست وجه نقد '
  'است یا مال\u200cالتجاره یا برات در صورتی که برات باشدبه رؤیت است یا به وعده. ۶) امضاء طرفین معامله مطابق مقررات '
  'نظامنامه وزارت عدلیه. دفتر دلالی تابع کلیه مقررات راجع به دفاتر تجارتی است.'),
 (357,
  'حق\u200cالعمل\u200cکار کسی است که به اسم خود ولی به حساب دیگری (\u200cآمر) معاملاتی کرده و در مقابل '
  'حق\u200cالعملی دریافت می\u200cدارد.'),
 (358,
  'جز در مواردی که به موجب مواد ذیل استثناء شده مقررات راجعه به وکالت در حق\u200cالعمل\u200cکاری نیز رعایت خواهد '
  'شد.'),
 (359,
  'حق\u200cالعمل\u200cکار باید آمر را از جریان اقدامات خود مستحضر داشته و مخصوصاً در صورت انجام مأموریت این نکته را '
  'به فوریت به اواطلاع دهد.'),
 (360,
  'حق\u200cالعمل\u200cکار مکلف به بیمه کردن اموالی که موضوع معامله\u200cاست نیست مگر اینکه آمر دستور داده باشد.'),
 (361,
  'اگر مال\u200cالتجاره که برای فروش نزد حق\u200cالعمل\u200cکار ارسال شده دارای عیوب ظاهری باشد '
  'حق\u200cالعمل\u200cکار باید برای محفوظ داشتن حق رجوع\u200cبر علیه متصدی حمل و نقل و تعیین میزان خسارات بحری '
  '(\u200cآواری) به وسایل مقتضیه و محافظت مال\u200cالتجاره اقدامات لازمه به عمل آورده و آمر را ازاقدامات خود مستحضر '
  'کند و الا مسئول خسارات ناشیه از این غفلت خواهد بود.'),
 (362,
  'اگر بیم فساد سریع مال\u200cالتجاره رود که نزد حق\u200cالعمل\u200cکار برای فروش ارسال شده حق\u200cالعمل\u200cکار '
  'می\u200cتواند و حتی در صورتی که منافع آمرایجاب کند مکلف است مال\u200cالتجاره را با اطلاع مدعی\u200cالعمومی محلی '
  'که مال\u200cالتجاره در آنجا است یا نماینده او به فروش برساند.'),
 (363,
  'اگر حق\u200cالعمل\u200cکار مال\u200cالتجاره را به کمتر از حداقل قیمتی که آمر معین کرده به فروش رساند مسئول تفاوت '
  'خواهد بود مگر اینکه ثابت\u200cنماید از ضرر بیشتری احتراز کرده و تحصیل اجازه آمر در موقع مقدور نبوده\u200cاست.'),
 (364,
  'اگر حق\u200cالعمل\u200cکار تقصیر کرده باشد باید از عهده کلیه خساراتی نیز که از عدم رعایت دستور آمر ناشی شده '
  'برآید.'),
 (365,
  'اگر حق\u200cالعمل\u200cکار مال\u200cالتجاره را به کمتر از قیمتی که آمر معین کرده بخرد و یا به بیشتر از قیمتی که '
  'آمر تعیین نموده به فروش رساند حق\u200cاستفاده از تفاوت نداشته و باید آن را در حساب آمر محسوب دارد.'),
 (366,
  'اگر حق\u200cالعمل\u200cکار بدون رضایت آمر مالی را به نسیه بفروشد یا پیش قسطی دهد ضررهای ناشیه از آن متوجه خود او '
  'خواهد بود معذالک\u200cاگر فروش به نسیه داخل در عرف تجارتی محل باشد حق\u200cالعمل\u200cکار مأذون به آن محسوب '
  'می\u200cشود مگر در صورت دستور مخالف آمر.'),
 (367,
  'حق\u200cالعمل\u200cکار در مقابل آمر مسئول پرداخت وجوه و یا انجام سایر تعهدات طرف معامله نیست مگر اینکه مجاز در '
  'معامله به اعتبار نبوده\u200cو یا شخصاً ضمانت طرف معامله را کرده و یا عرف تجارتی بلد او را مسئول قرار دهد.'),
 (368,
  'مخارجی که حق\u200cالعمل\u200cکار کرده و برای انجام معامله و نفع آمر لازم بوده و همچنین هر مساعده که به نفع آمر '
  'داده باشد باید اصلاً ومنفعتاً به حق\u200cالعمل\u200cکار مسترد شود. حق\u200cالعمل\u200cکار می\u200cتواند مخارج '
  'انبارداری و حمل و نقل را نیز به حساب آمر گذارد.'),
 (369,
  'وقتی حق\u200cالعمل\u200cکار مستحق حق\u200cالعمل می\u200cشود که معامله اجرا شده و یا عدم اجرای آن مستند به فعل آمر '
  'باشد. نسبت به اموری که در نتیجه علل دیگری انجام\u200cپذیر نشده حق\u200cالعمل\u200cکار برای اقدامات خود فقط مستحق '
  'اجرتی خواهد بود که عرف و عادت محل معین\u200cمی\u200cنماید.'),
 (370,
  'اگر حق\u200cالعمل\u200cکار نادرستی کرده و مخصوصاً در موردی که به حساب آمر قیمتی علاوه بر قیمت خرید و یا کمتر از '
  'قیمت فروش محسوب\u200cدارد مستحق حق\u200cالعمل نخواهد بود - به علاوه در دو صورت اخیر آمر می\u200cتواند '
  'حق\u200cالعمل\u200cکار را خریدار یا فروشنده محسوب کند. تبصره - دستور فوق مانع از اجرای مجازاتی که برای خیانت در '
  'امانت مقرر است نیست.'),
 (371,
  'حق\u200cالعمل\u200cکار در مقابل آمر برای وصول مطالبات خود از او نسبت به اموالی که موضوع معامله بوده و یا نسبت به '
  'قیمتی که اخذ کرده -\u200cحق حبس خواهد داشت.'),
 (372,
  'اگر فروش مال ممکن نشده و یا آمر از اجازه فروش رجوع کرده و مال\u200cالتجاره را بیش از حد متعارف نزد '
  'حق\u200cالعمل\u200cکار بگذاردحق\u200cالعمل\u200cکار می\u200cتواند آن را با نظارت مدعی\u200cالعموم بدایت محل یا '
  'نماینده او به طریق مزایده به فروش برساند. اگر آمر در محل نبوده و در آنجا نماینده نیز نداشته باشد فروش بدون حضور '
  'او یا نماینده او به عمل خواهد آمد ولی در هر حال قبلاً باید به او اخطاریه رسمی ارسال گردد مگر اینکه اموال از جمله '
  'اموال سریع\u200cالفساد باشد.'),
 (373,
  'اگر حق\u200cالعمل\u200cکار مأمور به خرید یا فروش مال\u200cالتجاره یا اسناد تجارتی و یا سایر اوراق بهاداری باشد که '
  'مظنه بورسی یا بازاری داردمی\u200cتواند چیزی را که مأمور به خرید آن بوده خود شخصاً به عنوان فروشنده تسلیم بکند و '
  'یا چیزی را که مأمور به فروش آن بوده شخصاً به عنوان\u200cخریدار نگاه دارد مگر اینکه آمر دستور مخالفی داده باشد.'),
 (374,
  'در مورد ماده فوق حق\u200cالعمل\u200cکار باید قیمت را بر طبق مظنه بورسی یا نرخ بازار در روزی که وکالت خود را انجام '
  'می\u200cدهد منظور دارد وحق خواهد داشت که هم حق\u200cالعمل و هم مخارج عادیه حق\u200cالعمل\u200cکار را برداشت کند.'),
 (375,
  'در هر موردی که حق\u200cالعمل\u200cکار شخصاً می\u200cتواند خریدار یا فروشنده واقع شود اگر معامله را به آمر بدون '
  'تعیین طرف معامله اطلاع دهدخود طرف معامله محسوب خواهد شد.'),
 (376,
  'اگر آمر از امر خود رجوع کرده و حق\u200cالعمل\u200cکار قبل از ارسال خبر انجام معامله از این رجوع مستحضر گردد دیگر '
  'نمی\u200cتواند شخصاً\u200cخریدار یا فروشنده واقع شود.'),
 (377, 'متصدی حمل و نقل کسی است که در مقابل اجرت حمل اشیاء را به عهده می\u200cگیرد.'),
 (378, 'قرارداد حمل و نقل تابع مقررات وکالت خواهد بود مگر در مواردی که ذیلاً استثناء شده باشد.'),
 (379,
  'ارسال\u200cکننده باید نکات ذیل را به اطلاع متصدی حمل و نقل برساند: آدرس صحیح مرسل\u200cالیه - محل تسلیم مال - عده '
  'عدل یا بسته وطرز عدل\u200cبندی - وزن و محتوی عدل\u200cها - مدتی که مال باید در آن مدت تسلیم شود - راهی که حمل '
  'باید از آن راه به عمل آید - قیمت اشیایی که\u200cگرانبها است. خسارات ناشیه از عدم تعیین نکات فوق و یا از تعیین '
  'آنها به غلط متوجه ارسال\u200cکننده خواهد بود.'),
 (380,
  'ارسال\u200cکننده باید مواظبت نماید که مال\u200cالتجاره به طرز مناسبی عدل\u200cبندی شود - خسارات بحری (آواری) ناشی '
  'از عیوب عدل\u200cبندی به\u200cعهده ارسال\u200cکننده\u200cاست.'),
 (381,
  'اگر عدل\u200cبندی عیب ظاهر داشته و متصدی حمل و نقل مال را بدون قید عدم مسئولیت قبول کرده باشد مسئول آواری خواهد '
  'بود.'),
 (382,
  'ارسال\u200cکننده می\u200cتواند مادام که مال\u200cالتجاره در ید متصدی حمل و نقل است آن را با پرداخت مخارجی که '
  'متصدی حمل و نقل کرده وخسارات او پس بگیرد.'),
 (383,
  'در موارد ذیل ارسال\u200cکننده نمی\u200cتواند از حق استرداد مذکور در ماده ۳۸۲ استفاده کند: ۱ - در صورتی که بارنامه '
  'توسط ارسال\u200cکننده تهیه و به وسیله متصدی حمل و نقل به مرسل\u200cالیه تسلیم شده باشد. ۳ - در صورتی که متصدی حمل '
  'و نقل به مرسل\u200cالیه اعلام کرده باشد که مال\u200cالتجاره به مقصد رسیده و باید آن را تحویل گیرد. ۴ - در صورتی '
  'که پس از وصول مال\u200cالتجاره به مقصد مرسل\u200cالیه تسلیم آن را تقاضا کرده باشد. در این موارد متصدی حمل و نقل '
  'باید مطابق دستور مرسل\u200cالیه عمل کند معذالک اگر متصدی حمل و نقل رسیدی به ارسال\u200cکننده داده مادام '
  'که\u200cمال\u200cالتجاره به مقصد نرسیده مکلف به رعایت دستور مرسل\u200cالیه نخواهد بود مگر اینکه رسید به '
  'مرسل\u200cالیه تسلیم شده باشد.'),
 (384,
  'اگر مرسل\u200cالیه مال\u200cالتجاره را قبول نکند و یا مخارج و سایر مطالبات متصدی حمل و نقل بابت مال\u200cالتجاره '
  'تأدیه نشود و یا به مرسل\u200cالیه\u200cدسترسی نباشد متصدی حمل و نقل باید مراتب را به اطلاع ارسال\u200cکننده '
  'رسانیده و مال\u200cالتجاره را موقتاً نزد خود به طور امانت نگاهداشته یا نزد ثالثی\u200cامانت گذارد و در هر دو صورت '
  'مخارج و هر نقص و عین به عهده ارسال\u200cکننده خواهد بود. اگر ارسال\u200cکننده و یا مرسل\u200cالیه در مدت مناسبی '
  'تکلیف مال\u200cالتجاره را معین نکند متصدی حمل و نقل می\u200cتواند مطابق ماده ۳۶۲ آن را به فروش برساند.'),
 (385,
  'اگر مال\u200cالتجاره در معرض تضییع سریع باشد و یا قیمتی که می\u200cتوان برای آن فرض کرد با مخارجی که برای آن شده '
  'تکافو ننماید متصدی\u200cحمل و نقل باید فوراً مراتب را به اطلاع مدعی\u200cالعموم بدایت محل یا نماینده او رسانیده و '
  'با نظارت او مال را به فروش رساند. حتی\u200cالمقدور ارسال\u200cکننده و مرسل\u200cالیه را باید از اینکه '
  'مال\u200cالتجاره به فروش خواهد رسید مسبوق نمود.'),
 (386,
  'اگر مال\u200cالتجاره تلف یا گم شود متصدی حمل و نقل مسئول قیمت آن خواهد بود مگر اینکه ثابت نماید تلف یا گم شدن '
  'مربوط به جنس\u200cخود مال\u200cالتجاره یا مستند به تقصیر ارسال\u200cکننده و یا مرسل\u200cالیه و یا ناشی از '
  'تعلیماتی بوده که یکی از آنها داده\u200cاند و یا مربوط به حوادثی بوده که هیچ\u200cمتصدی مواظبی نیز نمی\u200cتوانست '
  'از آن جلوگیری نماید قرارداد طرفین می\u200cتواند برای میزان خسارت مبلغی کمتر یا زیادتر از قیمت کامل '
  'مال\u200cالتجاره معین\u200cنماید.'),
 (387,
  'در مورد خسارات ناشیه از تأخیر تسلیم یا نقص یا خسارات بحری (\u200cآواری) مال\u200cالتجاره نیز متصدی حمل و نقل در '
  'حدود ماده فوق\u200cمسئول خواهد بود. خسارات مزبور نمی\u200cتواند از خساراتی که ممکن بود در صورت تلف شدن تمام '
  'مال\u200cالتجاره حکم به آن شود تجاوز نماید مگر اینکه قرارداد طرفین\u200cخلاف این ترتیب را مقرر داشته باشد.'),
 (388,
  'متصدی حمل و نقل مسئول حوادث و تقصیراتی است که در مدت حمل و نقل واقع شده اعم از اینکه خود مباشرت به حمل و '
  'نقل\u200cکرده و یا حمل و نقل\u200cکننده دیگری را مأمور کرده باشد - بدیهی است که در صورت اخیر حق رجوع او به متصدی '
  'حمل و نقلی که از جانب او مأمورشده محفوظ است.'),
 (389, 'متصدی حمل و نقل باید به محض وصول مال\u200cالتجاره مرسل\u200cالیه را مستحضر نماید.'),
 (390,
  'اگر مرسل\u200cالیه میزان مخارج و سایر وجوهی را که متصدی حمل و نقل بابت مال\u200cالتجاره مطالبه می\u200cنماید قبول '
  'نکند حق تقاضای تسلیم\u200cمال\u200cالتجاره را نخواهد داشت مگر اینکه مبلغ متنازع\u200cفیه را تا ختم اختلاف در '
  'صندوق عدلیه امانت گذارد.'),
 (391,
  'اگر مال\u200cالتجاره بدون هیچ قیدی قبول و کرایه آن تأدیه شود دیگر بر علیه متصدی حمل و نقل دعوی پذیرفته نخواهد شد '
  'مگر در موردتدلیس یا تقصیر عمده به علاوه متصدی حمل و نقل مسئول آواری غیر ظاهر نیز خواهد بود در صورتی که '
  'مرسل\u200cالیه آن آواری را در مدتی که مطابق\u200cاوضاع و احوال رسیدگی به مال\u200cالتجاره ممکن بود به عمل آید و '
  'یا بایستی به عمل آمده باشد مشاهده کرده و فوراً پس از مشاهده به متصدی حمل و نقل\u200cاطلاع دهد در هر حال این اطلاع '
  'باید منتها تا هشت روز بعد از تحویل گرفتن مال\u200cالتجاره داده شود.'),
 (392,
  'در هر موردی که بین متصدی حمل و نقل و مرسل\u200cالیه اختلاف باشد محکمه صلاحیتدار محل می\u200cتواند به تقاضای یکی '
  'از طرفین امر دهدمال\u200cالتجاره نزد ثالثی امانت گذارده شده و یا لدی\u200cالاقتضاء فروخته شود در صورت اخیر فروش '
  'باید پس از تنظیم صورت\u200cمجلسی حاکی از آنکه\u200cمال\u200cالتجاره در چه حال بوده به عمل آید. به وسیله پرداخت '
  'تمام مخارج و وجوهی که بابت مال\u200cالتجاره ادعا می\u200cشود و یا سپردن آن به صندوق عدلیه از فروش '
  'مال\u200cالتجاره می\u200cتوان جلوگیری کرد.'),
 (393,
  'نسبت به دعوی خسارت بر علیه متصدی حمل و نقل مدت مرور زمان یک سال است - مبدأ این مدت در صورت تلف یا گم '
  'شدن\u200cمال\u200cالتجاره و یا تأخیر در تسلیم روزی است که تسلیم بایستی در آن روز به عمل آمده باشد و در صورت '
  'خسارات بحری (\u200cآواری) روزی که مال به\u200cمرسل\u200cالیه تسلیم شده.'),
 (394, 'حمل و نقل به وسیله پست تابع مقررات این باب نیست.'),
 (395,
  'قائم\u200cمقام تجارتی کسی است که رییس تجارتخانه او را برای انجام کلیه امور مربوطه به تجارتخانه یا یکی از شعب آن '
  'نایب خود قرار داده\u200cو امضای او برای تجارتخانه الزام\u200cآور است. سمت مزبور ممکن است کتباً داده شود یا '
  'عملاً.'),
 (396, 'تحدید اختیارات قائم\u200cمقام تجارتی در مقابل اشخاصی که از آن اطلاع نداشته\u200cاند معتبر نیست.'),
 (397,
  'قائم\u200cمقام تجارتی ممکن است به چند نفر مجتمعاً داده شود با قید اینکه تا تمام امضاء نکنند تجارتخانه ملزم نخواهد '
  'شد ولی در مقابل\u200cاشخاص ثالثی که از این قید اطلاع نداشته\u200cاند فقط در صورتی می\u200cتوان از آن استفاده کرد '
  'که این قید مطابق مقررات وزارت عدلیه به ثبت رسیده و اعلان\u200cشده باشد.'),
 (398,
  'قائم\u200cمقام تجارتی بدون اذن رییس تجارتخانه نمی\u200cتواند کسی را در کلیه کارهای تجارتخانه نایب خود قرار دهد.'),
 (399,
  'عزل قائم\u200cمقام تجارتی که وکالت او به ثبت رسیده و اعلان شده باید مطابق مقررات وزارت عدلیه به ثبت رسیده و اعلان '
  'شود و الا درمقابل ثالثی که از عزل مطلع نبوده وکالت باقی محسوب می\u200cشود.'),
 (400,
  'با فوت یا حجر رییس تجارتخانه قائم\u200cمقام تجارتی منعزل نیست با انحلال شرکت قائم\u200cمقام تجارتی منعزل است.'),
 (401,
  'وکالت سایر کسانی که در قسمتی از امور تجارتخانه یا شعبه تجارتخانه سمت نمایندگی دارند تابع مقررات عمومی راجع به '
  'وکالت\u200cاست.'),
 (402,
  'ضامن وقتی حق دارد از مضمون\u200cله تقاضا نماید که بدواً به مدیون اصلی رجوع کرده و در صورت عدم وصول طلب به او رجوع '
  'نماید که\u200cبین طرفین (\u200cخواه ضمن قرارداد مخصوص خواه در خود ضمانت\u200cنامه) این ترتیب مقرر شده باشد.'),
 (403,
  'در کلیه مواردی که به موجب قوانین یا موافق قراردادهای خصوصی ضمانت تضامنی باشد طلبکار می\u200cتواند به ضامن و مدیون '
  'اصلی\u200cمجتمعاً رجوع کرده یا پس از رجوع به یکی از آنها و عدم وصول طلب خود برای تمام یا بقیه طلب به دیگری رجوع '
  'نماید'),
 (404, 'حکم فوق در موردی نیز جاری است که چند نفر به موجب قرارداد یا قانون متضامناً مسئول انجام تعهدی باشند.'),
 (405,
  'قبل از رسیدن اجل دین اصلی ضامن ملزم به تأدیه نیست ولو اینکه به واسطه ورشکستگی یا فوت مدیون اصلی دین مؤجل او '
  'حال\u200cشده باشد.'),
 (406, 'ضمان حال از قاعده فوق مستثنی است.'),
 (407, 'اگر حق مطالبه دین اصلی مشروط به اخطار قبلی است این اخطار نسبت به ضامن نیز باید به عمل آید.'),
 (408, 'همین که دین اصلی به نحوی از انحاء ساقط شده ضامن نیز بری می\u200cشود.'),
 (409,
  'همین که دین حال شد ضامن می\u200cتواند مضمون\u200cله را به دریافت طلب یا انصراف از ضمان ملزم کند ولو ضمان مؤجل '
  'باشد.'),
 (410,
  'استنکاف مضمون\u200cله از دریافت طلب یا امتناع از تسلیم وثیقه - اگر دین با وثیقه بوده - ضامن را فوراً و به خودی '
  'خود بری خواهدساخت.'),
 (411,
  'پس از آنکه ضامن دین اصلی را پرداخت مضمون\u200cله باید تمام اسناد و مدارکی را که برای رجوع ضامن به مضمون\u200cعنه '
  'لازم و مفید است\u200cبه او داده و اگر دین اصلی با وثیقه باشد آن را به ضامن تسلیم نماید - اگر دین اصلی وثیقه غیر '
  'منقول داشته مضمون\u200cعنه مکلف به انجام تشریفاتی است\u200cکه برای انتقال وثیقه به ضامن لازم است.'),
 (412,
  'ورشکستگی تاجر یا شرکت تجارتی در نتیجه توقف از تأدیه وجوهی که بر عهده او است حاصل می\u200cشود. حکم ورشکستگی تاجری '
  'را که حین\u200cالفوت در حال توقیف بوده تا یک سال بعد از مرگ او نیز می\u200cتوان صادر نمود.'),
 (413,
  'تاجر باید در ظرف سه روز از تاریخ وقفه که در تأدیه قروض یا سایر تعهدات نقدی او حاصل شده\u200cاست توقف خود را به '
  'دفتر محکمه\u200cبدایت محل اقامت خود اظهار نموده صورت\u200cحساب دارایی و کلیه دفاتر تجارتی خود را به دفتر محکمه '
  'مزبوره تسلیم نماید.'),
 (414,
  'صورتحساب مذکور در ماده فوق باید مورخ بوده و به امضاء تاجر رسیده و متضمن مراتب ذیل باشد: ۱) تعداد و تقویم کلیه '
  'اموال منقول و غیر منقول تاجر متوقف به طور مشروح. ۲) صورت کلیه قروض و مطالبات. ۳) صورت نفع و ضرر و صورت مخارج '
  'شخصی. در صورت توقف شرکتهای تضامنی - مختلط یا نسبی اسامی و محل اقامت کلیه شرکاء ضامن نیز باید ضمیمه شود.'),
 (415,
  'ورشکستگی تاجر به حکم محکمه بدایت در موارد ذیل اعلام می\u200cشود: الف) بر حسب اظهار خود تاجر. ب) به موجب تقاضای یک '
  'یا چند نفر از طلبکارها. ج) بر حسب تقاضای مدعی\u200cالعموم بدایت.'),
 (416, 'محکمه باید در حکم خود تاریخ توقف تاجر را معین نماید و اگر در حکم معین نشد تاریخ حکم تاریخ توقف محسوب است.'),
 (417, 'حکم ورشکستگی به طور موقت اجرا می\u200cشود.'),
 (418,
  'تاجر ورشکسته از تاریخ صدور حکم از مداخله در تمام اموال خود حتی آنچه که ممکن است در مدت ورشکستگی عاید او گرددممنوع '
  'است. در کلیه اختیارات و حقوق مالی ورشکسته که استفاده از آن مؤثر در تأدیه دیون او باشد مدیر تصفیه قائم\u200cمقام '
  'قانونی ورشکسته بوده و حق\u200cدارد به جای او از اختیارات و حقوق مزبوره استفاده کند.'),
 (419,
  'از تاریخ حکم ورشکستگی هر کس نسبت به تاجر ورشکسته دعوایی از منقول یا غیر منقول داشته باشد باید بر مدیر تصفیه اقامه '
  'یا به\u200cطرفیت او تعقیب کند - کلیه اقدامات اجرایی نیز مشمول همین دستور خواهد بود.'),
 (420, 'محکمه هر وقت صلاح بداند می\u200cتواند ورود تاجر ورشکسته را به عنوان شخص ثالث در دعوی مطروحه اجازه دهد.'),
 (421, 'همین که حکم ورشکستگی صادر شد قروض مؤجل با رعایت تخفیفات مقتضیه نسبت به مدت به قروض حال مبدل می\u200cشود.'),
 (422,
  'هر گاه تاجر ورشکسته فته\u200cطلبی داده یا براتی صادر کرده که قبول نشده یا براتی را قبولی نوشته سایر اشخاصی که '
  'مسئول تأدیه وجه\u200cفته\u200cطلب یا برات می\u200cباشند باید با رعایت تخفیفات مقتضیه نسبت به مدت وجه آن را نقداً '
  'بپردازند یا تأدیه آن را در سر وعده تأمین نمایند.'),
 (423,
  'هر گاه تاجر بعد از توقف معاملات ذیل را بنماید باطل و بلااثر خواهد بود: ۱) هر صلح محاباتی یا هبه و به طور کلی هر '
  'نقل و انتقال بلاعوض اعم از اینکه راجع به منقول یا غیر منقول باشد. ۲) تأدیه هر قرض اعم از حال یا مؤجل به هر وسیله '
  'که به عمل آمده باشد. ۳) هر معامله که مالی از اموال منقول یا غیر منقول تاجر را مقید نماید و به ضرر طلبکاران تمام '
  'شود.'),
 (424,
  'هر گاه در نتیجه اقامه دعوی از طرف مدیر تصفیه یا طلبکاری بر اشخاصی که با تاجر طرف معامله بوده یا بر قائم\u200cمقام '
  'قانونی آنها ثابت\u200cشود تاجر متوقف قبل از تاریخ توقف خود برای فرار از ادای دین یا برای اضرار به طلبکارها معامله '
  'نموده که متضمن ضرری بیش از ربع قیمت\u200cحین\u200cالمعامله بوده\u200cاست آن معامله قابل فسخ است مگر اینکه طرف '
  'معامله قبل از صدور حکم فسخ تفاوت قیمت را بپردازد دعوی فسخ در ظرف دوسال از تاریخ وقوع معامله در محکمه پذیرفته '
  'می\u200cشود.'),
 (425,
  'هر گاه محکمه به موجب ماده قبل حکم فسخ معامله را صادر نماید محکوم\u200cعلیه باید پس از قطعی شدن حکم مالی را که '
  'موضوع معامله\u200cبوده\u200cاست عیناً به مدیر تصفیه تسلیم و قیمت حین\u200cالمعامله آن را قبل از آنکه دارایی تاجر '
  'به غرما تقسیم شود دریافت دارد و اگر عین مال مزبور درتصرف او نباشد تفاوت قیمت را خواهد داد.'),
 (426,
  'اگر در محکمه ثابت شود که معامله به طور صوری یا مسبوق به تبانی بوده\u200cاست آن معامله خود به خود باطل - عین و '
  'منافع مالی که\u200cموضوع معامله بوده مسترد و طرف معامله اگر طلبکار شود جزو غرما حصه خواهد بود.'),
 (427, 'در حکمی که به موجب آن ورشکستگی تاجر اعلان می\u200cشود محکمه یک نفر را به سمت عضو ناظر معین خواهد کرد.'),
 (428, 'عضو ناظر مکلف است به نظارت در اداره امور راجعه به ورشکستگی و سرعت جریان آن است.'),
 (429, 'تمام منازعات ناشیه از ورشکستگی را که حل آن از صلاحیت محکمه\u200cاست عضو ناظر به محکمه راپرت خواهد داد.'),
 (430, 'شکایت از تصمیمات عضو ناظر فقط در مواردی ممکن است که این قانون معین نموده.'),
 (431, 'مرجع شکایت محکمه\u200cاست که عضو ناظر را معین کرده.'),
 (432, 'محکمه همیشه می\u200cتواند عضو ناظر با تبدیل و دیگری را به جای او بگمارد.'),
 (433, 'محکمه در حکم ورشکستگی امر به مهر و موم را نیز می\u200cدهد.'),
 (434,
  'مهر و موم باید فوراً توسط عضو ناظر به عمل آید مگر در صورتی که به عقیده عضو مزبور برداشتن صورت دارایی تاجر در یک '
  'روزممکن باشد در این صورت باید فوراً شروع به برداشتن صورت شود.'),
 (435, 'اگر تاجر ورشکسته به مفاد ماده ۴۱۳ - ۴۱۴ عمل نکرده باشد محکمه در حکم ورشکستگی قرار توقیف تاجر را خواهد داد.'),
 (436,
  'قرار توقیف ورشکسته در مواقعی نیز داده خواهد شد که معلوم گردد به واسطه اقدامات خود از اداره و تسویه شدن عمل '
  'ورشکستگی\u200cمی\u200cخواهد جلوگیری کند.'),
 (437,
  'در صورتی که تاجر مقروض فرار کرده یا تمام یا قسمتی از دارایی خود را مخفی نموده باشد امین صلح می\u200cتواند بر حسب '
  'تقاضای یک\u200cیا چند نفر از طلبکاران فوراً اقدام به مهر و موم نماید و باید بلافاصله این اقدام خود را به '
  'مدعی\u200cالعموم اطلاع دهد.'),
 (438,
  'انبارها و حجره\u200cها و صندوق و اسناد و دفاتر و نوشتجات و اسباب و اثاثیه تجارتخانه و منزل تاجر باید مهر موم '
  'شود.'),
 (439,
  'در صورت ورشکستگی شرکتهای تضامنی - مختلط یا نسبی اموال شخصی شرکاء ضامن مهر و موم نخواهد شد مگر اینکه '
  'حکم\u200cورشکستگی آنها نیز در ضمن حکم ورشکستگی شرکت یا به موجب حکم جداگانه صادر شده باشد. تبصره - در مورد این '
  'ماده و ماده فوق مستثنیات دین از مهر و موم معاف است.'),
 (440,
  'محکمه در ضمن حکم ورشکستگی یا منتهی در ظرف پنج روز پس از صدور حکم یک نفر را به سمت مدیریت تصفیه معین می\u200cکند.'),
 (441,
  'اقدامات مدیر تصفیه برای تهیه صورت طلبکاران و اخطار به آنها و مدتی که در آن مدت طلبکاران باید خود را معرفی نمایند '
  'و به طورکلی وظایف مدیر تصفیه علاوه بر آن قسمتی که به موجب این قانون معین شده بر طبق نظامنامه که از طرف وزارت '
  'عدلیه تنظیم می\u200cشود معین خواهدشد.'),
 (442, 'میزان حق\u200cالزحمه مدیر تصفیه را محکمه در حدود مقررات وزارت عدلیه معین خواهد کرد.'),
 (443, 'اگر مهر و موم قبل از تعیین مدیر تصفیه به عمل نیامده باشد مدیر مزبور تقاضای انجام آن را خواهد نمود.'),
 (444,
  'عضو ناظر به تقاضای مدیر تصفیه به او اجازه می\u200cدهد که اشیاء ذیل را از مهر و موم مستثنی کرده و اگر مهر و موم '
  'شده\u200cاست از توقیف\u200cخارج نماید: ۳ - اشیایی که برای به کار انداختن سرمایه تاجر ورشکسته و استفاده از آن لازم '
  'است در صورتی که توقیف آنها موجب خسارت ارباب طلب باشد. اشیاء مذکور در فقره ثانیه و ثالثه باید فوراً تقویم و صورت '
  'آن برداشته شود.'),
 (445,
  'فروش اشیایی که ممکن است قریباً ضایع شده یا کسر قیمت حاصل کند و اشیایی که نگاه داشتن آنها مفید نیست و همچنین به '
  'کارانداختن سرمایه تاجر ورشکسته با اجازه عضو ناظر به توسط مدیر تصفیه به عمل می\u200cآید.'),
 (446,
  'دفتردار محکمه دفاتر تاجر ورشکسته را به اتفاق عضو ناظر یا امین صلحی که آنها را مهر و موم نموده\u200cاست از توقیف '
  'خارج کرده پس ازآن که ذیل دفاتر را بست آنها را به مدیر تصفیه تسلیم می\u200cنماید. دفتردار باید در صورت\u200cمجلس '
  'کیفیت دفاتر را به طور خلاصه قید کند - اوراق تجارتی هم که وعده آنها نزدیک است یا باید قبولی آنها نوشته شود و '
  'یانسبت به آنها باید اقدامات تأمینیه به عمل آید از توقیف خارج شده در صورت\u200cمجلس ذکر و به مدیر تصفیه تحویل '
  'می\u200cشود تا وجه آن را وصول نماید وفهرستی که از مدیر تصفیه گرفته می\u200cشود به عضو ناظر تسلیم می\u200cگردد - '
  'سایر مطالبات را مدیر تصفیه در مقابل قبضی که می\u200cدهد وصول می\u200cنمایدمراسلاتی که به اسم تاجر ورشکسته '
  'می\u200cرسد به مدیر تصفیه تسلیم و به توسط او باز می\u200cشود و اگر خود ورشکسته حاضر باشد در باز کردن '
  'مراسلات\u200cمی\u200cتواند شرکت کند.'),
 (447,
  'تاجر ورشکسته در صورتی که وسیله دیگری برای اعاشه نداشته باشد می\u200cتواند نفقه خود و خانواده\u200cاش را از دارایی '
  'خود درخواست کند- در این صورت عضو ناظر نفقه و مقدار آن را با تصویب محکمه معین می\u200cنماید.'),
 (448,
  'مدیر تصفیه تاجر ورشکسته را برای بستن دفاتر احضار می\u200cنماید برای حضور او منتها چهل و هشت ساعت مهلت داده '
  'می\u200cشود درصورتی که تاجر حاضر نشد با حضور عضو ناظر اقدام به عمل خواهد آمد - تاجر ورشکسته می\u200cتواند در موقع '
  'کلیه عملیات تأمینیه حاضر باشد.'),
 (449,
  'در صورتی که تاجر ورشکسته صورت دارایی خود را تسلیم ننموده باشد مدیر تصفیه آن را فوراً به وسیله دفاتر و اسناد '
  'مشارالیه و سایراطلاعاتی که تحصیل می\u200cنماید تنظیم می\u200cکند.'),
 (450,
  'عضو ناظر مجاز است که راجع به تنظیم صورت دارایی و نسبت به اوضاع و احوال ورشکستگی از تاجر ورشکسته و شاگردها '
  'ومستخدمین او و همچنین از اشخاص دیگر توضیحات بخواهد و باید از تحقیقات مذکوره صورت\u200cمجلس ترتیب دهد.'),
 (451,
  'مدیر تصفیه پس از تقاضای رفع توقیف شروع به تنظیم صورت دارایی نموده و تاجر ورشکسته را هم در این موقع احضار '
  'می\u200cکند ولی\u200cعدم حضور او مانع از عمل نیست.'),
 (452,
  'مدیر تصفیه به تدریجی که رفع توقیف می\u200cشود صورت دارایی را در دو نسخه تهیه می\u200cنماید. یکی از نسختین به دفتر '
  'محکمه تسلیم\u200cشده و دیگری در نزد او می\u200cماند.'),
 (453,
  'مدیر تصفیه می\u200cتواند برای تهیه صورت دارایی و تقویم اموال از اشخاصی که لازم بداند استمداد کند صورت اشیایی که '
  'موافق ماده ۴۴۴\u200cدر تحت توقیف نیامده ولی قبلاً تقویم شده\u200cاست ضمیمه صورت دارایی خواهد شد.'),
 (454,
  'مدیر تصفیه باید در ظرف پانزده روز از تاریخ مأموریت خود صورت خلاصه از وضعیت ورشکستگی و همچنین از علل و اوضاعی '
  'که\u200cموجب آن شده و نوع ورشکستگی که ظاهراً به نظر می\u200cآید ترتیب داده به عضو ناظر بدهد. عضو ناظر صورت مزبور '
  'را فوراً به مدعی\u200cالعمومی ابتدایی\u200cمحل تسلیم می\u200cنماید.'),
 (455,
  'صاحب\u200cمنصبان پارکه می\u200cتوانند فقط به عنوان نظارت به منزل تاجر ورشکسته رفته و در حین برداشتن صورت دارایی '
  'حضور به هم\u200cرسانند. مأمورین پارکه در هر موقع حق دارند به دفاتر و اسناد و نوشتجات مربوطه به ورشکستگی مراجعه '
  'کنند. این مراجعه نباید باعث تعطیل جریان امر باشد.'),
 (456,
  'پس از تهیه شدن صورت دارایی تمام مال\u200cالتجاره و وجه نقد و اسناد طلب و دفاتر و نوشتجات و اثاثیه (\u200cبه غیر '
  'از مستثنیات دین) واشیاء تاجر ورشکسته به مدیر تصفیه تسلیم می\u200cشود.'),
 (457,
  'مدیر تصفیه با نظارت عضو ناظر به وصول مطالبات مداومت می\u200cنماید و همچنین می\u200cتواند با اجازه '
  'مدعی\u200cالعموم و نظارت عضو ناظر به\u200cفروش اثاث\u200cالبیت و مال\u200cالتجاره تاجر مباشرت نماید لیکن قبلاً '
  'باید اظهارات تاجر ورشکسته را استماع یا لااقل مشارالیه را برای دادن توضیحات احضارکند - ترتیب فروش به موجب نظامنامه '
  'وزارت عدلیه معین خواهد شد.'),
 (458,
  'نسبت به تمام دعاوی که هیأت طلبکارها در آن ذینفع می\u200cباشند مدیر تصفیه با اجازه عضو ناظر می\u200cتواند دعوی را '
  'به صلح خاتمه دهداگر چه دعاوی مزبوره راجع به اموال غیر منقول باشد و در این مورد تاجر ورشکسته باید احضار شده باشد.'),
 (459,
  'اگر موضوع صلح قابل تقویم نبوده یا بیش از پنج هزار ریال باشد صلح لازم\u200cالاجرا نخواهد بود مگر اینکه محکمه آن '
  'صلح را تصدیق\u200cنماید در موقع تصدیق صلحنامه تاجر ورشکسته احضار می\u200cشود و در هر صورت مشارالیه حق دارد که به '
  'صلح اعتراض کند - اعتراض ورشکسته درصورتی که صلح راجع به اموال غیر منقول باشد برای جلوگیری از صلح کافی خواهد بود تا '
  'محکمه تکلیف صلح را معین نماید.'),
 (460,
  'وجوهی که به توسط مدیر تصفیه دریافت می\u200cشود باید فوراً به صندوق عدلیه محل تسلیم گردد. صندوق مزبور حساب مخصوصی '
  'برای\u200cعمل ورشکسته اعم از عایدات و مخارج باز می\u200cکند وجوه مزبور از صندوق مسترد نمی\u200cگردد مگر به حواله '
  'عضو ناظر و تصدیق مدیر تصفیه.'),
 (461,
  'مدیر تصفیه مکلف است از روز شروع به مأموریت اقدامات تأمینیه برای حفظ حقوق تاجر ورشکسته نسبت به مدیونین او به '
  'عمل\u200cآورد.'),
 (462,
  'پس از صدور حکم ورشکستگی طلبکارها مکلفند - در مدتی که به موجب اخطار مدیر تصفیه در حدود نظامنامه وزارت عدلیه '
  'معین\u200cشده - اسناد طلب خود یا سواد مصدق آن را به انضمام فهرستی که کلیه مطالبات آنها را معین می\u200cنماید به '
  'دفتردار محکمه تسلیم کرده قبض دریافت\u200cدارند.'),
 (463,
  'تشخیص مطالبات طلبکارها در ظرف سه روز از تاریخ انقضای مهلت مذکور در ماده قبل شروع شده و بدون وقفه در محل و روز '
  'وساعتی که از طرف عضو ناظر معین می\u200cگردد - به ترتیبی که در نظامنامه معین خواهد شد - تعقیب می\u200cشود.'),
 (464,
  'هر طلبکاری که طلب او تشخیص یا جزء صورت\u200cحساب دارایی منظور شده می\u200cتواند در حین تشخیص مطالبات سایر '
  'طلبکارها حضوربه هم رسانیده و نسبت به طلبهایی که سابقاً تشخیص شده یا فعلاً در تحت رسیدگی است اعتراض نماید - همین '
  'حق را خود تاجر ورشکسته هم\u200cخواهد داشت.'),
 (465,
  'محل اقامت طلبکارها و وکلای آنها در صورت\u200cمجلس تشخیص مطالبات معین و به علاوه توصیف مختصری از سند داده '
  'می\u200cشود وتعیین قلم\u200cخوردگی یا تراشیدگی یا الحاقات بین\u200cالسطور نیز باید در صورت\u200cمجلس قید و این '
  'نکته مسلم شود که طلب مسلم یا متنازع\u200cفیه\u200cاست.'),
 (466,
  'عضو ناظر می\u200cتواند به نظر خود امر به ابراز دفاتر طلبکارها دهد یا از محکمه محل تقاضا نماید صورتی از دفاتر '
  'طلبکارها استخراج کرده\u200cو نزد او بفرستد.'),
 (467,
  'اگر طلب مسلم و قبول شد مدیر تصفیه در روی سند عبارت ذیل را نوشته امضاء نموده و عضو ناظر نیز آن را تصدیق '
  'می\u200cکند: «جزو قروض........ مبلغ....... قبول شد به تاریخ.........» هر طلبکار باید در ظرف مدت و به ترتیبی که به '
  'موجب نظامنامه وزارت عدلیه معین می\u200cشود التزام بدهد طلبی را که اظهار کرده طلب حقیقی و بدون\u200cقصد استفاده '
  'نامشروع است.'),
 (468,
  'اگر طلب متنازع\u200cفیه واقع شده عضو ناظر می\u200cتواند حل قضیه را به محکمه رجوع و محکمه باید فوراً از روی راپرت '
  'عضو ناظر رسیدگی\u200cنماید محکمه می\u200cتواند امر دهد که با حضور عضو ناظر تحقیق در امر به عمل آید و اشخاصی را که '
  'می\u200cتوانند راجع به این طلب اطلاعاتی دهند عضوناظر احضار یا از آنها کسب اطلاع کند.'),
 (469,
  'در موقعی که اختلاف راجع به تشخیص طلبی به محکمه رجوع شده و قضیه طوری باشد که محکمه نتواند در ظرف پانزده روز '
  'حکم\u200cصادر کند باید بر حسب اوضاع امر دهد که انعقاد مجلس هیأت طلبکارها برای ترتیب قرارداد ارفاقی به تأخیر افتد '
  'و یا اینکه منتظر نتیجه رسیدگی نشده\u200cو مجلس مزبور منعقد شود.'),
 (470,
  'محکمه می\u200cتواند در صورت تصمیم به انعقاد مجلس قرار دهد که صاحب طلب متنازع\u200cفیه معادل مبلغی که محکمه در '
  'قرار مزبور معین\u200cمی\u200cکند موقتاً طلبکار شناخته شده در مذاکرات هیأت طلبکارها برای مبلغ مذکور شرکت نماید.'),
 (471,
  'در صورتی که طلبی مورد تعقیب جزایی واقع شده باشد محکمه می\u200cتواند قرار تأخیر مجلس را بدهد ولی اگر تصمیم به عدم '
  'تأخیرمجلس نمود نمی\u200cتواند صاحب آن طلب را موقتاً جزو طلبکاران قبول نماید و مادام که محاکم صالحه حکم خود را '
  'نداده\u200cاند طلبکار مزبور نمی\u200cتواند به\u200cهیچ وجه در عملیات راجعه به ورشکستگی شرکت کند.'),
 (472,
  'پس از انقضای مهلت\u200cهای معین در مواد ۴۶۲ و ۴۶۷ به ترتیب قرارداد ارفاقی و به سایر عملیات راجعه به ورشکستگی '
  'مداومت\u200cمی\u200cشود.'),
 (473,
  'طلبکارهایی که در مواعد معینه حاضر نشده و مطابق ماده ۴۶۲ عمل نکردند نسبت به عملیات و تشخیصات و تصمیماتی که راجع '
  'به\u200cتقسیم وجوه قبل از آمدن آنها به عمل آمده حق هیچ گونه اعتراضی ندارند ولی در تقسیماتی که ممکن است به عمل آید '
  'جزء غرما حساب می\u200cشوندبدون اینکه حق داشته باشند حصه را که در تقسیمات سابق به آنها تعلق می\u200cگرفت از اموالی '
  'که هنوز تقسیم نشده مطالبه نمایند.'),
 (474,
  'اگر اشخاصی نسبت به اموال متصرفی تاجر ورشکسته دعوی خیاراتی دارند و صرفنظر از آن نمی\u200cکنند باید آن را در حین '
  'تصفیه عمل\u200cورشکستگی ثابت نموده و به موقع اجرا گذارند.'),
 (475,
  'حکم فوق درباره دعوی خیاراتی نیز مجری خواهد بود که تاجر ورشکسته نسبت به اموال متصرفی خود یا دیگران دارد مشروط '
  'براینکه بر ضرر طلبکارها نباشد.'),
 (476,
  'عضو ناظر در ظرف هشت روز از تاریخ موعدی که به موجب نظامنامه مذکور در ماده ۴۶۷ معین شده به توسط دفتردار محکمه '
  'کلیه\u200cطلبکارهایی را که طلب آنها تشخیص و تصدیق یا موقتاً قبول شده\u200cاست برای مشاوره در انعقاد قرارداد '
  'ارفاقی دعوت می\u200cنماید - موضوع دعوت مجمع\u200cعمومی طلبکارها در رقعه\u200cهای دعوت و اعلانات مندرجه در جراید '
  'باید تصریح شود.'),
 (477,
  'مجمع عمومی مزبور در محل و روز و ساعتی که از طرف عضو ناظر معین شده\u200cاست در تحت ریاست مشارالیه منعقد '
  'می\u200cشود -\u200cطلبکارهایی که طلب آنها تشخیص و تصدیق شده\u200cاست و همچنین طلبکارهایی که طلب آنها موقتاً قبول '
  'گردیده یا وکیل ثابت\u200cالوکاله آنها حاضرمی\u200cشوند تاجر ورشکسته نیز به این مجمع احضار می\u200cشود مشارالیه '
  'باید شخصاً حاضر گردد و فقط وقتی می\u200cتواند اعزام وکیل نماید که عذر موجه داشته\u200cو صحت آن به تصدیق عضو ناظر '
  'رسیده باشد.'),
 (478,
  'مدیر تصفیه به مجمع طلبکارها راپورتی از وضعیت ورشکستگی و اقداماتی که به عمل آمده و عملیاتی که با استحضار تاجر '
  'ورشکسته\u200cشده\u200cاست می\u200cدهد راپورت مزبور به امضاء مدیر تصفیه رسیده به عضو ناظر تقدیم می\u200cشود و عضو '
  'ناظر باید از کلیه مذاکرات و تصمیمات مجمع\u200cطلبکارها صورت مجلسی ترتیب دهد. فقره اول - در ترتیب قرارداد ارفاقی'),
 (479,
  'قرارداد ارفاقی تاجر ورشکسته و طلبکارهای او منعقد نمی\u200cشود مگر پس از اجرای مراسمی که در فوق مقرر '
  'شده\u200cاست.'),
 (480,
  'قرارداد ارفاقی فقط وقتی منعقد می\u200cشود که لااقل نصف به علاوه یک نفر از طلبکارها با داشتن لااقل سه ربع از کلیه '
  'مطالباتی که مطابق\u200cمبحث پنجم از فصل ششم تشخیص و تصدیق شده یا موقتاً قبول گشته\u200cاست در آن قرارداد شرکت '
  'نموده باشند و الا بلااثر خواهد بود.'),
 (481,
  'هر گاه در مجلس قرارداد ارفاقی اکثریت طلبکارها عدداً حاضر شوند ولی از حیث مبلغ دارای سه ربع از مطالبات نباشند یا '
  'آنکه دارای\u200cسه ربع از مطالبات باشند ولی اکثریت عددی را حائز نباشند نتیجه حاصله از آن مجلس معلق و قرار انعقاد '
  'مجلس ثانی برای یک هفته بعد داده می\u200cشود.'),
 (482,
  'طلبکارهایی که در مجلس اول خود یا وکیل ثابت\u200cالوکاله آنها حاضر بوده و صورت\u200cمجلس را امضاء نموده\u200cاند '
  'مجبور نیستند در مجلس\u200cثانی حاضر شوند مگر آنکه بخواهند در تصمیم خود تغییری دهند ولی اگر حاضر نشدند تصمیمات '
  'سابق آنها به اعتبار خود باقی است - اگر در جلسه\u200cثانی اکثریت عددی و مبلغی مطابق ماده ۴۸۰ تکمیل شود قرارداد '
  'ارفاقی قطعی خواهد بود.'),
 (483,
  'اگر تاجر به عنوان ورشکسته به تقلب محکم شده باشد قرارداد ارفاقی منعقد نمی\u200cشود - در موقعی که تاجر به عنوان '
  'ورشکسته به تقلب\u200cتعقیب می\u200cشود لازم است طلبکارها دعوت شوند و معلوم کنند که آیا با احتمال حصول برائت تاجر '
  'و انعقاد قرارداد ارفاقی تصمیم خود را در امرمشارالیه به زمان حصول نتیجه رسیدگی به تقلب موکول خواهند کرد یا تصمیم '
  'فوری خواهند گرفت اگر بخواهند تصمیم را موکول به زمان بعد نمایندباید طلبکارهای حاضر از حیث عده و از حیث مبلغ اکثریت '
  'معین در ماده ۴۸۰ را حائز باشند چنانچه در انقضای مدت و حصول نتیجه رسیدگی به\u200cتقلب بنای انعقاد قرارداد ارفاقی '
  'شود قواعدی که به موجب مواد قبل مقرر است در این موقع نیز باید معمول گردد.'),
 (484,
  'اگر تاجر به عنوان ورشکستگی به تقصیر محکوم شود انعقاد قرارداد ارفاقی ممکن است لیکن در صورتی که تعقیب تاجر شروع '
  'شده\u200cباشد طلبکارها می\u200cتوانند تا حصول نتیجه تعقیب و با رعایت مقررات ماده قبل تصمیم در قرارداد را تأخیر '
  'بیندازند.'),
 (485,
  'کلیه طلبکارها که حق شرکت در انعقاد قرارداد ارفاقی داشته\u200cاند می\u200cتوانند راجع به قرارداد اعتراض کنند - '
  'اعتراض باید موجه بوده و درظرف یک هفته از تاریخ قرارداد به مدیر تصفیه و خود تاجر ورشکسته ابلاغ شود و الا از درجه '
  'اعتبار ساقط خواهد بود. مدیر تصفیه و تاجر ورشکسته به اولین جلسه محکمه که به عمل ورشکستگی رسیدگی می\u200cکنند احضار '
  'می\u200cشوند.'),
 (486,
  'قرارداد ارفاقی باید به تصدیق محکمه برسد و هر یک از طرفین قرارداد می\u200cتوانند تصدیق آن را از محکمه تقاضا نماید. '
  'محکمه نمی\u200cتواند قبل از انقضای مدت یک هفته مذکور در ماده قبل تصمیمی راجع به تصدیق اتخاذ نماید - هر گاه در ظرف '
  'این مدت از طرف\u200cطلبکارهایی که حق اعتراض دارند اعتراضاتی به عمل آمده باشد محکمه باید در موضوع اعتراضات و تصدیق '
  'قرارداد ارفاقی حکم واحد صادر کند -\u200cاگر اعتراضات تصدیق شود قرارداد نسبت به تمام اشخاص ذینفع بلااثر '
  'می\u200cشود.'),
 (487,
  'قبل از آن که محکمه در باب تصدیق قرارداد رأی دهد عضو ناظر باید راپورتی که متضمن کیفیت ورشکستگی و امکان قبول '
  'قراردادباشد به محکمه تقدیم نماید.'),
 (488,
  'در صورت عدم رعایت قواعد مقرره محکمه از تصدیق قرارداد ارفاقی امتناع خواهد نمود. فقره دوم - در اثرات قرارداد '
  'ارفاقی'),
 (489,
  'همین که قرارداد ارفاقی تصدیق شد نسبت به طلبکارهایی که در اکثریت بوده\u200cاند یا در ظرف ده روز از تاریخ تصدیق آن '
  'را امضاء نموده\u200cاندقطعی خواهد بود ولی طلبکارهایی که جزو اکثریت نبوده و قرارداد را هم امضاء نکرده\u200cاند '
  'می\u200cتوانند سهم خود را موافق آنچه از دارایی تاجر به طلبکارهامی\u200cرسد دریافت نمایند لیکن حق ندارند در آتیه '
  'از دارایی تاجر ورشکسته بقیه طلب خود را مطالبه کنند مگر پس از تأدیه تمام طلب کسانی که در قراردادارفاقی شرکت داشته '
  'یا آن را در ظرف ده روز مزبور امضاء نموده\u200cاند.'),
 (490,
  'پس از تصدیق شدن قرارداد ارفاقی دعوی بطلان نسبت به آن قبول نمی\u200cشود مگر اینکه پس از تصدیق مکشوف شود که در '
  'میزان دارایی\u200cیا مقدار قروض حیله به کار رفته و قدر حقیقی قلمداد نشده\u200cاست.'),
 (491,
  'همین که حکم محکمه راجع به تصدیق قرارداد قطعی شد مدیر تصفیه صورت\u200cحساب کاملی با حضور عضو ناظر به تاجر '
  'ورشکسته\u200cمی\u200cدهد که در صورت عدم اختلاف بسته می\u200cشود - مدیر تصفیه کلیه دفاتر و اسناد و نوشتجات و '
  'همچنین دارایی ورشکسته را به استثنای آنچه که بایدبه طلبکارانی که قرارداد ارفاقی را امضاء نکرده\u200cاند داده شود '
  'به مشارالیه رد کرده رسید می\u200cگیرد و پس از آنکه قرار تأدیه سهم طلبکاران مذکور را دادمأموریت مدیر تصفیه ختم '
  'می\u200cشود - از تمام این مراتب عضو ناظر صورت\u200cمجلسی تهیه می\u200cنماید و مأموریتش خاتمه می\u200cیابد - در '
  'صورت تولیداختلاف محکمه رسیدگی کرده حکم مقتضی خواهد داد. فقره سوم - در ابطال یا فسخ قرارداد ارفاقی'),
 (492, 'در مورد ذیل قرارداد ارفاقی باطل است:'),
 (493,
  'اگر محکمه حکم بطلان قرارداد ارفاقی را بدهد ضمانت ضامن یا ضامنها (\u200cدر صورتی که باشد) به خودی خود ملغی '
  'می\u200cشود.'),
 (494,
  'اگر تاجر ورشکسته شرایط قرارداد ارفاقی را اجرا نکرد ممکن است برای فسخ قرارداد مزبور بر علیه او اقامه دعوی نمود.'),
 (495,
  'در صورتی که اجرای تمام یا قسمتی از قرارداد را یک یا چند نفر ضمانت کرده باشند طلبکارها می\u200cتوانند اجرای تمام '
  'یا قسمتی از قراردادرا که ضامن دارد از او بخواهند و در مورد اخیر آن قسمت از قرارداد که ضامن نداشته فسخ '
  'می\u200cشود. در صورت تعدد ضامن مسئولیت آنها تضامنی است.'),
 (496,
  'اگر تاجر ورشکسته پس از تصدیق قرارداد به عنوان ورشکستگی به تقلب تعقیب شده در تحت توقیف یا حبس در آید محکمه '
  'می\u200cتواندهر قسم وسایل تأمینیه را که مقتضی بداند اتخاذ کند ولی به محض صدور قرار منع تعقیب یا حکم تبرئه وسائل '
  'مزبوره مرتفع می\u200cشود.'),
 (497,
  'پس از صدور حکم ورشکستگی به تقلب یا حکم ابطال یا فسخ قرارداد ارفاقی محکمه یک عضو ناظر و یک مدیر تصفیه معین '
  'می\u200cکند.'),
 (498,
  'مدیر تصفیه می\u200cتواند دارایی تاجر را توقیف و مهر و موم نماید مدیر تصفیه فوراً از روی صورت دارایی سابق اقدام به '
  'رسیدگی اسناد ونوشتجات نموده و اگر لازم باشد متممی برای صورت دارایی ترتیب می\u200cدهد مدیر تصفیه باید فوراً به '
  'وسیله اعلان در روزنامه طلبکارهای جدید را اگرباشند دعوت نماید که در ظرف یک ماه اسناد مطالبات خود را برای رسیدگی '
  'ابراز کنند - در اعلان مزبور مفاد قرار محکمه که به موجب آن مدیر تصفیه\u200cمعین شده\u200cاست باید درج شود.'),
 (499,
  'بدون فوت وقت به اسنادی که مطابق ماده قبل ابراز شده رسیدگی می\u200cشود - نسبت به مطالباتی که سابقاً تشخیص یا تصدیق '
  'شده است\u200cرسیدگی جدید به عمل نمی\u200cآید - مطالباتی که تمام یا قسمتی از آنها بعد از تصدیق پرداخته '
  'شده\u200cاست موضوع می\u200cشود.'),
 (500,
  'معاملاتی که تاجر ورشکسته پس از صدور حکم راجع به تصدیق قرارداد ارفاقی تا صدور حکم بطلان یا فسخ قرارداد مزبور نموده '
  'باطل\u200cنمی\u200cشود مگر در صورتی که معلوم شود به قصد اضرار بوده و به ضرر طلبکاران هم باشد.'),
 (501,
  'در صورت فسخ یا ابطال قرارداد ارفاقی دارایی تاجر بین طلبکاران ارفاقی و اشخاصی که بعد از قرارداد ارفاقی طلبکار '
  'شده\u200cاند به غرماتقسیم می\u200cشود.'),
 (502,
  'اگر طلبکاران ارفاقی بعد از توقف تاجر تا زمان فسخ یا ابطال چیزی گرفته\u200cاند مأخوذی آنها از وجهی که به ترتیب '
  'غرما به آنها می\u200cرسدکسر خواهد شد.'),
 (503,
  'هر گاه تاجری ورشکست و امرش منتهی به قرارداد ارفاقی گردید و ثانیاً بدون اینکه قرارداد مزبور ابطال یا فسخ شود '
  'ورشکست شدمقررات دو ماده قبل در ورشکستگی ثانوی لازم\u200cالاجرا است.'),
 (504, 'اگر قرارداد ارفاقی منعقد نشد مدیر تصفیه فوراً به عملیات تصفیه و تفریغ عمل ورشکستگی شروع خواهد کرد.'),
 (505,
  'در صورتی که اکثریت مذکور در ماده (۴۸۰) موافقت نماید محکمه مبلغی را برای اعاشه ورشکسته در حدود مقررات ماده ۴۴۷ '
  'معین\u200cخواهد کرد.'),
 (506,
  'اگر شرکت تضامنی - مختلط یا نسبی ورشکست شود طلبکارها می\u200cتوانند قرارداد ارفاقی را با شرکت یا منحصراً با یک یا '
  'چند نفر ازشرکاء ضامن منعقد نمایند. در صورت ثانی دارایی شرکت تابع مقررات این مبحث و به غرما تقسیم می\u200cشود ولی '
  'دارایی شخصی شرکایی که با آنهاقرارداد ارفاقی منعقد شده\u200cاست به غرما تقسیم نخواهد شد - شریک یا شرکاء ضامن که با '
  'آنها قرارداد خصوصی منعقد شده نمی\u200cتوانند تعهد حصه\u200cنمایند مگر از اموال شخصی خودشان - شریکی که با او '
  'قرارداد مخصوص منعقد شده از مسئولیت ضمانتی مبری است.'),
 (507,
  'اگر طلبکارها بخواهند تجارت تاجر ورشکسته را ادامه دهند می\u200cتوانند برای این امر وکیل یا عامل مخصوصی انتخاب '
  'نموده یا به خودمدیر تصفیه این مأموریت را بدهند.'),
 (508,
  'در ضمن تصمیمی که وکالت مذکور در ماده فوق را مقرر می\u200cدارد باید مدت و حدود وکالت و همچنین میزان وجهی که وکیل '
  'می\u200cتواندبرای مخارج لازمه پیش خود نگاهدارد معین گردد - تصمیم مذکور اتخاذ نمی\u200cشود مگر با حضور عضو ناظر و '
  'با اکثریت سه ربع از طلبکارها عدداً ومبلغاً - خود تاجر ورشکسته و همچنین طلبکارهای مخالف (\u200cبا رعایت ماده ۴۷۳) '
  'می\u200cتوانند نسبت به این تصمیم در محکمه اعتراض نمایند - این\u200cاعتراض اجرای تصمیم را به تأخیر '
  'نمی\u200cاندازد.'),
 (509,
  'اگر از معاملات وکیل یا عاملی که تجارت ورشکسته را ادامه می\u200cدهد تعهداتی حاصل شود که بیش از حد دارایی تاجر '
  'ورشکسته است\u200cفقط طلبکارهایی که آن اجازه را داده\u200cاند شخصاً علاوه بر حصه که در دارایی مزبور دارند به نسبت '
  'طلبشان در حدود اختیاراتی که داده\u200cاند مسئول\u200cتعهدات مذکوره می\u200cباشند.'),
 (510,
  'در صورتی که عمل تاجر ورشکسته منجر به تفریغ حساب شود مدیر تصفیه مکلف است تمام اموال منقول و غیر منقول تاجرورشکسته '
  'را به فروش رسانیده مطالبات و دیون و حقوق او را صلح و مصالحه و وصول و تفریغ کند تمام این مراتب در تحت نظر عضو ناظر '
  'و باحضور تاجر ورشکسته به عمل می\u200cآید. اگر تاجر ورشکسته از حضور استنکاف نمود استحضار مدعی\u200cالعموم کافی است '
  '- فروش اموال مطابق نظامنامه\u200cوزارت عدلیه به عمل خواهد آمد.'),
 (511,
  'همین که تفریغ عمل تاجر به اتمام رسید عضو ناظر طلبکارها و تاجر ورشکسته را دعوت می\u200cنماید. در این جلسه مدیر '
  'تصفیه حساب\u200cخود را خواهد داد.'),
 (512,
  'هر گاه اموالی در اجاره تاجر ورشکسته باشد مدیر تصفیه در فسخ یا ابقاء اجاره به نحوی که موافق منافع طلبکارها باشد '
  'اتخاذ تصمیم\u200cمی\u200cکند - اگر تصمیم بر فسخ اجاره شده صاحبان اموال مستأجره از بابت مال\u200cالاجاره که تا آن '
  'تاریخ مستحق شده\u200cاند جزو غرما منظور می\u200cشوند اگرتصمیم بر ابقاء اجاره بوده و تأمیناتی هم سابقاً به موجب '
  'اجاره\u200cنامه به موجر داده شده باشد آن تأمینات ابقاء خواهد شد و الا تأمیناتی که پس ازورشکستگی داده می\u200cشود '
  'باید کافی باشد - در صورتی که با تصمیم مدیر تصفیه بر فسخ اجاره موجر راضی به فسخ نشود حق مطالبه تأمین را نخواهد '
  'داشت.'),
 (513,
  'مدیر تصفیه می\u200cتواند با اجازه عضو ناظر اجاره را برای بقیه مدت به دیگری تفویض نماید (\u200cمشروط بر اینکه به '
  'موجب قرارداد کتبی\u200cطرفین این حق منع نشده باشد) و در صورت تفویض به غیر باید وثیقه کافی که تأمین پرداخت '
  'مال\u200cالاجاره را بنماید به مالک اموال مستأجره داده و کلیه\u200cشرایط و مقررات اجاره\u200cنامه را به موقع خود '
  'اجرا کند.'),
 (514, 'طلبکارهایی که رهینه در دست دارند فقط در صورت غرما برای یادداشت قید می\u200cشوند.'),
 (515,
  'مدیر تصفیه می\u200cتواند در هر موقع با اجازه عضو ناظر طلب طلبکارها را داده و شیء مرهون را از رهن خارج و جزو '
  'دارایی تاجرورشکسته منظور دارد.'),
 (516,
  'اگر وثیقه فک نشود مدیر تصفیه باید با نظارت مدعی\u200cالعموم آن را به فروش برساند و مرتهن نیز در آن موقع باید دعوت '
  'شود. اگر قیمت\u200cفروش وثیقه پس از وضع مخارج بیش از طلب طلبکار باشد مازاد به مدیر تصفیه تسلیم می\u200cشود و اگر '
  'قیمت فروش کمتر شد مرتهن برای بقیه طلب\u200cخود در جزو طلبکارهای عادی در غرما منظور خواهد شد.'),
 (517,
  'مدیر تصفیه صورت طلبکارهایی را که ادعای وثیقه می\u200cنمایند به عضو ناظر تقدیم می\u200cکند. عضو مزبور در صورت لزوم '
  'اجازه می\u200cدهدطلب آنها از اولین وجوهی که تهیه می\u200cشود پرداخته گردد در صورتی که نسبت به حق وثیقه طلبکارها '
  'اعتراض داشته باشند به محکمه رجوع می\u200cشود.'),
 (518,
  'اگر تقسیم وجوهی که از فروش اموال غیر منقول حاصل شده قبل از تقسیم دارایی منقول یا در همان حین به عمل آمده '
  'باشدطلبکارهایی که نسبت به اموال غیر منقول حقوقی دارند و حاصل فروش اموال مزبور کفایت طلب آنها را ننموده\u200cاست '
  'نسبت به بقیه طلب خود جزوغرما معمولی منظور و از وجوهی که برای غرما مزبور مقرر است حصه می\u200cبرند مشروط بر اینکه '
  'طلب آنها به طوری که قبلاً مذکور شده\u200cاست تصدیق\u200cشده باشد.'),
 (519,
  'اگر قبل از تقسیم وجوهی که از فروش اموال غیر منقول حاصل شده وجهی از بابت دارایی منقول تقسیم شود طلبکارهایی که نسبت '
  'به\u200cاموال غیر منقول حقوقی دارند و طلب آنها تصدیق و اعتراف شده\u200cاست به میزان کلیه طلب خود جزو سایر غرما '
  'وارد و از وجوه مزبوره حصه می\u200cبرندولی عندالاقتضاء مبلغ دریافتی در موقع تقسیم حاصل اموال غیر منقول از طلب آنها '
  'موضوع می\u200cشود.'),
 (520,
  'در مورد طلبکارهایی که نسبت به اموال غیر منقول حقوقی دارند ولی به واسطه مقدم بودن سایر طلبکارها نمی\u200cتوانند در '
  'حین تقسیم\u200cقیمت اموال غیر منقول طلب خود را تماماً وصول کنند ترتیب ذیل مرعی خواهد بود: اگر طلبکارهای مزبور قبل '
  'از تقسیم حاصل اموال غیر منقول از بابت طلب خود وجهی دریافت داشته باشند این مبلغ از حصه که از بابت اموال غیرمنقول '
  'به آنها تعلق می\u200cگیرد موضوع و به حصه که باید بین طلبکارهای معمولی تقسیم شود اضافه می\u200cگردد و بقیه '
  'طلبکارهایی که در اموال غیر منقول\u200cذیحق بوده\u200cاند برای بقیه طلب خود نسبت آن بقیه جزو غرما محسوب شده حصه '
  'می\u200cبرند.'),
 (521,
  'اگر به واسطه مقدم بودن طلبکارهای دیگر بعضی از طلبکارهایی که نسبت به اموال غیر منقول حقی دارند وجهی دریافت نکنند '
  'طلب\u200cآنها جزو غرما محسوب و بدین سمت هر معامله که از بابت قرارداد ارفاقی و غیره با غرما می\u200cشود با آنها '
  'نیز به عمل خواهد آمد.'),
 (522,
  'پس از وضع مخارج اداره امور و ورشکستگی و اعانه که ممکن است به تاجر ورشکسته داده شده باشد و وجوهی که باید به '
  'صاحبان\u200cمطالبات ممتازه تأدیه گردد مجموع دارایی منقول بین طلبکارها به نسبت طلب آنها که قبلاً تشخیص و تصدیق '
  'شده\u200cاست خواهد شد.'),
 (523,
  'مدیر تصفیه برای اجرای مقصود مذکور در ماده فوق ماهی یک مرتبه صورت\u200cحساب عمل ورشکستگی را با تعیین وجوه موجوده '
  'به\u200cعضو ناظر می\u200cدهد. عضو مذکور در صورت لزوم امر به تقسیم وجوه مزبور بین طلبکارها داده مبلغ آن را معین و '
  'مواظبت می\u200cنماید که به تمام طلبکارهااطلاع داده شود.'),
 (524,
  'در موقع تقسیم وجه بین طلبکارها حصه طلبکارهای مقیم ممالک خارجه به نسبت طلب آنها که در صورت دارایی و قروض '
  'منظورشده\u200cاست موضوع می\u200cگردد. چنانچه مطالبات مزبور صحیحاً در صورت دارایی و قروض منظور نشده باشد عضو ناظر '
  'می\u200cتواند حصه موضوعی را زیادکند. برای مطالباتی که هنوز در باب آنها تصمیم قطعی اتخاذ نشده\u200cاست باید مبلغی '
  'موضوع کرد.'),
 (525,
  'وجوهی که برای طلبکارهای مقیم خارجه موضوع شده\u200cاست تا مدتی که قانون برای آنها معین کرده به طور امانت به صندوق '
  'عدلیه\u200cسپرده خواهد شد - اگر طلبکارهای مذکور مطابق این قانون مطالبات خود را به تصدیق نرسانند مبلغ مزبور بین '
  'طلبکارهایی که طلب آنها به تصدیق\u200cرسیده تقسیم می\u200cگردد. وجوهی که برای مطالبات تصدیق\u200cنشده موضوع گردیده '
  'در صورت عدم تصدیق آن مطالبات بین طلبکارهایی که طلب آنها تصدیق شده تقسیم می\u200cشود.'),
 (526,
  'هیچ طلبی را مدیر تصفیه نمی\u200cپردازد مگر آنکه مدارک و اسناد آن را قبلاً ملاحظه کرده باشد مدیر تصفیه مبلغی را که '
  'پرداخته در روی\u200cسند قید می\u200cکند عضو ناظر در صورت عدم امکان ابراز سند می\u200cتواند اجازه دهد که به موجب '
  'صورت\u200cمجلسی که طلب در آن تصدیق شده وجهی\u200cپرداخته شود در هر حال باید طلبکارها رسید وجه را در ذیل صورت '
  'تقسیم ذکر کنند.'),
 (527,
  'ممکن است هیأت طلبکارها با استحضار تاجر ورشکسته از محکمه تحصیل اجازه نمایند که تمام یا قسمتی از حقوق و مطالبات '
  'تاجرورشکسته را که هنوز وصول نشده به طوری که صرفه و صلاح تاجر ورشکسته هم منظور شود خودشان قبول و مورد معامله قرار '
  'دهند در این صورت\u200cمدیر تصفیه اقدامات مقتضیه را به عمل خواهد آورد - در این خصوص هر طلبکاری می\u200cتواند به '
  'عضو ناظر مراجعه کرده تقاضا نماید که طلبکارهای\u200cدیگر را عودت نماید تا تصمیم خود را اتخاذ بنمایند.'),
 (528,
  'اگر قبل از ورشکستگی تاجر کسی اوراق تجارتی به او داده باشد که وجه آن را وصول و به حساب صاحب سند نگاهدارد و یا '
  'به\u200cمصرف معینی برساند و وجه اوراق مزبور وصول یا تأدیه نگشته و اسناد عیناً در حین ورشکستگی در نزد تاجر ورشکسته '
  'موجود باشد صاحبان آن\u200cمی\u200cتوانند عین اسناد را استرداد کنند.'),
 (529,
  'مال\u200cالتجاره\u200cهایی که در نزد تاجر ورشکسته امانت بوده یا به مشارالیه داده شده\u200cاست که به حساب صاحب '
  'مال\u200cالتجاره به فروش برساندمادام که عین آنها کلاً یا جزئاً نزد تاجر ورشکسته موجود یا نزد شخص دیگری از طرف '
  'تاجر مزبور به امانت یا برای فروش گذارده شده و موجود باشدقابل استرداد است.'),
 (530,
  'مال\u200cالتجاره\u200cهایی که تاجر ورشکسته به حساب دیگری خریداری کرده و عین آن موجود است اگر قیمت آن پرداخته نشده '
  'باشد از طرف\u200cفروشنده و الا از طرف کسی که به حساب او آن مال خریداری شده قابل استرداد است.'),
 (531,
  'هر گاه تمام یا قسمتی از مال\u200cالتجاره که برای فروش به تاجر ورشکسته داده شده بود معامله شده و به هیچ نحوی بین '
  'خریدار و تاجرورشکسته احتساب نشده باشد از طرف صاحب مال قابل استرداد است اعم از اینکه نزد تاجر ورشکسته یا خریدار '
  'باشد و به طور کلی عین هر مال\u200cمتعلق به دیگری که در نزد تاجر ورشکسته موجود باشد قابل استرداد است.'),
 (532,
  'اگر مال\u200cالتجاره که برای تاجر ورشکسته حمل شده قبل از وصول از روی صورت\u200cحساب یا بارنامه که دارای امضاء '
  'ارسال\u200cکننده\u200cاست به\u200cفروش رسیده و فروش صوری نباشد دعوی استرداد پذیرفته نمی\u200cشود و الا موافق ماده '
  '۵۲۹ قابل استرداد است و استردادکننده باید وجوهی را که به\u200cطور علی\u200cالحساب گرفته یا مساعدتاً از بابت کرایه '
  'حمل و حق کمیسیون و بیمه و غیره تأدیه شده یا از این بابت\u200cها باید تأدیه بشود به طلبکارها بپردازند.'),
 (533,
  'هر گاه کسی مال\u200cالتجاره به تاجر ورشکسته فروخته ولیکن هنوز آن جنس نه به خود تاجر ورشکسته تسلیم شده و نه به کس '
  'دیگر که به\u200cحساب او بیاورد آن کس می\u200cتواند به اندازه که وجه آن را نگرفته از تسلیم مال\u200cالتجاره امتناع '
  'کند.'),
 (534,
  'در مورد دو ماده قبل مدیر تصفیه می\u200cتواند با اجازه عضو ناظر تسلیم مال\u200cالتجاره را تقاضا نماید ولی باید '
  'قیمتی را که بین فروشنده و تاجرورشکسته مقرر شده\u200cاست بپردازد.'),
 (535,
  'مدیر تصفیه می\u200cتواند با تصویب عضو ناظر تقاضای استرداد را قبول نماید و در صورت اختلاف محکمه پس از استماع عقیده '
  'عضو ناظرحکم مقتضی را می\u200cدهد.'),
 (536,
  'حکم اعلان ورشکستگی و همچنین حکمی که به موجب آن تاریخ توقف تاجر در زمانی قبل از اعلان ورشکستگی تشخیص شود '
  'قابل\u200cاعتراض است.'),
 (537,
  'اعتراض باید از طرف تاجر ورشکسته در ظرف ده روز و از طرف اشخاص ذینفع که در ایران مقیمند در ظرف یک ماه و از طرف '
  'آنهایی\u200cکه در خارجه اقامت دارند در ظرف دو ماه به عمل آید ابتدای مدتهای مزبور از تاریخی است که احکام مذکوره '
  'اعلان می\u200cشود.'),
 (538,
  'پس از انقضای مهلتی که برای تشخیص و تصدیق مطالبات طلبکارها معین شده\u200cاست دیگر هیچ تقاضایی از طرف طلبکارها راجع '
  'به\u200cتعیین تاریخ توقف به غیر آن تاریخی که به موجب حکم ورشکستگی یا حکم دیگری که در این باب صادر شده قبول نخواهد '
  'شد - همین که مهلتهای\u200cمزبور منقضی شد تاریخ توقف نسبت به طلبکارها قطعی و غیر قابل تغییر خواهد بود.'),
 (539,
  'مهلت استیناف از حکم ورشکستگی ده روز از تاریخ ابلاغ است - به این مدت برای کسانی که محل اقامت آنها از مقر محکمه بیش '
  'ازشش فرسخ فاصله دارد از قرار هر شش فرسخ یک روز اضافه می\u200cشود.'),
 (540,
  'قرارهای ذیل قابل اعتراض و استیناف و تمیز نیست: ۱) قرارهای راجعه به تعیین یا تغییر عضو ناظر یا مدیر تصفیه. ۲) '
  'قرارهای راجعه به تقاضای اعانه به جهت تاجر ورشکسته یا خانواده او. ۳) قرارهای فروش اسباب یا مال\u200cالتجاره که '
  'متعلق به ورشکسته\u200cاست. ۴) قرارهایی که قرارداد ارفاقی را موقتاً موقوف یا قبول موقتی مطالبات متنازع\u200cفیه را '
  'مقرر می\u200cدارد. ۵) قرارهای صادره در خصوص شکایت از اوامری که عضو ناظر در حدود صلاحیت خود صادر کرده\u200cاست.'),
 (541,
  'تاجر در موارد ذیل ورشکسته به تقصیر اعلان می\u200cشود: ۱) در صورتی که محقق شود مخارج شخصی یا مخارج خانه مشارالیه '
  'در ایام عادی بالنسبه به عایدی او فوق\u200cالعاده بوده\u200cاست. ۲) در صورتی که محقق شود که تاجر نسبت به سرمایه '
  'خود مبالغ عمده صرف معاملاتی کرده که در عرف تجارت موهوم یا نفع آن منوط به اتفاق\u200cمحض است. ۳) اگر به قصد تأخیر '
  'انداختن ورشکستگی خود خریدی بالاتر یا فروشی نازلتر از مظنه روز کرده باشد یا اگر به همان قصد وسایلی که دور از '
  'صرفه\u200cاست به کار برده تا تحصیل وجهی نماید اعم از اینکه از راه استقراض یا صدور برات یا به طریق دیگر باشد. ۴) '
  'اگر یکی از طلبکارها را پس از تاریخ توقف بر سایرین ترجیح داده و طلب او را پرداخته باشد.'),
 (542,
  'در موارد ذیل هر تاجر ورشکسته ممکن است ورشکسته به تقصیر اعلان شود: ۱) اگر به حساب دیگری و بدون آنکه در مقابل عوضی '
  'دریافت نماید تعهداتی کرده باشد که نظر به وضعیت مالی او در حین انجام آنها آن تعهدات\u200cفوق\u200cالعاده باشد. ۲) '
  'اگر عملیات تجارتی او متوقف شده و مطابق ماده ۴۱۳ این قانون رفتار نکرده باشد. ۳) اگر از تاریخ اجرای قانون تجارت '
  'مصوب ۲۵ دلو ۱۳۰۳ و ۱۲ فروردین و ۱۲ خرداد ۱۳۰۴ دفتر نداشته یا دفاتر او ناقص یا بی\u200cترتیب بوده یا درصورت دارایی '
  'وضعیت حقوقی خود را اعم از قروض و مطالبات به طور صحیح معین نکرده باشد (\u200cمشروط بر اینکه در این موارد مرتکب '
  'تقلبی نشده\u200cباشد).'),
 (543, 'ورشکستگی به تقصیر جنحه محسوب و مجازات آن از ۶ ماه تا سه سال حبس تأدیبی است.'),
 (544,
  'رسیدگی به جرم فوق بر حسب تقاضای مدیر تصفیه یا هر یک از طلبکارها یا تعقیب مدعی\u200cالعموم در محکمه جنحه به عمل '
  'می\u200cآید.'),
 (545,
  'در صورتی که تعقیب تاجر ورشکسته به تقصیر از طرف مدعی\u200cالعموم به عمل آمده باشد مخارج آن را به هیچ وجه '
  'نمی\u200cتوان به هیأت\u200cطلبکارها تحمیل نمود - در صورت انعقاد قرارداد ارفاقی مأمورین اجرا نمی\u200cتوانند اقدام '
  'به وصول این مخارج کنند مگر پس از انقضای مدتهای معینه درقرارداد.'),
 (546,
  'مخارج تعقیبی که از طرف مدیر تصفیه به نام طلبکارها می\u200cشود در صورت برائت تاجر به عهده هیأت طلبکارها و در صورتی '
  'که محکوم\u200cشد به عهده دولت است لیکن دولت حق دارد مطابق ماده قبل به تاجر ورشکسته مراجعه نماید.'),
 (547,
  'مدیر تصفیه نمی\u200cتواند تاجر ورشکسته را به عنوان ورشکستگی به تقصیر تعقیب کند یا از طرف هیأت طلبکارها مدعی خصوصی '
  'واقع\u200cشود مگر پس از تصویب اکثریت طلبکارهای حاضر.'),
 (548,
  'مخارج تعقیبی که از طرف یکی از طلبکارها به عمل می\u200cآید در صورت محکومیت تاجر ورشکسته به عهده دولت و در صورت '
  'برائت\u200cذمه به عهده تعقیب\u200cکننده\u200cاست.'),
 (549,
  'هر تاجر ورشکسته که دفاتر خود را مفقود نموده یا قسمتی از دارایی خود را مخفی کرده و یا به طریق مواضعه و معاملات '
  'صوری ازمیان برده و همچنین هر تاجر ورشکسته که خود را به وسیله اسناد و یا به وسیله صورت دارایی و قروض به طور تقلب '
  'به میزانی که در حقیقت مدیون\u200cنمی\u200cباشد مدیون قلمداد نموده\u200cاست ورشکسته به تقلب اعلام و مطابق قانون '
  'جزا مجازات می\u200cشود.'),
 (550, 'راجع به تقاضای تعقیب و مخارج آن در موارد ماده قبل مفاد مواد ۵۴۵ تا ۵۴۸ لازم\u200cالرعایه\u200cاست.'),
 (551,
  'در مورد ورشکستگی اشخاص ذیل مجرم محسوب و مطابق قانون جزا به مجازات ورشکسته به تقلب محکوم خواهند شد: ۱) اشخاصی که '
  'عالماً به نفع تاجر ورشکسته تمام یا قسمتی از دارایی منقول یا غیر منقول او را از میان ببرند یا پیش خود نگاهدارند یا '
  'مخفی\u200cنمایند. ۲) اشخاصی که به قصد تقلب به اسم خود یا به اسم دیگری طلب غیر مواقعی را قلمداد کرده و مطابق ماده '
  '۴۶۷ التزام داده باشند.'),
 (552,
  'اشخاصی که به اسم دیگری یا به اسم موهومی تجارت نموده و اعمال مندرجه در ماده ۵۴۹ را مرتکب شده\u200cاند به مجازاتی '
  'که برای\u200cورشکسته به تقلب مقرر است محکوم می\u200cباشند.'),
 (553,
  'اگر اقوام شخص ورشکسته بدون شرکت مشارالیه اموال او را از میان ببرند یا مخفی نمایند یا پیش خود نگاهدارند به مجازاتی '
  'که برای\u200cسرقت معین است محکوم خواهند شد.'),
 (554,
  'در موارد معینه در مواد قبل محکمه که رسیدگی می\u200cکند باید در خصوص مسائل ذیل ولو اینکه متهم تبرئه شده باشد - حکم '
  'بدهد: ۱) راجع به رد کلیه اموال و حقوقی که موضوع جرم بوده\u200cاست به هیأت طلبکارها - این حکم را محکمه در صورتی که '
  'مدعی خصوصی هم نباشدباید صادر کند. ۲) راجع به ضرر و خساراتی که ادعا شده\u200cاست.'),
 (555,
  'اگر مدیر تصفیه در حین تصدی به امور تاجر ورشکسته وجهی را حیف و میل کرده باشد به مجازات خیانت در امانت محکوم '
  'خواهدشد.'),
 (556,
  'هر گاه مدیر تصفیه اعم از اینکه طلبکار باشد یا نباشد در مذاکرات راجعه به ورشکستگی با شخص ورشکسته یا با دیگری تبانی '
  'نماید یاقرارداد خصوصی منعقد کند که آن تبانی یا قرارداد به نفع مرتکب و به ضرر طلبکارها یا بعضی از آنها باشد در '
  'محکمه جنحه به حبس تأدیبی از شش ماه\u200cتا دو سال محکوم می\u200cشود.'),
 (557,
  'کلیه قراردادهایی که پس از تاریخ توقف تاجر منعقد شده باشد نسبت به هر کس حتی خود تاجر ورشکسته محکوم به بطلان است '
  '-\u200cطرف قرارداد مجبور است که وجوه یا اموالی را که به موجب قرارداد باطل شده دریافت کرده\u200cاست به اشخاص ذیحق '
  'مسترد دارد.'),
 (558, 'هر حکم محکومیتی که به موجب این فصل یا به موجب فصل سابق صادر بشود باید به خرج محکوم\u200cعلیه اعلان گردد.'),
 (559,
  'در تمام مواردی که کسی به واسطه ورشکستگی به تقصیر یا به تقلب تعقیب و محکوم می\u200cشود رسیدگی به کلیه دعاوی حقوقی '
  'به غیراز آنچه در ماده ۵۵۴ مذکور است از صلاحیت محکمه جزا خارج خواهد بود.'),
 (560,
  'مدیر تصفیه مکلف است در صورت تقاضای مدعی\u200cالعموم بدایت کلیه اسناد و نوشتجات و اوراق و اطلاعات لازمه را به او '
  'بدهد.'),
 (561,
  'هر تاجر ورشکسته که کلیه دیون خود را با متفرعات و مخارجی که به آن تعلق گرفته\u200cاست کاملاً بپردازد حقاً اعاده '
  'اعتبار می\u200cنماید.'),
 (562,
  'طلبکارها نمی\u200cتوانند از جهت تأخیری که در اداء طلب آنها شده\u200cاست برای بیش از پنجاه سال مطالبه متفرعات و '
  'خسارت نمایند و در هرحال متفرعاتی که مطالبه می\u200cشود در سال نباید بیش از صدی هفت طلب باشد.'),
 (563,
  'برای آنکه شریک ضامن یک شریک ورشکسته که حکم ورشکستگی او نیز صادر شده بتواند حق اعاده اعتبار حاصل کند باید '
  'ثابت\u200cنماید که به ترتیب فوق تمام دیون شرکت را پرداخته\u200cاست ولو اینکه نسبت به شخص او قرارداد ارفاقی مخصوصی '
  'وجود داشته باشد.'),
 (564,
  'در صورتی که یک یا چند نفر از طلبکارها مفقودالاثر یا غائب بوده یا اینکه از دریافت وجه امتناع نمایند تاجر ورشکسته '
  'باید وجوهی راکه به آنها مدیون است با اطلاع مدعی\u200cالعموم در صندوق عدلیه بسپارد و همین که تاجر معلوم کرد این '
  'وجوه را سپرده\u200cاست بری\u200cالذمه محسوب است.'),
 (565,
  'تجار ورشکسته در دو مورد ذیل پس از اثبات صحت عمل در مدت پنج سال از تاریخ اعلان ورشکستگی می\u200cتوانند اعتبار خود '
  'را اعاده\u200cنمایند: ۱) تاجر ورشکسته که تحصیل قرارداد ارفاقی نموده و تمام وجوهی را که به موجب قرارداد به عهده '
  'گرفته\u200cاست پرداخته باشد. این ترتیب در موردشریک شرکت ورشکسته که شخصاً تحصیل قرارداد ارفاقی جداگانه '
  'نموده\u200cاست نیز رعایت می\u200cشود. ۲) تاجر ورشکسته که کلیه طلبکاران ذمه او را بری کرده یا به اعاده اعتبار او '
  'رضایت داده\u200cاند.'),
 (566,
  'عرضحال اعاده اعتبار باید به انضمام اسناد مثبته آن به مدعی\u200cالعموم حوزه ابتدایی داده شود که اعلان ورشکستگی در '
  'آن حوزه واقع\u200cشده\u200cاست.'),
 (567,
  'سواد این عرضحال در مدت یک ماه در اتاق جلسه محکمه ابتدایی و همچنین در اداره مدعی\u200cالعموم بدایت الصاق و اعلان '
  'می\u200cشود به\u200cعلاوه دفتردار محکمه باید مفاد عرضحال مزبور را به کلیه طلبکارهایی که مطالبات آنها در حین تصفیه '
  'عمل تاجر ورشکسته یا بعد از آن تصدیق شده وهنوز طلب خود را بر طبق مواد ۵۶۱ و ۵۶۲ کاملاً دریافت نکرده\u200cاند به '
  'وسیله مکتوب سفارشی اعلام دارد.'),
 (568,
  'هر طلبکاری که مطابق مقررات مواد ۵۶۱ و ۵۶۲ طلب خود را کاملاً دریافت نکرده می\u200cتواند در مدت یک ماه از تاریخ '
  'اعلام مذکور درماده قبل به عرضحال اعاده اعتبار اعتراض کند.'),
 (569,
  'اعتراض به وسیله اظهارنامه که به ضمیمه اسناد مثبته به دفتر محکمه بدایت داده می\u200cشود به عمل می\u200cآید - '
  'طلبکار معترض می\u200cتواند به\u200cموجب عرضحال در حین رسیدگی به دعوی اعتبار به طور شخص ثالث ورود کند.'),
 (570,
  'پس از انقضای موعد نتیجه تحقیقاتی که به توسط مدعی\u200cالعموم به عمل آمده\u200cاست به انضمام عرایض اعتراض به رییس '
  'محکمه داده\u200cمی\u200cشود رییس مزبور در صورت لزوم مدعی و معترضین را به جلسه خصوصی محکمه احضار می\u200cکند.'),
 (571,
  'در مورد ماده ۵۶۱ محکمه فقط صحت مدارک را سنجیده در صورت موافقت آنها با قانون حکم اعاده اعتبار می\u200cدهد و در '
  'مورد ماده۵۶۵ محکمه اوضاع و احوال را سنجیده به طوری که مقتضی عدل و انصاف بداند حکم می\u200cدهد و در هر دو صورت حکم '
  'باید در جلسه علنی صادرگردد.'),
 (572,
  'مدعی اعاده اعتبار و همچنین مدعی عمومی و طلبکارهای معترض می\u200cتوانند در ظرف ده روز از تاریخ اعلام حکم به وسیله '
  'مکتوب\u200cسفارشی از حکمی که در خصوص اعاده اعتبار صادر شده استیناف بخواهند - محکمه استیناف پس از رسیدگی بر حسب '
  'مقررات ماده ۵۷۱ حکم\u200cصادر می\u200cکند.'),
 (573, 'اگر عرضحال اعاده اعتبار رد بشود تجدید ممکن نیست مگر پس از انقضای شش ماه.'),
 (574,
  'اگر عرضحال قبول شود حکمی که صادر می\u200cگردد در دفتر مخصوصی که در محکمه بدایت محل اقامت تاجر برای این کار مقرر '
  'است\u200cثبت خواهد شد. اگر محل اقامت تاجر در حوزه محکمه که حکم می\u200cدهد نباشد در ستون ملاحظات دفتر ثبت اسامی '
  'ورشکستگان که در دائره ثبت اسناد محل موجوداست مقابل اسم تاجر ورشکسته با مرکب قرمز به حکم مزبور اشاره می\u200cشود.'),
 (575,
  'ورشکستگان به تقبل و همچنین اشخاصی که برای سرقت یا کلاهبرداری یا خیانت در امانت محکوم شده\u200cاند مادامی که از '
  'جنبه جزایی\u200cاعاده حیثیت نکرده\u200cاند نمی\u200cتوانند از جنبه تجارتی اعاده اعتبار کنند.'),
 (576, 'ثبت اسم تجارتی اختیاری است مگر در مواردی که وزارت عدلی ثبت آن را الزامی کند.'),
 (577,
  'صاحب تجارتخانه که شریک در تجارتخانه ندارد نمی\u200cتواند اسمی برای تجارتخانه خود انتخاب کند که موهم وجود شریک '
  'باشد.'),
 (578,
  'اسم تجارتی ثبت شده را هیچ شخص دیگری در همان محل نمی\u200cتواند اسم تجارتی خود قرار دهد ولو اینکه اسم تجارتی ثبت '
  'شده بااسم خانوادگی او یکی باشد.'),
 (579, 'اسم تجارتی قابل انتقال است.'),
 (580, 'مدت اعتبار ثبت اسم تجارتی پنج سال است.'),
 (581,
  'در مواردی که ثبت اسم تجارتی الزامی شده در موعد مقرر ثبت به عمل نیاید اداره ثبت اقدام به ثبت کرده و سه برابر '
  'حق\u200cالثبت مأخوذخواهد داشت.'),
 (582,
  'وزارت عدلیه به موجب نظامنامه ترتیب ثبت اسم تجارتی و اعلان آن و اصول محاکمات در دعاوی مربوطه به اسم تجارتی را '
  'معین\u200cخواهد کرد.'),
 (583, 'کلیه شرکتهای تجارتی مذکور در این قانون شخصیت حقوقی دارند.'),
 (584,
  'تشکیلات و مؤسساتی که برای مقاصد غیر تجارتی تأسیس شده یا بشوند از تاریخ ثبت در دفتر ثبت مخصوصی که وزارت عدلیه '
  'معین\u200cخواهد کرد شخصیت حقوقی پیدا می\u200cکنند.'),
 (585,
  'شرایط ثبت مؤسسات و تشکیلات مذکور در ماده فوق به موجب نظامنامه وزارت عدلیه معین خواهد شد. حق\u200cالثبت مؤسسات و '
  'تشکیلات مطابق نظامنامه از پنج ریال طلا تا پنج پهلوی و به علاوه مشمول ماده ۱۳۵ قانون ثبت اسناد و املاک است.'),
 (586, 'مؤسسات و تشکیلاتی را که مقاصد آنها مخالف با انتظامات عمومی یا نامشروع است نمی\u200cتوان ثبت کرد.'),
 (587, 'مؤسسات و تشکیلات دولتی و بلدی به محض ایجاد و بدون احتیاج به ثبت دارای شخصیت حقوقی می\u200cشوند.'),
 (588,
  'شخص حقوقی می\u200cتواند دارای کلیه حقوق و تکالیفی شود که قانون برای افراد قائل است مگر حقوق و وظائفی که بالطبیعه '
  'فقط انسان\u200cممکن است دارای آن باشد مانند حقوق و وظایف ابوت - نبوت و امثال ذالک.'),
 (589, 'تصمیمات شخص حقوقی به وسیله مقاماتی که به موجب قانون یا اساسنامه صلاحیت اتخاذ تصمیم دارند گرفته می\u200cشود.'),
 (590, 'اقامتگاه شخص حقوقی محلی است که اداره شخص حقوقی در آنجا است.'),
 (591, 'اشخاص حقوقی تابعیت مملکتی را دارند که اقامتگاه آنها در آن مملکت است.'),
 (592,
  'در مورد معاملاتی که سابقاً تجار یا شرکتها و مؤسسات تجارتی به اعتبار بیش از یک امضاء کرده\u200cاند خواه بعضی از '
  'امضاکنندگان به\u200cعنوان ضامن امضاء کرده باشند خواه به عنوان دیگر طلبکار می\u200cتواند به امضاکنندگان مجتمعاً یا '
  'منفرداً رجوع نماید.'),
 (593,
  'در مورد ماده فوق مطالبه از هر یک از اشخاصی که طلبکار حق رجوع به آنها دارد قاطع مرور زمان نسبت به دیگران نیز هست.'),
 (594,
  'به استثنای شرکتهای سهامی و شرکتهای مختلط سهامی به کلیه شرکتهای ایرانی موجود که به امور تجارتی اشتغال دارند تا اول '
  'تیر ماه۱۳۱۱ مهلت داده می\u200cشود که خود را با مقررات یکی از شرکتهای مذکور در این قانون وفق داده و تقاضای ثبت '
  'نمایند و الا نسبت به شرکت متخلف\u200cمطابق ماده دوم قانون ثبت شرکتها مصوب خرداد ماه ۱۳۱۰ رفتار خواهد شد.'),
 (595,
  'هر گاه مدت مذکور در ماده فوق برای تهیه مقدمات ثبت کافی نباشد ممکن است تا شش ماه دیگر از طرف محکمه صلاحیتدار '
  'مهلت\u200cاضافی داده شود مشروط بر اینکه در موقع تقاضای تمدید نصف حق\u200cالثبت شرکت پرداخته شود.'),
 (596,
  'تاریخ اجرای ماده ۱۵ این قانون در آن قسمتی که مربوط به جزای نقدی است و تاریخ اجرای ماده ۲۰۱ و تبصره آن و قسمت اخیر '
  'ماده۲۲۰ اول فروردین ۱۳۱۲ خواهد بود.'),
 (597,
  'شرکت\u200cهای مختلط سهامی موجود مکلف هستند که در ظرف ۶ ماه از تاریخ اجرای این قانون هیأت نظاری مطابق مقررات این '
  'قانون\u200cتشکیل دهند و الا هر صاحب سهمی حق دارد انحلال شرکت را تقاضا کند.'),
 (598,
  'طلبکاران تاجر متوقفی که قبل از تاریخ اجرای این قانون طلب خود را مطالبه کرده\u200cاند مشمول مقررات ماده ۴۷۳ نبوده '
  'و از حقی که به\u200cموجب قانون سابق برای آنها مقرر بوده استفاده خواهند کرد.'),
 (599,
  'نسبت به طلبکارانی که در امور ورشکستگی\u200cهای سابق قبل از تاریخ اجرای این قانون طلب خود را مطالبه نکرده\u200cاند '
  'مدیر تصفیه هرورشکسته اعلانی منتشر کرده و یک ماه به آنها مهلت خواهد داد که مطابق ماده ۴۶۲ این قانون رفتار کنند و '
  'الا مشمول مقررات ماده ۴۷۳ خواهند شد.'),
 (600,
  'قوانین ذیل: قانون تجارت مصوب ۲۵ دلو ۱۳۰۳ و دوازدهم فروردین و دوازدهم خرداد ۱۳۰۴ - قانون اصلاح ماده ۲۰۶ قانون '
  'تجارت راجع به اعتراض عدم تأدیه\u200cمصوب ۲ تیر ماه ۱۳۰۷ - قانون اجازه عدم رعایت ماده ۲۷۰ و قسمتی از ماده ۴۴ قانون '
  'تجارت نسبت به تشکیلات و اساسنامه شرکت سهامی بانک\u200cملی و شرکت سهامی بانک پهلوی مصوب ۳۰ تیر ماه ۱۳۰۷ از تاریخ '
  'اول خرداد ماه ۱۳۱۱ نسخ و این قانون از تاریخ مزبور به موقع اجرا گذاشته\u200cمی\u200cشود.')]

COMMERCIAL_CODE_PENALTY_ARTICLES_1403 = [15, 16, 18, 201, 220, 346]

